class PolicyCreateController extends Controller
{
    /**
     * Per-vehicle motor extension premium columns. Each vehicle's TOTAL
     * annual premium = motor.calculated_value (own-damage / base) + sum of
     * these extension columns. Pro-rata math uses the total so a change to
     * any single extension generates a delta even when calculated_value
     * itself is unchanged. Mirror of the React frontend's MOTOR_PREMIUM_FIELDS.
     */
    private const MOTOR_EXTENSION_PREMIUM_COLUMNS = [
        'premium_wreckage_removal', 'premium_window_glass', 'premium_locks_keys',
        'premium_parts_accessories', 'premium_audio_accessories', 'premium_riot_strike',
        'premium_car_hire_theft', 'premium_credit_shortfall', 'premium_insured_driver',
        'premium_insured_family', 'premium_medical_expenses', 'premium_passenger_liability',
        'premium_third_party_liability', 'premium_specified_accessories',
        'premium_unorthorised_passanger_liability', 'premium_parking_facilities',
        'premium_com_windscreen',
    ];

    /**
     * Sum every motor extension premium column on a row (stdClass or array)
     * to produce the row's total extension premium.
     */
    private static function sumMotorExtensionPremiums($row): float
    {
        if (!$row) return 0.0;
        $total = 0.0;
        foreach (self::MOTOR_EXTENSION_PREMIUM_COLUMNS as $col) {
            $val = is_array($row) ? ($row[$col] ?? 0) : ($row->$col ?? 0);
            $total += (float) $val;
        }
        return $total;
    }

    // 14 premium columns shared by motor_traders + motor_traders_internal.
    // Sum across both tables for the supplied policy_coverage_ids — this is
    // the bucket that flows into the Rate banner / recomputeActionTotals.
    // Mirrors the MIS report's motor_traders_total_sum recipe at
    // getMISReport.php:547-570.
    private const MOTOR_TRADERS_PREMIUM_COLUMNS = [
        'loss_or_damage_calculated_value',
        'third_party_liability_calculated_value',
        'medical_benefits_calculated_value',
        'vehicle_lent_hire_calculated_value',
        'social_domestic_pleasure_calculated_value',
        'unauthoried_use_calculated_value',
        'windscreen_calculated_value',
        'contigent_liability_calculated_value',
        'wreckage_removal_calculated_value',
        'loss_of_key_calculated_value',
        'Loss_of_use_of_customer_calculated_value',
        'motor_cycle_motor_tricycle_calculated_value',
        'passanger_liability_respect_of_motor_calculated_value',
        'special_type_vehicle_calculated_value',
    ];

    // Sum Insured columns paired 1:1 with MOTOR_TRADERS_PREMIUM_COLUMNS above —
    // the migration defines both `*_coverage_value` and `*_calculated_value`
    // per MT field. Used to hydrate the "Sum Insured" column on the saved
    // coverages list for MOTORTRADERSEXTERNAL / MOTORTRADERSINTERNAL rows,
    // where the parent policy_coverages row carries no Sum Insured itself.
    private const MOTOR_TRADERS_COVERAGE_COLUMNS = [
        'loss_or_damage_coverage_value',
        'third_party_liability_coverage_value',
        'medical_benefits_coverage_value',
        'vehicle_lent_hire_coverage_value',
        'social_domestic_pleasure_coverage_value',
        'unauthoried_use_coverage_value',
        'windscreen_coverage_value',
        'contigent_liability_coverage_value',
        'wreckage_removal_coverage_value',
        'loss_of_key_coverage_value',
        'Loss_of_use_of_customer_coverage_value',
        'motor_cycle_motor_tricycle_coverage_value',
        'passanger_liability_respect_of_motor_coverage_value',
        'special_type_vehicle_coverage_value',
    ];

    private static function sumMotorTradersPremium($pcIds): float
    {
        if ($pcIds === null || (is_object($pcIds) && method_exists($pcIds, 'isEmpty') && $pcIds->isEmpty()) || (is_array($pcIds) && empty($pcIds))) {
            return 0.0;
        }
        $cols = self::MOTOR_TRADERS_PREMIUM_COLUMNS;
        // Wrap each column in COALESCE so NULL fields don't NULL the sum.
        $sumExpr = implode(' + ', array_map(fn($c) => "COALESCE(`{$c}`, 0)", $cols));
        $total = 0.0;
        foreach (['motor_traders', 'motor_traders_internal'] as $tbl) {
            if (!\Schema::hasTable($tbl)) continue;
            $total += (float) DB::table($tbl)
                ->whereIn('policy_coverage_id', $pcIds)
                ->whereNull('deleted_at')
                ->sum(DB::raw($sumExpr));
        }
        return $total;
    }

    /**
     * Specialist coverage tables that each carry their own premium columns
     * (one row per policy_coverage), keyed to the column recipe the Rate
     * path has always used.
     *
     * ADDITIVE vs ALTERNATIVES: car_coverages has no grand total column, so
     * its annual = Section 1 + 2 + 3 (all listed columns summed). Every other
     * table lists ALTERNATIVES — a grand total with section fallbacks
     * (ear/par) or annual_premium||premium (medical/D&O) — so only the first
     * present column is taken, otherwise the row double-counts.
     *
     * NOTE — deliberately NOT SpecialistCoverageRegistry::TABLES. That
     * registry lists travel_coverages => ['policy_amount'], which is the
     * pre-VAT amount; the contract premium actually charged (and shown on the
     * Rate banner / V2 Quote / Policy Doc) is `total` = policy_amount + vat.
     * Swapping to the registry here would silently drop the VAT portion off
     * every Travel policy's annual. The registry is for the pro-rata writer,
     * which works off its own per-row baseline.
     */
    private const SPECIALIST_PREMIUM_TABLES = [
        'ear_coverages'                       => ['total_premium', 'section1_total_premium', 'section3_total_premium'],
        'car_coverages'                       => ['section1_total_premium', 'section2_total_premium', 'section3_total_premium'],
        'par_coverages'                       => ['total_premium', 'section2_total_premium'],
        'professional_indemnity_coverages'    => ['premium'],
        'medical_malpractice_coverages'       => ['annual_premium', 'premium'],
        'marine_cargo_once_off_coverages'     => ['premium'],
        'marine_cargo_open_coverages'         => ['premium'],
        'marine_directors_officers_coverages' => ['premium', 'annual_premium'],
        'machinery_breakdown_coverages'       => ['premium'],
        'medical_evacuation_coverages'        => ['premium'],
        'commercial_crime_coverages'          => ['premium'],
        'environmental_liability_coverages'   => ['premium'],
        'bonds_coverages'                     => ['premium'],
        // Travel: `total` (policy_amount + vat) is the VAT-inclusive contract
        // premium actually charged. `policy_amount` alone is pre-VAT and
        // undercounts the Rate banner / V2 Quote Sheet.
        'travel_coverages'                    => ['total'],
    ];

    /** Tables whose listed columns are additive sections, not alternatives. */
    private const SPECIALIST_ADDITIVE_TABLES = ['car_coverages'];

    /**
     * PRODUCT GUARD: only products that actually use specialist coverages —
     * Engineering (16), Commercial Specialist (17), Domestic Engineering (18),
     * Domestic Specialist (19), Commercial Liabilities (20), Marine (22),
     * Guarantee (23), Misc (24). For Commercial Insurance (7) / Domestic (8) /
     * motor-only policies these tables don't apply, and any rows that exist
     * are stale data from prior testing or product migration — including them
     * inflates the total (e.g. policy 213363 picked up a phantom 2,983 from
     * ear_coverages on a Commercial Motor-only policy).
     */
    private const SPECIALIST_PRODUCT_IDS = [16, 17, 18, 19, 20, 22, 23, 24];

    /**
     * COMPANY-ONLY PRODUCTS: Commercial Liabilities (20), Guarantee (23),
     * Miscellaneous (24) — Annual term only. The holder is NOT constrained
     * here: per UW (2026-08-26) Commercial Liabilities takes an Individual or
     * an Organisation, and the Organisation-only rule for 23 / 24 is enforced
     * in the UI alone (CompanyOnlyProducts::entityLocked). The list and
     * the reasoning live in Support\CompanyOnlyProducts, which the two Livewire
     * wizards read as well; these are thin aliases so the guards below stay
     * readable. The create/edit wizard locks both fields in the UI (React:
     * CreateWizard/helpers.ts::isCompanyOnlyProduct, Livewire: the
     * applicant-information partial) — the guards here are the API-side
     * backstop for a stale draft, an older client or a direct API call.
     */
    private const ANNUAL_FREQ = CompanyOnlyProducts::ANNUAL_FREQ;

    /** True when the product is issued on an Annual term only. */
    private static function isCompanyOnlyProduct($productId): bool
    {
        return CompanyOnlyProducts::includes($productId);
    }

    /**
     * Annual specialist premium for one action.
     *
     * SINGLE SOURCE OF TRUTH for the specialist bucket. Both writers to
     * policy_actions.annual_premium must call this — calculatePremium (the
     * Rate click) and recomputeActionTotals (every non-Rate coverage edit:
     * save, delete/reinstate sub-coverage, delete extension, cancel
     * coverage). recomputeActionTotals previously omitted the bucket
     * entirely, so any coverage edit on a specialist policy overwrote a
     * correctly-rated annual with one missing its specialist premium — the
     * Rate banner and the Added Coverages "Total Premium" (which read the
     * column verbatim) went wrong while the V2 Quote stayed right, because
     * the Quote falls back to its own per-section sum when the column reads
     * 0 (v2-quote-sheet.blade.php Annual Total).
     *
     * $pcIds must be the ACTIVE (non-soft-deleted) policy_coverages for the
     * action — a cancelled coverage contributes zero to the annual baseline;
     * its refund flows through pro_rate_premium instead.
     */
    private static function sumSpecialistPremium($pcIds, int $policyId, ?int $actionId, int $productId): float
    {
        if (!in_array($productId, self::SPECIALIST_PRODUCT_IDS, true)) {
            return 0.0;
        }

        $specialistPremium = 0.0;
        foreach (self::SPECIALIST_PREMIUM_TABLES as $table => $cols) {
            try {
                if (!\Schema::hasTable($table)) continue;
                $tableCols = \Schema::getColumnListing($table);

                // Scope to THIS action's coverages — NOT the whole policy.
                // These tables hold one row per coverage PER ACTION (every
                // endorsement clones the coverage), so summing by policy_id
                // alone accumulates every prior endorsement's section total
                // into the rate. e.g. COMG2026213566 has five car_coverages
                // rows (400+490+550+400+400) and Rate reported 2,240 instead
                // of the current action's 400.
                $q = DB::table($table);
                if (in_array('policy_coverage_id', $tableCols, true)) {
                    if ($pcIds === null || (is_object($pcIds) && method_exists($pcIds, 'isEmpty') && $pcIds->isEmpty()) || (is_array($pcIds) && empty($pcIds))) {
                        continue;
                    }
                    $q->whereIn('policy_coverage_id', $pcIds);
                } else {
                    // Legacy tables without policy_coverage_id: fall back to
                    // policy_id + action_id so we still scope to this action.
                    $q->where('policy_id', $policyId);
                    if ($actionId && in_array('action_id', $tableCols, true)) {
                        $q->where('action_id', $actionId);
                    }
                }
                if (in_array('deleted_at', $tableCols, true)) {
                    $q->whereNull('deleted_at');
                }

                $sumAllColumns = in_array($table, self::SPECIALIST_ADDITIVE_TABLES, true);
                foreach ($q->get() as $row) {
                    // Machinery Breakdown prices section by section, so its
                    // annual is rebuilt from the section item premiums rather
                    // than trusting the scalar column. Rows saved before the
                    // header Premium box became a computed field can carry a
                    // stale or blank scalar while every section is priced —
                    // reading the column verbatim rated those at P 0.00.
                    // resolvedPremium() falls back to the scalar when the
                    // sections are empty, so nothing is lost either way.
                    if ($table === 'machinery_breakdown_coverages') {
                        $specialistPremium += \AlphaDirect\Models\MachineryBreakdownCoverage::resolvedPremium($row);
                        continue;
                    }
                    // PAR: same rule. total_premium is client-supplied and only
                    // recomputed by the capture page when the items grid is
                    // touched, so it drifts from the schedule it is meant to
                    // total. The specialist ENDORSE delta now resolves PAR from
                    // the schedule (SpecialistEndorseCalculator), so the ANNUAL
                    // must too — otherwise the banner's annual and its pro-rata
                    // are built off different bases and stop reconciling.
                    // Falls back to the scalar on a schedule-less row.
                    if ($table === 'par_coverages') {
                        $specialistPremium += \AlphaDirect\Models\ParCoverage::resolvedPremium($row);
                        continue;
                    }
                    foreach ($cols as $col) {
                        if (in_array($col, $tableCols, true) && !empty($row->{$col})) {
                            $specialistPremium += (float) $row->{$col};
                            if (!$sumAllColumns) {
                                break; // alternatives — first available only
                            }
                        }
                    }
                }
            } catch (\Throwable $e) {
                \Log::warning("Specialist-premium sum skipped for {$table}: " . $e->getMessage());
            }
        }

        return $specialistPremium;
    }

    /**
     * Get predefined extension coverage value based on extension name.
     * Maps extension names to their default values from the legacy system.
     */
    private static function getPredefinedExtensionValue(string $extensionName, string $parentCoverageCode = ''): ?string
    {
        $name = strtolower(trim($extensionName));
        $code = strtoupper(trim($parentCoverageCode));

        $predefinedValues = [
            'water leakage' => 5000,
            'television equipment maintenance' => 5000,
            'loss of money' => ['default' => 3000, 'exclude' => ['PERSONALALLRISKS']],
            'refrigerator or deep freeze contents' => 5000,
            'veterinary fees' => 2000,
            'goods in the open' => 5000,
            'locks and keys' => 5000,
            'golfers hole-in-one' => ['default' => 2000, 'exclude' => ['PERSONALALLRISKS']],
            'property of domestic employees' => 5000,
            'personal effects of guests' => 5000,
            'medical expenses' => 5000,
            'death by accident' => 10000,
            'fatal injury - death by accident' => 10000,
            'death by thieves or fire' => 15000,
            'fatal injury - death by thieves or fire' => 15000,
            'temporary repairs and other measures' => 5000,
            'repairs and measures after a loss - temporary repairs and other measures' => 5000,
            'emergency accommodation' => 5000,
            'repairs and measures after a loss - emergency accommodation' => 5000,
        ];

        if (isset($predefinedValues[$name])) {
            $value = $predefinedValues[$name];

            if (is_array($value)) {
                if (in_array($code, $value['exclude'] ?? [], true)) {
                    return null;
                }
                return (string) $value['default'];
            }

            return (string) $value;
        }

        return null;
    }

    /**
     * Step 1: Create policy with customer details.
     * Creates: Customer, CustomerProfile, Policy, PolicyTerm, PolicyAction.
     */
    public function store(Request $request): JsonResponse
    {
        // MIS / motor / retail products (2, 3 and other non-7/8/16-19 ids)
        // are intentionally out of V2's scope — they have distinct policy
        // wordings and rating and stay on legacy graphite. Catch the
        // routing mistake before validation so operators get a clear
        // "go to legacy" message instead of a generic 422 about the
        // `in:` rule. 2026-04-20 product decision.
        $incomingPid = $request->input('product_id');
        $v2SupportedProducts = [7, 8, 16,17,18,20,22,23,24];
        if ($incomingPid !== null && !in_array((int) $incomingPid, $v2SupportedProducts, true)) {
            $productName = optional(\AlphaDirect\Product::find((int) $incomingPid))->name ?? "product #{$incomingPid}";
            return response()->json([
                'error'               => "V2 only handles DomCom and Engineering/Specialist products (ids 7, 8, 16, 17, 18, 20, 22, 23, 24). {$productName} must be created on legacy graphite — it has its own policy wording and rating.",
                'code'                => 'PRODUCT_NOT_SUPPORTED_IN_V2',
                'requested_product_id'=> (int) $incomingPid,
                'supported_products'  => $v2SupportedProducts,
                'legacy_url'          => 'https://graphite.alphadirect.co.bw',
            ], 422);
        }

        // Agent is optional. A blank select can arrive as '', '0', 0 or any
        // non-positive / non-numeric value; normalise all of those to null so
        // the nullable rule applies (an empty string would otherwise fail the
        // integer rule).
        $agentId = $request->input('agent_id');
        if ($agentId === null || !ctype_digit((string) $agentId) || (int) $agentId <= 0) {
            $request->merge(['agent_id' => null]);
        }

        $validated = $request->validate([
            // Policy fields
            'product_id'    => 'required|integer|in:7,8,16,17,18,20,22,23,24',
            'plan_id'       => 'required|integer|exists:product_plans,id',
            'agency_id'     => 'required|integer|exists:agencies,id',
            // Agent is optional — some agencies have no captured agents, so a
            // policy can be saved against the agency alone.
            'agent_id'      => 'nullable|integer|exists:users,id',
            'premium_freq'  => 'required|string|in:1,3,5,6',
            'term_start_date' => 'required|date_format:Y-m-d',
            'expiry_date'   => 'required|date_format:Y-m-d|after:term_start_date',
            'gfs_policy_no' => 'nullable|string|max:50',

            // Binder date — the intermediary's cover-in-principle date.
            // Legacy stores this on customer_profile.binder_date (varchar),
            // used by the quotation PDF and downstream rate calc. Prior to
            // this capture, every V2-created COMG/DOMG policy had NULL here.
            // Accept either Y-m-d or an empty string (frontend sometimes
            // emits '').
            'binder_date'   => 'nullable|date_format:Y-m-d|before_or_equal:term_start_date',

            // Customer fields
            'entity_type'   => 'required|string|in:Individual,Organisation',
            'company_id'    => 'required_if:entity_type,Organisation|nullable|integer',

            // Individual customer fields
            'first_name'    => 'required_if:entity_type,Individual|nullable|string|max:100',
            'middle_name'   => 'nullable|string|max:100',
            'last_name'     => 'required_if:entity_type,Individual|nullable|string|max:100',
            'email'         => 'required_if:entity_type,Individual|nullable|email|max:255',
            'cellphone'     => 'required_if:entity_type,Individual|nullable|string|min:8|max:8',
            'gender'        => 'required_if:entity_type,Individual|nullable|string|in:Male,Female',
            // DOB must be Y-m-d and at least 18 years ago — minors can't
            // hold an insurance policy. `before` accepts strtotime
            // strings; 'today' avoids edge cases with people born
            // exactly 18 years ago to the day.
            'dob'           => 'required_if:entity_type,Individual|nullable|date_format:Y-m-d|before:18 years ago',
            'marital_status'=> 'required_if:entity_type,Individual|nullable|string',
            'omang'         => 'nullable|string|max:25',
            'passport'      => 'nullable|string|max:25',
            'state'         => 'required_if:entity_type,Individual|nullable|integer',
            'city'          => 'required_if:entity_type,Individual|nullable|integer',
            'post_address'  => 'nullable|string|max:500',
            'source_of_income' => 'required_if:entity_type,Individual|nullable|string',
            'employment'    => 'nullable|array',

            // KYC questions
            'currently_insured' => 'nullable|string',
            'current_insurer_detail' => 'nullable|string|max:500',
            'hear_about_alpha'  => 'nullable|string',
            'decline_proposal'  => 'nullable|boolean',
            'refused_policy'    => 'nullable|boolean',
            'cancel_policy'     => 'nullable|boolean',
            'business_note'     => 'nullable|string|max:1000',

            // COMG-specific
            'firm_member'   => 'nullable|boolean',
            'books'         => 'nullable|boolean',
            'date'          => 'nullable|date_format:Y-m-d',
        ], [
            'dob.before'      => 'The policy holder must be at least 18 years old.',
            'dob.date_format' => 'DOB must be a valid date in YYYY-MM-DD format.',
            'dob.required_if' => 'Date of birth is required for individual policy holders.',
        ]);

        // Company-only products (20 / 23 / 24) are Annual-term. Reject rather
        // than silently coerce — a Monthly entity would already have been
        // priced per-month upstream.
        //
        // NO entity_type guard here. It used to reject a non-Organisation
        // holder on all three, which blocked the Individual option UW asked
        // for on Commercial Liabilities (20). The Organisation-only rule for
        // Guarantee (23) / Miscellaneous (24) now lives in the UI alone —
        // React (isOrganisationOnlyProduct) and the Livewire entity select /
        // saveStep1 coercion (CompanyOnlyProducts::entityLocked) — so the API
        // no longer second-guesses the holder the operator picked.
        if (self::isCompanyOnlyProduct($validated['product_id'])) {
            $companyOnlyErrors = [];
            if ($validated['premium_freq'] !== self::ANNUAL_FREQ) {
                $companyOnlyErrors['premium_freq'] = 'Only Annual frequency is allowed on this product.';
            }
            if ($companyOnlyErrors) {
                return response()->json([
                    'message' => 'Validation failed.',
                    'errors'  => $companyOnlyErrors,
                ], 422);
            }
        }

        // Omang or Passport is mandatory ONLY for Individual policy holders.
        // Organisation (Commercial) policies are held by a company, not a
        // natural person — UW asked for this guard to be lifted on Commercial.
        if ($validated['entity_type'] === 'Individual'
            && empty($validated['omang']) && empty($validated['passport'])) {
            return response()->json([
                'message' => 'Validation failed.',
                'errors' => ['omang' => 'Either Omang ID or Passport is required for individual policy holders.'],
            ], 422);
        }

        try {
            DB::beginTransaction();

            // Create or find customer
            if ($validated['entity_type'] === 'Organisation') {
                $customer = Customer::where('company_id', $validated['company_id'])->first();
                if (!$customer) {
                    $customer = Customer::create([
                        'company_id' => $validated['company_id'],
                        'firstName'  => Company::find($validated['company_id'])->name ?? 'Organisation',
                        'lastName'   => '',
                        'email'      => $validated['email'] ?? null,
                        'cellphone'  => $validated['cellphone'] ?? null,
                    ]);
                }
            } else {
                // Check for existing customer
                $customer = Customer::where('email', $validated['email'])
                    ->where('cellphone', $validated['cellphone'])
                    ->first();

                if (!$customer) {
                    $customer = Customer::create([
                        'firstName'  => $validated['first_name'],
                        'middleName' => $validated['middle_name'] ?? null,
                        'lastName'   => $validated['last_name'],
                        'email'      => $validated['email'],
                        'cellphone'  => $validated['cellphone'],
                    ]);
                } else {
                    $customer->update([
                        'firstName'  => $validated['first_name'],
                        'middleName' => $validated['middle_name'] ?? null,
                        'lastName'   => $validated['last_name'],
                    ]);
                }
            }

            // Create or update customer profile
            $profileData = [
                'customer_id'      => $customer->id,
                'entity_type'      => $validated['entity_type'],
                'gender'           => $this->genderCode($validated['gender'] ?? null),
                'dob'              => !empty($validated['dob']) ? Carbon::parse($validated['dob']) : null,
                'maritalstatus'    => $validated['marital_status'] ?? null,
                'omang'            => $validated['omang'] ?? null,
                'passport'         => $validated['passport'] ?? null,
                'state'            => $validated['state'] ?? null,
                'city'             => $validated['city'] ?? null,
                'post_address'     => $validated['post_address'] ?? null,
                'address'          => $validated['post_address'] ?? null,
                'source_of_income' => json_encode($this->buildSourceOfIncome(
                    $validated['source_of_income'] ?? null,
                    $validated['employment'] ?? []
                )),
                'Insure'           => $validated['currently_insured'] ?? null,
                'current_insurer' => $validated['current_insurer_detail'] ?? null,
                'about_alpha'      => $validated['hear_about_alpha'] ?? null,
                'decline_proposal' => $validated['decline_proposal'] ?? false ? 1 : 0,
                'refused_policy'   => $validated['refused_policy'] ?? false ? 1 : 0,
                'cancel_policy'    => $validated['cancel_policy'] ?? false ? 1 : 0,
                'business_note'    => $validated['business_note'] ?? null,
                // binder_date is varchar(255) in legacy prod — keep it as a
                // string rather than Carbon-casting, so existing rows and
                // round-trips stay shape-stable.
                'binder_date'      => !empty($validated['binder_date']) ? $validated['binder_date'] : null,
            ];

            if ($validated['entity_type'] === 'Organisation') {
                $profileData['company_id'] = $validated['company_id'];
            }

            // COMG-specific fields
            if (in_array($validated['product_id'], [7, 16, 17])) {
                $profileData['firm_member'] = $validated['firm_member'] ?? false ? 1 : 0;
                $profileData['books'] = $validated['books'] ?? false ? 1 : 0;
                if (!empty($validated['date'])) {
                    $profileData['date'] = Carbon::parse($validated['date']);
                }
            }

            $profile = CustomerProfile::updateOrCreate(
                ['customer_id' => $customer->id],
                $profileData
            );

            // Generate policy number
            $latest = Policy::orderBy('id', 'desc')->first(['id']);
            $nextId = $latest ? $latest->id + 1 : 1;

            if (in_array($validated['product_id'], [7, 16,17,20,22,23,24])) {
                $policyNo = 'COMG' . Carbon::now()->year . str_pad($nextId, 6, '0', STR_PAD_LEFT);
            } elseif (in_array($validated['product_id'], [8, 18])) {
                $policyNo = 'DOMG' . Carbon::now()->year . str_pad($nextId, 6, '0', STR_PAD_LEFT);
            } else {
                $policyNo = 'MIS' . Carbon::now()->year . str_pad($nextId, 6, '0', STR_PAD_LEFT);
            }

            // Create policy
            $policy = Policy::create([
                'customer_id'        => $customer->id,
                'product_id'         => $validated['product_id'],
                'plan_id'            => $validated['plan_id'],
                'agency_id'          => $validated['agency_id'],
                'agent_id'           => $validated['agent_id'] ?? null,
                'premium_freq'       => $validated['premium_freq'],
                'policyNumber'       => $policyNo,
                'term_start_date'    => Carbon::parse($validated['term_start_date']),
                'expiry_date'        => Carbon::parse($validated['expiry_date']),
                'status'             => 0, // Quote
                'is_draft'           => 1,
                'has_member'         => 1,
                'policyActivatedDate'=> null,
                // billingStartDate mirrors the binder_date the operator set.
                // Legacy AddWizard uses the same single input to seed both.
                'billingStartDate'   => !empty($validated['binder_date'])
                    ? Carbon::parse($validated['binder_date'])
                    : null,
                'gfs_policy_no'      => $validated['gfs_policy_no'] ?? null,
            ]);

            // Log activity
            activity('Policy')
                ->performedOn($policy)
                ->causedBy(auth()->user())
                ->log('Policy Created');

            // Create policy term
            $termId = PolicyTerm::addPolicyTerm([
                'policy_id'          => $policy->id,
                'term_start_date'    => $policy->term_start_date,
                'term_end_date'      => $policy->expiry_date,
                'premium'            => $policy->premium,
                'annual_premium'     => null,
                'vat'                => $policy->vat,
                'vat_percent'        => $policy->vat_percent,
                'renewed_by'         => $policy->agent_id,
                'renewals_date'      => Carbon::now()->addYear()->format('Y-m-d'),
                'frequency'          => $policy->premium_freq,
                'first_premium'      => $policy->first_premium,
                'billing_start_date' => null,
                'policy_documents'   => null,
                'policyActivatedDate'=> null,
                'payment_method'     => null,
                'payment_reference'  => $policy->id,
                'trans_type'         => 'NEW BUSINESS',
                'status'             => 'Active',
                'created_at'         => Carbon::now()->format('Y-m-d'),
            ]);

            activity('Policy Term Created')
                ->performedOn($policy)
                ->causedBy(auth()->user())
                ->log('Term Date : ' . $policy->term_start_date . ' - ' . $policy->expiry_date);

            // Create policy action
            $action = PolicyAction::create([
                'policy_id'       => $policy->id,
                'term_id'         => $termId,
                'note'            => 'New Business',
                'policy_quote_no' => $policyNo . '/01',
                'effective_from'  => $policy->term_start_date,
                'effective_to'    => $policy->expiry_date,
            ]);

            activity('Policy Action Created')
                ->performedOn($policy)
                ->causedBy(auth()->user())
                ->log('Effective Date : ' . $policy->term_start_date . ' - ' . $policy->expiry_date . ' , Transaction Type : NEW BUSINESS , Status : QUOTE');

            DB::commit();

            // Notify the customer (SMS + email) that the policy/quote was
            // created. Premium is not rated yet at this point, so it resolves
            // from policies.premium (likely null → "to be confirmed").
            // Non-fatal — the service swallows its own errors.
            (new \AlphaDirect\Services\CustomerNotificationService())
                ->notifyPolicyCreated($policy->id, $policyNo);

            return response()->json([
                'data' => [
                    'policy_id'     => $policy->id,
                    'policy_number' => $policyNo,
                    'term_id'       => $termId,
                    'action_id'     => $action->id,
                    'customer_id'   => $customer->id,
                    'status'        => 'quote',
                ],
                'message' => 'Policy created successfully. Proceed to add risk addresses.',
            ], 201);

        } catch (\Illuminate\Validation\ValidationException $ve) {
            DB::rollBack();
            return response()->json([
                'message' => 'Validation failed.',
                'errors'  => $ve->errors(),
            ], 422);
        } catch (\Exception $e) {
            DB::rollBack();
            Log::error('Policy creation failed: ' . $e->getMessage(), ['trace' => $e->getTraceAsString()]);
            return response()->json([
                'message' => 'Failed to create policy.',
                'error'   => $e->getMessage(),
            ], 500);
        }
    }

    /**
     * Load a policy's data for editing in the create form.
     * Wrapped in try/catch so any DB or model error returns a descriptive JSON response
     * rather than a generic 500, making frontend debugging much easier.
     */
    public function editData(int $policyId, Request $request = null): JsonResponse
    {
        try {
            $policy = Policy::with(['customer', 'customer.profile', 'customer.banking'])->findOrFail($policyId);

            // Null-safe access: customer and profile may be null for old/imported policies
            $customer = $policy->customer;
            $profile  = $customer ? ($customer->profile ?? null) : null;

            // Optional ?action_id=... to load a specific action's data. Default
            // behaviour: prefer the latest QUOTE action (editable). If none,
            // fall back to the latest action. Mirrors graphiteBWV8 EditWizard
            // which targets the open endorsement/renewal.
            $requestedActionId = $request ? $request->query('action_id') : request()->query('action_id');
            $term   = PolicyTerm::where('policy_id', $policyId)->orderBy('id', 'desc')->first();
            $action = null;
            if ($requestedActionId) {
                $action = PolicyAction::where('policy_id', $policyId)
                    ->where('id', $requestedActionId)
                    ->first();
            }
            if (!$action) {
                $action = PolicyAction::where('policy_id', $policyId)
                    ->where('status', 'QUOTE')
                    ->orderBy('id', 'desc')
                    ->first()
                    ?? PolicyAction::where('policy_id', $policyId)->orderBy('id', 'desc')->first();
            }

            // Cancel Sub Coverage endorse: subcoverage rows are intentionally
            // zeroed (SI/Premium = 0) but must still be SHOWN on edit (with
            // their free text / rate) instead of being dropped by the default
            // ">0 only" subcoverage display filter. Scoped to this reason only.
            // Scoped to DomCom products (7, 8) only.
            $reasonNormForCancel = strtolower(preg_replace('/\s+/', '', (string) ($action->transaction_reason ?? '')));
            $isCancelSubEndorse = $action
                && in_array((int) ($policy->product_id ?? 0), [7, 8], true)
                && $action->transaction_type === 'ENDORSE'
                && in_array($reasonNormForCancel, ['subcovcancel', 'cancelsubcoverage'], true);

            // Risk addresses — filter by latest action to avoid duplicates (each endorsement
            // replicates risk_address rows via PolicyAction::newPolicyAction).
            // Fallback: if current action has no addresses, show most-recent non-empty action's addresses.
            // Include cancelled (soft-deleted) addresses so the wizard can
            // render them with a Reinstate button. The model exposes
            // deleted_at automatically when withTrashed() is used.
            $riskAddresses = RiskAddress::withTrashed()
                ->where('policy_id', $policyId)
                ->when($action, fn($q) => $q->where('action_id', $action->id))
                ->get();
            if ($riskAddresses->isEmpty()) {
                $riskAddresses = RiskAddress::withTrashed()
                    ->where('policy_id', $policyId)
                    ->orderBy('id', 'desc')
                    ->get()
                    ->unique(fn($r) => trim(($r->address_name ?? '') . '|' . ($r->physical_address ?? '') . '|' . ($r->risk_state ?? '') . '|' . ($r->risk_city ?? '')))
                    ->values();
            }

            // Coverages with subcoverage details — filter by latest action to avoid duplicates.
            // Include cancelled (soft-deleted) coverages too so the wizard can
            // render them with a Reinstate button. Each row's `deleted_at`
            // is exposed in the response so the frontend can branch on it.
            $coveragesRaw = \AlphaDirect\Models\PolicyCoverage::withTrashed()
                ->with(['coverage', 'coverageDetail', 'coverageDetail.coverage'])
                ->where('policy_id', $policyId)
                ->when($action, fn($q) => $q->where('action_id', $action->id))
                ->orderBy('id')
                ->get();
            $allPcIds = $coveragesRaw->pluck('id')->all();

            // ── BULK PRE-LOAD — replaces N+1 storm for large policies ─────────
            // For policies with hundreds of coverages (e.g. large COMG groups),
            // loading extensions/items/notes/motor-counts per coverage caused
            // Cloudflare timeouts. Load everything once and group by pc_id.
            //
            // Join to `extentions` master for s_ScreenName — policy_extention_detail
            // itself only stores extentions_id, so without the join the frontend
            // row renders with an empty/type-only label ("Extention") and
            // operators can't tell which extension they're editing.
            $hasExtCustomName = \Schema::hasColumn('policy_extention_detail', 'custom_name');
            $extSelect = [
                'ped.*',
                'e.s_ScreenName as ext_screen_name',
                'e.s_CoverageName as ext_coverage_name',
                'e.extention_type as ext_field_type',
            ];
            $extensionsByPc = empty($allPcIds) ? collect() : DB::table('policy_extention_detail as ped')
                ->leftJoin('extentions as e', 'e.id', '=', 'ped.extentions_id')
                ->whereIn('ped.policy_coverage_id', $allPcIds)
                ->whereNull('ped.deleted_at')
                ->select($extSelect)
                ->get()
                ->groupBy('policy_coverage_id');

            // Specified items — include motor_id so frontend can show items per-motor
            // (for MOTOR coverages, each item can be attached to a specific motor vehicle).
            // policy_coverage_id is the canonical action scope here:
            // policy_coverages are replicated per action and $allPcIds is
            // already filtered to this action's pcs (line 411). Do NOT also
            // filter by policy_specified_items.action_id — the legacy
            // wizard / addMotorSpecifiedItem stamped that column with
            // "latest action by id" rather than the coverage's own action,
            // so rows added under a different latest-action context were
            // hidden from the action that actually owns them. Existing
            // production data has this drift (e.g. pc 132806 carries items
            // with action_id 40099 / 40174 even though the pc itself lives
            // on action 40177). Trusting the pc relationship alone unhides
            // them and matches the same pattern used for extensions, motor,
            // and notes loaders below.
            // Include soft-deleted items so the frontend can display them with
            // a "Reinstate" button (deleted_at will be set for soft-deleted rows)
            $specifiedItemsRaw = empty($allPcIds) ? collect() : DB::table('policy_specified_items')
                ->whereIn('policy_coverage_id', $allPcIds)
                ->get();
            // Bulk lookup specified-coverage names
            $specifiedNameMap = collect();
            if ($specifiedItemsRaw->isNotEmpty()) {
                $specifiedIds = $specifiedItemsRaw->pluck('specified_coverage_id')->filter()->unique()->all();
                if (!empty($specifiedIds)) {
                    $specifiedNameMap = DB::table('specified_coverage_items')
                        ->whereIn('id', $specifiedIds)
                        ->pluck('specified_name', 'id');
                }
            }
            $specifiedByPc = $specifiedItemsRaw->groupBy('policy_coverage_id');

            // Notes — also load per-motor notes (graphiteBWV8 stores coverage-level
            // AND motor-level notes in the same table, keyed by (pc_id, motor_id)).
            // Include benefits_note (WC / Stated Benefits "Benefits for the
            // circumstances") only when the column exists — it's added by
            // migration 2026_06_03_000001; selecting it before that would error.
            $noteCols = ['policy_coverage_id', 'motor_id', 'note', 'memoranda_warranty', 'cash_warranty'];
            if (\Schema::hasColumn('policy_coverage_notes', 'benefits_note')) {
                $noteCols[] = 'benefits_note';
            }
            $notesRows = empty($allPcIds) ? collect() : DB::table('policy_coverage_notes')
                ->whereIn('policy_coverage_id', $allPcIds)
                ->whereNull('deleted_at')
                ->orderBy('id')
                ->get($noteCols);
            // Coverage-level note = row where motor_id is NULL (or 0).
            // A coverage can carry MORE THAN ONE such row: the Money warranty
            // writes used to look the row up by `motor_id IS NULL` only, so a
            // note row stored with motor_id = 0 was missed and a second row
            // was inserted. keyBy() keeps the LAST row, so the note saved on
            // the older row read back blank. Fold every coverage-level row
            // into one — last non-empty value wins per column — so existing
            // duplicated data still shows correctly; the save path now keeps
            // a single row going forward.
            $notesByPc = $notesRows
                ->filter(fn($n) => empty($n->motor_id))
                ->groupBy('policy_coverage_id')
                ->map(function ($rows) use ($noteCols) {
                    $merged = (object) array_fill_keys($noteCols, null);
                    foreach ($rows as $row) {
                        foreach ($noteCols as $col) {
                            if (trim((string) ($row->{$col} ?? '')) !== '') {
                                $merged->{$col} = $row->{$col};
                            }
                        }
                    }
                    return $merged;
                });
            // Per-motor notes
            $notesByMotor = $notesRows
                ->filter(fn($n) => !empty($n->motor_id))
                ->keyBy('motor_id')
                ->map(fn($n) => $n->note);

            // Motor totals + counts, bulk
            // Per-vehicle premium = own-damage base (calculated_value) + every
            // extension premium column. The saved-coverages "Premium" must show
            // the WHOLE motor section, so fold the extension columns into `calc`
            // here (mirrors motorAggregate on the React side and the Rate banner).
            // Without this the list showed only Σ own-damage, dropping every
            // sub-coverage / extension premium the operator entered per vehicle.
            $motorCalcExpr = 'COALESCE(calculated_value, 0) + ' . implode(' + ', array_map(
                fn($c) => "COALESCE(`{$c}`, 0)", self::MOTOR_EXTENSION_PREMIUM_COLUMNS));
            $motorByPc = empty($allPcIds) ? collect() : DB::table('motor')
                ->whereIn('policy_coverage_id', $allPcIds)
                ->whereNull('deleted_at')
                ->selectRaw("policy_coverage_id, COALESCE(SUM(coverage_value),0) cv, COALESCE(SUM({$motorCalcExpr}),0) calc, COUNT(*) cnt")
                ->groupBy('policy_coverage_id')
                ->get()
                ->keyBy('policy_coverage_id');

            // Motor Traders totals, bulk — sums the 14 SI columns and 14
            // premium columns from motor_traders / motor_traders_internal so
            // the saved-coverages list can show a non-zero Sum Insured /
            // Premium for MOTORTRADERSEXTERNAL / MOTORTRADERSINTERNAL rows.
            // Without this the parent policy_coverages row carries zero
            // (MT data lives in a separate single-row table per coverage),
            // so the wizard summary collapsed to P 0 / P 0.00 even after
            // the operator saved their MT fields.
            $mtCvExpr   = implode(' + ', array_map(fn($c) => "COALESCE(`{$c}`, 0)", self::MOTOR_TRADERS_COVERAGE_COLUMNS));
            $mtCalcExpr = implode(' + ', array_map(fn($c) => "COALESCE(`{$c}`, 0)", self::MOTOR_TRADERS_PREMIUM_COLUMNS));
            $mtByPc = collect();
            if (!empty($allPcIds)) {
                foreach (['motor_traders', 'motor_traders_internal'] as $tbl) {
                    if (!\Schema::hasTable($tbl)) continue;
                    $rows = DB::table($tbl)
                        ->whereIn('policy_coverage_id', $allPcIds)
                        ->whereNull('deleted_at')
                        ->selectRaw("policy_coverage_id, ({$mtCvExpr}) AS cv, ({$mtCalcExpr}) AS calc")
                        ->get();
                    foreach ($rows as $r) {
                        $existing = $mtByPc->get($r->policy_coverage_id);
                        $mtByPc->put($r->policy_coverage_id, (object) [
                            'cv'   => (float) ($existing->cv ?? 0) + (float) $r->cv,
                            'calc' => (float) ($existing->calc ?? 0) + (float) $r->calc,
                        ]);
                    }
                }
            }


            // Fidelity Guarantee data — load per coverage
            $fidelityByPc = empty($allPcIds) ? collect() : DB::table('policy_coverages_data')
                ->whereIn('policyCoverageID', $allPcIds)
                ->where('policy_id', $policyId)
                ->get()
                ->groupBy('policyCoverageID');

            // Theft General Questions — load per coverage
            $theftByPc = empty($allPcIds) ? collect() : DB::table('theft_general_questions')
                ->whereIn('policy_coverage_id', $allPcIds)
                ->get()
                ->groupBy('policy_coverage_id');

            $coverages = $coveragesRaw
                ->map(function ($pc) use ($extensionsByPc, $specifiedByPc, $specifiedNameMap, $notesByPc, $motorByPc, $mtByPc, $fidelityByPc, $theftByPc, $isCancelSubEndorse) {
                    $totalCv = $pc->coverageDetail->sum('coverage_value');
                    $totalCalc = $pc->coverageDetail->sum('calculated_value');

                    // For motor coverages, aggregate from motor table (bulk pre-loaded)
                    if ($totalCv == 0 && $totalCalc == 0 && isset($motorByPc[$pc->id])) {
                        $mt = $motorByPc[$pc->id];
                        $totalCv   = (float) $mt->cv;
                        $totalCalc = (float) $mt->calc;
                    }

                    // For Motor Traders Ext/Int, aggregate the 14 SI + 14
                    // premium columns from motor_traders / motor_traders_internal
                    // (bulk pre-loaded above). MT data lives in a separate
                    // single-row table per coverage, so the parent policy_coverages
                    // row is zero — without this branch the saved-coverages
                    // list would render P 0 / P 0.00 for every MT row.
                    $coverageCodeForMt = strtoupper($pc->coverage?->s_CoverageCode ?? '');
                    if (in_array($coverageCodeForMt, ['MOTORTRADERSEXTERNAL', 'MOTORTRADERSINTERNAL'], true)
                        && isset($mtByPc[$pc->id])) {
                        $mt = $mtByPc[$pc->id];
                        $totalCv   = (float) $mt->cv;
                        $totalCalc = (float) $mt->calc;
                    }

                    // For Fidelity Guarantee, sum amount_to_be_guaranteed from policy_coverages_data
                    // instead of coverage_value from policy_coverage_detail
                    $coverageCodeForFidelity = strtoupper($pc->coverage?->s_CoverageCode ?? '');
                    if ($coverageCodeForFidelity === 'FIDELITYGUARANTEE' && isset($fidelityByPc[$pc->id])) {
                        $fidelityRows = $fidelityByPc[$pc->id];
                        $totalCv = $fidelityRows->sum('amount_to_be_guaranteed');
                        $totalCalc = $fidelityRows->sum('premium');
                    }

                    if ($totalCv == 0 && $totalCalc == 0) {
                        $totalCv   = $pc->coverage_value;
                        $totalCalc = $pc->calculated_value;
                    }
                    // Use saved description (coverage_value_string) over master name.
                    // Workers Compensation rows additionally carry their own
                    // free-text note in coverage_value_string and a per-row
                    // discount/surcharge triplet — we surface them so the
                    // wizard can rehydrate the WC-only layout. Master sub-rows
                    // (Free text, Employers Liability, etc.) keep their
                    // s_ScreenName from the master so the locked label still
                    // reads correctly when the saved coverage_value_string is
                    // a per-row note rather than the screen name.
                    $subs = $pc->coverageDetail
                        ->filter(function ($d) use ($isCancelSubEndorse) {
                            if ((float) ($d->coverage_value ?? 0) > 0 || (float) ($d->calculated_value ?? 0) > 0) {
                                return true;
                            }
                            // A second-field-only sub-coverage row carries NO money:
                            // Public Liability "Basis of cover" (Claims Made /
                            // Claims Occurring) lives solely in limit_id, and its
                            // "Full address of…" rows solely in
                            // coverage_value_string, with SI + Premium left at 0.
                            // The ">0" test above dropped those rows on load, so the
                            // wizard re-rendered the select as "- Select -" (and the
                            // free text as blank) and the operator's saved pick looked
                            // lost even though it was sitting in
                            // policy_coverage_detail. Keep any live row whose second
                            // field holds a real value — same storage targets the
                            // wizard's getSubcoverageSecondField writes, and the same
                            // "'' / '0' means no selection" rule the save path uses.
                            if ($d->deleted_at === null) {
                                foreach ([
                                    $d->limit_id ?? null,
                                    $d->coverage_value_string ?? null,
                                    $d->ratefactor_type ?? null,
                                    $d->ratefactor_value ?? null,
                                ] as $v) {
                                    $t = trim((string) ($v ?? ''));
                                    if ($t !== '' && $t !== '0') {
                                        return true;
                                    }
                                }
                            }
                            // Cancel Sub Coverage endorse only: show every
                            // subcoverage row that has not been soft-deleted,
                            // even when zeroed (SI/Premium = 0), so cancelled
                            // covers stay visible on edit with their 0/0 values
                            // instead of dropping to a blank row. Other actions
                            // keep the ">0 only" filter.
                            if ($isCancelSubEndorse) {
                                return $d->deleted_at === null;
                            }
                            return false;
                        })
                        ->map(fn($d) => [
                        'id'              => $d->id,
                        'detail_id'       => $d->id,
                        'sub_coverage_id' => $d->coverage_id,
                        's_ScreenName'    => $d->coverage?->s_ScreenName ?: ($d->coverage_value_string ?: ''),
                        's_CoverageGroupName' => $d->coverage?->s_CoverageGroupName ?? '',
                        's_SubCoverageMainName' => $d->coverage?->s_SubCoverageMainName ?? '',
                        // CRITICAL: Include field configuration so form shows correct layout
                        's_CoverageCode'  => $d->coverage?->s_CoverageCode ?? '',
                        's_ParentCoverageCode' => $d->coverage?->s_ParentCoverageCode ?? '',
                        's_LimitTypeCode' => $d->coverage?->s_LimitTypeCode ?? '',  // Determines Free Text vs Sum Insured layout
                        'coverage_value'  => (string) ($d->coverage_value ?? 0),
                        'rate'            => (string) ($d->rate ?? 0),
                        'calculated_value'=> (string) ($d->calculated_value ?? 0),
                        'coverage_value_string' => $d->coverage_value_string ?? '',
                        // DROPDOWN / RADIO second-field selection — holds
                        // tb_cvgpclimits.n_PCLimitId_PK (e.g. Public Liability
                        // "Basis of cover" → Claims Made). Without this the
                        // wizard re-renders the select as "- Select -" on edit
                        // and the operator's saved pick looks lost.
                        'limit_id'        => $d->limit_id !== null ? (string) $d->limit_id : '',
                        // Workers Compensation specific fields
                        'ratefactor_type' => $d->ratefactor_type ?? '',
                        'ratefactor_value' => $d->ratefactor_value ?? '',
                        'ratefactor_value_check'    => $d->ratefactor_value_check ?? '',
                        'ratefactor_AnnualWages'    => $d->ratefactor_AnnualWages ?? '',
                        'ratefactor_deposit_min_pre'=> $d->ratefactor_deposit_min_pre ?? '',
                        // Discount/Surcharge — captured for WC. Empty string
                        // when no discount applied (legacy enum nullable).
                        'discount_surcharge'        => $d->discount_surcharge ?? '',
                        'discount_surcharge_type'   => $d->discount_surcharge_type ?? '',
                        'discount_surcharge_value'  => (string) ($d->discount_surcharge_value ?? ''),
                    ])->values()->toArray();

                    // Extensions — from bulk pre-load. Name comes from the
                    // joined `extentions` master (ext_screen_name /
                    // ext_coverage_name). Fallback to the FK id so the row
                    // still carries something recognisable even if the master
                    // row was deleted.
                    $extensions = ($extensionsByPc[$pc->id] ?? collect())->map(fn($e) => [
                        'extentions_id' => $e->extentions_id,
                        // Prefer per-policy override (custom_name) when set,
                        // else the master s_ScreenName. Keeps operator-edited
                        // names local to this policy without touching master.
                        's_ScreenName'  => ($e->custom_name ?? null) ?: ($e->ext_screen_name ?? $e->ext_coverage_name ?? ('Extension #' . $e->extentions_id)),
                        'type'          => $e->type ?? 'Extention',
                        'extention_type'=> $e->ext_field_type ?? 'NUMBER',
                        'extention_coverage_value' => (string) (!empty($e->extention_coverage_value) ? $e->extention_coverage_value : (self::getPredefinedExtensionValue($e->ext_screen_name ?? $e->ext_coverage_name ?? '', $pc->coverage?->s_CoverageCode ?? '') ?? '')),
                        'extention_text_value'     => $e->extention_text_value ?? '',
                        'extention_limit_id'       => $e->extention_limit_id,
                        'extention_excess_min_value' => (string) ($e->extention_excess_min_value ?? ''),
                        'extention_excess_max_value' => (string) ($e->extention_excess_max_value ?? ''),
                        'extention_discount_surcharge'       => $e->extention_discount_surcharge ?? '',
                        'extention_discount_surcharge_type'  => $e->extention_discount_surcharge_type ?? '',
                        'extention_discount_surcharge_value' => (string) ($e->extention_discount_surcharge_value ?? ''),
                        'extention_calculated_value' => (string) ($e->extention_calculated_value ?? ''),
                        'extention_sum_insured' => (string) ($e->extention_sum_insured ?? ''),
                    ])->values()->toArray();

                    // Specified items — from bulk pre-load (with pre-resolved names)
                    // Includes motor_id so frontend can group items under a specific
                    // motor vehicle on motor coverages (mirrors graphiteBWV8).
                    $coverageCodeRaw = strtoupper($pc->coverage?->s_CoverageCode ?? '');
                    // Motor Traders Ext/Int are NOT per-vehicle products — they store
                    // their specified items at the coverage level (motor_id = NULL).
                    // Excluding them from $isMotorCov makes the filter below keep
                    // those rows (otherwise the editData endpoint silently drops
                    // every MT specified item on reload, so the wizard re-renders
                    // an empty Miscellaneous Items table after Update Coverage).
                    $isMotorCov = in_array($coverageCodeRaw, ['COMMERCIALMOTOR', 'PERSONALMOTOR', 'DOMESTICMOTOR', 'DOMMOTOR', 'MOTOR']);
                    $specifiedItems = ($specifiedByPc[$pc->id] ?? collect())
                        // On motor coverages only keep rows that are bound to a motor —
                        // unbound rows were coverage-level "sub-coverage extras" that
                        // legacy code duplicated per vehicle; don't surface them again.
                        ->filter(fn($s) => $isMotorCov ? !empty($s->motor_id) : true)
                        ->map(fn($s) => [
                            'id'                    => $s->id,
                            'specified_coverage_id' => $s->specified_coverage_id,
                            'motor_id'              => $s->motor_id ?? null,
                            // Master pick → master name. Custom free-text → custom_name.
                            'name'                  => $specifiedNameMap[$s->specified_coverage_id]
                                                        ?? ($s->custom_name ?? ''),
                            'isCustom'              => empty($s->specified_coverage_id),
                            'sum_insured'           => (string) ($s->sum_insured ?? ''),
                            'rate'                  => (string) ($s->rate ?? ''),
                            'calculated_value'      => (string) ($s->calculated_value ?? ''),
                            'deleted_at'            => $s->deleted_at,
                        ])->values()->toArray();

                    // Deduplicate on non-motor coverages: legacy sometimes wrote the
                    // same (specified_coverage_id, sum_insured, rate) triplet twice
                    // during endorsement replication. Monika #5 showed the same
                    // specified item repeated 4× in a single non-motor coverage on
                    // COMG2024112441. Keep the first row per unique triplet; on
                    // motor coverages we don't dedupe because each motor_id row
                    // is legitimately distinct.
                    if (!$isMotorCov) {
                        $seen = [];
                        $specifiedItems = array_values(array_filter($specifiedItems, function ($s) use (&$seen) {
                            $key = ($s['specified_coverage_id'] ?? '').'|'.($s['sum_insured'] ?? '').'|'.($s['rate'] ?? '');
                            if (isset($seen[$key])) return false;
                            $seen[$key] = true;
                            return true;
                        }));
                    }

                    // Motor coverages: fold per-vehicle MISC (specified items)
                    // into the section Sum Insured / Premium. $motorByPc above
                    // only covers the motor rows themselves; the misc items live
                    // in policy_specified_items (motor_id set) and must be added
                    // so the saved-coverages list shows motors + extensions + misc.
                    if ($isMotorCov && !empty($specifiedItems)) {
                        foreach ($specifiedItems as $si) {
                            if (!empty($si['deleted_at'])) continue;
                            $totalCalc += (float) ($si['calculated_value'] ?? 0);
                            $totalCv   += (float) ($si['sum_insured'] ?? 0);
                        }
                    }

                    // Note + Fidelity data — from bulk pre-load
                    $note = $notesByPc[$pc->id] ?? null;
                    $fidelityData = ($fidelityByPc[$pc->id] ?? collect())->map(fn($f) => [
                        'id'                      => $f->id,
                        'cover_type'              => $f->cover_type ?? '',
                        'cover_area'              => $f->cover_area ?? '',
                        'name_and_position'       => $f->name_and_position ?? '',
                        'designation'             => $f->designation ?? '',
                        'length_of_service'       => $f->length_of_service ?? '',
                        'amount_to_be_guaranteed' => (string) ($f->amount_to_be_guaranteed ?? ''),
                        'premium'                 => (string) ($f->premium ?? ''),
                    ])->values()->toArray();

                    // Theft General Questions — from bulk pre-load
                    $theftData = ($theftByPc[$pc->id] ?? collect())->map(fn($t) => [
                        'physical_protection_implemented' => $t->physical_protection_implemented ?? '',
                        'premises_alarmed' => $t->premises_alarmed ?? '',
                        'subscribe_armed_security' => $t->subscribe_armed_security ?? '',
                        'security_company' => $t->security_company ?? '',
                        'maintenance_contract' => $t->maintenance_contract ?? '',
                        'alarmed_installed_date' => $t->alarmed_installed_date ?? '',
                        'opening_closing_signals' => $t->opening_closing_signals ?? '',
                    ])->values()->toArray();

                    $coverageCode = strtoupper($pc->coverage?->s_CoverageCode ?? '');
                    $motorCount = isset($motorByPc[$pc->id]) ? (int) $motorByPc[$pc->id]->cnt : 0;

                    return [
                        'id'              => $pc->id,
                        'coverage_id'     => $pc->coverage_id,
                        'coverage_name'   => $pc->coverage?->s_ScreenName ?? $pc->coverage?->s_CoverageName ?? $pc->coverage?->s_CoverageCode ?? '',
                        'coverage_code'   => $coverageCode,
                        'risk_address_id' => $pc->risk_address_id,
                        'action_id'       => $pc->action_id,
                        'term_id'         => $pc->term_id,
                        'coverage_value'  => (string) $totalCv,
                        'rate'            => '0',
                        'calculated_value'=> (string) $totalCalc,
                        'motor_count'     => $motorCount,
                        'subcoverages'    => $subs,
                        'extensions'      => $extensions,
                        'specified_items' => $specifiedItems,
                        'fidelity_data'   => $fidelityData,
                        'theft_questions' => $theftData,
                        'property_business_being' => $pc->property_business_being ?? '',
                        'burglar_alarm_warranty' => $pc->burglar_alarm_warranty ?? '',
                        // "Benefits for the circumstances" lives in
                        // policy_coverage_notes.benefits_note (V1 parity), not the
                        // non-existent policy_coverages.stated_benefits. Return it
                        // under the `stated_benefits` key the wizard field binds to,
                        // so edit-load, save, quote and doc all use the same source.
                        'stated_benefits' => $note?->benefits_note ?? '',
                        'memoranda_warranty' => $note?->memoranda_warranty ?? '',
                        'cash_warranty' => $note?->cash_warranty ?? '',
                        'notes'           => $note?->note ?? '',
                        'publicliability_date' => $pc->publicliability_date ?? '',
                        // Cancelled-state marker so the wizard can render the
                        // Reinstate button instead of Cancel.
                        'deleted_at'      => $pc->deleted_at,
                    ];
                })
                // Deduplicate: for the same (coverage_id, risk_address_id) pair,
                // drop rows that are empty (no subcoverages, zero value) when
                // non-empty rows exist for the same pair. This cleans up duplicate
                // rows created by old bugs without touching the database.
                ->pipe(function ($col) {
                    $grouped = $col->groupBy(fn($c) => $c['coverage_id'] . '_' . ($c['risk_address_id'] ?? 'null'));
                    return $grouped->flatMap(function ($group) {
                        if ($group->count() === 1) return $group->values();
                        // Keep rows that have real data; drop zero/empty duplicates
                        $withData = $group->filter(
                            fn($c) => !empty($c['subcoverages']) || (float)($c['coverage_value'] ?? 0) > 0
                        );
                        if ($withData->isNotEmpty()) return $withData->values();
                        // All empty — keep only the most recent one
                        return collect([$group->sortByDesc('id')->first()]);
                    })->values();
                });

            // Parse source of income and employment details from JSON
            // Note: $profile->source_of_income is already JSON-decoded by the model accessor
            $sourceOfIncome = null;
            $employment = [];
            if ($profile && !empty($profile->source_of_income)) {
                $decoded = $profile->source_of_income;
                // The accessor may return a decoded object/array or a string
                // If it's an object, convert to array
                if (is_object($decoded)) {
                    $decoded = json_decode(json_encode($decoded), true);
                }
                // If decoded is an array with a key, extract source and employment
                if (is_array($decoded) && !empty($decoded)) {
                    // Array form: ['employment' => {...}], ['business' => {...}], etc.
                    $sourceOfIncome = array_key_first($decoded);
                    $employment = $decoded[$sourceOfIncome] ?? [];
                } else {
                    // String form: just the source like 'unemployed', 'pensioner_retired'
                    $sourceOfIncome = is_string($decoded) ? $decoded : null;
                }
            }

            // DOM/COM (7 & 8): the edited action's effective_from / effective_to
            // are the source of truth for the Start/Expiry shown on Edit Policy,
            // and the billing frequency is derived from that span so the form
            // header, the dates and the frequency all agree with the action being
            // edited (e.g. a monthly ANNIVERSARY-RENEW shows its 1-month period
            // and MONTHLY, not the policy's stale annual term). Non-DOM/COM
            // products and actions without an effective range fall back to the
            // policy/term dates and the stored frequency.
            //
            // Engineering (16) reads its Start/Expiry from the edited action too:
            // update() already writes the dates back to the action for it (see
            // DATE_SYNC_PRODUCT_IDS), so reading them from the policy row made the
            // Edit Policy page show the same stale period for every action in the
            // EDITING ACTION dropdown. Frequency stays policy-derived — the
            // DOM/COM span→freq mapping does not apply to Engineering.
            $isDomCom      = in_array((int) $policy->product_id, [7, 8], true);
            $actionDatesOn = $isDomCom || (int) $policy->product_id === self::ENGINEERING_PRODUCT_ID;
            $actionStart = ($actionDatesOn && $action && $action->effective_from) ? Carbon::parse($action->effective_from) : null;
            $actionEnd   = ($actionDatesOn && $action && $action->effective_to)   ? Carbon::parse($action->effective_to)   : null;
            $actionFreq  = $this->deriveDomComFreq($policy->product_id, $isDomCom ? $actionStart : null, $isDomCom ? $actionEnd : null);

            return response()->json([
                'data' => [
                    'policy' => [
                        'id'              => $policy->id,
                        'policy_number'   => $policy->policyNumber,
                        'product_id'      => $policy->product_id,
                        'plan_id'         => $policy->plan_id,
                        'agency_id'       => $policy->agency_id,
                        'agent_id'        => $policy->agent_id,
                        'premium'         => $policy->premium,
                        'annual_premium'  => $policy->annual_premium,
                        'first_premium'   => $policy->first_premium,
                        'sum_assured'     => $policy->sum_assured,
                        'premium_freq'    => (string) ($actionFreq ?? $policy->premium_freq ?? '3'),
                        'term_start_date' => $actionStart
                            ? $actionStart->format('Y-m-d')
                            : ($policy->term_start_date
                            ? Carbon::parse($policy->term_start_date)->format('Y-m-d')
                            : ($term?->term_start_date ? Carbon::parse($term->term_start_date)->format('Y-m-d')
                            : ($policy->billingStartDate ? Carbon::parse($policy->billingStartDate)->format('Y-m-d') : null))),
                        'expiry_date'     => $actionEnd
                            ? $actionEnd->format('Y-m-d')
                            : ($policy->expiry_date
                            ? Carbon::parse($policy->expiry_date)->format('Y-m-d')
                            : ($term?->term_end_date ? Carbon::parse($term->term_end_date)->format('Y-m-d')
                            : ($policy->term_end_date ? Carbon::parse($policy->term_end_date)->format('Y-m-d') : null))),
                        'billing_start_date' => $policy->billingStartDate ? Carbon::parse($policy->billingStartDate)->format('Y-m-d') : null,
                        'activated_date'  => $policy->policyActivatedDate ? Carbon::parse($policy->policyActivatedDate)->format('Y-m-d') : null,
                        'gfs_policy_no'   => $policy->gfs_policy_no,
                        'status'          => $policy->status,
                        'is_draft'        => (bool) $policy->is_draft,
                        'note'            => $policy->note,
                    ],
                    'customer' => [
                        'id'             => $customer->id ?? null,
                        // Legacy V1 wrote 'Person' where V2 writes 'Individual'
                        // (same class of drift as gender / maritalstatus below).
                        // The Entity Type toggle compares strictly against the V2
                        // ids, so a raw 'Person' left NEITHER option selected and a
                        // save echoing it back failed the in:Individual,Organisation
                        // rule with a 422. Normalise on the way out only — the
                        // stored value is left as-is until the operator saves.
                        'entity_type'    => ($profile?->entity_type === 'Organisation') ? 'Organisation' : 'Individual',
                        'company_id'     => $profile?->company_id ?? null,
                        'first_name'     => $customer?->firstName ?? '',
                        'middle_name'    => $customer?->middleName ?? '',
                        'last_name'      => $customer?->lastName ?? '',
                        'email'          => $customer?->email ?? '',
                        'cellphone'      => $customer?->cellphone ?? '',
                        // UAT 2026-05-27 (Arjun B3): legacy V1 stored gender as
                        // 0/1 integer and maritalstatus as 1-6 code. The V2
                        // Edit Policy form's SelectField/toggle compares
                        // strictly against V2 string IDs ('Male'/'Female',
                        // 'Single'/'Married'/'Divorced'/'Widowed') so legacy
                        // numeric values render as blank dropdowns. Map them
                        // on the way out so the FE form pre-populates. New
                        // V2-created policies that already store the V2
                        // strings flow through unchanged.
                        'gender'         => $this->mapLegacyGender($profile?->gender),
                        'dob'            => $profile?->dob ? Carbon::parse($profile->dob)->format('Y-m-d') : '',
                        'marital_status' => $this->mapLegacyMaritalStatus($profile?->maritalstatus),
                        'omang'          => $profile?->omang ?? '',
                        'passport'       => $profile?->passport ?? '',
                        'nationality'    => $profile?->nationality ?? '',
                        'driving_license'=> $profile?->drivingLicense ?? '',
                        'license_valid_till' => $profile?->licenseValidTill ? Carbon::parse($profile->licenseValidTill)->format('Y-m-d') : '',
                        'occupation'     => $profile?->occupation ?? '',
                        'income_bracket' => $profile?->incomeBracket ?? '',
                        'tax_id_number'  => $profile?->taxIdNumber ?? '',
                        'employer_name'  => $profile?->employerName ?? '',
                        'employee_no'    => $profile?->employeeNo ?? '',
                        'employer_phone' => $profile?->employerPhone ?? '',
                        'salary_pay_date'=> $profile?->salaryPayDate ?? '',
                        'state'          => $profile?->state ? (int) $profile->state : null,
                        'city'           => $profile?->city  ? (int) $profile->city  : null,
                        'post_address'   => $profile?->post_address ?? $profile?->address ?? '',
                        'source_of_income'  => $sourceOfIncome,
                        'employment'        => $employment,
                        'currently_insured' => $profile?->Insure ?? '',
                        'current_insurer_detail' => $profile?->current_insurer ?? '',
                        'hear_about_alpha'  => $profile?->about_alpha ?? '',
                        'decline_proposal'  => (bool) ($profile?->decline_proposal ?? false),
                        'refused_policy'    => (bool) ($profile?->refused_policy ?? false),
                        'cancel_policy'     => (bool) ($profile?->cancel_policy ?? false),
                        'business_note'     => $profile?->business_note ?? '',
                        'firm_member'       => (bool) ($profile?->firm_member ?? false),
                        'books'             => (bool) ($profile?->books ?? false),
                        'date'              => $profile?->date ? Carbon::parse($profile->date)->format('Y-m-d') : '',
                    ],
                    // UAT 2026-05-27 (Arjun B3): bundle the cities for the
                    // customer's saved state so the FE can hydrate the City
                    // dropdown atomically. Otherwise the form sets
                    // form.city=N immediately while the cities-by-state
                    // fetch races behind it — the dropdown renders blank
                    // until the API returns ~100-300 ms later.
                    'cities_for_saved_state' => $profile?->state
                        ? \AlphaDirect\City::where('state_id', (int) $profile->state)
                            ->select('id', 'name')
                            ->orderBy('name')
                            ->get()
                        : [],
                    'term_id'        => $term?->id,
                    'action_id'      => $action?->id,
                    'risk_addresses' => $riskAddresses,
                    'coverages'      => $coverages,
                    // Canonical Total Premium = the CURRENT annual premium of
                    // the resolved action, recomputed live from its coverage
                    // lines via PolicyAction::sumActionAnnualPremium (the same
                    // per-section basis the V2 Quote / Rate Sheet use). This
                    // replaces the prior `$action->premium ?? annual_premium`
                    // source, which broke for endorsed specialist policies
                    // (CAR/EAR/PAR/Machinery/Marine/etc.): on those, `.premium`
                    // is the pro-rata delta and the stored `.annual_premium`
                    // accumulates across endorsements, so the edit-page total
                    // diverged from the (correct) V2 Quote. Re-deriving here
                    // keeps the edit page == quote sheet. The pro-rata delta is
                    // still surfaced separately as `proRataPremium` below.
                    // Fall back to the old stored figure only when the live
                    // recompute yields 0 (e.g. legacy rows with no line data).
                    'totalPremium'      => $action
                        ? ((float) PolicyAction::sumActionAnnualPremium($action->id, $term?->id, $policyId)
                            ?: (float) ($action->premium ?? $action->annual_premium ?? 0))
                        : 0,
                    'proRataPremium'    => $action && $action->transaction_type === 'ENDORSE'
                        ? (float) ($action->premium ?? 0)
                        : 0,
                    // All actions on the policy so the edit UI can show a switcher.
                    // Ordered newest first; status is kept so the UI can disable
                    // frozen ISSUED actions from being edited.
                    'actions' => PolicyAction::where('policy_id', $policyId)
                        ->orderByDesc('id')
                        ->get(['id', 'transaction_type', 'status', 'effective_from', 'effective_to', 'policy_quote_no', 'transaction_reason'])
                        ->map(fn($a) => [
                            'id'                 => $a->id,
                            'transaction_type'   => $a->transaction_type,
                            'status'             => $a->status,
                            'effective_from'     => $a->effective_from,
                            'effective_to'       => $a->effective_to,
                            'policy_quote_no'    => $a->policy_quote_no,
                            'transaction_reason' => $a->transaction_reason,
                        ])->toArray(),
                ],
            ]);
        } catch (\Illuminate\Database\Eloquent\ModelNotFoundException $e) {
            return response()->json(['error' => 'Policy not found.'], 404);
        } catch (\Exception $e) {
            Log::error('editData error for policy ' . $policyId . ': ' . $e->getMessage());
            return response()->json(['error' => 'Failed to load policy data: ' . $e->getMessage()], 500);
        }
    }

    /**
     * Update a draft policy (status=0) or an active policy with an open QUOTE
     * action — allows editing policy + customer details.
     */
    public function update(Request $request, int $policyId): JsonResponse
    {
        $policy = Policy::findOrFail($policyId);

        $hasQuoteAction = PolicyAction::where('policy_id', $policy->id)
            ->where('status', 'QUOTE')
            ->exists();

        if ((int) $policy->status !== 0 && (int) $policy->is_draft !== 1 && !$hasQuoteAction) {
            return response()->json(['message' => 'Only draft policies can be updated.'], 422);
        }

        // Agent is optional and may be cleared on edit. A blank select can
        // arrive as '', '0', 0 or any non-positive / non-numeric value;
        // normalise all of those to null so the nullable rule applies (an
        // empty string would otherwise fail the integer rule).
        if ($request->has('agent_id')) {
            $agentId = $request->input('agent_id');
            if ($agentId === null || !ctype_digit((string) $agentId) || (int) $agentId <= 0) {
                $request->merge(['agent_id' => null]);
            }
        }

        $validated = $request->validate([
            'product_id'    => 'sometimes|integer|in:7,8,16,17,18,20,22,23,24',
            'plan_id'       => 'sometimes|integer|exists:product_plans,id',
            'agency_id'     => 'sometimes|integer|exists:agencies,id',
            // Agent is optional and may be cleared on edit.
            'agent_id'      => 'sometimes|nullable|integer|exists:users,id',
            'premium_freq'  => 'sometimes|string|in:1,3,5,6',
            // Entity type + company must be editable after issuance so UW can
            // switch a holder between Individual and Organisation (mirrors store()).
            'entity_type'   => 'sometimes|string|in:Individual,Organisation',
            'company_id'    => 'sometimes|nullable|integer',
            'term_start_date' => 'sometimes|date_format:Y-m-d',
            'expiry_date'   => 'sometimes|date_format:Y-m-d',
            'gfs_policy_no' => 'nullable|string|max:50',

            'first_name'    => 'nullable|string|max:100',
            'middle_name'   => 'nullable|string|max:100',
            'last_name'     => 'nullable|string|max:100',
            'email'         => 'nullable|email|max:255',
            'cellphone'     => 'nullable|string|min:8|max:8',
            'gender'        => 'nullable|string|in:Male,Female',
            // Same 18+ rule as store() — minors cannot hold a policy, so
            // corrections through update() must respect it too.
            'dob'           => 'nullable|date_format:Y-m-d|before:18 years ago',
            'marital_status'=> 'nullable|string',
            'omang'         => 'nullable|string|max:25',
            'passport'      => 'nullable|string|max:25',
            'state'         => 'nullable|integer',
            'city'          => 'nullable|integer',
            'post_address'  => 'nullable|string|max:500',
            'source_of_income' => 'nullable|string',
            'employment'    => 'nullable|array',
            'currently_insured' => 'nullable|string',
            'current_insurer_detail' => 'nullable|string|max:500',
            'hear_about_alpha'  => 'nullable|string',
            'decline_proposal'  => 'nullable|boolean',
            'refused_policy'    => 'nullable|boolean',
            'cancel_policy'     => 'nullable|boolean',
            'business_note'     => 'nullable|string|max:1000',
            'firm_member'   => 'nullable|boolean',
            'books'         => 'nullable|boolean',
            'date'          => 'nullable|date_format:Y-m-d',
        ], [
            'dob.before'      => 'The policy holder must be at least 18 years old.',
            'dob.date_format' => 'DOB must be a valid date in YYYY-MM-DD format.',
        ]);

        // Date-order guard. The dates edited here fan out to THREE rows —
        // policies, policy_term and the editable QUOTE action — so an expiry
        // that precedes the start is written to all three and leaves the policy
        // with a backwards period (e.g. 17/08/2025 – 16/08/2025). issuePolicy
        // recomputes policies.expiry_date but copies the action's effective_to
        // verbatim, so issuing repairs only the policy card and the action stays
        // wrong — which is why the detail card and the Policy Actions dropdown
        // disagree on affected policies.
        //
        // Deliberately NOT `after:term_start_date` in the rules array above:
        // Laravel resolves that operand from the REQUEST, so a partial edit
        // sending only expiry_date has nothing to compare against and passes
        // silently. Compare against the stored value instead.
        // Effective product, not the stored one — product_id is itself editable
        // here, and the guard must follow the product the policy is being saved
        // as. (The sync block below reads $policy->product_id directly because
        // by then $policy->update() has already applied the new value.)
        if (in_array((int) ($validated['product_id'] ?? $policy->product_id), self::DATE_SYNC_PRODUCT_IDS, true)
            && !empty($validated['expiry_date'])
        ) {
            $guardStart = $validated['term_start_date'] ?? $policy->term_start_date;
            if (!empty($guardStart)
                && !Carbon::parse($validated['expiry_date'])->greaterThan(Carbon::parse($guardStart))
            ) {
                return response()->json([
                    'message' => 'The policy expiry date must be after the policy start date.',
                    'errors'  => ['expiry_date' => ['The policy expiry date must be after the policy start date.']],
                ], 422);
            }
        }

        // Company-only products (20 / 23 / 24): Annual term. Same rule as
        // store(), resolved against the EFFECTIVE premium_freq — product_id and
        // premium_freq are both `sometimes` here, so each falls back to what is
        // already stored.
        //
        // NO entity_type guard here — see store(). This is the 422 the Edit
        // Policy screen surfaced as "This product is issued to an Organisation
        // only." after the operator picked Individual on Commercial
        // Liabilities: the holder had already been chosen in the UI and the API
        // rejected it. Holder choice is the UI's call now.
        if (self::isCompanyOnlyProduct($validated['product_id'] ?? $policy->product_id)) {
            $companyOnlyErrors = [];
            if ((string) ($validated['premium_freq'] ?? $policy->premium_freq) !== self::ANNUAL_FREQ) {
                $companyOnlyErrors['premium_freq'] = ['Only Annual frequency is allowed on this product.'];
            }
            if ($companyOnlyErrors) {
                return response()->json([
                    'message' => 'Validation failed.',
                    'errors'  => $companyOnlyErrors,
                ], 422);
            }
        }

        try {
            DB::beginTransaction();

            // Track which groups of fields actually changed so the Logs tab
            // entry names them ("customer info, dates") instead of a vague
            // "Draft Policy Updated".
            $changedGroups = [];

            // Update policy fields
            $policyFields = array_intersect_key($validated, array_flip([
                'product_id', 'plan_id', 'agency_id', 'agent_id', 'premium_freq', 'gfs_policy_no',
            ]));
            if (!empty($validated['term_start_date'])) {
                $policyFields['term_start_date'] = Carbon::parse($validated['term_start_date']);
            }
            if (!empty($validated['expiry_date'])) {
                $policyFields['expiry_date'] = Carbon::parse($validated['expiry_date']);
            }

            // DOM/COM (products 7 & 8): when the term dates are amended on edit,
            // the billing frequency must follow the actual term length instead of
            // whatever value the form happened to submit. A 1-month term => MONTHLY
            // (1), a 3-month term => QUARTERLY (5), a 12-month term => ANNUAL (3).
            // Any other span is left untouched (e.g. manual-input terms).
            if (!empty($validated['term_start_date']) || !empty($validated['expiry_date'])) {
                $startForFreq = !empty($validated['term_start_date'])
                    ? $validated['term_start_date']
                    : $policy->term_start_date;
                $endForFreq = !empty($validated['expiry_date'])
                    ? $validated['expiry_date']
                    : $policy->expiry_date;
                $derivedFreq = $this->deriveDomComFreq($policy->product_id, $startForFreq, $endForFreq);
                if ($derivedFreq !== null) {
                    $policyFields['premium_freq'] = $derivedFreq;
                }
            }

            if (!empty($policyFields)) {
                $policy->update($policyFields);
                $changedGroups[] = 'policy details';
            }

            // Update customer
            $customer = $policy->customer;

            // HOLDER SWITCH (Individual <-> Organisation).
            //
            // Customer and CustomerProfile are SHARED rows, not per-policy:
            // store() resolves an Organisation holder with
            // Customer::where('company_id', ...)->first(), so every policy of
            // that company points at the SAME customers row, and profile() is
            // a hasOne on customer_id. Writing the new holder onto that shared
            // row therefore (a) renames the company's customer to a person's
            // name and (b) flips entity_type for every other policy of that
            // company — while THIS policy still displays the company name,
            // which reads to the operator as "the change didn't save".
            //
            // So when the shape actually flips, re-point policies.customer_id
            // at a row of the new shape and let the block below populate it.
            // Only fires on a genuine flip; a same-shape edit is untouched.
            // Needed since Commercial Liabilities (20) started offering both
            // holders again (UW 2026-08-26), but the hazard was never
            // product-specific — the rule applies to every product.
            if ($customer && array_key_exists('entity_type', $validated)) {
                // Legacy rows store 'Person' rather than 'Individual', so
                // compare on "is it the Organisation shape", not on equality.
                $wasOrganisation = optional($customer->profile)->entity_type === 'Organisation';
                $isOrganisation  = $validated['entity_type'] === 'Organisation';

                // Both lookups below must be fed real values: Laravel turns
                // where('col', null) into "col IS NULL", which would adopt an
                // unrelated row (any company-less customer, or any customer
                // with a blank email). Fall back to creating the row instead.
                $companyId = $validated['company_id'] ?? null;
                $email     = $validated['email'] ?? null;
                $cellphone = $validated['cellphone'] ?? null;
                $holder    = null;

                if ($wasOrganisation !== $isOrganisation) {
                    if ($isOrganisation) {
                        // Mirrors store(): one customers row per company. With
                        // no company picked there is nothing to re-point to —
                        // leave the holder alone rather than guess.
                        if ($companyId) {
                            $holder = Customer::where('company_id', $companyId)->first();
                            if (!$holder) {
                                $holder = Customer::create([
                                    'company_id' => $companyId,
                                    'firstName'  => optional(Company::find($companyId))->name ?? 'Organisation',
                                    'lastName'   => '',
                                    'email'      => $email ?? $customer->email,
                                    'cellphone'  => $cellphone ?? $customer->cellphone,
                                ]);
                            }
                        }
                    } else {
                        // Individual: match on email + cellphone as store()
                        // does, but never adopt a company's shared row —
                        // that is the row we are moving off.
                        if ($email && $cellphone) {
                            $holder = Customer::whereNull('company_id')
                                ->where('email', $email)
                                ->where('cellphone', $cellphone)
                                ->first();
                        }
                        if (!$holder) {
                            $holder = Customer::create([
                                'firstName'  => $validated['first_name'] ?? '',
                                'middleName' => $validated['middle_name'] ?? null,
                                'lastName'   => $validated['last_name'] ?? '',
                                'email'      => $email,
                                'cellphone'  => $cellphone,
                            ]);
                        }
                    }

                    if ($holder && (int) $holder->id !== (int) $customer->id) {
                        $policy->update(['customer_id' => $holder->id]);
                        $customer = $holder->fresh();
                        $changedGroups[] = 'policy holder';
                    }
                }
            }

            if ($customer) {
                $customerFields = [];
                if (isset($validated['first_name'])) $customerFields['firstName'] = $validated['first_name'];
                if (isset($validated['middle_name'])) $customerFields['middleName'] = $validated['middle_name'];
                if (isset($validated['last_name'])) $customerFields['lastName'] = $validated['last_name'];
                if (isset($validated['email'])) $customerFields['email'] = $validated['email'];
                if (isset($validated['cellphone'])) $customerFields['cellphone'] = $validated['cellphone'];
                if (!empty($customerFields)) {
                    $customer->update($customerFields);
                    $changedGroups[] = 'customer info';
                }

                // Update profile
                $profileData = [];
                // Persist entity-type switch + selected company (mirrors store()).
                // On Organisation, attach the picked company; on Individual, clear it.
                if (array_key_exists('entity_type', $validated)) {
                    $profileData['entity_type'] = $validated['entity_type'];
                }
                if (array_key_exists('entity_type', $validated) || array_key_exists('company_id', $validated)) {
                    $effectiveEntityType = $validated['entity_type'] ?? optional($customer->profile)->entity_type;
                    $profileData['company_id'] = $effectiveEntityType === 'Organisation'
                        ? ($validated['company_id'] ?? null)
                        : null;
                }
                foreach (['gender', 'omang', 'passport', 'state', 'city', 'post_address'] as $field) {
                    if (array_key_exists($field, $validated)) {
                        $profileData[$field] = $validated[$field];
                    }
                }
                if (array_key_exists('post_address', $validated)) {
                    $profileData['address'] = $validated['post_address'];
                }
                if (array_key_exists('dob', $validated) && $validated['dob']) {
                    $profileData['dob'] = Carbon::parse($validated['dob']);
                }
                if (array_key_exists('marital_status', $validated)) {
                    $profileData['maritalstatus'] = $validated['marital_status'];
                }
                if (array_key_exists('source_of_income', $validated)) {
                    $profileData['source_of_income'] = json_encode($this->buildSourceOfIncome(
                        $validated['source_of_income'] ?? null,
                        $validated['employment'] ?? []
                    ));
                }
                foreach (['currently_insured' => 'Insure', 'current_insurer_detail' => 'current_insurer', 'hear_about_alpha' => 'about_alpha', 'decline_proposal' => 'decline_proposal', 'refused_policy' => 'refused_policy', 'cancel_policy' => 'cancel_policy', 'business_note' => 'business_note'] as $k => $v) {
                    $src = $k;
                    $dst = $v;
                    if (array_key_exists($src, $validated)) {
                        $profileData[$dst] = is_bool($validated[$src]) ? ($validated[$src] ? 1 : 0) : $validated[$src];
                    }
                }
                if (in_array($policy->product_id, [7, 16, 17])) {
                    if (array_key_exists('firm_member', $validated)) $profileData['firm_member'] = $validated['firm_member'] ? 1 : 0;
                    if (array_key_exists('books', $validated)) $profileData['books'] = $validated['books'] ? 1 : 0;
                    if (!empty($validated['date'])) $profileData['date'] = Carbon::parse($validated['date']);
                }

                if (!empty($profileData)) {
                    CustomerProfile::updateOrCreate(
                        ['customer_id' => $customer->id],
                        $profileData
                    );
                    $changedGroups[] = 'company/profile info';
                }
            }

            // Update term dates if changed
            if (!empty($validated['term_start_date']) || !empty($validated['expiry_date'])) {
                $changedGroups[] = 'policy dates';
                $isDateSyncProduct = in_array((int) $policy->product_id, self::DATE_SYNC_PRODUCT_IDS, true);

                // Keep the action's period in step with the policy term. On
                // create the action's effective_from/effective_to are seeded
                // from term_start_date/expiry_date, but a later draft edit
                // (e.g. switching premium_freq from Annual to Monthly, which
                // recomputes expiry_date to the first billing period) only
                // updated the policy + term — leaving the action showing the
                // stale annual range in the "Select Policy Action" dropdown.
                // Only a still-editable QUOTE action is re-synced; issued /
                // renewed / endorsed actions are never touched.
                //
                // Resolved BEFORE the term because the term to write is the one
                // this action belongs to, not simply the newest row.
                $targetAction = PolicyAction::where('policy_id', $policyId)
                    ->where('transaction_type', 'NEWBUSINESS')
                    ->where('status', 'QUOTE')
                    ->whereNull('deleted_at')
                    ->orderBy('id', 'desc')
                    ->first();

                // Specialist products (16/17/18/20/22/23/24): the gate at the
                // top of this method admits a policy whenever ANY action is on
                // QUOTE, so an edit can legitimately be made against a RENEW /
                // REISSUE / REINSTATE quote with no NEWBUSINESS quote left
                // open. Those fell through the NEWBUSINESS-only lookup above
                // and the action kept its stale dates while the policy and term
                // moved. Fall back to the newest QUOTE action of any type.
                // Scoped to these products so DomCom (7/8) behaviour is
                // byte-for-byte unchanged.
                if (!$targetAction && $isDateSyncProduct) {
                    $targetAction = PolicyAction::where('policy_id', $policyId)
                        ->where('status', 'QUOTE')
                        ->whereNull('deleted_at')
                        ->orderBy('id', 'desc')
                        ->first();
                }

                // The term row to update: the one the action points at, so the
                // action and its term can never drift onto different rows.
                // Falls back to the newest term when the action carries no
                // term_id or the row is missing. Same product scoping as above.
                $term = null;
                if ($isDateSyncProduct && !empty($targetAction?->term_id)) {
                    $term = PolicyTerm::where('policy_id', $policyId)
                        ->where('id', $targetAction->term_id)
                        ->first();
                }
                if (!$term) {
                    $term = PolicyTerm::where('policy_id', $policyId)->orderBy('id', 'desc')->first();
                }
                if ($term) {
                    $termUpdate = [];
                    if (!empty($validated['term_start_date'])) $termUpdate['term_start_date'] = Carbon::parse($validated['term_start_date']);
                    if (!empty($validated['expiry_date'])) $termUpdate['term_end_date'] = Carbon::parse($validated['expiry_date']);
                    $term->update($termUpdate);
                }

                if ($targetAction) {
                    $actionUpdate = [];
                    if (!empty($validated['term_start_date'])) $actionUpdate['effective_from'] = Carbon::parse($validated['term_start_date']);
                    if (!empty($validated['expiry_date'])) $actionUpdate['effective_to'] = Carbon::parse($validated['expiry_date']);
                    if (!empty($actionUpdate)) {
                        $targetAction->update($actionUpdate);
                    }
                }
            }

            // Only log when something actually changed, and name what changed
            // — so the Logs tab shows "Policy edited: customer info, dates"
            // instead of a row that fires on every save with no detail.
            if (!empty($changedGroups)) {
                activity('Policy')
                    ->performedOn($policy)
                    ->causedBy(auth()->user())
                    ->log('Policy edited: ' . implode(', ', $changedGroups));
            }

            DB::commit();

            return response()->json([
                'data' => [
                    'policy_id'     => $policy->id,
                    'policy_number' => $policy->policyNumber,
                    'status'        => 'updated',
                ],
                'message' => 'Draft policy updated successfully.',
            ]);

        } catch (\Exception $e) {
            DB::rollBack();
            Log::error('Draft policy update failed: ' . $e->getMessage(), ['trace' => $e->getTraceAsString()]);
            return response()->json([
                'message' => 'Failed to update draft policy.',
                'error'   => config('app.debug') ? $e->getMessage() : 'Internal server error',
            ], 500);
        }
    }

    /**
     * Derive the DOM/COM (products 7 & 8) billing frequency code from a policy
     * term span — the term length is the single source of truth. The span comes
     * from the edited action's effective_from / effective_to dates (or the
     * policy term when an action range is absent): a 1-month term is MONTHLY
     * (1), 3 months is QUARTERLY (5), 12 months is ANNUAL (3).
     *
     * Returns null for any other span — or for a non-DOM/COM product — so the
     * caller keeps the stored frequency untouched. Expiry is stored inclusive
     * (term_start + N months − 1 day), so the day is added back before measuring.
     */
    private function deriveDomComFreq($productId, $start, $end): ?string
    {
        if (!in_array((int) $productId, [7, 8], true) || empty($start) || empty($end)) {
            return null;
        }

        $start = $start instanceof Carbon ? $start : Carbon::parse($start);
        $end   = $end instanceof Carbon ? $end : Carbon::parse($end);
        if (!$end->greaterThan($start)) {
            return null;
        }

        $months = (int) $start->diffInMonths($end->copy()->addDay());
        if ($months === 1) {
            return '1';   // MONTHLY
        }
        if ($months === 3) {
            return '5';   // QUARTERLY
        }
        if ($months === 12) {
            return '3';   // ANNUAL
        }
        return null;
    }

    /**
     * Step 2: Add a risk address to a policy.
     */
    public function addRiskAddress(Request $request, int $policyId): JsonResponse
    {
        $policy = Policy::findOrFail($policyId);

        $validated = $request->validate([
            'term_id'          => 'required|integer',
            'action_id'        => 'required|integer',
            'address_name'     => 'required|string|max:255',
            'physical_address' => 'required|string|max:500',
            'lat'              => 'nullable|numeric',
            'lng'              => 'nullable|numeric',
            'risk_state'       => 'required|integer',
            'risk_city'        => 'required|integer',
            'extension'        => 'nullable|string|max:255',
            'occupation'       => 'nullable|string|max:255',
            'town_class'       => 'nullable|string|max:50',
            'risk_class'       => 'nullable|string|max:50',
            'iso_rcv'          => 'nullable|numeric',
            'year_built'       => 'nullable|string|max:10',
            'area'             => 'nullable|string|max:100',
            'structure_type'   => 'nullable|string|max:100',
            'const_type'       => 'required|string|max:100',
            'distance_to_water'  => 'nullable|string|max:50',
            'distance_to_fire'   => 'nullable|string|max:50',
            'distance_to_hydrant'=> 'nullable|string|max:50',
            'usage'            => 'nullable|string|max:100',
            'occupancy_type'   => 'nullable|string|max:100',
            'central_fire'     => 'nullable|boolean',
            'central_burglar'  => 'nullable|boolean',
            'gated_community'  => 'nullable|boolean',
            'automatic'        => 'nullable|boolean',
            'company_id'       => 'nullable|integer',
        ]);

        // Risk addresses are per-action rows. The action decides the term, so
        // derive term_id from it — the caller's term_id is only a fallback for
        // legacy actions with no term stamped. Prevents a row landing on the
        // latest term while its action belongs to an earlier one.
        $targetAction = PolicyAction::where('policy_id', $policy->id)
            ->where('id', $validated['action_id'])
            ->first(['id', 'term_id']);
        if (!$targetAction) {
            return response()->json(['error' => 'Selected policy action does not belong to this policy.'], 422);
        }

        // Only a QUOTE action accepts risk-address changes.
        if ($locked = $this->ensureActionEditable((int) $targetAction->id)) {
            return $locked;
        }

        $riskAddress = RiskAddress::create([
            'policy_id'       => $policy->id,
            'customer_id'     => $policy->customer_id,
            'term_id'         => $targetAction->term_id ?: $validated['term_id'],
            'action_id'       => $targetAction->id,
            'address_name'    => $validated['address_name'],
            'physical_address'=> $validated['physical_address'],
            'lat'             => $validated['lat'] ?? null,
            'lng'             => $validated['lng'] ?? null,
            'risk_state'      => $validated['risk_state'],
            'risk_city'       => $validated['risk_city'],
            'extension'       => $validated['extension'] ?? null,
            'occupation'      => $validated['occupation'] ?? null,
            'town_class'      => $validated['town_class'] ?? null,
            'risk_class'      => $validated['risk_class'] ?? null,
            'iso_rcv'         => $validated['iso_rcv'] ?? null,
            'year_built'      => $validated['year_built'] ?? null,
            'area'            => $validated['area'] ?? null,
            'structure_type'  => $validated['structure_type'] ?? null,
            'const_type'      => $validated['const_type'],
            'distance_to_water'  => $validated['distance_to_water'] ?? null,
            'distance_to_fire'   => $validated['distance_to_fire'] ?? null,
            'distance_to_hydrant'=> $validated['distance_to_hydrant'] ?? null,
            'usage'           => $validated['usage'] ?? null,
            'occupancy_type'  => $validated['occupancy_type'] ?? null,
            'central_fire'    => ($validated['central_fire'] ?? false) ? 1 : 0,
            'central_burglar' => ($validated['central_burglar'] ?? false) ? 1 : 0,
            'gated_community' => ($validated['gated_community'] ?? false) ? 1 : 0,
            'automatic'       => ($validated['automatic'] ?? false) ? 1 : 0,
            'company_id'      => $validated['company_id'] ?? null,
        ]);

        activity('Risk Address')
            ->performedOn($policy)
            ->causedBy(auth()->user())
            ->log('Risk Address Added');

        return response()->json([
            'data'    => $riskAddress,
            'message' => 'Risk address added successfully.',
        ], 201);
    }

    /**
     * Update a risk address.
     */
    public function updateRiskAddress(Request $request, int $policyId, int $riskAddressId): JsonResponse
    {
        $policy = Policy::findOrFail($policyId);

        $riskAddress = RiskAddress::where('policy_id', $policyId)
            ->findOrFail($riskAddressId);

        // Edits are action-scoped: each action carries its own copy of the
        // address, so when the caller says which action it is editing the row
        // must belong to that action. A stale list (tab left open, action
        // switched underneath) can therefore never rewrite another
        // transaction's address. Answered as 409 rather than letting the
        // lookup 404 so the wizard can show why. Omitting action_id keeps the
        // legacy id-only behaviour.
        $requestedActionId = (int) $request->input('action_id');
        if ($requestedActionId && (int) $riskAddress->action_id && $requestedActionId !== (int) $riskAddress->action_id) {
            return response()->json([
                'error' => "This risk address belongs to transaction #{$riskAddress->action_id}, not the one you have open (#{$requestedActionId}). Reload the policy on that transaction to edit it.",
                'action_id' => $riskAddress->action_id,
            ], 409);
        }

        // Only a QUOTE action accepts risk-address changes — keyed on the row's
        // OWN action, so the lock holds no matter what the caller claims.
        if ($locked = $this->ensureRiskAddressEditable($riskAddress)) {
            return $locked;
        }

        $validated = $request->validate([
            // Action-wise scope: risk_address rows are replicated per action,
            // so the wizard sends the action it has open. Optional (legacy
            // callers omit it) but validated when present — see the guard below.
            'action_id'        => 'nullable|integer',
            'address_name'     => 'sometimes|string|max:255',
            'physical_address' => 'sometimes|string|max:500',
            'lat'              => 'nullable|numeric',
            'lng'              => 'nullable|numeric',
            'risk_state'       => 'sometimes|integer',
            'risk_city'        => 'sometimes|integer',
            'extension'        => 'nullable|string|max:255',
            'occupation'       => 'nullable|string|max:255',
            'town_class'       => 'nullable|string|max:50',
            'risk_class'       => 'nullable|string|max:50',
            'iso_rcv'          => 'nullable|numeric',
            'year_built'       => 'nullable|string|max:10',
            'area'             => 'nullable|string|max:100',
            'structure_type'   => 'nullable|string|max:100',
            'const_type'       => 'sometimes|string|max:100',
            'distance_to_water'  => 'nullable|string|max:50',
            'distance_to_fire'   => 'nullable|string|max:50',
            'distance_to_hydrant'=> 'nullable|string|max:50',
            'usage'            => 'nullable|string|max:100',
            'occupancy_type'   => 'nullable|string|max:100',
            'central_fire'     => 'nullable|boolean',
            'central_burglar'  => 'nullable|boolean',
            'gated_community'  => 'nullable|boolean',
            'automatic'        => 'nullable|boolean',
            'company_id'       => 'nullable|integer',
        ]);

        // action_id is a scope, not an editable column — never re-stamp the
        // row's own action from an edit (that would move the address between
        // transactions).
        unset($validated['action_id']);

        // Identity of the row BEFORE the edit — used to find this same address's
        // copies on the policy's other actions (see syncRiskAddressCopies). Read
        // it now because the update itself may rename the address.
        $originalIdentity = [
            'address_name'     => $riskAddress->address_name,
            'physical_address' => $riskAddress->physical_address,
        ];

        // Convert booleans
        if (isset($validated['central_fire'])) $validated['central_fire'] = $validated['central_fire'] ? 1 : 0;
        if (isset($validated['central_burglar'])) $validated['central_burglar'] = $validated['central_burglar'] ? 1 : 0;
        if (isset($validated['gated_community'])) $validated['gated_community'] = $validated['gated_community'] ? 1 : 0;
        if (isset($validated['automatic'])) $validated['automatic'] = $validated['automatic'] ? 1 : 0;

        $riskAddress->update($validated);
        $changedFields = array_keys(array_diff_key($riskAddress->getChanges(), ['updated_at' => null]));

        // Keep the same address's per-action copies in sync (the reason a V2
        // Quote could still print the OLD construction type after an edit).
        [$syncedIds, $lockedIds] = $this->syncRiskAddressCopies($riskAddress, $originalIdentity, $validated, $request);

        // Log WHICH row on WHICH action changed and which columns moved —
        // "Risk Address Updated" alone can't be traced back to a transaction.
        // Field names only (no values): physical address / lat-lng are
        // identifiable data and don't belong in the activity log.
        activity('Risk Address')
            ->performedOn($policy)
            ->causedBy(auth()->user())
            ->withProperties([
                'risk_address_id' => $riskAddress->id,
                'action_id'       => $riskAddress->action_id,
                'fields'          => $changedFields,
                'synced_copies'   => $syncedIds,
                'locked_copies'   => $lockedIds,
            ])
            ->log('Risk Address Updated');

        // Tell the operator what the edit reached. The locked count is the
        // answer to "I changed the Construction Type but the V2 Quote still
        // prints the old one" — those transactions are already issued, so their
        // printed detail only changes through a new endorsement.
        $message = 'Risk address updated successfully.';
        if ($syncedIds) {
            $message .= ' ' . count($syncedIds) . ' matching copy/copies on other open transactions updated too.';
        }
        if ($lockedIds) {
            $message .= ' ' . count($lockedIds) . ' issued transaction(s) keep their existing detail — raise an endorsement to change what they print.';
        }

        return response()->json([
            'data'          => $riskAddress->fresh(),
            'synced_copies' => $syncedIds,
            'locked_copies' => $lockedIds,
            'message'       => $message,
        ]);
    }

    /**
     * Apply the same edit to this address's copies on the policy's OTHER actions.
     *
     * risk_address rows are versioned per policy_action: every endorsement /
     * renewal replicates them and re-points policy_coverages.risk_address_id at
     * the new action's copy (PolicyAction::replicateRecords, matched by
     * address_name). The V2 Quote / Policy Schedule render
     * $coverages->riskAddress — i.e. the copy belonging to the action being
     * printed. Editing one copy therefore left every other action still holding
     * the old values, and a quote printed on any other transaction kept showing
     * the stale Construction Type / usage / distances. Nothing here is
     * premium-bearing — these are descriptive risk attributes, so correcting one
     * corrects the address everywhere it is quoted.
     *
     * Match is on the PRE-edit identity (address_name, falling back to
     * physical_address) — the same key replication uses — so a rename lands on
     * every copy as well, which keeps the next replication's name match working.
     *
     * Pass sync_all_actions=false to keep the legacy single-row behaviour.
     *
     * @param  array<string,mixed>  $identity  pre-edit address_name / physical_address
     * @param  array<string,mixed>  $attrs     the validated columns just written
     * @return array{0: array<int,int>, 1: array<int,int>}  [ids synced, ids left
     *         alone because their transaction is frozen]
     */
    private function syncRiskAddressCopies(RiskAddress $edited, array $identity, array $attrs, Request $request): array
    {
        if (!$request->boolean('sync_all_actions', true) || empty($attrs)) {
            return [[], []];
        }

        $name = trim((string) ($identity['address_name'] ?? ''));
        $phys = trim((string) ($identity['physical_address'] ?? ''));
        [$column, $value] = $name !== '' ? ['address_name', $name] : ['physical_address', $phys];
        if ($value === '') {
            return [[], []];
        }

        // Live copies only — a soft-deleted row is a cancelled snapshot and the
        // riskAddress relation never renders it.
        //
        // Copies sitting on a non-QUOTE action are skipped: only QUOTE actions
        // may have their risk address changed, so an ISSUED / APPROVED
        // transaction keeps the detail it was rated and printed on. Legacy rows
        // with no action / no status stay in scope (same rule as
        // ensureActionEditable).
        $copies = RiskAddress::where('policy_id', $edited->policy_id)
            ->where('id', '!=', $edited->id)
            ->whereRaw('LOWER(TRIM(' . $column . ')) = ?', [mb_strtolower($value)])
            ->get();

        $syncedIds = $lockedIds = [];
        foreach ($copies as $copy) {
            if ($this->ensureRiskAddressEditable($copy) !== null) {
                $lockedIds[] = (int) $copy->id;
                continue;
            }
            // Per-row update (not a bulk query) so each copy keeps its own audit
            // trail — risk_address is Auditable.
            $copy->update($attrs);
            $syncedIds[] = (int) $copy->id;
        }

        if ($syncedIds || $lockedIds) {
            \Log::info('updateRiskAddress: synced address copies on other actions', [
                'policy_id'         => $edited->policy_id,
                'edited_id'         => $edited->id,
                'edited_action'     => $edited->action_id,
                'matched_on'        => $column,
                'synced_ids'        => $syncedIds,
                'skipped_locked_ids'=> $lockedIds,
                'fields'            => array_keys($attrs),
            ]);
        }

        return [$syncedIds, $lockedIds];
    }

    /**
     * Delete a risk address.
     */
    public function deleteRiskAddress(int $policyId, int $riskAddressId): JsonResponse
    {
        $policy = Policy::findOrFail($policyId);

        // Same action scoping as updateRiskAddress — cancel only the row that
        // belongs to the action the operator is viewing.
        $requestedActionId = request()->input('action_id');
        $riskAddress = RiskAddress::where('policy_id', $policyId)
            ->when($requestedActionId, fn($q) => $q->where('action_id', $requestedActionId))
            ->findOrFail($riskAddressId);

        // A cancel is an edit too: only a QUOTE action may be changed.
        if ($locked = $this->ensureRiskAddressEditable($riskAddress)) {
            return $locked;
        }

        // CANCEL semantics — soft-delete the risk address AND every coverage
        // under it (and every child of those coverages: detail, motor, ext,
        // specified items). Stamp endors_flag + previousActionIdCov so Rate's
        // pro-rata sum picks up each cancelled coverage's full premium as a
        // negative delta (refund). Operator can reinstate later.
        $coverageIds = PolicyCoverage::where('risk_address_id', $riskAddressId)
            ->whereNull('deleted_at')->pluck('id', 'action_id');
        $allCoverageIds = $coverageIds->values()->all();

        // Track all action_ids touched so we can recompute their totals once
        // at the end (a risk address typically has all coverages on the same
        // action, but defence-in-depth for legacy data drift).
        $actionIds = PolicyCoverage::where('risk_address_id', $riskAddressId)
            ->whereNull('deleted_at')->pluck('action_id')->unique()->filter()->all();

        if (!empty($allCoverageIds)) {
            // Stamp wizard markers on every premium-bearing child row of
            // the cancelled coverages, grouped by their action_id.
            foreach ($actionIds as $aid) {
                $covIdsForAction = PolicyCoverage::where('risk_address_id', $riskAddressId)
                    ->where('action_id', $aid)->whereNull('deleted_at')->pluck('id')->all();
                if (empty($covIdsForAction)) continue;
                DB::table('policy_coverage_detail')->whereIn('policy_coverage_id', $covIdsForAction)
                    ->whereNull('deleted_at')
                    ->update(['endors_flag' => 1, 'previousActionIdCov' => $aid, 'updated_at' => now()]);
                DB::table('motor')->whereIn('policy_coverage_id', $covIdsForAction)
                    ->whereNull('deleted_at')
                    ->update(['endors_flag' => 1, 'previousActionIdCov' => $aid, 'updated_at' => now()]);
                if (\Schema::hasColumn('policy_extention_detail', 'endors_flag')) {
                    DB::table('policy_extention_detail')->whereIn('policy_coverage_id', $covIdsForAction)
                        ->whereNull('deleted_at')
                        ->update(['endors_flag' => 1, 'previousActionIdCov' => $aid, 'updated_at' => now()]);
                }
                if (\Schema::hasColumn('policy_specified_items', 'endors_flag')) {
                    DB::table('policy_specified_items')->whereIn('policy_coverage_id', $covIdsForAction)
                        ->whereNull('deleted_at')
                        ->update(['endors_flag' => '1', 'previousActionIdCov' => $aid, 'updated_at' => now()]);
                }
            }

            // Soft-delete every child row.
            DB::table('policy_coverage_detail')->whereIn('policy_coverage_id', $allCoverageIds)
                ->whereNull('deleted_at')->update(['deleted_at' => now()]);
            DB::table('motor')->whereIn('policy_coverage_id', $allCoverageIds)
                ->whereNull('deleted_at')->update(['deleted_at' => now()]);
            DB::table('policy_extention_detail')->whereIn('policy_coverage_id', $allCoverageIds)
                ->whereNull('deleted_at')->update(['deleted_at' => now()]);
            DB::table('policy_specified_items')->whereIn('policy_coverage_id', $allCoverageIds)
                ->whereNull('deleted_at')->update(['deleted_at' => now()]);

            // Soft-delete the parent coverage rows.
            PolicyCoverage::where('risk_address_id', $riskAddressId)->whereNull('deleted_at')->delete();
        }

        // Soft-delete the risk address itself.
        $riskAddress->delete();

        // Recompute action totals so Rate banner / Total Coverage Premium /
        // V2 Quote / wizard footer all reflect the cancellation immediately.
        foreach ($actionIds as $aid) {
            if (self::actionRepriceable($aid)) self::recomputeActionTotals($policyId, (int) $aid);
        }

        activity('Risk Address')
            ->performedOn($policy)
            ->causedBy(auth()->user())
            ->log('Risk Address Cancelled');

        // Single high-level entry on the audits table so the Logs tab shows
        // "Risk Address Cancelled" labelled clearly. The bulk DB::table
        // updates above intentionally bypass per-row audit to keep write
        // load proportional to the operator action, not the row count.
        $this->logCustomAudit(
            $policyId,
            'Risk Address Cancelled',
            ['risk_address_id' => $riskAddressId, 'address_name' => $riskAddress->address_name, 'coverages_cancelled' => count($allCoverageIds ?? [])],
            null,
            \AlphaDirect\Models\RiskAddress::class,
            $riskAddressId,
        );

        return response()->json([
            'message' => 'Risk address cancelled successfully.',
        ]);
    }

    /**
     * Reinstate a cancelled risk address — restores the address row plus
     * every coverage and child row that was soft-deleted alongside it.
     * Stamps endors_flag + previousActionIdCov so Rate's pro-rata picks
     * the reinstate up: same-action cancel-then-reinstate gives delta 0
     * (no charge), different-action reinstate gives delta = +full value
     * (charge), because writeLineLevelProRata compares against the
     * immediately-previous action.
     */
    public function reinstateRiskAddress(int $policyId, int $riskAddressId): JsonResponse
    {
        $policy = Policy::findOrFail($policyId);
        $riskAddress = RiskAddress::onlyTrashed()
            ->where('policy_id', $policyId)
            ->where('id', $riskAddressId)
            ->first();
        if (!$riskAddress) {
            return response()->json(['error' => 'Risk address is not cancelled — nothing to reinstate.'], 422);
        }

        // Un-cancelling is a change like any other: only a QUOTE action.
        // Without this, cancel was gated but reinstate wasn't — so an ISSUED
        // transaction could still have its risk address (and every coverage
        // under it) brought back.
        if ($locked = $this->ensureRiskAddressEditable($riskAddress)) {
            return $locked;
        }

        $riskAddress->restore();

        // Restore coverages + children that share this risk_address_id and
        // were soft-deleted (we only reactivate rows that are currently
        // trashed — don't touch independently-cancelled rows).
        $trashedCoverages = PolicyCoverage::onlyTrashed()
            ->where('risk_address_id', $riskAddressId)->get(['id', 'action_id']);
        $allCoverageIds = $trashedCoverages->pluck('id')->all();
        $actionIds = $trashedCoverages->pluck('action_id')->unique()->filter()->all();

        if (!empty($allCoverageIds)) {
            DB::table('policy_coverage_detail')->whereIn('policy_coverage_id', $allCoverageIds)
                ->whereNotNull('deleted_at')->update(['deleted_at' => null]);
            DB::table('motor')->whereIn('policy_coverage_id', $allCoverageIds)
                ->whereNotNull('deleted_at')->update(['deleted_at' => null]);
            DB::table('policy_extention_detail')->whereIn('policy_coverage_id', $allCoverageIds)
                ->whereNotNull('deleted_at')->update(['deleted_at' => null]);
            DB::table('policy_specified_items')->whereIn('policy_coverage_id', $allCoverageIds)
                ->whereNotNull('deleted_at')->update(['deleted_at' => null]);
            PolicyCoverage::onlyTrashed()->whereIn('id', $allCoverageIds)->restore();

            // Stamp wizard markers per action so Rate sees the reinstate.
            foreach ($actionIds as $aid) {
                $covIdsForAction = PolicyCoverage::where('risk_address_id', $riskAddressId)
                    ->where('action_id', $aid)->pluck('id')->all();
                if (empty($covIdsForAction)) continue;
                DB::table('policy_coverage_detail')->whereIn('policy_coverage_id', $covIdsForAction)
                    ->update(['endors_flag' => 1, 'previousActionIdCov' => $aid, 'updated_at' => now()]);
                DB::table('motor')->whereIn('policy_coverage_id', $covIdsForAction)
                    ->update(['endors_flag' => 1, 'previousActionIdCov' => $aid, 'updated_at' => now()]);
                if (\Schema::hasColumn('policy_extention_detail', 'endors_flag')) {
                    DB::table('policy_extention_detail')->whereIn('policy_coverage_id', $covIdsForAction)
                        ->update(['endors_flag' => 1, 'previousActionIdCov' => $aid, 'updated_at' => now()]);
                }
                if (\Schema::hasColumn('policy_specified_items', 'endors_flag')) {
                    DB::table('policy_specified_items')->whereIn('policy_coverage_id', $covIdsForAction)
                        ->update(['endors_flag' => '1', 'previousActionIdCov' => $aid, 'updated_at' => now()]);
                }
            }

            foreach ($actionIds as $aid) {
                if (self::actionRepriceable($aid)) self::recomputeActionTotals($policyId, (int) $aid);
            }
        }

        activity('Risk Address')
            ->performedOn($policy)
            ->causedBy(auth()->user())
            ->log('Risk Address Reinstated');

        // Single Logs-tab entry — pairs with the cancel entry above.
        $this->logCustomAudit(
            $policyId,
            'Risk Address Reinstated',
            ['risk_address_id' => $riskAddressId, 'address_name' => $riskAddress->address_name, 'coverages_reinstated' => count($allCoverageIds ?? [])],
            null,
            \AlphaDirect\Models\RiskAddress::class,
            $riskAddressId,
        );

        return response()->json(['message' => 'Risk address reinstated successfully.']);
    }

    /**
     * Clone a coverage master immediately (for subcoverage duplication via "+")
     * Returns the newly cloned coverage_id to be used in policy_coverage_detail
     */
    public function cloneCoverageMaster(Request $request, int $policyId, int $masterId): JsonResponse
    {
        try {
            $policy = Policy::findOrFail($policyId);
            $master = CoverageMaster::findOrFail($masterId);

            // Clone the master coverage (same as GraphiteBWV8 repeateSubCoverage)
            $clonedMaster = $master->replicate();
            $clonedMaster->policy_id = null;
            $clonedMaster->save();

            return response()->json([
                'cloned_id' => $clonedMaster->id,
                'message' => 'Coverage cloned successfully.',
            ], 200);
        } catch (\Illuminate\Database\Eloquent\ModelNotFoundException $e) {
            \Log::error('PolicyCreateController::cloneCoverageMaster - Model not found', [
                'policyId' => $policyId,
                'masterId' => $masterId,
                'error' => $e->getMessage(),
            ]);
            return response()->json([
                'message' => 'Coverage or policy not found.',
                'error' => 'MODEL_NOT_FOUND',
            ], 404);
        } catch (\Exception $e) {
            \Log::error('PolicyCreateController::cloneCoverageMaster - Error', [
                'policyId' => $policyId,
                'masterId' => $masterId,
                'error' => $e->getMessage(),
                'trace' => $e->getTraceAsString(),
            ]);
            return response()->json([
                'message' => 'Failed to clone coverage.',
                'error' => $e->getMessage(),
            ], 500);
        }
    }

    // COM/DOM products (7/8). For these the coverage-wise "Main" total-premium
    // row is never kept in policy_coverage_detail — premium comes only from the
    // per-row (sub-coverage) detail rows.
    private const DOM_COM_PRODUCT_IDS = [7, 8];

    /**
     * Engineering. Its Edit Policy Start/Expiry are read from the edited
     * policy_actions row (effective_from / effective_to) rather than the policy
     * row — see editData(). Scoped to this single id on purpose: the other
     * DATE_SYNC_PRODUCT_IDS keep their existing policy-level date display.
     */
    private const ENGINEERING_PRODUCT_ID = 16;

    /**
     * Products whose Edit Policy date changes must fan out to policy_term and
     * the editable QUOTE action — Engineering (16), Commercial Specialist (17),
     * Domestic Engineering (18), Commercial Liabilities (20), Marine (22),
     * Guarantee (23), Miscellaneous (24).
     *
     * update() already synced both rows for EVERY product, so this list does
     * NOT gate the sync itself — removing DomCom from it would be a regression.
     * It scopes only the parts that CHANGE existing behaviour: the fallback to a
     * non-NEWBUSINESS QUOTE action, picking the term the action points at, and
     * the expiry-after-start guard. DomCom (7/8) therefore keeps its exact
     * current behaviour, per "existing functionality for other products
     * remains unaffected".
     *
     * NOTE: deliberately not SPECIALIST_PRODUCT_IDS, which also carries 19 —
     * that product is out of scope for this change.
     */
    private const DATE_SYNC_PRODUCT_IDS = [16, 17, 18, 20, 22, 23, 24];

    private function isDomComProduct($policy): bool
    {
        return in_array((int) ($policy->product_id ?? 0), self::DOM_COM_PRODUCT_IDS, true);
    }

    /**
     * Coverage codes whose premium is stored in a DEDICATED table, not in
     * policy_coverage_detail — the specialist schedules (SPECIALIST_PREMIUM_TABLES)
     * plus Fidelity Guarantee (policy_coverages_data).
     *
     * These must never get a coverage-wise "Main" total-premium row. Writing one
     * puts the same premium in two buckets of the annual recipe — the Main row is
     * summed by $totalPremium (policy_coverage_detail) while the schedule row is
     * summed by $specialistPremium — so the Rate banner reports exactly DOUBLE.
     * That is the same reason motor coverages are excluded ($motorIsolatedIds:
     * premium lives in motor/motor_traders) and COM/DOM are excluded
     * (isDomComProduct). Specialist covers were simply never added to the list,
     * so every product in SPECIALIST_PRODUCT_IDS (16/17/18/19/20/22/23/24) rated
     * at twice its premium.
     *
     * Mirrors $hideMainFieldsCodes in addCoverage — the wizard hides the
     * Sum Insured / Rate / Premium trio for exactly these codes, because the
     * schedule page owns their pricing. Kept as a SEPARATE const because that
     * local list also drives request VALIDATION (coverage_value required vs
     * nullable) and the two concerns must be free to diverge.
     */
    private const OWN_PREMIUM_TABLE_COVERAGE_CODES = [
        'MEDICAMALPRACTICEINSURANCE', 'PROFESSIONALINDEMNITY', 'TRAVELINSURANCE',
        'CONTRACTORSALLRISKS', 'PLANTALLRISKS', 'ERECTIONALLRISKS',
        'DIRECTORSOFFICERSLIABILITY', 'MARINEDIRECTORSOFFICERS', 'MACHINERYBREAKDOWN',
        'MARINEONCEOFFCOVER', 'MARINECARGOONCEOFF', 'MARINEOPENCOVER',
        'FIDELITYGUARANTEE',
        'MEDICALEVACUATION', 'COMMERCIALCRIME', 'ENVIRONMENTALLIABILITY', 'BONDSANDGUARANTEES',
    ];

    /** Does this coverage master store its premium outside policy_coverage_detail? */
    private static function isOwnPremiumTableCoverage($coverageId): bool
    {
        if (empty($coverageId)) return false;
        $code = strtoupper((string) DB::table('tb_cvgpccoverages')
            ->where('id', $coverageId)
            ->value('s_CoverageCode'));
        return $code !== '' && in_array($code, self::OWN_PREMIUM_TABLE_COVERAGE_CODES, true);
    }

    /**
     * Total of the stale "Main" rows that must NOT count toward the annual.
     *
     * The write-side guards below stop new ones being created, but policies
     * rated before this fix already carry the duplicate row. Subtracting it at
     * read time makes those policies correct on the next Rate click instead of
     * requiring every coverage to be re-saved first.
     *
     * A Main row is the policy_coverage_detail row keyed on the PARENT
     * coverage_id (same identity deleteMainCoverageDetailRow uses). Genuine
     * sub-coverage rows have a different coverage_id and are left alone.
     */
    private static function sumDuplicateMainPremiumRows($pcIds): float
    {
        if ($pcIds === null || (is_object($pcIds) && method_exists($pcIds, 'isEmpty') && $pcIds->isEmpty()) || (is_array($pcIds) && empty($pcIds))) {
            return 0.0;
        }

        // Only coverages that ACTUALLY have a row in one of the dedicated
        // premium tables. Without this the subtraction would also strip the
        // Main row of a specialist coverage whose schedule was never captured —
        // there the Main row is the only premium on record, not a duplicate,
        // and removing it would understate the policy instead of correcting it.
        $dupPcIds = collect();
        foreach (array_keys(self::SPECIALIST_PREMIUM_TABLES) as $table) {
            try {
                if (!\Schema::hasTable($table)) continue;
                $q = DB::table($table)->whereIn('policy_coverage_id', $pcIds);
                if (in_array('deleted_at', \Schema::getColumnListing($table), true)) {
                    $q->whereNull('deleted_at');
                }
                $dupPcIds = $dupPcIds->merge($q->pluck('policy_coverage_id'));
            } catch (\Throwable $e) {
                \Log::warning("Duplicate-main scan skipped for {$table}: " . $e->getMessage());
            }
        }
        // Fidelity Guarantee's premium lives in policy_coverages_data.
        if (\Schema::hasTable('policy_coverages_data')) {
            $dupPcIds = $dupPcIds->merge(
                DB::table('policy_coverages_data')->whereIn('policyCoverageID', $pcIds)->pluck('policyCoverageID')
            );
        }
        $dupPcIds = $dupPcIds->filter()->unique()->values();
        if ($dupPcIds->isEmpty()) return 0.0;

        return (float) DB::table('policy_coverage_detail as pcd')
            ->join('policy_coverages as pc', 'pc.id', '=', 'pcd.policy_coverage_id')
            ->join('tb_cvgpccoverages as cv', 'cv.id', '=', 'pc.coverage_id')
            ->whereIn('pcd.policy_coverage_id', $dupPcIds)
            ->whereColumn('pcd.coverage_id', 'pc.coverage_id')
            ->whereIn(DB::raw('UPPER(cv.s_CoverageCode)'), self::OWN_PREMIUM_TABLE_COVERAGE_CODES)
            ->whereNull('pcd.deleted_at')
            ->sum('pcd.calculated_value');
    }

    // Soft-delete the coverage-wise "Main" row (the policy_coverage_detail row
    // keyed on the PARENT coverage_id). Used wherever a Main total row must not
    // survive — both the sub-coverage edit path and the COM/DOM no-detail path.
    /**
     * Collapse redundant sub-coverage rows on ONE coverage, keeping the richest
     * copy per sub-coverage. Self-heal for the "premium counted twice" shape.
     *
     * A sub-coverage's identity is (policy_coverage_id, coverage_id) — the key
     * the upsert loops above use (updateOrCreate) and the key the replicator
     * matches on. A second LIVE row on that key is therefore unreachable by the
     * wizard, but every premium recipe sums policy_coverage_detail raw, so it is
     * charged twice: on the Added Coverages card (policy_coverages
     * .calculated_value is re-derived as SUM of live detail rows just below),
     * on the Rate banner (calculatePremium / recomputeActionTotals) and on the
     * V2 Quote Sheet section + Total Premium. UW hit this on a COM quote where
     * Public Liability printed P 666.68 for a P 333.34 cover.
     *
     * A "+ Add another row" line is NOT touched: the wizard clones the master
     * into tb_cvgpccoverages first, so each extra line carries its own
     * coverage_id.
     *
     * The stale copies are soft-deleted with their pro-rata stamps cleared —
     * the pro-rata sums deliberately include deleted rows (that is how a cancel
     * refund is read), so a stamped leftover would make the next Rate refund
     * premium that was never charged.
     */
    private static function collapseDuplicateDetailRows(int $policyCoverageId): void
    {
        $rows = DB::table('policy_coverage_detail')
            ->where('policy_coverage_id', $policyCoverageId)
            ->whereNull('deleted_at')
            ->orderBy('id')
            ->get(['id', 'coverage_id', 'coverage_value', 'calculated_value']);

        if ($rows->count() < 2) return;

        $dropIds = [];
        $winners = [];
        foreach ($rows as $row) {
            $key = (int) ($row->coverage_id ?? 0);
            // No business key to compare on — leave the row alone.
            if ($key === 0) continue;

            $current = $winners[$key] ?? null;
            if (!$current) {
                $winners[$key] = $row;
                continue;
            }
            // Richest wins (premium, then sum insured); ties keep the original,
            // so collapsing can never drop a real premium for an empty twin.
            $calcNew = (float) ($row->calculated_value ?? 0);
            $calcOld = (float) ($current->calculated_value ?? 0);
            $isRicher = $calcNew !== $calcOld
                ? $calcNew > $calcOld
                : (float) ($row->coverage_value ?? 0) > (float) ($current->coverage_value ?? 0);

            if ($isRicher) {
                $dropIds[]     = $current->id;
                $winners[$key] = $row;
            } else {
                $dropIds[] = $row->id;
            }
        }

        if (empty($dropIds)) return;

        $update = ['deleted_at' => now()];
        foreach (['pro_rate_premium' => 0, 'endors_flag' => 0, 'previousActionIdCov' => 0] as $col => $val) {
            if (\Schema::hasColumn('policy_coverage_detail', $col)) {
                $update[$col] = $val;
            }
        }

        DB::table('policy_coverage_detail')->whereIn('id', $dropIds)->update($update);

        \Log::info('collapseDuplicateDetailRows: removed duplicate sub-coverage rows', [
            'policy_coverage_id' => $policyCoverageId,
            'dropped'            => $dropIds,
        ]);
    }

    private function deleteMainCoverageDetailRow(int $policyCoverageId, int $coverageId): void
    {
        PolicyCoverageDetail::where('policy_coverage_id', $policyCoverageId)
            ->where('coverage_id', $coverageId)
            ->whereNull('deleted_at')
            ->update(['deleted_at' => now()]);
    }

    /**
     * Normalise the numeric fields of the excesses[] payload in-place before
     * validation.
     *
     * The wizard's excess amount / percent inputs are MoneyInputs, but the
     * edit-load hydrator (StepCoverages) reconstructs excesses from the
     * type='Excess' rows in policy_extention_detail and carries whatever string
     * was stored there straight back into state. A legacy / formatted value
     * (e.g. "5,000", or a partial "5000.") is then POSTed verbatim when the
     * operator edits the coverage WITHOUT re-typing that field, and fails
     * `excesses.*.min_amt => nullable|numeric` ("The excesses.0.min_amt must be
     * a number.").
     *
     * TrimStrings + ConvertEmptyStringsToNull already turn blank/whitespace into
     * null (which passes `nullable`), so the only values that reach here are
     * non-empty. We mirror the frontend's unformatNumber() — strip thousands
     * separators and any non-numeric characters — then coerce a still-invalid
     * leftover to null rather than 422'ing the whole coverage save on a stale
     * value the operator never touched (min_amt = null simply means "no minimum
     * excess amount", a valid state). Genuinely numeric values, formatted or
     * not, are preserved.
     */
    private function normalizeExcessNumerics(Request $request): void
    {
        $excesses = $request->input('excesses');
        if (!is_array($excesses)) {
            return;
        }
        $numericKeys = ['min_amt', 'min_percent', 'discount_surcharge_value', 'premium'];
        foreach ($excesses as $i => $exc) {
            if (!is_array($exc)) {
                continue;
            }
            foreach ($numericKeys as $key) {
                if (!array_key_exists($key, $exc) || $exc[$key] === null || is_numeric($exc[$key])) {
                    continue;
                }
                // Mirror utils/format.ts unformatNumber: drop commas, then keep
                // only digits, decimal point and minus sign.
                $clean = preg_replace('/[^0-9.\-]/', '', str_replace(',', '', (string) $exc[$key]));
                $excesses[$i][$key] = is_numeric($clean) ? $clean : null;
            }
        }
        $request->merge(['excesses' => $excesses]);
    }

    /**
     * Step 3: Save coverage for a risk address.
     */
    public function addCoverage(Request $request, int $policyId): JsonResponse
    {
        $policy = Policy::findOrFail($policyId);

        // Trace payload on every call so 422 failures can be diagnosed
        // without round-tripping with the user. Strip large arrays from
        // the log to keep entries readable.
        \Log::info('addCoverage payload', [
            'policy_id'       => $policyId,
            'risk_address_id' => $request->input('risk_address_id'),
            'coverage_id'     => $request->input('coverage_id'),
            'coverage_value'  => $request->input('coverage_value'),
            'rate'            => $request->input('rate'),
            'calculated_value'=> $request->input('calculated_value'),
            'action_id'       => $request->input('action_id'),
            'term_id'         => $request->input('term_id'),
            'details_count'   => is_array($request->input('details')) ? count($request->input('details')) : 0,
            'details_sample'  => is_array($request->input('details')) ? array_slice($request->input('details'), 0, 2) : null,
            'extensions_count' => is_array($request->input('extensions')) ? count($request->input('extensions')) : 0,
            'specified_items_count' => is_array($request->input('specified_items')) ? count($request->input('specified_items')) : 0,
        ]);

        // coverage_value is optional for motor coverages — the per-vehicle
        // motor schedule is the source of truth, the coverage-level Sum
        // Insured field is hidden in the wizard. Detect by coverage CODE
        // (not hardcoded id) so this covers Commercial Motor / Domestic
        // Motor / Personal Motor / Motor Traders without future drift.
        $motorCodes = ['COMMERCIALMOTOR', 'PERSONALMOTOR', 'MOTORTRADERSINTERNAL', 'MOTORTRADERSEXTERNAL', 'MOTOR', 'DOMMOTOR'];
        // Specialist covers where the wizard hides the coverage-level Sum
        // Insured input — real values live on extensions/details/specified_items
        // child rows. Mirror HIDE_MAIN_COVERAGE_FIELDS_CODES in
        // PolicyCreatePage.tsx so FE/BE agree, otherwise the form submits with
        // no coverage_value and validation 422s before any row is written.
        // Fidelity Guarantee stores data in policy_coverages_data instead.
        $hideMainFieldsCodes = [
            'MEDICAMALPRACTICEINSURANCE', 'PROFESSIONALINDEMNITY', 'TRAVELINSURANCE',
            'CONTRACTORSALLRISKS', 'PLANTALLRISKS', 'ERECTIONALLRISKS',
            'DIRECTORSOFFICERSLIABILITY', 'MACHINERYBREAKDOWN',
            'MARINEONCEOFFCOVER', 'MARINEOPENCOVER', 'FIDELITYGUARANTEE',
            // Added with the Guarantee/Miscellaneous/Environmental Liability
            // specialist coverages (2026-06-24 migration) — the FE's
            // HIDE_MAIN_COVERAGE_FIELDS_CODES (StepCoverages.tsx) already
            // hides Sum Insured for these and submits an empty coverage_value,
            // but this BE list wasn't updated to match, so every Add Coverage
            // call for these 4 types 422'd with "coverage value field is
            // required" before any row was written — confirmed live on
            // staging (POST .../coverages with coverage_value:"" -> 422).
            'MEDICALEVACUATION', 'COMMERCIALCRIME', 'ENVIRONMENTALLIABILITY', 'BONDSANDGUARANTEES',
        ];
        $covCodeForGuard = strtoupper((string) DB::table('tb_cvgpccoverages')
            ->where('id', $request->input('coverage_id'))
            ->value('s_CoverageCode'));
        $isMotorRequest      = in_array($covCodeForGuard, $motorCodes, true);
        $isHideFieldsRequest = in_array($covCodeForGuard, $hideMainFieldsCodes, true);
        $this->normalizeExcessNumerics($request);
        $validated = $request->validate([
            'risk_address_id' => 'required|integer|exists:risk_address,id',
            'action_id'       => 'nullable|integer',
            'term_id'         => 'nullable|integer',
            'coverage_id'     => 'required|integer',
            'coverage_value'  => (($isMotorRequest || $isHideFieldsRequest) ? 'nullable' : 'required') . '|numeric|min:0',
            'rate'            => 'nullable|numeric|min:0',
            'calculated_value'=> 'nullable|numeric|min:0',
            'type_string'     => 'nullable|string|max:50',
            'type_value'      => 'nullable|numeric',
            'entity_type'     => 'nullable|string|max:50',
            'details'                    => 'nullable|array',
            'details.*.description'      => 'nullable|string',
            'details.*.value'            => 'nullable|numeric',
            'details.*.coverage_value'   => 'nullable|numeric',
            'details.*.rate'             => 'nullable|numeric',
            'details.*.calculated_value' => 'nullable|numeric',
            'details.*.sub_coverage_id'  => 'nullable|integer',
            'details.*.type_id'          => 'nullable|integer',
            // DROPDOWN / RADIO second-field pick (tb_cvgpclimits.n_PCLimitId_PK).
            // String, not integer — the column is a varchar and some coverages
            // persist the literal "0" for "no selection".
            'details.*.limit_id'         => 'nullable|string|max:255',
            // Workers Compensation fields in details (using existing columns only)
            'details.*.ratefactor_type'           => 'nullable|string',
            'details.*.ratefactor_value'          => 'nullable|string',
            'details.*.ratefactor_value_check'    => 'nullable|string|max:255',
            'details.*.ratefactor_AnnualWages'    => 'nullable|numeric',
            'details.*.ratefactor_deposit_min_pre' => 'nullable|numeric',
            // Workers Compensation discount/surcharge per detail row.
            // Stored on policy_coverage_detail (columns exist as enums per
            // 2023_07_06_102643_update_policy_coverages_tables migration).
            // Premium is hand-entered by the operator — we DO NOT auto-apply
            // the discount math (UW does that calc themselves). These columns
            // are persisted purely for audit/display.
            'details.*.discount_surcharge'        => 'nullable|string|in:Discount,Surcharge,None',
            'details.*.discount_surcharge_type'   => 'nullable|string|in:Flat,Percentage',
            'details.*.discount_surcharge_value'  => 'nullable|numeric',
            'details.*.coverage_value_string'     => 'nullable|string',
            // Extensions
            'extensions'                              => 'nullable|array',
            'extensions.*.extentions_id'              => 'required_with:extensions|integer',
            'extensions.*.s_ScreenName'               => 'nullable|string|max:255',
            'extensions.*.extention_coverage_value'   => 'nullable|numeric',
            'extensions.*.extention_text_value'       => 'nullable|string',
            'extensions.*.extention_limit_id'         => 'nullable|integer',
            'extensions.*.extention_excess_min_value' => 'nullable|numeric',
            'extensions.*.extention_excess_max_value' => 'nullable|numeric',
            'extensions.*.extention_discount_surcharge'       => 'nullable|string|in:Discount,Surcharge',
            'extensions.*.extention_discount_surcharge_type'  => 'nullable|string|in:Flat,Percentage',
            'extensions.*.extention_discount_surcharge_value' => 'nullable|numeric',
            'extensions.*.extention_calculated_value' => 'nullable|numeric',
            'extensions.*.extention_sum_insured'      => 'nullable|numeric',
            'extensions.*.type'                       => 'nullable|string|in:Extention,Perils,Memoranda,Excess,FirstAmountPayable,BurglarAlarmWarranty',
            // Specified Items — master pick or custom free-text
            'specified_items'                         => 'nullable|array',
            'specified_items.*.id'                    => 'nullable|integer',
            'specified_items.*.specified_coverage_id'  => 'nullable|integer',
            'specified_items.*.name'                   => 'nullable|string|max:255',
            'specified_items.*.sum_insured'            => 'nullable|numeric',
            'specified_items.*.rate'                   => 'nullable|numeric',
            'specified_items.*.calculated_value'       => 'nullable|numeric',
            // Fidelity Guarantee data
            'fidelity_data'                           => 'nullable|array',
            'fidelity_data.*.cover_type'              => 'nullable|string|max:255',
            'fidelity_data.*.cover_area'              => 'nullable|string|max:255',
            'fidelity_data.*.name_and_position'       => 'nullable|string|max:255',
            'fidelity_data.*.designation'             => 'nullable|string|max:255',
            'fidelity_data.*.length_of_service'       => 'nullable|string|max:255',
            'fidelity_data.*.amount_to_be_guaranteed' => 'nullable|numeric',
            'fidelity_data.*.premium'                 => 'nullable|numeric',
            // Excesses for Theft, Electronics Equipment, Business All Risks, etc.
            'excesses'                                => 'nullable|array',
            'excesses.*.excesses'                     => 'nullable|string',
            'excesses.*.min_percent'                  => 'nullable|numeric',
            'excesses.*.min_amt'                      => 'nullable|numeric',
            'excesses.*.discount_surcharge'           => 'nullable|string|in:Discount,Surcharge',
            'excesses.*.discount_surcharge_type'      => 'nullable|string|in:Flat,Percentage',
            'excesses.*.discount_surcharge_value'     => 'nullable|numeric',
            'excesses.*.premium'                      => 'nullable|numeric',
            // Theft General Questions
            'theft_questions'                         => 'nullable|array',
            'theft_questions.physical_protection_implemented' => 'nullable|string|max:255',
            'theft_questions.premises_alarmed'        => 'nullable|string|max:255',
            'theft_questions.subscribe_armed_security' => 'nullable|string|max:255',
            'theft_questions.security_company'        => 'nullable|string|max:255',
            'theft_questions.maintenance_contract'    => 'nullable|string|max:255',
            'theft_questions.alarmed_installed_date'  => 'nullable|date',
            'theft_questions.opening_closing_signals' => 'nullable|string|max:255',
            // Goods In Transit field
            'property_business_being'                 => 'nullable|string',
            // Office Content: Burglar Alarm Warranty field
            'burglar_alarm_warranty'                  => 'nullable|string',
            // Stated Benefits for Employees Liability / Workers Compensation
            'stated_benefits'                         => 'nullable|string',
            // Money coverage fields (stored in policy_coverage_notes table)
            'memoranda_warranty'                      => 'nullable|string',
            'cash_warranty'                           => 'nullable|string',
            // Notes — written to policy_coverage_notes (1:1 with the
            // coverage). addCoverage previously ignored the field, so
            // notes typed on the Create Wizard's coverage step were
            // silently dropped — the user had to save, then re-open and
            // edit to get them to stick. Matches updateCoverage which
            // already upserts this table.
            'notes'                                   => 'nullable|string',
            // Workers Compensation specific fields
            'ratefactor_type'  => 'nullable|string|max:255',
            'ratefactor_value' => 'nullable|string',
        ]);

        // Resolve the SAME action editData() loads so the write and the reload
        // stay on one action. editData (line ~492) honours an explicit
        // action_id first — the exact action the wizard opened — then falls
        // back to the latest QUOTE action, then the latest action overall.
        //
        // addCoverage MUST mirror that order. Previously it always took the
        // latest QUOTE action by id, which broke ANNIVERSARY-RENEW / endorse
        // editing on DOM/COM: those products auto-generate future-dated RENEW
        // actions whose ids are HIGHER than the anniversary/endorse QUOTE the
        // operator is editing. So a coverage added on the anniversary quote
        // landed on the higher-id future renewal action while editData kept
        // showing the anniversary action — the row saved (200, no error) but
        // never appeared. The frontend sends the action editData gave it
        // (policyResult.action_id), so honouring the supplied action_id (when
        // it is a real action on this policy) keeps the write on the edited
        // action. Falls back to QUOTE/latest when none is supplied.
        $suppliedActionId = $validated['action_id'] ?? null;
        $editAction = null;
        if (!empty($suppliedActionId)) {
            $editAction = \AlphaDirect\Models\PolicyAction::where('policy_id', $policyId)
                ->where('id', $suppliedActionId)
                ->first();
        }
        if (!$editAction) {
            $editAction = \AlphaDirect\Models\PolicyAction::where('policy_id', $policyId)
                ->where('status', 'QUOTE')
                ->orderBy('id', 'desc')
                ->first()
                ?? \AlphaDirect\Models\PolicyAction::where('policy_id', $policyId)->orderBy('id', 'desc')->first();
        }
        $resolvedActionId = $editAction?->id ?? $validated['action_id'];
        $resolvedTermId   = $editAction?->term_id ?? $validated['term_id'];

        // Same rule as ensureCoverageEditable, which only ever protected an
        // EDIT: updateCoverage 409s on a non-QUOTE action while addCoverage had
        // no guard at all, so a new section could be written straight onto an
        // ISSUED transaction. The Smart Upload target picker offers every
        // action regardless of status, so applying a schedule to an issued
        // NEWBUSINESS correctly refused the sections already on it and then
        // silently added the rest — desyncing the printed schedule from the
        // data it was rated on. Blank status = legacy row, treated as editable.
        if ($locked = $this->ensureActionEditable((int) $resolvedActionId, 'Coverages')) {
            return $locked;
        }

        // The action being written to. Used below for endors_flag (only ENDORSE
        // actions flag as endorsement) and the pro-rata period calc. This was
        // referenced but never defined, throwing "Undefined variable
        // $latestAction" when adding/editing a coverage; it must be the resolved
        // (selected) edit action, not "latest by id".
        $latestAction = $editAction;

        // Specialist coverages that are tied to a single project / site / risk
        // (CAR / PAR / EAR / Machinery Breakdown / Medical Malpractice /
        // Professional Indemnity / D&O / Marine Cargo Open / Marine Cargo Once-Off
        // / Travel Insurance) — a risk address may have at most ONE row of each
        // type per action. Block duplicates here.
        $masterForGuard = CoverageMaster::find($validated['coverage_id']);
        $codeUpper = strtoupper($masterForGuard?->s_CoverageCode ?? '');
        $singletonFamilies = self::singletonCoverageFamilies();
        $matchedFamily = null;
        foreach ($singletonFamilies as $family => $codes) {
            if (in_array($codeUpper, $codes, true)) { $matchedFamily = $family; break; }
        }
        if ($matchedFamily) {
            $familyCodeIds = CoverageMaster::whereIn('s_CoverageCode', $singletonFamilies[$matchedFamily])
                ->pluck('id')->all();
            $duplicate = PolicyCoverage::where('policy_id', $policy->id)
                ->where('risk_address_id', $validated['risk_address_id'])
                ->whereIn('coverage_id', $familyCodeIds)
                ->when($resolvedActionId, fn($q) => $q->where('action_id', $resolvedActionId))
                ->whereNull('deleted_at')
                ->exists();
            if ($duplicate) {
                return response()->json([
                    'error'   => "This risk address already has a {$matchedFamily} coverage. Only one {$matchedFamily} coverage is allowed per risk address.",
                    'message' => "This risk address already has a {$matchedFamily} coverage. Only one {$matchedFamily} coverage is allowed per risk address.",
                ], 422);
            }
        }

        // One-to-one Risk Address ↔ Coverage rule for the specialist single-site
        // products (Engineering 16/17, Specialist 18, Commercial Liabilities 20,
        // Marine 22): a risk address may hold only ONE coverage of ANY type.
        // Stricter than the per-family guard above. Re-saving the SAME coverage
        // (an edit) is allowed — only a DIFFERENT coverage on the same address
        // is blocked, scoped to the resolved action.
        if (in_array((int) $policy->product_id, [16, 17, 18, 20, 22], true)) {
            $otherOnAddress = PolicyCoverage::with('coverage')
                ->where('policy_id', $policy->id)
                ->where('risk_address_id', $validated['risk_address_id'])
                ->where('coverage_id', '!=', $validated['coverage_id'])
                ->when($resolvedActionId, fn($q) => $q->where('action_id', $resolvedActionId))
                ->whereNull('deleted_at')
                ->first();
            if ($otherOnAddress) {
                $existingName = $otherOnAddress->coverage?->s_ScreenName
                    ?? $otherOnAddress->coverage?->s_CoverageCode
                    ?? 'another';
                return response()->json([
                    'error'   => "This risk address already has a {$existingName} coverage. Only one coverage is allowed per risk address.",
                    'message' => "This risk address already has a {$existingName} coverage. Only one coverage is allowed per risk address.",
                ], 422);
            }
        }

        // Motor Traders Ext/Int store 14 SI + 14 premium columns in their own
        // table; the parent policy_coverages row must NOT carry a Main
        // coverage_value / calculated_value (otherwise Rate banner double-counts
        // a phantom Main premium on top of the motor_traders aggregate).
        $isMotorTraders = in_array($covCodeForGuard, ['MOTORTRADERSEXTERNAL', 'MOTORTRADERSINTERNAL'], true);

        // Universal duplicate guard — one (policy, risk_address, coverage,
        // action, term) row ever. Replaces a prior `updateOrCreate` call that
        // double-inserted under two conditions:
        //   1. Operator double-click before the first POST committed — no row
        //      visible yet to the second query, so both inserts ran.
        //   2. Eloquent's match query rendered `risk_address_id = NULL`,
        //      which is always false in MySQL (needs `IS NULL`); a null
        //      risk_address therefore skipped the existing-row check.
        // Explicit lookup inside a row-level lock makes the second request
        // block until the first commits, then update instead of insert.
        // coverage_value is nullable in validation for motor + hide-main-field
        // specialist covers (CAR/EAR/PAR/MachineryBreakdown/MedMalpractice/PI/
        // D&O/Travel/Marine Open + Once-Off). FE sends `undefined` for those,
        // so the key is absent from $validated and a direct read raises
        // "Undefined array key coverage_value". Default to 0 — the real Sum
        // Insured is reconstructed from details/extensions/specified_items
        // and re-summed below. For motor traders we hard-force 0 regardless
        // of what the FE sends (defence-in-depth).
        $coverageAttrs = [
            'coverage_value'   => $isMotorTraders ? 0 : ($validated['coverage_value'] ?? 0),
            'rate'             => $isMotorTraders ? 0 : ($validated['rate'] ?? 0),
            'calculated_value' => $isMotorTraders ? 0 : ($validated['calculated_value'] ?? 0),
            'type_string'      => $validated['type_string'] ?? null,
            'type_value'       => $validated['type_value'] ?? null,
            'entity_type'      => $validated['entity_type'] ?? 'Risk Address',
            'property_business_being' => $validated['property_business_being'] ?? null,
            'burglar_alarm_warranty' => $validated['burglar_alarm_warranty'] ?? null,
            'stated_benefits' => $validated['stated_benefits'] ?? null,
        ];

        $coverage = DB::transaction(function () use (
            $policy, $validated, $resolvedActionId, $resolvedTermId, $coverageAttrs
        ) {
            $query = PolicyCoverage::where('policy_id', $policy->id)
                ->where('coverage_id', $validated['coverage_id'])
                ->whereNull('deleted_at');

            if ($validated['risk_address_id'] === null) {
                $query->whereNull('risk_address_id');
            } else {
                $query->where('risk_address_id', $validated['risk_address_id']);
            }

            if ($resolvedActionId !== null) {
                $query->where('action_id', $resolvedActionId);
            } else {
                $query->whereNull('action_id');
            }

            if ($resolvedTermId !== null) {
                $query->where('term_id', $resolvedTermId);
            } else {
                $query->whereNull('term_id');
            }

            $existing = $query->lockForUpdate()->first();

            if ($existing) {
                $existing->fill($coverageAttrs)->save();
                return $existing;
            }

            return PolicyCoverage::create(array_merge($coverageAttrs, [
                'policy_id'       => $policy->id,
                'risk_address_id' => $validated['risk_address_id'],
                'coverage_id'     => $validated['coverage_id'],
                'action_id'       => $resolvedActionId,
                'term_id'         => $resolvedTermId,
            ]));
        });

        // Handle retroactive date for Public Liability coverage
        $retroactiveDate = $request->input('retroactive_date');
        if ($retroactiveDate !== null && $retroactiveDate !== '') {
            try {
                $date = \Carbon\Carbon::createFromFormat('Y-m-d', $retroactiveDate);
                $coverage->update(['publicliability_date' => $date->format('Y-m-d')]);
            } catch (\Exception $e) {
                // Invalid date format, continue without saving date
            }
        }

        // Save coverage details / subcoverages if provided.
        // Motor & Motor-Traders coverages do NOT use policy_coverage_detail —
        // their premium / sum-insured lives in dedicated tables:
        //   COMMERCIALMOTOR / DOMMOTOR  → `motor` (per-vehicle rows)
        //   MOTORTRADERSEXTERNAL        → `motor_traders` (14 SI + 14 premium cols)
        //   MOTORTRADERSINTERNAL        → `motor_traders_internal` (same shape)
        // Any policy_coverage_detail row under these coverages is a phantom
        // (the legacy "Main" sub-cov inherited from tb_cvgpccoverages) that
        // double-counts into Rate banner + V2 Quote totals. Skip the insert
        // loop entirely. The Personal Motor (covered by 22/27 motor isolation
        // elsewhere) is intentionally NOT in this list to avoid breaking the
        // legacy PERSONALMOTOR display label behaviour — extend if UW asks.
        $noDetailCodes = ['MOTORTRADERSEXTERNAL', 'MOTORTRADERSINTERNAL', 'COMMERCIALMOTOR', 'DOMMOTOR'];
        $skipDetailInserts = in_array($covCodeForGuard, $noDetailCodes, true);
        // Cloning happens on FRONTEND when "+" is clicked (immediate clone in tb_cvgpccoverages).
        // Backend just receives the already-cloned coverage_id and uses it directly.
        if (!$skipDetailInserts && !empty($validated['details'])) {
            \Log::info('DETAILS ARRAY RECEIVED', ['count' => count($validated['details'])]);
            foreach ($validated['details'] as $detail) {
                $covValue = $detail['coverage_value'] ?? $detail['value'] ?? 0;
                $calcValue = $detail['calculated_value'] ?? 0;

                \Log::info('Processing detail', [
                    'description' => $detail['description'] ?? 'NO DESC',
                    'covValue' => $covValue,
                    'calcValue' => $calcValue,
                    'ratefactor_type' => $detail['ratefactor_type'] ?? null,
                    'ratefactor_value' => $detail['ratefactor_value'] ?? null,
                    'ratefactor_value_check' => $detail['ratefactor_value_check'] ?? null,
                    'ratefactor_AnnualWages' => $detail['ratefactor_AnnualWages'] ?? null,
                    'ratefactor_deposit_min_pre' => $detail['ratefactor_deposit_min_pre'] ?? null,
                    'coverage_value_string' => $detail['coverage_value_string'] ?? null,
                ]);

                // Skip inserting if ALL fields are empty (coverage_value, calculated_value, and ratefactor fields)
                // Allow saving if ANY field has a meaningful value (including ratefactor_value for Free Text)
                $hasAnyValue = $covValue > 0 || $calcValue > 0 ||
                    !empty($detail['ratefactor_value']) ||
                    !empty($detail['ratefactor_type']) ||
                    !empty($detail['ratefactor_value_check']) ||
                    !empty($detail['ratefactor_AnnualWages']) ||
                    !empty($detail['ratefactor_deposit_min_pre']) ||
                    !empty($detail['coverage_value_string']) ||
                    // A DROPDOWN/RADIO-only row (e.g. Public Liability "Basis of
                    // cover" → Claims Made) carries no SI/premium/free-text, so
                    // without this it was silently skipped and never inserted.
                    !empty($detail['limit_id']);

                if ($hasAnyValue) {
                    // Use coverage_id directly (already cloned on frontend, or existing from DB)
                    $detailCoverageId = $detail['coverage_id'] ?? $validated['coverage_id'];

                    // Use updateOrCreate to prevent duplicates - if same (policy_coverage_id, coverage_id)
                    // exists, update it; otherwise create new
                    $updateData = [
                        'coverage_value'     => $covValue,
                        'rate'               => $detail['rate'] ?? 0,
                        'calculated_value'   => $calcValue,
                        'pro_rate_premium'   => $calcValue,
                        // Use coverage_value_string as sent by frontend. Don't fall back to
                        // description — if user leaves the free text field empty, it should
                        // stay empty (NULL). Frontend now explicitly sends this field.
                        'coverage_value_string' => (($detail['coverage_value_string'] ?? '') === '') ? null : $detail['coverage_value_string'],
                        // Second-field selection for DROPDOWN/RADIO subcoverages.
                        // This previously read `type_id` — a key the wizard has
                        // never sent (and not even a column on this table), so
                        // every add silently stored NULL. Read `limit_id` first,
                        // keeping `type_id` as a fallback for the older
                        // syncCoverages spelling. Empty string → null so a
                        // cleared select stores clean.
                        'limit_id'           => (($detail['limit_id'] ?? $detail['type_id'] ?? '') === '')
                            ? null
                            : ($detail['limit_id'] ?? $detail['type_id']),
                        'ratefactor_type'    => $detail['ratefactor_type'] ?? null,
                        'ratefactor_value'   => $detail['ratefactor_value'] ?? null,
                        'ratefactor_value_check' => $detail['ratefactor_value_check'] ?? null,
                        'ratefactor_AnnualWages' => $detail['ratefactor_AnnualWages'] ?? null,
                        'ratefactor_deposit_min_pre' => $detail['ratefactor_deposit_min_pre'] ?? null,
                        // endors_flag is always 0 for non-ENDORSE actions (NEWBUSINESS, RENEW, etc.)
                        // Only ENDORSE actions can have endors_flag = 1
                        'endors_flag'        => ($latestAction && $latestAction->transaction_type !== 'ENDORSE') ? 0 : ($resolvedActionId ? 1 : 0),
                        'previousActionIdCov' => $resolvedActionId,
                        'deleted_at'         => null,
                    ];
                    // Discount/Surcharge — Schema-gated so older envs without
                    // these columns don't 500. Default to empty string (column
                    // does not allow NULL).
                    if (\Schema::hasColumn('policy_coverage_detail', 'discount_surcharge')) {
                        $ds = $detail['discount_surcharge'] ?? '';
                        $updateData['discount_surcharge'] = ($ds === 'None' || $ds === '') ? '' : $ds;
                    }
                    if (\Schema::hasColumn('policy_coverage_detail', 'discount_surcharge_type')) {
                        $dst = $detail['discount_surcharge_type'] ?? '';
                        $updateData['discount_surcharge_type'] = ($dst === '') ? '' : $dst;
                    }
                    if (\Schema::hasColumn('policy_coverage_detail', 'discount_surcharge_value')) {
                        $updateData['discount_surcharge_value'] = isset($detail['discount_surcharge_value'])
                            ? (float) $detail['discount_surcharge_value'] : 0;
                    }
                    PolicyCoverageDetail::withTrashed()->updateOrCreate(
                        [
                            'policy_coverage_id' => $coverage->id,
                            'coverage_id'        => $detailCoverageId,
                        ],
                        $updateData
                    );
                }
            }
        }

        // Calculate premium if not provided
        $master = CoverageMaster::find($validated['coverage_id']);
        $rate = $validated['rate'] ?? ($master->rate ?? 0);
        // coverage_value is nullable for motor + hide-main-field specialist
        // covers (CAR/PAR/EAR/MachineryBreakdown/MedMalpractice/PI/D&O/Travel/Marine)
        // — premium for those comes from extensions/details/specified_items rows,
        // not the (hidden) coverage-level Sum Insured. Falling back to 0 keeps
        // the guard below from raising "Undefined array key coverage_value".
        $coverageValue = $validated['coverage_value'] ?? 0;
        // Persist the Main row in policy_coverage_detail so recomputeActionTotals
        // (which sums detail rows) picks it up. Two cases:
        //   1. Auto-compute when rate>0 and user did not provide a premium
        //   2. User-entered Premium (any rate, including 0) — UW typed it in
        //      the Main Premium field; honour that value directly.
        // Motor coverages (Commercial Motor 22, Personal Motor 27, Motor
        // Traders Ext 15, Motor Traders Int 26) are excluded — premium for
        // those lives in motor / motor_traders / motor_traders_internal,
        // NOT in policy_coverage_detail. Writing a Main row for them would
        // double-count in recomputeActionTotals.
        // CRITICAL: NEVER save main coverage row if detail rows exist
        // The main row is ONLY for simple coverages without subcoverages.
        // If subcoverages exist, data lives ONLY in the detail rows.
        $motorIsolatedIds = [22, 27, 15, 26];
        $isMotorIsolated = in_array((int) $validated['coverage_id'], $motorIsolatedIds, true);
        // COM/DOM (product 7/8): per UW, NEVER write a coverage-wise "Main"
        // policy_coverage_detail row — for these products premium comes only
        // from the per-row (sub-coverage) data. Other products (specialist,
        // simple single-value covers) keep the Main row as their premium store.
        $isDomComProduct = $this->isDomComProduct($policy);
        // CRITICAL: If detail rows (subcoverages) exist, SKIP main row entirely
        $hasDetailRows = !empty($validated['details']) && count($validated['details']) > 0;

        $userProvidedPremium = isset($validated['calculated_value']) && (float) $validated['calculated_value'] > 0;
        $autoCompute = $rate > 0 && $coverageValue > 0 && empty($validated['calculated_value']);

        // CRITICAL: do NOT write a "Main"/total-premium row for coverages that have
        // sub-coverages — premium comes from summing the detail rows. The Main row is
        // only written for SIMPLE single-value coverages (no details), where it is the
        // only premium row. COM/DOM never get a Main row at all.
        // Specialist / Fidelity covers are excluded for the same reason as motor:
        // their premium already lives in a dedicated table that the annual recipe
        // sums separately, so a Main row here is counted twice. See
        // OWN_PREMIUM_TABLE_COVERAGE_CODES.
        $isOwnPremiumTableCoverage = self::isOwnPremiumTableCoverage($validated['coverage_id']);
        if (!$isMotorIsolated && !$isDomComProduct && !$isOwnPremiumTableCoverage && !$hasDetailRows && ($autoCompute || $userProvidedPremium)) {
            $calculatedPremium = $userProvidedPremium
                ? (float) $validated['calculated_value']
                : ($coverageValue * $rate) / 100;

            // Pro-rate only on auto-compute path; user-entered premium is
            // assumed already final (UW types the value they want).
            if ($autoCompute) {
                $action = $latestAction ?? \AlphaDirect\Models\PolicyAction::find($resolvedActionId);
                if ($action && $action->effective_from && $action->effective_to) {
                    $months = \Carbon\Carbon::parse($action->effective_from)->diffInMonths(\Carbon\Carbon::parse($action->effective_to));
                    if ($months > 0 && $months < 12) {
                        $calculatedPremium = ($calculatedPremium / 12) * $months;
                    }
                }
            }

            $coverage->update(['calculated_value' => round($calculatedPremium, 2)]);

            // Upsert the Main detail row keyed on (policy_coverage_id, coverage_id)
            // so repeated saves update the same row instead of accumulating.
            if ($coverageValue > 0 || round($calculatedPremium, 2) > 0) {
                \AlphaDirect\Models\PolicyCoverageDetail::updateOrCreate(
                    ['policy_coverage_id' => $coverage->id, 'coverage_id' => $validated['coverage_id']],
                    [
                        'coverage_value' => $coverageValue,
                        'rate' => $rate,
                        'calculated_value' => round($calculatedPremium, 2),
                        'pro_rate_premium' => round($calculatedPremium, 2),
                        'endors_flag'         => $resolvedActionId ? 1 : 0,
                        'previousActionIdCov' => $resolvedActionId,
                    ]
                );
            }
        }

        // Convert excesses to extensions format before saving
        // Theft, Electronics Equipment, Business All Risks, and Fidelity Guarantee excesses are stored as extensions with type='Excess'
        if (!empty($validated['excesses'])) {
            foreach ($validated['excesses'] as $exc) {
                if (!empty($exc['excesses']) || !empty($exc['min_percent']) || !empty($exc['min_amt']) || !empty($exc['discount_surcharge']) || !empty($exc['premium'])) {
                    $validated['extensions'][] = [
                        'type' => 'Excess',
                        's_ScreenName' => $exc['excesses'] ?? 'Excess',
                        'extention_text_value' => $exc['excesses'] ?? null,
                        'extention_excess_min_value' => $exc['min_percent'] ?? 0,
                        'extention_excess_max_value' => $exc['min_amt'] ?? 0,
                        'extention_discount_surcharge' => $exc['discount_surcharge'] ?? '',
                        'extention_discount_surcharge_type' => $exc['discount_surcharge_type'] ?? '',
                        'extention_discount_surcharge_value' => $exc['discount_surcharge_value'] ?? 0,
                        'extention_calculated_value' => $exc['premium'] ?? 0,
                        'extention_coverage_value' => 0,
                        'extention_sum_insured' => null,
                    ];
                }
            }
        }

        // Save extensions (policy_extention_detail)
        // Store all master data columns from extentions table (s_CoverageName, s_CoverageCode, s_ScreenName, etc)
        if (!empty($validated['extensions'])) {
            $coverageMaster = CoverageMaster::find($validated['coverage_id']);
            $hasCustomName = \Schema::hasColumn('policy_extention_detail', 'custom_name');

            foreach ($validated['extensions'] as $ext) {
                // Skip extensions with no meaningful data (all fields empty)
                // Include s_ScreenName/custom_name check for Theft excesses which may only have a name
                $hasValue = !empty($ext['extention_coverage_value']) || !empty($ext['extention_text_value'])
                    || !empty($ext['extention_limit_id']) || !empty($ext['extention_discount_surcharge_value'])
                    || !empty($ext['extention_calculated_value']) || !empty($ext['extention_sum_insured'])
                    || !empty($ext['s_ScreenName']) || !empty($ext['custom_name'])
                    || !empty($ext['extention_excess_min_value']) || !empty($ext['extention_excess_max_value']);
                if (!$hasValue) continue;

                // For type='Excess' (Theft excesses), allow without extentions_id
                // For other types, require a valid extension master record
                $isExcess = ($ext['type'] ?? '') === 'Excess';
                if (!$isExcess) {
                    $extMaster = DB::table('extentions')->where('id', $ext['extentions_id'])->first();
                    if (!$extMaster) continue;
                } else {
                    $extMaster = null;
                }

                $row = [
                    'policy_coverage_id'                    => $coverage->id,
                    'extentions_id'                         => $ext['extentions_id'] ?? null,
                    's_ParentCoverageID'                    => $extMaster?->s_ParentCoverageID ?? $coverageMaster?->s_ParentCoverageID ?: $coverageMaster?->id,
                    's_ParentCoverageCode'                  => $extMaster?->s_ParentCoverageCode ?? '',
                    'type'                                  => $ext['type'] ?? 'Extention',
                    'extention_coverage_value'              => $ext['extention_coverage_value'] ?? 0,
                    'extention_text_value'                  => $ext['extention_text_value'] ?? null,
                    'extention_limit_id'                    => $ext['extention_limit_id'] ?? null,
                    'extention_excess_min_value'            => $ext['extention_excess_min_value'] ?? 0,
                    'extention_excess_max_value'            => $ext['extention_excess_max_value'] ?? 0,
                    'extention_discount_surcharge'          => $ext['extention_discount_surcharge'] ?? '',
                    'extention_discount_surcharge_type'     => $ext['extention_discount_surcharge_type'] ?? '',
                    'extention_discount_surcharge_value'    => $ext['extention_discount_surcharge_value'] ?? 0,
                    'extention_calculated_value'            => $ext['extention_calculated_value'] ?? 0,
                    // extention_sum_insured is NOT NULL with no DB default —
                    // coalesce to 0 (the value the FE/excess path implies when
                    // the field is absent). The Excess→extension conversion
                    // sends null here, which 1048'd the whole Update/Add
                    // Coverage save ("Column 'extention_sum_insured' cannot be
                    // null") on coverages carrying an excess (e.g. Electronic
                    // Equipment). Existing excess rows store 0.
                    'extention_sum_insured'                 => $ext['extention_sum_insured'] ?? 0,
                    'created_at'                            => now(),
                    'updated_at'                            => now(),
                ];

                // Wizard-gate: stamp previousActionIdCov + endors_flag so an
                // ENDORSE that ADDS this coverage gets its extensions pro-rated.
                // Mirrors the sub-coverage rows above and updateCoverage(). Without
                // it, store()-created extensions have previousActionIdCov = NULL, so
                // writeLineLevelProRata and the pro-rata delta sum skip them and the
                // added extension premium is never charged (policy 213667 ADDCOVG
                // pro-rated only the 200 of subs, dropping 1,000 of extension premium
                // → 149.59 instead of 897.53).
                if (\Schema::hasColumn('policy_extention_detail', 'previousActionIdCov')) {
                    $row['previousActionIdCov'] = $resolvedActionId;
                }
                if (\Schema::hasColumn('policy_extention_detail', 'endors_flag')) {
                    $row['endors_flag'] = ($latestAction && $latestAction->transaction_type !== 'ENDORSE') ? 0 : ($resolvedActionId ? 1 : 0);
                }

                // Add optional master metadata columns only if they exist in schema and master exists
                if ($extMaster) {
                    $optionalCols = ['s_CoverageName', 's_CoverageCode', 's_ScreenName', 's_CoverageDesc', 's_ExtensionsGroupName',
                                     'n_DisplaySequence', 'extention_type', 'rate', 'd_EffectiveDt', 'd_ExpirationDt', 's_RatingMethod', 's_DISPLAYTOUSER'];
                    foreach ($optionalCols as $col) {
                        if (\Schema::hasColumn('policy_extention_detail', $col)) {
                            $row[$col] = $extMaster->$col ?? null;
                        }
                    }

                    if ($hasCustomName && !empty($ext['s_ScreenName']) && $ext['s_ScreenName'] !== $extMaster->s_ScreenName) {
                        $row['custom_name'] = $ext['s_ScreenName'];
                    }
                } else if ($isExcess && $hasCustomName) {
                    // For Excess type without master, use s_ScreenName as custom_name
                    $row['custom_name'] = $ext['s_ScreenName'] ?? null;
                }

                $extModel = new \AlphaDirect\Models\PolicyExtentionDetails();
                $extModel->forceFill($row)->save();
            }
        }

        // Save specified items (policy_specified_items). Accept both master
        // picks (specified_coverage_id set) and custom free-text rows
        // (custom_name carries the description). Skip rows with no useful
        // payload.
        if (!empty($validated['specified_items'])) {
            $hasCustomNameCol = \Schema::hasColumn('policy_specified_items', 'custom_name');
            $seenItems = [];  // Track items to detect duplicates for same risk address + coverage

            foreach ($validated['specified_items'] as $item) {
                // Skip motor-attached items — owned by per-motor endpoints
                // (addMotorSpecifiedItem etc). Inserting them here would
                // duplicate rows already created by the per-motor flow.
                if (!empty($item['motor_id'])) continue;
                $hasPayload = !empty($item['sum_insured']) || !empty($item['calculated_value']);
                $hasIdentity = !empty($item['specified_coverage_id']) || !empty($item['name']);
                if (!$hasPayload || !$hasIdentity) continue;

                // CRITICAL: Check for duplicate item for same risk address
                // Prevent: same specified_coverage_id + risk_address_id for same coverage
                // Also check soft-deleted items and suggest reinstatement
                // Trim whitespace from name for consistent comparison
                $specCovId = $item['specified_coverage_id'] ?? null;
                $itemName = isset($item['name']) ? trim($item['name']) : null;
                $riskAddressId = $item['address_id'] ?? $validated['risk_address_id'] ?? null;

                if ($riskAddressId && ($specCovId || $itemName)) {
                    // For master items: use specified_coverage_id
                    // For custom items: use trimmed name
                    $dupeKey = $specCovId ? "{$specCovId}_{$riskAddressId}" : "custom_{$itemName}_{$riskAddressId}";

                    if (isset($seenItems[$dupeKey])) {
                        return response()->json([
                            'error' => "This item for same risk address already exist for this coverage",
                        ], 422);
                    }
                    $seenItems[$dupeKey] = true;

                    // Check for soft-deleted item (deleted_at is NOT null)
                    $deletedQuery = \AlphaDirect\Models\PolicySpecifiedItem::where('policy_coverage_id', $coverage->id)
                        ->whereNotNull('deleted_at');

                    if ($specCovId) {
                        $deletedQuery->where('specified_coverage_id', $specCovId);
                    } else if ($itemName) {
                        $deletedQuery->whereRaw("TRIM(custom_name) = ?", [$itemName]);
                    }

                    $deletedItem = $deletedQuery->first();

                    if ($deletedItem) {
                        return response()->json([
                            'error' => "this deleted item already exist just reinstate it",
                        ], 422);
                    }

                    // Check database for existing active items (in case of edit)
                    $existingQuery = \AlphaDirect\Models\PolicySpecifiedItem::where('policy_coverage_id', $coverage->id)
                        ->whereNull('deleted_at');

                    if ($specCovId) {
                        $existingQuery->where('specified_coverage_id', $specCovId);
                    } else if ($itemName) {
                        $existingQuery->whereRaw("TRIM(custom_name) = ?", [$itemName]);
                    }

                    $existingItem = $existingQuery->first();

                    if ($existingItem && $existingItem->id !== ($item['id'] ?? null)) {
                        return response()->json([
                            'error' => "This item for same risk address already exist for this coverage",
                        ], 422);
                    }
                }
                $calcVal = (($item['sum_insured'] ?? 0) * ($item['rate'] ?? 0)) / 100;
                $row = array_merge([
                    'policy_coverage_id'    => $coverage->id,
                    'specified_coverage_id' => $item['specified_coverage_id'] ?? null,
                    'sum_insured'           => $item['sum_insured'] ?? 0,
                    'rate'                  => $item['rate'] ?? 0,
                    'calculated_value'      => $item['calculated_value'] ?? round($calcVal, 2),
                    'term_id'               => $resolvedTermId,
                    'action_id'             => $resolvedActionId,
                ], $this->auditStamps('policy_specified_items'));
                if ($hasCustomNameCol && empty($item['specified_coverage_id']) && !empty($item['name'])) {
                    $row['custom_name'] = $item['name'];
                }
                // ENDORSE that ADDS a Miscellaneous Item must get it pro-rated,
                // exactly like the sub-coverage detail and extension inserts
                // above (which stamp every product). Without the
                // previousActionIdCov stamp the new row keeps it NULL, so
                // writeLineLevelProRata's specified-items gate
                // (previousActionIdCov === actionId) skips it → pro_rate_premium
                // stays 0 → it drops out of $deltaSpec on the Rate banner and in
                // recomputeActionTotals. The misc line then shows on the
                // schedule but rates P0. This is the new-coverage / new-risk-
                // address create path; the edit paths (updateCoverage smart-sync,
                // addSpecifiedItem) already stamp for ALL products, so this just
                // brings the create path in line. COM/DOM Fire misc included;
                // motor-attached items are skipped above and stay untouched.
                if (\Schema::hasColumn('policy_specified_items', 'previousActionIdCov')) {
                    $row['previousActionIdCov'] = $resolvedActionId;
                }
                if (\Schema::hasColumn('policy_specified_items', 'endors_flag')) {
                    $row['endors_flag'] = ($latestAction && $latestAction->transaction_type !== 'ENDORSE') ? 0 : ($resolvedActionId ? 1 : 0);
                }
                // Eloquent forceFill+save so PolicySpecifiedItem Auditable
                // fires for the Logs tab. The model's boot() also re-derives
                // calculated_value via creating(), so passing both is fine.
                $siModel = new \AlphaDirect\Models\PolicySpecifiedItem();
                $siModel->forceFill($row)->save();
            }
        }

        // Save coverage note (policy_coverage_notes — 1:1 with coverage)
        // via Eloquent so PolicyCoverageNote Auditable fires for the Logs
        // tab. Upsert pattern matches updateCoverage so the same record is
        // overwritten rather than duplicated if the wizard is retried.
        if (isset($validated['notes']) && $validated['notes'] !== '') {
            $this->coverageLevelNoteRow((int) $coverage->id)
                ->forceFill(['note' => $validated['notes']])->save();
        }

        // Money warranties — same coverage-level row as `note`. The create
        // path validated these but never wrote them, so a Money coverage
        // added in one pass lost its Memoranda / Cash Carrying Warranty
        // until the operator hit Update Coverage a second time.
        if (!empty(trim($validated['memoranda_warranty'] ?? ''))) {
            $this->coverageLevelNoteRow((int) $coverage->id)
                ->forceFill(['memoranda_warranty' => $validated['memoranda_warranty']])->save();
        }
        if (!empty(trim($validated['cash_warranty'] ?? ''))) {
            $this->coverageLevelNoteRow((int) $coverage->id)
                ->forceFill(['cash_warranty' => $validated['cash_warranty']])->save();
        }

        // "Benefits for the circumstances" (WC / Stated Benefits) — V1 stores
        // this in policy_coverage_notes.benefits_note. FE sends it as
        // `stated_benefits`. Requires migration 2026_06_03_000001.
        if (!empty(trim($validated['stated_benefits'] ?? ''))
            && \Schema::hasColumn('policy_coverage_notes', 'benefits_note')) {
            $this->coverageLevelNoteRow((int) $coverage->id)
                ->forceFill(['benefits_note' => $validated['stated_benefits']])->save();
        }

        // Save Fidelity Guarantee data (policy_coverages_data)
        if (array_key_exists('fidelity_data', $validated) && is_array($validated['fidelity_data'])) {
            Log::info('Saving fidelity_data in addCoverage', [
                'coverage_id'      => $coverage->id,
                'policy_id'        => $policy->id,
                'fidelity_count'   => count($validated['fidelity_data']),
            ]);
            foreach ($validated['fidelity_data'] as $fid) {
                Log::info('Processing fidelity row in addCoverage', ['data' => $fid]);

                // Skip if soft-deleted
                if (!empty($fid['deleted_at'])) {
                    Log::info('Skipping soft-deleted row');
                    continue;
                }

                // Skip empty rows
                if (empty($fid['cover_type']) && empty($fid['cover_area']) && empty($fid['name_and_position'])
                    && empty($fid['designation']) && empty($fid['length_of_service'])
                    && empty($fid['amount_to_be_guaranteed']) && empty($fid['premium'])) {
                    Log::info('Skipping empty row');
                    continue;
                }

                $payload = [
                    'cover_type'                  => $fid['cover_type'] ?? '',
                    'cover_area'                  => $fid['cover_area'] ?? '',
                    'name_and_position'           => $fid['name_and_position'] ?? '',
                    'designation'                 => $fid['designation'] ?? '',
                    'length_of_service'           => $fid['length_of_service'] ?? '',
                    'amount_to_be_guaranteed'     => $fid['amount_to_be_guaranteed'] ?? 0,
                    'premium'                     => $fid['premium'] ?? 0,
                ];

                $fidModel = new \AlphaDirect\Models\PolicyCoveragesData();
                $fidModel->forceFill(array_merge([
                    'policyCoverageID' => $coverage->id,
                    'policy_id'        => $policy->id,
                    'risk_address'     => $coverage->risk_address_id,
                ], $payload))->save();
                Log::info('Inserted fidelity row in addCoverage', ['id' => $fidModel->id]);
            }
        }

        // Save Theft General Questions (theft_general_questions)
        if (array_key_exists('theft_questions', $validated) && is_array($validated['theft_questions'])) {
            Log::info('Saving theft_questions in addCoverage', [
                'coverage_id'      => $coverage->id,
                'policy_id'        => $policy->id,
            ]);
            $theftData = $validated['theft_questions'];

            // Check if any data exists
            if (!empty($theftData['physical_protection_implemented']) || !empty($theftData['premises_alarmed']) ||
                !empty($theftData['subscribe_armed_security']) || !empty($theftData['security_company']) ||
                !empty($theftData['maintenance_contract']) || !empty($theftData['alarmed_installed_date']) ||
                !empty($theftData['opening_closing_signals'])) {

                \AlphaDirect\Models\TheftGeneralQuestions::updateOrCreate(
                    [
                        'policy_coverage_id' => $coverage->id,
                    ],
                    [
                        'coverage_id'                      => $validated['coverage_id'],
                        'physical_protection_implemented'  => $theftData['physical_protection_implemented'] ?? '',
                        'premises_alarmed'                 => $theftData['premises_alarmed'] ?? '',
                        'subscribe_armed_security'         => $theftData['subscribe_armed_security'] ?? '',
                        'security_company'                 => $theftData['security_company'] ?? '',
                        'maintenance_contract'             => $theftData['maintenance_contract'] ?? '',
                        'alarmed_installed_date'           => $theftData['alarmed_installed_date'] ?? null,
                        'opening_closing_signals'          => $theftData['opening_closing_signals'] ?? '',
                    ]
                );
                Log::info('Inserted theft questions in addCoverage', ['coverage_id' => $coverage->id]);
            }
        }

        activity('Coverage')
            ->performedOn($policy)
            ->causedBy(auth()->user())
            ->log('Coverage Added: ' . ($validated['type_string'] ?? 'N/A'));

        return response()->json([
            'data'    => $coverage->fresh()->load('coverageDetail'),
            'message' => 'Coverage added successfully.',
        ], 201);
    }

    /**
     * Calculate premium for a coverage (without saving).
     */
    public function calculatePremium(Request $request, int $policyId): JsonResponse
    {
        // Lift PHP's default 60s execution limit. Rate sums 6 premium
        // buckets and writes per-line pro-rata across N coverages × M
        // detail/motor/extension rows. Large policies (>50 coverages)
        // legitimately need >60s.
        set_time_limit(300);
        ini_set('max_execution_time', '300');
        ini_set('memory_limit', '1024M');

        $validated = $request->validate([
            'coverage_id'    => 'nullable|integer',
            'coverage_value' => 'nullable|numeric|min:0',
            'rate'           => 'nullable|numeric|min:0',
            'action_id'      => 'nullable|integer',
        ]);

        // === Policy-level rating (Rate button on Policy Actions) ===
        // When coverage_id is null → sum all coverages for the action,
        // update action.premium, return total. Mirrors graphiteBWV8 Submit::calculatePremium().
        //
        // Wrapped in try/catch so a 500 from the Schema/specialist-table loop
        // returns a JSON error response (with CORS headers) rather than a raw
        // PHP fatal — which the browser reports as a misleading "CORS error".
        if (empty($validated['coverage_id'])) {
            try {
            $actionId = $validated['action_id'] ?? null;
            if (!$actionId) {
                $action = PolicyAction::where('policy_id', $policyId)->orderByDesc('id')->first();
                $actionId = $action?->id;
            } else {
                $action = PolicyAction::find($actionId);
            }

            if (!$action) {
                return response()->json(['error' => 'No policy action found'], 404);
            }

            // Policy needed downstream for the specialist-table product
            // guard. Load once here so the guard at line ~1755 has access.
            $policy = Policy::find($policyId);

            // Premium aggregation — mirrors legacy graphiteBWV8
            // Submit::calculatePremium so that Rate matches the figure the
            // PDF/blade and ledger compute later. Sums:
            //   1. policy_coverage_detail.calculated_value (sub-coverages)
            //   2. motor.calculated_value (per-vehicle)
            //   3. policy_extention_detail.extention_calculated_value (extensions)
            //   4. policy_specified_items.calculated_value (misc / specified)
            //   5. policy_coverages_data.premium (per-coverage breakdown rows
            //      used for fidelity / worker-comp / pet / etc — these go
            //      on policyCoverageID, NOT policy_coverage_id)
            //   6. specialist tables (EAR/CAR/PAR/PI/MM/Marine/MB)
            // The previous V2 implementation was undercounting by the sum
            // of #3 #4 #5 — large-premium policies with worker compensation
            // / extensions showed an annual ~25% lower than legacy.
            $pcIds = DB::table('policy_coverages')
                ->where('policy_id', $policyId)
                ->where('action_id', $actionId)
                ->whereNull('deleted_at')
                ->pluck('id');

            // Motor isolation applies only to coverage_id 22 (Commercial
            // Motor) and 27 (Personal Motor) — same scope as legacy
            // graphiteBWV8 ManageCoverages.php:3384. Motor Traders / other
            // motor variants continue to sum all 4 buckets normally.
            $motorCoverageIds = [22, 27];
            $motorPcIds = $pcIds->isEmpty()
                ? collect()
                : DB::table('policy_coverages')
                    ->whereIn('id', $pcIds)
                    ->whereIn('coverage_id', $motorCoverageIds)
                    ->pluck('id');
            $nonMotorPcIds = $pcIds->diff($motorPcIds);

            // Sub-coverages (policy_coverage_detail) — only summed for non-motor.
            // Minus any stale "Main" row on a specialist / Fidelity coverage:
            // that premium is already counted by $specialistPremium /
            // $coveragesDataPremium below, so leaving it here reports DOUBLE.
            // See sumDuplicateMainPremiumRows.
            $duplicateMainPremium = self::sumDuplicateMainPremiumRows($nonMotorPcIds);
            $totalPremium = $nonMotorPcIds->isEmpty()
                ? 0.0
                : (float) DB::table('policy_coverage_detail')
                    ->whereIn('policy_coverage_id', $nonMotorPcIds)
                    ->whereNull('deleted_at')
                    ->sum('calculated_value')
                  - $duplicateMainPremium;

            // Motor — calculated_value (OD) + every premium_* extension column.
            $motorPremium = 0.0;
            if ($pcIds->isNotEmpty()) {
                $motorRows = DB::table('motor')
                    ->whereIn('policy_coverage_id', $pcIds)
                    ->whereNull('deleted_at')
                    ->get();
                foreach ($motorRows as $m) {
                    $motorPremium += (float) ($m->calculated_value ?? 0)
                                  + self::sumMotorExtensionPremiums($m);
                }
            }

            // Section-level extensions (policy_extention_detail) — only for non-motor.
            // Motor extensions live in motor.premium_* columns above.
            // Sum extention_calculated_value across ALL extension types, not
            // just type='Extention'. That column is the extension PREMIUM, and
            // the save path stores premium on other types too (e.g. an Excess
            // or BurglarAlarmWarranty row — see store(), L2069). The FE per-row
            // Premium and per-coverage display already sum every type, so the
            // canonical annual MUST match or the edit-page Total / Rate / V2
            // Quote total drop that premium (e.g. policy 213667 Office Contents
            // lost a 400 BurglarAlarmWarranty extension → Total read 11,800
            // instead of 12,200). Non-premium types keep 0 here, so they're a
            // no-op.
            // DomCom (product 7/8) ONLY: Total Premium counts ONLY type='Extention'
            // rows. Every other extension type (Excess, BurglarAlarmWarranty,
            // FirstAmountPayable, Memoranda) is excluded — an excess is a
            // deductible, not a charge, and mis-attached foreign rows were
            // inflating totals (e.g. a 1,000,000,000 "All Glass" excess landing on
            // Public Liability → annual ~1bn). Other products sum all types.
            $isDomCom = in_array((int) ($policy->product_id ?? 0), [7, 8], true);
            $extPremium = $nonMotorPcIds->isEmpty()
                ? 0.0
                : (float) DB::table('policy_extention_detail')
                    ->whereIn('policy_coverage_id', $nonMotorPcIds)
                    ->whereNull('deleted_at')
                    ->when($isDomCom, fn ($q) => $q->where('type', 'Extention'))
                    ->sum('extention_calculated_value');

            $specifiedPremium = (float) DB::table('policy_specified_items')
                ->whereIn('policy_coverage_id', $pcIds)
                ->whereNull('deleted_at')
                ->sum('calculated_value');

            // policy_coverages_data — Fidelity Guarantee ONLY. Match the
            // V2 Quote Index map's Fidelity gate so this Rate-time canonical
            // doesn't sum stale non-Fidelity rows that the per-section
            // display ignores.
            $coveragesDataPremium = 0.0;
            if (\Schema::hasTable('policy_coverages_data') && !$pcIds->isEmpty()) {
                $fidelityPcIds = DB::table('policy_coverages as pc')
                    ->join('tb_cvgpccoverages as cv', 'cv.id', '=', 'pc.coverage_id')
                    ->whereIn('pc.id', $pcIds)
                    ->where('cv.s_CoverageCode', 'FIDELITYGUARANTEE')
                    ->pluck('pc.id');
                if ($fidelityPcIds->isNotEmpty()) {
                    $coveragesDataPremium = (float) DB::table('policy_coverages_data')
                        ->whereIn('policyCoverageID', $fidelityPcIds)
                        ->where('policy_id', $policyId)
                        ->sum('premium');
                }
            }

            // Sum specialist coverage tables (EAR/CAR/PAR + marine + professional
            // indemnity + medical malpractice + machinery breakdown + D&O).
            // Legacy ManageCoverages.php aggregates section totals into each
            // table's own total_premium (or section{N}_total_premium) column.
            //
            // Table map, column-combination rules and the product guard all
            // live in sumSpecialistPremium so recomputeActionTotals — the
            // OTHER writer to policy_actions.annual_premium — uses the exact
            // same recipe. When the two drifted, any non-Rate coverage edit
            // silently dropped this bucket from an already-rated annual.
            // Also gates the CANCEL refund formula (specialist products are
            // always date-based, never per-month) and the endorse pro-rata
            // specialist delta below.
            $skipSpecialist = !in_array((int) ($policy->product_id ?? 0), self::SPECIALIST_PRODUCT_IDS, true);
            $specialistPremium = self::sumSpecialistPremium(
                $pcIds,
                $policyId,
                $actionId,
                (int) ($policy->product_id ?? 0)
            );

            // Motor Traders Ext/Int premiums live in their own tables (one
            // row per policy_coverage with 14 *_calculated_value columns).
            // Folded into the Rate banner total so MT coverages show their
            // premium contribution alongside the other buckets.
            $motorTradersPremium = self::sumMotorTradersPremium($pcIds);

            $annualPremium = round(($totalPremium + $motorPremium + $extPremium + $specifiedPremium + $coveragesDataPremium + $specialistPremium + $motorTradersPremium), 2);

            // Pro-rata is ONLY for ENDORSE actions — every other transaction
            // type (NEWBUSINESS / RENEW / ANNIVERSARY-RENEW / REISSUE /
            // REINSTATE / CANCEL / EXTENSION-COVER / ENDORSE-RENEW) shows
            // the rated annual premium as-is. UW books the annual; the
            // ledger module handles instalment splits separately.
            //
            // For ENDORSE only:
            //   delta_annual = current.annual − source_state_action.annual
            //   factor       = current.days / source_state_action.days
            //   pro_rated    = delta × factor
            //
            // delta < 0 (e.g. cancelling a coverage) → negative pro-rata
            // (refund). delta > 0 (added/increased) → positive (charge).
            $proRataPremium = $annualPremium;
            $proRataFactor  = 1.0;

            // CANCEL pro-rata refund — frequency-wise as per dates.
            //   Annual    (freq=3)     → annualPremium × (daysFromCancel→termEnd / totalTermDays)
            //   Monthly   (freq=1,2,5) → (annualPremium ÷ 12) × (daysLeftInMonth / daysInMonth)
            // Stored as a NEGATIVE on policy_actions.premium because money flows
            // back to the customer. annual_premium column keeps the full-year
            // figure so the V2 Quote banner and ledger still reference it.
            if ($action->transaction_type === 'CANCEL'
                && $action->effective_from
                && $action->effective_to
                && $policy
                && $policy->term_start_date) {

                $cancelFrom = Carbon::parse($action->effective_from);
                $freq       = (int) ($policy->premium_freq ?? 3);

                // Specialist products (CAR/PAR/EAR/Marine/MM/PI/Travel) are paid
                // as an annual premium up front, so their cancel refund is ALWAYS
                // date-based: annual × (effective_from→term-end days ÷ total term
                // days) — regardless of premium_freq. Only genuinely monthly-billed
                // COM/DOM policies fall through to the per-month formula below
                // (unchanged), since they're collected month-by-month.
                if ($freq === 3 || !$skipSpecialist) {
                    // termEnd anchored on the action's effective_to — that's the
                    // operator-selected term boundary and may differ from
                    // policy.expiry_date if the policy record is stale.
                    $termEnd = Carbon::parse($action->effective_to);

                    // Term span comes from the state-establishing source action
                    // (NEWBUSINESS / RENEW / ANNIVERSARY-RENEW / REISSUE /
                    // REINSTATE) whose effective_to matches this CANCEL —
                    // that's the actual 365-day annual term being cancelled.
                    // policy.term_start_date is unreliable as a denominator
                    // source: it may be NULL (Carbon::parse(null) returns now,
                    // producing a partial-year span) or carry an inception
                    // date that pre-dates the current annual cycle. Either
                    // case shrinks totalTermDays below 365 and inflates the
                    // refund factor.
                    $stateTypes = ['NEWBUSINESS', 'ANNIVERSARY-RENEW', 'RENEW', 'REINSTATE', 'REISSUE'];
                    $sourceAction = PolicyAction::where('policy_id', $policyId)
                        ->where('id', '<', $action->id)
                        ->whereIn('transaction_type', $stateTypes)
                        ->where('effective_to', $action->effective_to)
                        ->orderByDesc('id')
                        ->first();

                    if ($sourceAction && $sourceAction->effective_from && $sourceAction->effective_to) {
                        $termStart = Carbon::parse($sourceAction->effective_from);
                        $totalTermDays = $termStart->diffInDays(Carbon::parse($sourceAction->effective_to)) + 1;
                    } elseif (!empty($policy->term_start_date)) {
                        $termStart = Carbon::parse($policy->term_start_date);
                        $totalTermDays = $termStart->diffInDays($termEnd) + 1;
                    } else {
                        $termStart = null;
                        $totalTermDays = 365;
                    }

                    $unexpiredDays = $cancelFrom->diffInDays($termEnd) + 1;
                    $proRataFactor = $totalTermDays > 0 ? ($unexpiredDays / $totalTermDays) : 0;
                    $refund        = $annualPremium * $proRataFactor;
                } else {
                    // Monthly-billed COM/DOM (freq=1,2,5): refund the unused
                    // portion of the CURRENT monthly billing PERIOD using that
                    // period's OWN premium. The period is the source
                    // NEWBUSINESS/RENEW whose effective_to matches this CANCEL
                    // (e.g. 26/06–25/07), NOT the calendar month — so a cancel on
                    // the period's start date (incl. inception, when NEWBUSINESS
                    // and CANCEL share a date) refunds the whole month, and the
                    // stored monthly premium is used as-is (no ÷12: it already is
                    // one month's charge). Previously this billed off the calendar
                    // month (e.g. June 1–30) and divided by 12, so an inception
                    // cancel on the 26th refunded only 5/30 of 1/12 of the premium
                    // (P33.51 instead of the full month's P2412.64).
                    $monthSource = PolicyAction::where('policy_id', $policyId)
                        ->where('id', '<', $action->id)
                        ->whereIn('transaction_type', ['NEWBUSINESS', 'ANNIVERSARY-RENEW', 'RENEW', 'REINSTATE', 'REISSUE'])
                        ->where('effective_to', $action->effective_to)
                        ->orderByDesc('id')
                        ->first();

                    $periodEnd     = Carbon::parse($action->effective_to);
                    $periodStart   = ($monthSource && $monthSource->effective_from)
                        ? Carbon::parse($monthSource->effective_from)
                        : $cancelFrom;
                    $periodPremium = ($monthSource && $monthSource->premium !== null)
                        ? (float) $monthSource->premium
                        : (float) $annualPremium;

                    $totalPeriodDays = $periodStart->diffInDays($periodEnd) + 1;
                    $unexpiredDays   = $cancelFrom->diffInDays($periodEnd) + 1;
                    $proRataFactor   = $totalPeriodDays > 0 ? ($unexpiredDays / $totalPeriodDays) : 0;
                    $refund          = $periodPremium * $proRataFactor;
                }

                // Cancel pro-rata is ALWAYS a refund (negative) — guard against
                // any upstream sign anomaly (negative annual_premium, weird
                // factor, etc.) by collapsing with -abs(). Spec: any cancel
                // transaction's pro-rata must be ≤ 0.
                $proRataPremium = -abs(round($refund, 2));

                \Log::info('CANCEL pro-rata', [
                    'policy_id'       => $policyId,
                    'action_id'       => $actionId,
                    'freq'            => $freq,
                    'term_start_raw'  => $policy->term_start_date,
                    'expiry_raw'      => $policy->expiry_date,
                    'effective_from_raw' => $action->effective_from,
                    'effective_to_raw'   => $action->effective_to,
                    'cancel_from_iso' => $cancelFrom->toDateString(),
                    'term_start_iso'  => isset($termStart) ? $termStart->toDateString() : null,
                    'term_end_iso'    => isset($termEnd) ? $termEnd->toDateString() : null,
                    'total_term_days' => $totalTermDays ?? null,
                    'unexpired_days'  => $unexpiredDays ?? null,
                    'days_in_month'   => $daysInMonth ?? null,
                    'days_left_month' => $daysLeftInMonth ?? null,
                    'factor'          => round($proRataFactor, 6),
                    'annual_premium'  => $annualPremium,
                    'refund'          => round($refund, 2),
                    'pro_rata_signed' => $proRataPremium,
                ]);
            }

            if ($action->transaction_type === 'ENDORSE'
                && $action->effective_from && $action->effective_to) {
                // ── diff_in_days_new_coverage ── current endorse period
                $newDays = Carbon::parse($action->effective_from)->diffInDays(Carbon::parse($action->effective_to)) + 1;

                // ── diff_in_days_main ── from the previous state-establishing
                // action that defines the BILLING period the endorse falls in.
                // Quarterly / monthly policies need the quarter/month source
                // (e.g. Q1 RENEW for a Q1 endorse, factor 90/90 = 1.0) — not
                // the annual NEWBUSINESS (which would give 90/365 ≈ 0.247 and
                // shrink the pro-rata to a quarter of what the customer
                // actually pays for that quarter's added coverage).
                //
                // Source-action selection priority:
                //   1. State action with SAME effective_to (quarterly billing
                //      match — Q1 endorse finds Q1 RENEW exactly).
                //   2. State action whose period CONTAINS the endorse start
                //      (mid-period endorse on a longer source).
                //   3. Most recent state action by id (legacy fallback).
                $stateTypes = ['NEWBUSINESS', 'ANNIVERSARY-RENEW', 'RENEW', 'REINSTATE', 'REISSUE'];
                $prev = PolicyAction::where('policy_id', $policyId)
                    ->where('id', '<', $action->id)
                    ->whereIn('transaction_type', $stateTypes)
                    ->where('effective_to', $action->effective_to)
                    ->orderByDesc('id')
                    ->first();
                if (!$prev) {
                    $prev = PolicyAction::where('policy_id', $policyId)
                        ->where('id', '<', $action->id)
                        ->whereIn('transaction_type', $stateTypes)
                        ->where('effective_from', '<=', $action->effective_from)
                        ->where('effective_to', '>=', $action->effective_from)
                        ->orderByDesc('id')
                        ->first();
                }
                if (!$prev) {
                    $prev = PolicyAction::where('policy_id', $policyId)
                        ->where('id', '<', $action->id)
                        ->whereIn('transaction_type', $stateTypes)
                        ->orderByDesc('id')
                        ->first();
                }

                $prevDays = ($prev && $prev->effective_from && $prev->effective_to)
                    ? (Carbon::parse($prev->effective_from)->diffInDays(Carbon::parse($prev->effective_to)) + 1)
                    : 365;
                // Pro-rata factor = newDays / prevDays. The source-action lookup
                // above already picks the correct billing-period source
                // (matching effective_to for quarterly/monthly RENEW; NEWBUSINESS
                // for annual), so prevDays already represents the billing
                // period — 91 for Q, 30 for M, 365/366 for Y — without an extra
                // /periodDays divide.
                //
                // Aligns with recomputeActionTotals (L4218) and the V2 Quote
                // canonical map ($_proRataFactor = $diff_in_days_new_coverage /
                // $diff_in_days_main, blade L743). Earlier this branch used a
                // hardcoded match(freq)=365 denominator for COM/DOM products
                // (7/8/16-22), which (a) disagreed with V2 Quote's 366-day
                // NEWBUSINESS span on annual policies and (b) could clamp to 1.0
                // when newDays >= 365, leaving Rate showing the unfactored full
                // annual delta (e.g. 1,000) while V2 Quote correctly showed
                // delta × factor (e.g. 748.63).
                $proRataFactor = $prevDays > 0 ? ($newDays / $prevDays) : 1.0;

                // Per-line pro_rate_premium MUST be written BEFORE we sum it
                // for the banner — writeLineLevelProRata stamps the deltas
                // (ADD: full new, CHANGE: new−old, CANCEL: −baseline) on
                // each row. We then sum those deltas × factor.
                static::writeLineLevelProRata($policyId, $actionId, $proRataFactor);
                $alreadyWroteLineLevel = true;

                // Banner = SUM(pro_rate_premium across all premium-bearing
                // tables for this action's coverages) × factor. This mirrors
                // the PDF spec's NET POSITION = sum of per-line pro-rata
                // amounts. The previous (current.annual − prev.annual) ×
                // factor formula gave wrong totals when only a subset of
                // tables changed (e.g. one MISC item added) because the
                // annual baseline could drift from the actual delta sum.
                // Pro-rata SUM must include cancelled (soft-deleted) parent
                // coverages — their child rows hold the negative-delta
                // pro_rate_premium that becomes the refund. Excluding them
                // here would silently drop coverage-level cancels from the
                // banner.
                $pcIdsForSum = DB::table('policy_coverages')
                    ->where('policy_id', $policyId)
                    ->where('action_id', $actionId)
                    ->pluck('id');
                if ($pcIdsForSum->isNotEmpty()) {
                    // Bucket scope MUST match the annual_premium recipe — otherwise
                    // a row stamped under a motor pc in policy_coverage_detail or
                    // policy_extention_detail (legacy/drift data) would inflate the
                    // pro-rata without showing in annual, producing a banner pair
                    // like Annual=4,054 / Pro-rata=1,173 with a mystery 391 delta.
                    // Annual splits detail/ext to non-motor pcs only and keeps
                    // motor in motor.* — pro-rata follows the same split.
                    $motorPcIdsForSum = DB::table('policy_coverages')
                        ->whereIn('id', $pcIdsForSum)
                        ->whereIn('coverage_id', [22, 27])
                        ->pluck('id');
                    $nonMotorPcIdsForSum = $pcIdsForSum->diff($motorPcIdsForSum);

                    // Only sum rows where the wizard explicitly marked this
                    // action — auto-detected diffs vs the source action
                    // don't count as user endorsements.
                    $deltaDetail = $nonMotorPcIdsForSum->isEmpty() ? 0.0 : (float) DB::table('policy_coverage_detail')
                        ->whereIn('policy_coverage_id', $nonMotorPcIdsForSum)
                        ->where('previousActionIdCov', $actionId)
                        ->sum('pro_rate_premium');
                    $deltaMotor = (float) DB::table('motor')
                        ->whereIn('policy_coverage_id', $pcIdsForSum)
                        ->where('previousActionIdCov', $actionId)
                        ->sum('pro_rate_premium');
                    $deltaExt = (\Schema::hasColumn('policy_extention_detail', 'pro_rate_premium') && $nonMotorPcIdsForSum->isNotEmpty())
                        ? (float) DB::table('policy_extention_detail')
                            ->whereIn('policy_coverage_id', $nonMotorPcIdsForSum)
                            ->where('previousActionIdCov', $actionId)
                            ->sum('pro_rate_premium')
                        : 0;
                    $deltaSpec = \Schema::hasColumn('policy_specified_items', 'pro_rate_premium')
                        ? (float) DB::table('policy_specified_items')
                            ->whereIn('policy_coverage_id', $pcIdsForSum)
                            ->where('previousActionIdCov', $actionId)
                            ->sum('pro_rate_premium')
                        : 0;
                    // Motor Traders Ext/Int — separate tables (14 premium
                    // columns each). pro_rate_premium holds the wizard-stamped
                    // row-total delta (see writeLineLevelProRata motor_traders
                    // block). Without this term, adding/changing motor traders
                    // during an ENDORSE silently dropped from the pro-rata
                    // banner while still contributing to annual_premium.
                    $deltaMt = \Schema::hasColumn('motor_traders', 'pro_rate_premium')
                        ? (float) DB::table('motor_traders')
                            ->whereIn('policy_coverage_id', $pcIdsForSum)
                            ->where('previousActionIdCov', $actionId)
                            ->sum('pro_rate_premium')
                        : 0;
                    $deltaMtInt = \Schema::hasColumn('motor_traders_internal', 'pro_rate_premium')
                        ? (float) DB::table('motor_traders_internal')
                            ->whereIn('policy_coverage_id', $pcIdsForSum)
                            ->where('previousActionIdCov', $actionId)
                            ->sum('pro_rate_premium')
                        : 0;
                    // Sum every wizard-stamped pro_rate_premium delta across the
                    // six buckets (detail, motor, ext, spec, mt, mt_internal)
                    // and apply the factor. Matches recomputeActionTotals and
                    // the V2 Quote canonical map (blade L892), so all three
                    // readers agree on the banner pro-rata.
                    //
                    // No motor-only clamp: legitimate specified-items added
                    // under a motor pc (e.g. ADDCOVG of a sub-coverage on
                    // Commercial Motor → specified_items.pro_rate_premium=delta)
                    // were being silently dropped by the old clamp, so Rate
                    // showed 0 (or the bare deltaMotor) while V2 Quote
                    // correctly summed them. Drift on specified_items is
                    // already gated by previousActionIdCov=actionId above —
                    // only wizard-touched rows contribute.
                    // Specialist tables (CAR/PAR/EAR/Travel/MM/PI/Machinery/
                    // Marine) hold premium in their own tables, so they never
                    // appear in the six buckets above — a specialist endorse
                    // banner-netted 0. Add their delta = this action − the
                    // IMMEDIATELY previous action (the same baseline
                    // writeLineLevelProRata uses, so ADD / CHANGE / CANCEL and
                    // stacked endorses all reconcile), both via the action-
                    // scoped helper; cancelled (soft-deleted) rows drop out →
                    // negative delta = refund. Same product guard as the annual
                    // recipe; a no-op for COM/DOM.
                    $deltaSpecialist = 0.0;
                    if (!$skipSpecialist) {
                        // Baseline = previous ISSUED state of the world in
                        // (effective_from, id) chronology, not "id - 1". A bare
                        // id-1 picks up an un-issued QUOTE / soft-deleted /
                        // future-dated action, so the delta (and the pro-rata on
                        // a newly added schedule item) is measured against a
                        // schedule the client was never on cover for. Same rule
                        // the Fidelity baseline below already applies.
                        $specPrev = SpecialistEndorseCalculator::baselineActionFor($policyId, $action);
                        $deltaSpecialist =
                            SpecialistEndorseCalculator::sumAnnualForAction((int) $actionId, (int) $action->term_id, (int) $policyId)
                            - ($specPrev && $specPrev->term_id
                                ? SpecialistEndorseCalculator::sumAnnualForAction((int) $specPrev->id, (int) $specPrev->term_id, (int) $policyId)
                                : 0.0);
                    }

                    // Fidelity Guarantee premium lives in policy_coverages_data,
                    // which none of the six line buckets nor writeLineLevelProRata
                    // cover — so a Fidelity cancel/edit was silently dropped from
                    // the pro-rata banner (refund showed only the misc items).
                    // Per-coverage delta keyed to the previous issued action by
                    // risk-address name (surrogate ids change on replication):
                    //   cancelled (soft-deleted) → refund THIS action's own
                    //     premium (matches the endorse screen / frontend row —
                    //     NOT the prior issued value, which can drift by a
                    //     rounding/duplicate cent);
                    //   new (no prev match)      → charge full this-action premium;
                    //   changed                  → this − prev.
                    // Separate queries throughout (no cross-connection join).
                    $fidPremiumForPc = function ($pcId) use ($policyId) {
                        return (float) DB::table('policy_coverages_data')
                            ->where('policyCoverageID', $pcId)
                            ->where('policy_id', $policyId)
                            ->sum('premium');
                    };
                    $fidPrevAct = PolicyAction::where('policy_id', $policyId)
                        ->where('id', '<', $actionId)->where('status', 'ISSUED')
                        ->orderByDesc('id')->first()
                        ?: PolicyAction::where('policy_id', $policyId)
                            ->where('id', '<', $actionId)->orderByDesc('id')->first();
                    $fidPrevByAddr = [];
                    if ($fidPrevAct) {
                        $prevFid = DB::table('policy_coverages as pc')
                            ->join('tb_cvgpccoverages as cv', 'cv.id', '=', 'pc.coverage_id')
                            ->leftJoin('risk_address as ra', 'ra.id', '=', 'pc.risk_address_id')
                            ->where('pc.policy_id', $policyId)
                            ->where('pc.action_id', $fidPrevAct->id)
                            ->whereNull('pc.deleted_at')
                            ->where('cv.s_CoverageCode', 'FIDELITYGUARANTEE')
                            ->get(['pc.id', 'ra.address_name']);
                        foreach ($prevFid as $pf) {
                            $k = trim((string) ($pf->address_name ?? ''));
                            $fidPrevByAddr[$k] = ($fidPrevByAddr[$k] ?? 0) + $fidPremiumForPc($pf->id);
                        }
                    }
                    $thisFid = DB::table('policy_coverages as pc')
                        ->join('tb_cvgpccoverages as cv', 'cv.id', '=', 'pc.coverage_id')
                        ->leftJoin('risk_address as ra', 'ra.id', '=', 'pc.risk_address_id')
                        ->where('pc.policy_id', $policyId)
                        ->where('pc.action_id', $actionId)
                        ->where('cv.s_CoverageCode', 'FIDELITYGUARANTEE')
                        ->get(['pc.id', 'pc.deleted_at', 'ra.address_name']);
                    $deltaFidelity = 0.0;
                    foreach ($thisFid as $tf) {
                        $k       = trim((string) ($tf->address_name ?? ''));
                        $thisVal = $fidPremiumForPc($tf->id);
                        if ($tf->deleted_at !== null) {
                            $deltaFidelity -= $thisVal;                                 // cancel → refund this-action premium
                        } else {
                            $deltaFidelity += $thisVal - ($fidPrevByAddr[$k] ?? 0.0);   // add / change
                        }
                    }

                    $deltaSum = $deltaDetail + $deltaMotor + $deltaExt + $deltaSpec + $deltaMt + $deltaMtInt + $deltaSpecialist + $deltaFidelity;
                    $proRataPremium = round($deltaSum * $proRataFactor, 2);
                } else {
                    $proRataPremium = 0;
                }
            }

            // Persist on the action:
            //   - policy_actions.annual_premium → full year (always)
            //   - policy_actions.premium        → ENDORSE: pro-rata,
            //                                     others: annual_premium
            // The V2 Quote PDF + frontend banner read .premium as the
            // billable amount for the transaction. Storing pro-rata in the
            // existing premium column avoids adding a new DB column.
            $billable = in_array($action->transaction_type, ['ENDORSE', 'CANCEL'], true)
                ? round($proRataPremium, 2)
                : $annualPremium;
            $updates = ['premium' => $billable];
            if (\Schema::hasColumn('policy_actions', 'annual_premium')) {
                $updates['annual_premium'] = $annualPremium;
            }
            $action->update($updates);

            // Per-line pro-rata — only mark rows that actually CHANGED vs
            // the previous ISSUED action. Replication carries every prior
            // line forward unchanged; setting endors_flag on every row
            // makes the V2 Quote sheet show pro-rata on lines the operator
            // didn't touch (e.g. Fire showing pro-rata when only Commercial
            // Motor was edited). Per spec section A/B/C/D: only the changed
            // line is pro-rated.
            // (writeLineLevelProRata is already called inside the ENDORSE
            // branch above so the per-row pro_rate_premium is available
            // when summing for the banner. NEWBUSINESS / RENEW / etc. don't
            // carry pro-rata columns in their PDF / blade output.)

            // NB: reinsurance recalc was previously triggered inline here, but
            // graphiteBWV8's Submit::calculatePremium() does no such thing —
            // rating is a plain SQL aggregation. The recalc was adding 60+ s
            // to the Rate response on DOMG/COMG (large treaty joins) and
            // landing as a 504 at the gateway. Reinsurance mapping now happens
            // on issue / on-demand via the dedicated endpoint, not during rate.

            activity('Policy Action')
                ->performedOn(Policy::find($policyId))
                ->causedBy(auth()->user())
                ->log('Rated — Premium: ' . $annualPremium);

            // Diagnostic: log the per-bucket breakdown that fed annual + pro-rata
            // so that a wrong banner total can be traced to a specific bucket
            // without DB access. Pro-rata side: also logs the source action,
            // newDays/prevDays, factor, and per-bucket pro_rate_premium sums.
            // Every bucket that feeds $annualPremium must appear here, or the
            // diagnostic stops being self-checking: `sum` is the figure on the
            // banner, so if the listed parts don't add up to it the breakdown
            // can't prove which bucket is wrong. motor_traders was missing.
            $diagAnnual = [
                'detail_non_motor' => round($totalPremium, 2),
                // Stale specialist/Fidelity Main rows excluded from the line
                // above. Non-zero means this policy predates the double-count
                // fix and still carries the duplicate row.
                'dup_main_excluded' => round($duplicateMainPremium, 2),
                'motor'            => round($motorPremium, 2),
                'motor_traders'    => round($motorTradersPremium, 2),
                'ext_non_motor'    => round($extPremium, 2),
                'specified_all'    => round($specifiedPremium, 2),
                'covdata_fidelity' => round($coveragesDataPremium, 2),
                'specialist'       => round($specialistPremium, 2),
                'sum'              => round($annualPremium, 2),
            ];
            $diagProRata = null;
            if ($action->transaction_type === 'ENDORSE') {
                $pcIdsForLog = DB::table('policy_coverages')
                    ->where('policy_id', $policyId)->where('action_id', $actionId)->pluck('id');
                $sumOrZero = function (string $table, $pcIds) use ($actionId) {
                    if ($pcIds->isEmpty()) return 0.0;
                    return (float) DB::table($table)
                        ->whereIn('policy_coverage_id', $pcIds)
                        ->where('previousActionIdCov', $actionId)
                        ->sum('pro_rate_premium');
                };
                $diagProRata = [
                    'prev_action_id'    => $prev?->id,
                    'new_days'          => $newDays ?? null,
                    'prev_days'         => $prevDays ?? null,
                    'factor'            => round($proRataFactor, 6),
                    'delta_detail'      => round($sumOrZero('policy_coverage_detail', $pcIdsForLog), 2),
                    'delta_motor'       => round($sumOrZero('motor', $pcIdsForLog), 2),
                    'delta_ext'         => \Schema::hasColumn('policy_extention_detail', 'pro_rate_premium')
                        ? round($sumOrZero('policy_extention_detail', $pcIdsForLog), 2) : 0,
                    'delta_spec'        => \Schema::hasColumn('policy_specified_items', 'pro_rate_premium')
                        ? round($sumOrZero('policy_specified_items', $pcIdsForLog), 2) : 0,
                    'delta_fidelity'    => round($deltaFidelity ?? 0, 2),
                    'pro_rate_premium'  => round($proRataPremium, 2),
                ];
            }
            \Log::info('Rate breakdown', [
                'policy_id'  => $policyId,
                'action_id'  => $actionId,
                'annual'     => $diagAnnual,
                'pro_rata'   => $diagProRata,
            ]);

            // High-level Logs-tab entry. The PolicyAction Auditable trait
            // already records the policy_actions.premium / annual_premium
            // diff; this row makes the operator action visible with a clear
            // tag plus the pro-rata so it's all in one place.
            $this->logCustomAudit(
                $policyId,
                'Rate Recomputed',
                [
                    'annual_premium'   => (float) $annualPremium,
                    'pro_rate_premium' => (float) $proRataPremium,
                    'action_id'        => $validated['action_id'] ?? null,
                    'breakdown'        => ['annual' => $diagAnnual, 'pro_rata' => $diagProRata],
                ],
                null,
                \AlphaDirect\Models\PolicyAction::class,
                $validated['action_id'] ?? null,
            );

            return response()->json([
                'annual_premium'   => $annualPremium,
                'pro_rate_premium' => $proRataPremium,
                'premium'          => $annualPremium,
                'message'          => 'Policy rated successfully.',
                // Same per-bucket breakdown already written to the Logs tab and
                // the laravel log. Returned so a disputed banner can be traced
                // to its bucket straight from the browser console — the Rate
                // button logs the whole response ([Rate] response) — without
                // needing server log or DB access. Diagnostic only: nothing in
                // the UI reads it.
                'breakdown'        => ['annual' => $diagAnnual, 'pro_rata' => $diagProRata],
            ]);
            } catch (\Throwable $e) {
                \Log::error('calculatePremium (policy-level) crash', [
                    'policy_id' => $policyId,
                    'action_id' => $validated['action_id'] ?? null,
                    'error'     => $e->getMessage(),
                    'trace'     => $e->getTraceAsString(),
                ]);
                return response()->json([
                    'error'   => 'Rating engine failed: ' . $e->getMessage(),
                    'detail'  => config('app.debug') ? $e->getTraceAsString() : null,
                ], 500);
            }
        }

        // === Per-coverage rating (legacy, used from Coverages tab) ===
        if (!isset($validated['coverage_value'])) {
            return response()->json(['error' => 'coverage_value is required for per-coverage rating'], 422);
        }

        $master = CoverageMaster::find($validated['coverage_id']);
        $rate = $validated['rate'] ?? ($master->rate ?? 0);
        $coverageValue = $validated['coverage_value'];

        $annualPremium = $rate > 0 ? ($coverageValue * $rate) / 100 : 0;
        $proRatePremium = $annualPremium;

        if ($validated['action_id'] ?? null) {
            $action = PolicyAction::find($validated['action_id']);
            if ($action && $action->effective_from && $action->effective_to) {
                $months = Carbon::parse($action->effective_from)->diffInMonths(Carbon::parse($action->effective_to));
                if ($months > 0 && $months < 12) {
                    $proRatePremium = ($annualPremium / 12) * $months;
                }
            }
        }

        return response()->json([
            'coverage_value'   => round($coverageValue, 2),
            // Keep 6-dp rate precision (rate columns are decimal(12,6)); rounding
            // to 4 dp here inflated premium on fine rates (e.g. 0.005593%).
            'rate'             => round($rate, 6),
            'annual_premium'   => round($annualPremium, 2),
            'pro_rate_premium' => round($proRatePremium, 2),
            'coverage_name'    => $master->s_CoverageName ?? null,
        ]);
    }

    /**
     * Update a coverage.
     */
    /**
     * Sync all coverages for a policy action — delete removed ones, update existing, add new.
     */
    public function syncCoverages(Request $request, int $policyId): JsonResponse
    {
        $policy = Policy::findOrFail($policyId);
        $action = \AlphaDirect\Models\PolicyAction::where('policy_id', $policyId)->orderBy('id', 'desc')->first();
        $term   = PolicyTerm::where('policy_id', $policyId)->orderBy('id', 'desc')->first();

        // This endpoint DELETES every coverage on the action that the payload
        // does not echo back, so it must never run against an issued action —
        // a stale or partial client list would silently discard issued cover.
        if ($action && ($r = $this->ensureActionEditable((int) $action->id))) return $r;

        $validated = $request->validate([
            'coverages'                    => 'required|array',
            'coverages.*.id'               => 'nullable|integer',
            'coverages.*.coverage_id'      => 'required|integer',
            'coverages.*.risk_address_id'  => 'required|integer',
            'coverages.*.coverage_value'   => 'nullable|numeric',
            'coverages.*.rate'             => 'nullable|numeric',
            'coverages.*.calculated_value' => 'nullable|numeric',
            'coverages.*.subcoverages'             => 'nullable|array',
            'coverages.*.subcoverages.*.detail_id' => 'nullable|integer',
        ]);

        $incomingIds = collect($validated['coverages'])->pluck('id')->filter()->toArray();

        // Delete coverages not in the incoming list (for this action)
        PolicyCoverage::where('policy_id', $policyId)
            ->when($action, fn($q) => $q->where('action_id', $action->id))
            ->whereNotIn('id', $incomingIds)
            ->each(function ($cov) {
                PolicyCoverageDetail::where('policy_coverage_id', $cov->id)->delete();
                $cov->delete();
            });

        // Block singleton-family duplicates (CAR/EAR/PAR/MB/MM/PI/D&O/Marine
        // Open/Marine Once-Off/Travel): at most one row per (risk_address,
        // family, action). Mirror the addCoverage/reinstateCoverage guard so
        // bulk-save paths can't bypass the rule.
        $singletonFamilies = self::singletonCoverageFamilies();
        $familyByCovId = [];
        foreach ($singletonFamilies as $familyLabel => $codes) {
            $ids = CoverageMaster::whereIn('s_CoverageCode', $codes)->pluck('id')->all();
            foreach ($ids as $cid) { $familyByCovId[(int) $cid] = $familyLabel; }
        }
        $newSingletonsThisRequest = [];
        foreach ($validated['coverages'] as $covData) {
            if (!empty($covData['id'])) continue; // updates can't introduce duplicates
            $covId = (int) $covData['coverage_id'];
            $familyLabel = $familyByCovId[$covId] ?? null;
            if (!$familyLabel) continue;
            $raId = (int) $covData['risk_address_id'];
            $familyCodeIds = array_keys(array_filter($familyByCovId, fn($f) => $f === $familyLabel));
            $existsInDb = PolicyCoverage::where('policy_id', $policyId)
                ->where('risk_address_id', $raId)
                ->whereIn('coverage_id', $familyCodeIds)
                ->when($action, fn($q) => $q->where('action_id', $action->id))
                ->whereIn('id', $incomingIds ?: [0]) // only count rows the request is keeping
                ->whereNull('deleted_at')
                ->exists();
            $key = $familyLabel . '|' . $raId;
            $existsInRequest = !empty($newSingletonsThisRequest[$key]);
            if ($existsInDb || $existsInRequest) {
                return response()->json([
                    'error'   => "This risk address already has a {$familyLabel} coverage. Only one {$familyLabel} coverage is allowed per risk address.",
                    'message' => "This risk address already has a {$familyLabel} coverage. Only one {$familyLabel} coverage is allowed per risk address.",
                ], 422);
            }
            $newSingletonsThisRequest[$key] = true;
        }

        // One-to-one Risk Address ↔ Coverage rule for the specialist single-site
        // products (16/17/18/20/22): a risk address may hold only ONE coverage
        // of ANY type. This bulk save reconciles to exactly the incoming list,
        // so each risk address may appear at most once. Stricter than the
        // per-family guard above (which only blocks same-family duplicates).
        if (in_array((int) $policy->product_id, [16, 17, 18, 20, 22], true)) {
            $countByAddress = [];
            foreach ($validated['coverages'] as $covData) {
                $raId = (int) $covData['risk_address_id'];
                $countByAddress[$raId] = ($countByAddress[$raId] ?? 0) + 1;
            }
            foreach ($countByAddress as $raId => $count) {
                if ($count > 1) {
                    $addrName = optional(RiskAddress::find($raId))->address_name ?: 'this risk address';
                    return response()->json([
                        'error'   => "Risk address \"{$addrName}\" can have only one coverage. Only one coverage is allowed per risk address.",
                        'message' => "Risk address \"{$addrName}\" can have only one coverage. Only one coverage is allowed per risk address.",
                    ], 422);
                }
            }
        }

        // Update existing / create new
        $savedIds = [];
        foreach ($validated['coverages'] as $covData) {
            if (!empty($covData['id'])) {
                // Update existing — preserve detail rows user didn't touch
                $cov = PolicyCoverage::find($covData['id']);
                if ($cov) {
                    if (!empty($covData['subcoverages'])) {
                        // Upsert each subcoverage detail row by coverage_id match
                        $totalCovVal = 0;
                        $totalCalc   = 0;
                        $touchedDetailIds = [];
                        foreach ($covData['subcoverages'] as $sub) {
                            $covVal  = (float) ($sub['coverage_value']   ?? 0);
                            $calcVal = (float) ($sub['calculated_value'] ?? 0);
                            $subCovId = $sub['sub_coverage_id'] ?? $sub['id'] ?? $covData['coverage_id'];
                            $totalCovVal += $covVal;
                            $totalCalc   += $calcVal;

                            // Try to find existing detail row by detail DB id or coverage_id
                            $detailId = $sub['detail_id'] ?? null;
                            $existing = $detailId
                                ? PolicyCoverageDetail::find($detailId)
                                : PolicyCoverageDetail::where('policy_coverage_id', $cov->id)
                                    ->where('coverage_id', $subCovId)
                                    ->whereNull('deleted_at')
                                    ->first();

                            // pro_rate_premium owned by Rate's
                            // writeLineLevelProRata — don't stamp it here.
                            $detailData = [
                                'coverage_value'     => $covVal,
                                'rate'               => (float) ($sub['rate'] ?? 0),
                                'calculated_value'   => $calcVal,
                                'coverage_value_string' => $sub['coverage_value_string'] ?? null,
                                'type_id'            => $sub['limit_id'] ?? null,
                                'ratefactor_type'    => $sub['ratefactor_type'] ?? null,
                                'ratefactor_value'   => $sub['ratefactor_value'] ?? null,
                                'ratefactor_value_check' => $sub['ratefactor_value_check'] ?? null,
                                'ratefactor_AnnualWages' => $sub['ratefactor_AnnualWages'] ?? null,
                                'ratefactor_deposit_min_pre' => $sub['ratefactor_deposit_min_pre'] ?? null,
                                'discount_surcharge'  => $sub['discount_surcharge'] ?? '',
                                'discount_surcharge_type' => $sub['discount_surcharge_type'] ?? '',
                                'discount_surcharge_value' => $sub['discount_surcharge_value'] ?? 0,
                            ];

                            if ($existing) {
                                $existing->update($detailData);
                                $touchedDetailIds[] = $existing->id;
                            } else {
                                $detailData['policy_coverage_id'] = $cov->id;
                                $detailData['coverage_id'] = $subCovId;
                                $newDetail = PolicyCoverageDetail::create($detailData);
                                $touchedDetailIds[] = $newDetail->id;
                            }
                        }
                        // Recalculate parent totals
                        $cov->update([
                            'coverage_value'   => round($totalCovVal, 2),
                            'calculated_value' => round($totalCalc, 2),
                        ]);
                    } elseif (isset($covData['coverage_value'])) {
                        // No subcoverages sent — don't touch existing details, just update parent if values provided
                        $cv = (float) $covData['coverage_value'];
                        $calc = (float) ($covData['calculated_value'] ?? 0);
                        if ($cv > 0 || $calc > 0) {
                            $cov->update([
                                'coverage_value'   => $cv,
                                'calculated_value' => $calc,
                            ]);
                        }
                        // Leave existing policy_coverage_detail rows untouched
                    }
                    $savedIds[] = $cov->id;
                }
            } else {
                // Create new
                $cov = PolicyCoverage::create([
                    'policy_id'       => $policyId,
                    'coverage_id'     => $covData['coverage_id'],
                    'risk_address_id' => $covData['risk_address_id'],
                    'action_id'       => $action?->id,
                    'term_id'         => $term?->id,
                    'row_type'        => 'NEW',
                ]);
                if (!empty($covData['subcoverages'])) {
                    // pro_rate_premium owned by Rate (writeLineLevelProRata).
                    foreach ($covData['subcoverages'] as $sub) {
                        PolicyCoverageDetail::create([
                            'policy_coverage_id' => $cov->id,
                            'coverage_id'        => $sub['sub_coverage_id'] ?? $sub['id'] ?? $covData['coverage_id'],
                            'coverage_value'     => $sub['coverage_value'] ?? 0,
                            'rate'               => $sub['rate'] ?? 0,
                            'calculated_value'   => $sub['calculated_value'] ?? 0,
                            'coverage_value_string' => $sub['coverage_value_string'] ?? null,
                        ]);
                    }
                }
                $savedIds[] = $cov->id;
            }
        }

        activity('Coverage')->performedOn($policy)->causedBy(auth()->user())->log('Coverages synced: ' . count($savedIds) . ' coverages');

        return response()->json(['message' => count($savedIds) . ' coverages updated successfully.', 'count' => count($savedIds)]);
    }

    /**
     * Reject mutations on coverages whose action is past QUOTE. Mirrors
     * legacy graphiteBWV8 EditWizard — an ISSUED/APPROVED action is frozen
     * until the user Unissues it. Returns null on OK, a JsonResponse on
     * reject.
     */
    /**
     * DOM/COM CRITICAL-02 — return created_by/updated_by stamps for raw
     * DB::table()->insert() sites. Eloquent paths get the stamps via the
     * model booted() hooks instead. Only emits columns that exist on the
     * target table so installs that haven't run the audit-columns
     * migration keep working.
     */
    private function auditStamps(string $table): array
    {
        $uid = auth()->id();
        if (!$uid) return [];
        $out = [];
        if (\Schema::hasColumn($table, 'created_by')) $out['created_by'] = $uid;
        if (\Schema::hasColumn($table, 'updated_by')) $out['updated_by'] = $uid;
        return $out;
    }

    /**
     * Free-text columns other than `note` that share the coverage-level
     * policy_coverage_notes row. Only the ones this codebase writes.
     */
    private const COVERAGE_NOTE_TEXT_COLUMNS = [
        'memoranda_warranty', 'cash_warranty', 'burglar_warranty',
        'endorsements', 'benefits_note',
    ];

    /**
     * The ONE coverage-level policy_coverage_notes row for a coverage —
     * `note`, the Money warranties and the WC benefits text all belong on it.
     * Coverage-level means motor_id NULL *or* 0 (legacy and replicated rows
     * store 0; the V2 insert leaves the column at its default), which is why
     * every caller must go through coverageLevel() rather than a bare
     * whereNull('motor_id') — the NULL-only lookup misses motor_id = 0 rows
     * and inserts a duplicate that then shadows the real note on read.
     *
     * Returns an unsaved model when the coverage has no row yet — seeded with
     * note = '' because policy_coverage_notes.note is NOT NULL with no
     * default, so a warranty-only insert would fail under strict mode.
     */
    private function coverageLevelNoteRow(int $coverageId): \AlphaDirect\Models\PolicyCoverageNote
    {
        return \AlphaDirect\Models\PolicyCoverageNote::where('policy_coverage_id', $coverageId)
            ->coverageLevel()->orderBy('id')->first()
            ?? new \AlphaDirect\Models\PolicyCoverageNote([
                'policy_coverage_id' => $coverageId,
                'note'               => '',
            ]);
    }

    /**
     * Copy any text the duplicate coverage-level note rows still hold onto the
     * row we keep, so consolidating them is never a data loss. Only fills
     * columns that are blank on the kept row — an edit in this request wins.
     */
    private function absorbDuplicateCoverageNotes(\AlphaDirect\Models\PolicyCoverageNote $keep, $duplicates): void
    {
        if ($duplicates->isEmpty()) return;
        $carry = [];
        foreach (self::COVERAGE_NOTE_TEXT_COLUMNS as $col) {
            if (!\Schema::hasColumn('policy_coverage_notes', $col)) continue;
            if (trim((string) ($keep->{$col} ?? '')) !== '') continue;
            foreach ($duplicates as $dup) {
                if (trim((string) ($dup->{$col} ?? '')) !== '') $carry[$col] = $dup->{$col};
            }
        }
        if ($carry) $keep->forceFill($carry)->save();
    }

    /** True when the note row still holds text in a column other than `note`. */
    private function coverageNoteCarriesOtherText(\AlphaDirect\Models\PolicyCoverageNote $row): bool
    {
        foreach (self::COVERAGE_NOTE_TEXT_COLUMNS as $col) {
            if (!\Schema::hasColumn('policy_coverage_notes', $col)) continue;
            if (trim((string) ($row->{$col} ?? '')) !== '') return true;
        }
        return false;
    }

    /**
     * Write a single high-level entry to the OwenIt `audits` table so the
     * Logs tab shows a labelled action ("Risk Address Cancelled", "Rate
     * Recomputed", etc.) without us having to flood the table with one row
     * per child mutation. Used by bulk endpoints that intentionally
     * DB::table-update many rows for performance.
     *
     * old/new are arrays — encoded to JSON inline. Pass null to skip the
     * column entirely (keeps audit row light).
     */
    private function logCustomAudit(int $policyId, string $tag, ?array $newValues = null, ?array $oldValues = null, ?string $auditableType = null, ?int $auditableId = null): void
    {
        $policyNumber = DB::table('policies')->where('id', $policyId)->value('policyNumber');
        if (!$policyNumber) return;
        DB::table('audits')->insert([
            'event'          => 'updated',
            'auditable_type' => $auditableType ?? \AlphaDirect\Policy::class,
            'auditable_id'   => $auditableId ?? $policyId,
            'tags'           => $tag,
            'old_values'     => $oldValues !== null ? json_encode($oldValues) : null,
            'new_values'     => $newValues !== null ? json_encode($newValues) : null,
            'user_id'        => auth()->id(),
            'user_type'      => \AlphaDirect\User::class,
            'policy_id'      => $policyId,
            'policy_number'  => $policyNumber,
            'ip_address'     => request()?->ip(),
            'url'            => request()?->fullUrl(),
            'user_agent'     => request()?->userAgent(),
            'created_at'     => now(),
            'updated_at'     => now(),
        ]);
    }

    /**
     * Write per-line pro_rate_premium per the Alpha Direct Endorsement
     * Pro-Rata spec (date-driven denominator, never hardcode 365).
     *
     * Spec mapping (PDF page 1 Core formula):
     *   total_policy_days = source.effective_to − source.effective_from + 1
     *                       (handles 365 / 366 / 90 / 91 / 28 / 31 etc.)
     *   unused_days       = source.effective_to − endorse.effective_from + 1
     *   factor            = unused_days / total_policy_days
     *
     *   ADD (no prev row):    pro_rate = full new × factor
     *   CHANGE (delta only):  pro_rate = (new − old) × factor
     *   CANCEL (row deleted): pro_rate = −baseline × factor (negative)
     *
     * IMPORTANT — pro_rate_premium stores the ANNUAL DELTA, not the pro-
     * rated amount. The blade applies `(diff_in_days_new_coverage /
     * diff_in_days_main)` at display time (legacy graphiteBWV8
     * v2-quote-sheet.blade.php lines 818, 950, 1274, 1291). Storing the
     * pre-multiplied value here would double-pro-rata the figure.
     * Untouched rows get pro_rate_premium = 0 and endors_flag = 0 so the
     * V2 Quote / Policy Doc blades don't show pro-rata charges on lines
     * the operator never edited.
     *
     * Match key:
     *   policy_coverage_detail → (parent_coverage.coverage_id, risk_address_id, sub-coverage_id)
     *   motor                  → (parent_coverage.coverage_id, risk_address_id, registration_no)
     *   policy_extention_detail → (parent_coverage.coverage_id, risk_address_id, extention master id)
     *
     * Delta semantics:
     *   delta == 0 → endors_flag=0, pro_rate_premium=0 (untouched)
     *   delta > 0  → endors_flag=1, pro_rate_premium=delta (charge)
     *   delta < 0  → endors_flag=1, pro_rate_premium=delta (refund, negative)
     *
     * @param  float  $factor  retained on signature for callers that want the
     *                         display-time factor; intentionally unused here.
     */
    private static function writeLineLevelProRata(int $policyId, int $actionId, float $factor): void
    {
        unset($factor); // pro_rate_premium = annual delta only — see docblock
        // Baseline = the state committed immediately before this action ON
        // THE TIMELINE — ordered by (effective_from, id), never by id alone.
        // This is the SAME action the endorse was replicated from
        // (newTransaction's source-action selection, ~L11800), so the
        // per-line value delta (newVal − prevVal) compares the current rows
        // against the exact state they were copied from — the policy's
        // committed state.
        //
        // CHRONOLOGY FIX (2026-08-08, policy 120909). newTransaction was moved
        // to the date-then-id key (PolicyAction::inForceAt) but this lookup
        // was not, so the two disagreed on a BACK-DATED endorse: the endorse
        // was replicated from the ISSUED ENDORSE in force at its effective
        // date, while the baseline took the highest-id ISSUED action — a
        // FUTURE quarterly RENEW whose coverage tree was generated BEFORE
        // that endorse existed and therefore does not contain its lines.
        // Every coverage added by endorse 1/2 then missed its baseline and
        // was re-charged at full value as "ADDED" on endorse 3 (Accidental
        // Damage / Business Interruption, 01/01/2026 endorse sitting behind
        // the 01/04 + 01/07 RENEWs). Bounding on (effective_from, id) keeps
        // same-date siblings chaining 1 → 2 → 3 by id — self is excluded
        // below, so the inclusive id bound behaves as a strict one — while
        // future-dated actions can no longer become the baseline.
        //
        // It still produces the right reinstate delta: a per-vehicle/coverage
        // cancel is committed on an ISSUED ENDORSE (the row is deleted there,
        // val=0), so reinstating in the next endorse reads prevVal=0 from that
        // issued cancel → delta=+X. Same-action cancel-then-reinstate stays at
        // delta=0 because the baseline (the issued source) still has the row
        // active at val=X.
        //
        // Why NOT the immediately-previous action of ANY status (the old
        // rule): a stack of abandoned QUOTE endorsements (e.g. unissued
        // COVERAGECANCEL / SUBCOVCANCEL attempts whose whole coverage pc is
        // soft-deleted) would become the baseline. The prev-coverage lookup
        // below filters whereNull('pc.deleted_at'), finds nothing, every
        // prevVal collapses to 0, and a genuine cancel nets delta=0 (no
        // refund) instead of −baseline. Sourcing from the latest ISSUED
        // action skips those dead quotes. For policies endorsed-and-issued in
        // sequence the latest ISSUED IS the immediately-previous action, so
        // normal flows are unchanged.
        $thisAction = \AlphaDirect\Models\PolicyAction::find($actionId);

        // Prior-state query, bounded to this action's position on the timeline.
        // $issuedOnly=false is the fallback tier (any status). Falls back to the
        // pure id walk only when the action has no effective_from to bound on.
        $priorStateQuery = function (bool $issuedOnly) use ($policyId, $actionId, $thisAction) {
            $q = \AlphaDirect\Models\PolicyAction::where('policy_id', $policyId)
                ->when($issuedOnly, fn ($w) => $w->where('status', 'ISSUED'));

            if ($thisAction && $thisAction->effective_from) {
                return \AlphaDirect\Models\PolicyAction::applyUpperBound($q, $thisAction)
                    ->where('id', '!=', $actionId)
                    ->orderByDesc('effective_from')
                    ->orderByDesc('id');
            }

            return $q->where('id', '<', $actionId)->orderByDesc('id');
        };

        $prev = $priorStateQuery(true)->first();
        // Fallback: no ISSUED ancestor at all (e.g. first endorse on a policy
        // still in QUOTE) — fall back to the immediately-previous action of
        // any status so a brand-new policy still gets an ADD baseline.
        if (!$prev) {
            $prev = $priorStateQuery(false)->first();
        }

        // No prior issued action — every line is "new", treat as ADD.
        // pro_rate_premium = full annual value (matches legacy Case 1).
        if (!$prev) {
            $coverageIds = DB::table('policy_coverages')
                ->where('policy_id', $policyId)->where('action_id', $actionId)
                ->whereNull('deleted_at')->pluck('id');
            if ($coverageIds->isEmpty()) return;
            DB::table('policy_coverage_detail')
                ->whereIn('policy_coverage_id', $coverageIds)->whereNull('deleted_at')
                ->update([
                    'pro_rate_premium'    => DB::raw("calculated_value"),
                    'endors_flag'         => 1,
                    'previousActionIdCov' => $actionId,
                    'updated_at'          => now(),
                ]);
            DB::table('motor')
                ->whereIn('policy_coverage_id', $coverageIds)->whereNull('deleted_at')
                ->update([
                    'pro_rate_premium' => DB::raw("calculated_value"),
                    'endors_flag'      => 1,
                    'updated_at'       => now(),
                ]);
            return;
        }

        // Build prev → (coverage_id, risk_address.address_name) → pc_id map.
        // Replication creates NEW risk_address rows for the new action with
        // their own surrogate ids, so matching by risk_address_id always
        // misses (every line treated as "new" → full pro_rate_premium on
        // every row, endors_flag=1 across the board). The address NAME
        // survives replication unchanged, so we key on that. Mirrors legacy
        // ManageCoverages::submit() which joins risk_address.address_name
        // for the prev-state lookup.
        $prevCoverages = DB::table('policy_coverages as pc')
            ->leftJoin('risk_address as ra', 'ra.id', '=', 'pc.risk_address_id')
            ->where('pc.policy_id', $policyId)
            ->where('pc.action_id', $prev->id)
            ->whereNull('pc.deleted_at')
            ->get(['pc.id', 'pc.coverage_id', 'pc.risk_address_id', 'ra.address_name']);
        $prevPcIdByKey = [];
        foreach ($prevCoverages as $pc) {
            $key = $pc->coverage_id . '|' . trim((string) ($pc->address_name ?? ''));
            $prevPcIdByKey[$key] = $pc->id;
        }

        // Walk new coverages → for each, find prev match → diff lines.
        // Include cancelled (soft-deleted) parent coverages too — when a
        // whole coverage is cancelled, its parent pc row has deleted_at set
        // and its child detail/motor/etc rows hold the negative-delta
        // pro_rate_premium that we must stamp + sum for the refund.
        $newCoverages = DB::table('policy_coverages as pc')
            ->leftJoin('risk_address as ra', 'ra.id', '=', 'pc.risk_address_id')
            ->where('pc.policy_id', $policyId)
            ->where('pc.action_id', $actionId)
            ->get(['pc.id', 'pc.coverage_id', 'pc.risk_address_id', 'ra.address_name']);

        // Performance: bulk-reset every detail/motor/extension row in this
        // action's coverages to (pro_rate_premium=0, endors_flag=0) in 3
        // queries. The per-row updates below then only fire for rows with
        // a non-zero delta, which is typically a tiny fraction of the
        // total. Without this we did N×M individual UPDATEs (~1000+ for
        // a Saleys-sized policy) and Rate timed out at 60s.
        // Bulk-reset only pro_rate_premium. endors_flag + previousActionIdCov
        // are now wizard-owned: the wizard endpoints (updateCoverage,
        // updateCoverageDetail, addCoverage, deleteCoverageDetail, etc.)
        // stamp them when the user actually touches a row. Rate doesn't
        // auto-flag anything anymore — it only computes the pro-rata delta
        // for rows the wizard already marked. This stops auto-detected diffs
        // (e.g. drift, replication-side mutations) from being treated as
        // user endorsements.
        $allCoverageIds = $newCoverages->pluck('id')->all();
        $prevPcIds      = collect($prevPcIdByKey)->values()->all();
        if (!empty($allCoverageIds)) {
            // ── Self-healing backfill (motor *_main columns) ──────────
            // Motor rows created via a legacy path (or before the
            // addMotorVehicle stamp was added) can have all-NULL *_main
            // columns. The V2 Quote Sheet motor schedule reads use_main /
            // type_of_cover_main / coverage_value_main / calculated_value_main
            // for display, and pro-rata case logic uses them as the
            // baseline. Backfill from current values when NULL so every
            // row has a usable baseline before pro-rata runs.
            DB::table('motor')
                ->whereIn('policy_coverage_id', $allCoverageIds)
                ->whereNull('deleted_at')
                ->whereNull('use_main')
                ->update([
                    'use_main'              => DB::raw('`use`'),
                    'type_of_cover_main'    => DB::raw('type_of_cover'),
                    'coverage_value_main'   => DB::raw('coverage_value'),
                    'calculated_value_main' => DB::raw('calculated_value'),
                    'updated_at'            => now(),
                ]);

            DB::table('policy_coverage_detail')
                ->whereIn('policy_coverage_id', $allCoverageIds)
                ->update(['pro_rate_premium' => 0, 'updated_at' => now()]);
            DB::table('motor')
                ->whereIn('policy_coverage_id', $allCoverageIds)
                ->update(['pro_rate_premium' => 0, 'updated_at' => now()]);
            if (\Schema::hasColumn('policy_extention_detail', 'pro_rate_premium')) {
                DB::table('policy_extention_detail')
                    ->whereIn('policy_coverage_id', $allCoverageIds)
                    ->update(['pro_rate_premium' => 0, 'updated_at' => now()]);
            }
            if (\Schema::hasColumn('policy_specified_items', 'pro_rate_premium')) {
                DB::table('policy_specified_items')
                    ->whereIn('policy_coverage_id', $allCoverageIds)
                    ->update(['pro_rate_premium' => 0, 'updated_at' => now()]);
            }
            // motor_traders / motor_traders_internal — one row per pc holds 14
            // _calculated_value premium columns. Bulk reset pro_rate_premium so
            // only wizard-touched rows (previousActionIdCov = actionId) end up
            // with a non-zero delta after the per-pc loop below.
            foreach (['motor_traders', 'motor_traders_internal'] as $mtTbl) {
                if (\Schema::hasColumn($mtTbl, 'pro_rate_premium')) {
                    DB::table($mtTbl)
                        ->whereIn('policy_coverage_id', $allCoverageIds)
                        ->update(['pro_rate_premium' => 0, 'updated_at' => now()]);
                }
            }
        }

        // Performance: batch fetch ALL details/motors/extensions for the
        // current action's coverages AND the previous action's coverages
        // up-front, group by policy_coverage_id, then loop without
        // hitting the DB per coverage. Previously this was N+1 (6
        // queries per coverage) — for 100-coverage policies that's 600
        // round-trips just for fetches, on top of the per-row updates.
        $newDetailsByPc = !empty($allCoverageIds)
            ? DB::table('policy_coverage_detail')
                ->whereIn('policy_coverage_id', $allCoverageIds)
                ->get(['id', 'policy_coverage_id', 'coverage_id', 'calculated_value', 'deleted_at', 'previousActionIdCov'])
                ->groupBy('policy_coverage_id')
            : collect();
        // Two guards mirror the motor baseline lookup ($prevMotorValByReg):
        //  1. Phantom exclusion — a detail row under a PRIOR issued coverage
        //     but stamped with the CURRENT action's id was forward-propagated
        //     there by this endorse's propagation. It equals the current
        //     value, so it would collapse a genuine delta to 0. Genuine prior
        //     state carries an older / null / different action id. Same guard
        //     as the motor $prevMotorValByReg lookup above.
        //  2. orderByDesc('id') + the array_key_exists tie-break in the build
        //     loop below make "newest active wins" deterministic when a prior
        //     coverage carries duplicate detail rows for the same coverage_id.
        $prevDetailsByPc = !empty($prevPcIds)
            ? DB::table('policy_coverage_detail')
                ->whereIn('policy_coverage_id', $prevPcIds)->whereNull('deleted_at')
                ->where(function ($q) use ($actionId) {
                    $q->whereNull('previousActionIdCov')
                      ->orWhere('previousActionIdCov', '!=', $actionId);
                })
                ->orderByDesc('id')
                ->get(['id', 'policy_coverage_id', 'coverage_id', 'calculated_value'])
                ->groupBy('policy_coverage_id')
            : collect();

        // Stable-identity map for the sub-coverage baseline FALLBACK below.
        // The primary match keys on the surrogate coverage_id, but an ENDORSE
        // builds fresh detail rows from the FE payload and a sub-coverage can
        // arrive with a NEW coverage_id (re-cloned on edit). That made a genuine
        // value CHANGE miss its baseline and get over-charged as a full-value
        // ADD (policy 130274 Fire). The coverage master's code survives the
        // clone, so we map coverage_id → stable code (s_CoverageCode, else
        // s_ScreenName / s_CoverageName) and use it ONLY as a 1:1 unambiguous
        // fallback in the detail loop — it can never mis-pair rows.
        $detailCodeById = [];
        $allDetailCoverageIds = [];
        foreach ($newDetailsByPc as $rows) foreach ($rows as $r) $allDetailCoverageIds[(int) $r->coverage_id] = true;
        foreach ($prevDetailsByPc as $rows) foreach ($rows as $r) $allDetailCoverageIds[(int) $r->coverage_id] = true;
        if (!empty($allDetailCoverageIds)) {
            $hasCode = \Schema::hasColumn('tb_cvgpccoverages', 's_CoverageCode');
            $hasName = \Schema::hasColumn('tb_cvgpccoverages', 's_CoverageName');
            $codeSel = ['id', 's_ScreenName'];
            if ($hasCode) $codeSel[] = 's_CoverageCode';
            if ($hasName) $codeSel[] = 's_CoverageName';
            foreach (DB::table('tb_cvgpccoverages')->whereIn('id', array_keys($allDetailCoverageIds))->get($codeSel) as $m) {
                $code = ($hasCode ? trim((string) ($m->s_CoverageCode ?? '')) : '');
                if ($code === '') $code = trim((string) ($m->s_ScreenName ?? ''));
                if ($code === '' && $hasName) $code = trim((string) ($m->s_CoverageName ?? ''));
                if ($code !== '') $detailCodeById[(int) $m->id] = $code;
            }
        }
        // Pull every premium_* extension column too so total premium per
        // vehicle = calculated_value + sum(extensions). Pro-rata delta on
        // motor compares totals so a change to any extension still
        // generates a delta even when calculated_value is unchanged.
        // engine_number / chassis_number are read only by the registration-
        // correction pairing below (they identify the vehicle when its plate
        // was amended); they take no part in any premium sum.
        $motorBaseCols   = ['id', 'policy_coverage_id', 'registration_no', 'engine_number', 'chassis_number', 'make', 'model', 'calculated_value', 'deleted_at', 'previousActionIdCov'];
        $motorFetchCols  = array_merge($motorBaseCols, self::MOTOR_EXTENSION_PREMIUM_COLUMNS);

        $newMotorsByPc = !empty($allCoverageIds)
            ? DB::table('motor')
                ->whereIn('policy_coverage_id', $allCoverageIds)
                ->get($motorFetchCols)
                ->groupBy('policy_coverage_id')
            : collect();
        // Per-vehicle baseline IGNORES deleted rows ANYWHERE in history: a
        // vehicle's previous value is its most recent NON-DELETED total
        // (calculated_value + extensions) across ALL prior ISSUED actions,
        // keyed by registration_no (stable across replication; motor.id is
        // not). A vehicle soft-deleted in a newer issued action — e.g. one
        // wrongly dropped by a renewal, or a stale row carried forward — no
        // longer zeroes the baseline; we look further back to the last
        // action where it was actually active. Newest active value wins.
        //
        // This is what lets a genuine vehicle Cancel produce its refund even
        // when the immediate prior issued state already shows the row deleted:
        // delta = newVal(0) − prevVal(last active) = −last-active = refund.
        //
        // Cross-action reinstate: re-adding a vehicle that was cancelled-with-
        // refund in a PRIOR issued endorse is charged as a brand-new add. The
        // $regCurrentlyCancelled map below detects that the registration's
        // committed state is "cancelled" and forces the per-vehicle baseline to
        // 0 in the motor loop, so the full new total is pro-rated for the
        // remaining period (not netted to ≈ 0 against the stale pre-cancel
        // value). Same-action cancel-then-reinstate still nets to 0 because the
        // registration was never committed as cancelled in an issued action.
        // Same timeline bound as the $prev baseline above: a back-dated endorse
        // must not read per-vehicle values out of a FUTURE issued action (e.g.
        // a later quarterly RENEW), or "newest active wins" hands it a value
        // that was not in force at this action's effective date.
        //
        // TERM BOUNDARY. "Newest active anywhere in history" must not reach back
        // past the start of the CURRENT cover term. COMG2024130199: B565BAA was
        // live on the 05/11/2025 endorse, the 01/01/2026 ANNIVERSARY-RENEW did
        // not carry it (dropped, or cancelled before the renewal), and a
        // 15/06/2026 endorse re-added it. Because the renewal holds no row at
        // all for that plate, neither $prevMotorValByReg (skips deleted rows,
        // so it kept walking back a whole term) nor $regCurrentlyCancelled
        // (newest occurrence was the ACTIVE 2025 row, so "cancelled" was false)
        // saw anything wrong: baseline = last year's value, delta ≈ 0, and the
        // re-added vehicle was never charged. $prevMotorActionEffByReg records
        // WHICH action each baseline came from so the motor loop can reject one
        // that predates this term — see the out-of-term override there.
        $priorIssuedActionIds = $priorStateQuery(true)->pluck('id');
        $prevMotorValByReg = [];
        $prevMotorIdentityByReg = [];
        $prevMotorMakeModelByReg = [];
        $prevMotorActionEffByReg = [];
        if ($priorIssuedActionIds->isNotEmpty()) {
            $histMotors = DB::table('motor as m')
                ->join('policy_coverages as pc', 'pc.id', '=', 'm.policy_coverage_id')
                ->join('policy_actions as pa', 'pa.id', '=', 'pc.action_id')
                ->whereIn('pc.action_id', $priorIssuedActionIds)
                ->whereNull('m.deleted_at')
                ->whereNull('pc.deleted_at')
                // Ignore forward-propagated phantoms — a row under a PRIOR issued
                // action but stamped with the CURRENT action's id was replicated
                // there by this endorse's propagation. It equals the current
                // value, so it would collapse a genuinely-added vehicle's delta
                // to 0 (P0 pro-rata). Genuine prior state carries an older /
                // null / 0 action id. Same guard as computeMotorProRataCase.
                ->where(function ($q) use ($actionId) {
                    $q->whereNull('m.previousActionIdCov')
                      ->orWhere('m.previousActionIdCov', '!=', $actionId);
                })
                // Chronological, not id order: a back-dated endorse issued into
                // an OLDER term carries a HIGHER id, so ordering by action_id
                // would hand the newest-active slot to a row that was not the
                // latest state on the timeline. Canonical key is
                // (effective_from, id) — see PolicyAction::applyChronoOrder.
                ->orderByDesc('pa.effective_from')
                ->orderByDesc('pa.id')
                ->get(array_merge(['m.registration_no', 'm.engine_number', 'm.chassis_number', 'm.make', 'm.model', 'pa.effective_from as action_effective_from'], array_map(fn ($c) => "m.$c", array_merge(['calculated_value'], self::MOTOR_EXTENSION_PREMIUM_COLUMNS))));
            foreach ($histMotors as $hm) {
                $reg = (string) $hm->registration_no;
                if ($reg === '' || array_key_exists($reg, $prevMotorValByReg)) continue; // newest active wins
                $prevMotorValByReg[$reg] = (float) ($hm->calculated_value ?? 0) + self::sumMotorExtensionPremiums($hm);
                $prevMotorActionEffByReg[$reg] = $hm->action_effective_from
                    ? \Carbon\Carbon::parse($hm->action_effective_from)->toDateString()
                    : null;
                // Engine/chassis of that same newest-active row — used only to
                // recognise the vehicle again if its plate was amended.
                $prevMotorIdentityByReg[$reg] = self::motorIdentityKey($hm);
                $prevMotorMakeModelByReg[$reg] = self::motorMakeModelKey($hm);
            }
        }

        // Per-registration committed CANCEL state across prior ISSUED actions.
        // Unlike $prevMotorValByReg (which skips deleted rows to find the last
        // active value), this looks at the NEWEST occurrence of each
        // registration INCLUDING soft-deleted rows. If that newest occurrence
        // is deleted, the vehicle's committed policy state is "cancelled" — so
        // an active, wizard-touched row in THIS action is a different-action
        // reinstate and must be charged as a brand-new add (baseline 0), not
        // diffed against the stale pre-cancel value (which nets delta ≈ 0).
        // Only consulted for ACTIVE rows in the loop below, so genuine cancel
        // refunds (deleted rows) keep reading their last-active baseline and
        // the phantom-drop workaround is preserved.
        $regCurrentlyCancelled = [];
        if ($priorIssuedActionIds->isNotEmpty()) {
            $histStates = DB::table('motor as m')
                ->join('policy_coverages as pc', 'pc.id', '=', 'm.policy_coverage_id')
                ->whereIn('pc.action_id', $priorIssuedActionIds)
                ->whereNull('pc.deleted_at')
                // Same forward-propagated phantom guard as the value lookup.
                ->where(function ($q) use ($actionId) {
                    $q->whereNull('m.previousActionIdCov')
                      ->orWhere('m.previousActionIdCov', '!=', $actionId);
                })
                ->orderByDesc('pc.action_id')
                ->orderByDesc('m.id')
                ->get(['m.registration_no', 'm.deleted_at']);
            foreach ($histStates as $hs) {
                $reg = (string) $hs->registration_no;
                if ($reg === '' || array_key_exists($reg, $regCurrentlyCancelled)) continue; // newest occurrence wins
                $regCurrentlyCancelled[$reg] = ($hs->deleted_at !== null);
            }
        }

        // Start of the CURRENT cover term — the inception of the annual period
        // this action falls in. Used by the motor loop to reject a per-vehicle
        // baseline that belongs to a PREVIOUS term (see $prevMotorActionEffByReg).
        //
        // Only NEWBUSINESS / ANNIVERSARY-RENEW count as a term boundary. Monthly
        // and quarterly RENEW deliberately do NOT: they open a new BILLING period
        // inside the same annual term, and a renew tree that half-replicated
        // (a known failure mode) would otherwise re-charge every vehicle on the
        // next endorse as if it were newly added. The annual boundary is the one
        // point where the schedule is legitimately re-stated from scratch.
        $currentTermStart = null;
        if ($thisAction && $thisAction->effective_from) {
            $termAnchor = \AlphaDirect\Models\PolicyAction::inForceAt(
                $policyId,
                $thisAction->effective_from,
                ['ISSUED'],
                $actionId,
                ['NEWBUSINESS', 'ANNIVERSARY-RENEW']
            );
            if ($termAnchor && $termAnchor->effective_from) {
                $currentTermStart = \Carbon\Carbon::parse($termAnchor->effective_from)->toDateString();
            }
        }

        // ── Registration correction (plate AMENDED on this action) ─────────
        // DO NOT REMOVE without reading this first. Shipped as PR #1736, then
        // lost on 2026-07-29 when commit b0ab581e6 reverted that whole PR for
        // unrelated renew-cron reasons — COMG2024128843/08 went on charging
        // pro-rata for "amend B734BHD to B743BHD" after the ticket was believed
        // closed. Pinned by tests/Feature/Vehicles/MotorRegistrationAmendProRataTest.php
        // and by the "Endorse pro-rata regression guard" job in pr-guard.yml.
        //
        // The per-vehicle baseline above is keyed on registration_no, so a row
        // whose plate was corrected in this endorsement ("amend B734BHD to
        // B743BHD") finds no history under its NEW plate: it is rated as a
        // brand-new vehicle and charged its full pro-rata premium, with no
        // offsetting refund because the old plate no longer exists anywhere in
        // this action. A registration-only amendment must be premium-neutral.
        //
        // A rename is distinguishable from a Cancel: cancelling a vehicle
        // leaves its row behind soft-deleted, so the old plate is STILL in this
        // action and keeps producing its refund. A renamed plate disappears
        // completely. Candidates are therefore plates that were live on the
        // immediately-preceding state and have vanished from this action
        // entirely — matched to the unmatched new plate on the vehicle's own
        // identity (engine/chassis), or on a 1:1 count when identity is blank
        // (common on trailers and older COM fleets). Anything ambiguous keeps
        // the existing baseline-0 behaviour, so nothing can be mis-paired.
        $renameBaseValByMotorId = [];
        if (!empty($prevMotorValByReg) && !empty($prevPcIds)) {
            $platesInAction = [];   // every plate this action holds, live OR cancelled
            $unmatchedNew   = [];   // rows this action rates that have no history
            foreach ($newMotorsByPc as $rowsForPc) {
                foreach ($rowsForPc as $m) {
                    $p = trim((string) $m->registration_no);
                    if ($p !== '') $platesInAction[$p] = true;
                    if ($p !== ''
                        && $m->deleted_at === null
                        && (int) ($m->previousActionIdCov ?? 0) === (int) $actionId
                        && !array_key_exists($p, $prevMotorValByReg)) {
                        $unmatchedNew[] = $m;
                    }
                }
            }

            if (!empty($unmatchedNew)) {
                // Plates live on the immediately-preceding coverages that this
                // action no longer carries in any form.
                $vanished = [];
                foreach (DB::table('motor')
                            ->whereIn('policy_coverage_id', $prevPcIds)
                            ->whereNull('deleted_at')
                            ->pluck('registration_no') as $pr) {
                    $pr = trim((string) $pr);
                    if ($pr === '' || isset($platesInAction[$pr])) continue;
                    if (!array_key_exists($pr, $prevMotorValByReg)) continue;
                    if (!empty($regCurrentlyCancelled[$pr])) continue;
                    $vanished[$pr] = $prevMotorValByReg[$pr];
                }

                if (!empty($vanished)) {
                    // Tier 1 — same engine/chassis on both sides, unique either way.
                    $newIdentityCount = [];
                    foreach ($unmatchedNew as $m) {
                        $k = self::motorIdentityKey($m);
                        if ($k !== '') $newIdentityCount[$k] = ($newIdentityCount[$k] ?? 0) + 1;
                    }
                    $vanishedByIdentity = [];
                    foreach (array_keys($vanished) as $vReg) {
                        $k = $prevMotorIdentityByReg[$vReg] ?? '';
                        if ($k !== '') $vanishedByIdentity[$k][] = $vReg;
                    }
                    foreach ($unmatchedNew as $m) {
                        $k = self::motorIdentityKey($m);
                        if ($k === '' || ($newIdentityCount[$k] ?? 0) !== 1) continue;
                        if (count($vanishedByIdentity[$k] ?? []) !== 1) continue;
                        $renameBaseValByMotorId[(int) $m->id] = $vanished[$vanishedByIdentity[$k][0]];
                    }
                    // Tier 2 — no engine/chassis to go on: pair only when exactly
                    // one plate appeared without history and exactly one vanished.
                    //
                    // The 1:1 count alone is NOT enough evidence. The same shape
                    // occurs when one vehicle left the action untombstoned (a
                    // replication that never carried it forward) while another
                    // was genuinely added — pairing those hands the new vehicle
                    // the old one's baseline, nets its delta negative and drops
                    // the line entirely, so the addition is never charged. Two
                    // further conditions must hold before we call it a rename:
                    //   • NEITHER side carries an engine/chassis number — a
                    //     present but DIFFERENT identity is positive evidence
                    //     these are different vehicles and must not be papered
                    //     over by the count;
                    //   • make + model agree, the only remaining description of
                    //     the vehicle once the plate itself is in question.
                    // Anything else keeps the existing baseline-0 behaviour.
                    if (empty($renameBaseValByMotorId) && count($unmatchedNew) === 1 && count($vanished) === 1) {
                        $cand = $unmatchedNew[0];
                        $vReg = (string) array_key_first($vanished);
                        $identityBlank = self::motorIdentityKey($cand) === ''
                            && ($prevMotorIdentityByReg[$vReg] ?? '') === '';
                        $candMakeModel = self::motorMakeModelKey($cand);
                        $sameMakeModel = $candMakeModel !== ''
                            && $candMakeModel === ($prevMotorMakeModelByReg[$vReg] ?? '');
                        if ($identityBlank && $sameMakeModel) {
                            $renameBaseValByMotorId[(int) $cand->id] = $vanished[$vReg];
                        }
                    }
                    if (!empty($renameBaseValByMotorId)) {
                        Log::info('writeLineLevelProRata: registration correction detected — baseline carried from the old plate', [
                            'policy_id' => $policyId,
                            'action_id' => $actionId,
                            'vanished'  => array_keys($vanished),
                            'paired'    => $renameBaseValByMotorId,
                        ]);
                    }
                }
            }
        }

        $extColumnExists = \Schema::hasColumn('policy_extention_detail', 'pro_rate_premium');
        // Process ALL extension types, not just 'Extention' — extention_calculated_value
        // is the premium and other types (Excess, BurglarAlarmWarranty) carry it too.
        // `type` is added to the match key below so cross-type rows can't collide on
        // s_ParentCoverageID|extentions_id (Extention matching is unchanged — both
        // sides simply gain the same |Extention suffix).
        $newExtsByPc = ($extColumnExists && !empty($allCoverageIds))
            ? DB::table('policy_extention_detail')
                ->whereIn('policy_coverage_id', $allCoverageIds)
                ->get(['id', 'policy_coverage_id', 's_ParentCoverageID', 'extentions_id', 'type', 'extention_calculated_value', 'deleted_at', 'previousActionIdCov'])
                ->groupBy('policy_coverage_id')
            : collect();
        // Same forward-propagated phantom guard + newest-active-wins tie-break
        // as the detail / motor / specified-item baselines above: an extension
        // row under a PRIOR issued coverage stamped with the CURRENT action id
        // was cloned there by this endorse's propagation and holds the current
        // value, so it would net a genuine extension change to delta 0.
        $prevExtsByPc = ($extColumnExists && !empty($prevPcIds))
            ? DB::table('policy_extention_detail')
                ->whereIn('policy_coverage_id', $prevPcIds)->whereNull('deleted_at')
                ->where(function ($q) use ($actionId) {
                    $q->whereNull('previousActionIdCov')
                      ->orWhere('previousActionIdCov', '!=', $actionId);
                })
                ->orderByDesc('id')
                ->get(['policy_coverage_id', 's_ParentCoverageID', 'extentions_id', 'type', 'extention_calculated_value'])
                ->groupBy('policy_coverage_id')
            : collect();

        // policy_specified_items — match key includes motor.registration_no
        // for vehicle-attached items (motor_id changes during replication
        // but registration_no survives), specified_coverage_id for master
        // picks, and custom_name for free-text rows. Coverage-level items
        // (motor_id null/0) match cleanly on (specified_coverage_id|custom_name).
        $specColumnExists = \Schema::hasColumn('policy_specified_items', 'pro_rate_premium');
        $hasCustomNameCol = \Schema::hasColumn('policy_specified_items', 'custom_name');
        $specSelect = ['psi.id', 'psi.policy_coverage_id', 'psi.specified_coverage_id', 'psi.motor_id', 'psi.calculated_value', 'psi.deleted_at', 'psi.previousActionIdCov', 'm.registration_no'];
        if ($hasCustomNameCol) $specSelect[] = 'psi.custom_name';
        $newSpecsByPc = ($specColumnExists && !empty($allCoverageIds))
            ? DB::table('policy_specified_items as psi')
                ->leftJoin('motor as m', 'm.id', '=', 'psi.motor_id')
                ->whereIn('psi.policy_coverage_id', $allCoverageIds)
                ->get($specSelect)
                ->groupBy('policy_coverage_id')
            : collect();
        $prevSpecSelect = ['psi.policy_coverage_id', 'psi.specified_coverage_id', 'psi.motor_id', 'psi.calculated_value', 'm.registration_no'];
        if ($hasCustomNameCol) $prevSpecSelect[] = 'psi.custom_name';
        // Two guards, identical to the motor ($prevMotorValByReg) and
        // policy_coverage_detail ($prevDetailsByPc) baseline lookups:
        //  1. Phantom exclusion — a specified item sitting under a PRIOR issued
        //     coverage but stamped with the CURRENT action's id was written
        //     there by this endorse's forward propagation (BackdatedEndorse
        //     Refresher::copyMotorSpecifiedItems / replicateRecordsIfMissing
        //     clone the whole row, stamps included). It holds the CURRENT
        //     value, so using it as the baseline collapses a genuine value
        //     change to delta 0 — the item's annual premium moves but its
        //     pro-rata reads P0. Genuine prior state carries an older / null /
        //     different action id.
        //  2. orderByDesc('psi.id') + the array_key_exists tie-break in the
        //     build loop below make "newest active wins" deterministic when the
        //     prior coverage carries duplicate rows for the same item (legacy
        //     replication duplicated child rows forward). Previously the last
        //     row returned in arbitrary order silently won.
        $prevSpecsByPc = ($specColumnExists && !empty($prevPcIds))
            ? DB::table('policy_specified_items as psi')
                ->leftJoin('motor as m', 'm.id', '=', 'psi.motor_id')
                ->whereIn('psi.policy_coverage_id', $prevPcIds)->whereNull('psi.deleted_at')
                ->where(function ($q) use ($actionId) {
                    $q->whereNull('psi.previousActionIdCov')
                      ->orWhere('psi.previousActionIdCov', '!=', $actionId);
                })
                ->orderByDesc('psi.id')
                ->get($prevSpecSelect)
                ->groupBy('policy_coverage_id')
            : collect();

        // Stable-name map for the specified-item baseline FALLBACK below.
        // The primary match keys on specified_coverage_id, but an ENDORSE can
        // re-pick a master item so it arrives with a NEW specified_coverage_id
        // even though it is the SAME item (policy 130274 Fire: baseline items
        // 17821/17822 re-created as 19627/19626 on a value increase). That made
        // a genuine value CHANGE miss its baseline and get over-charged as a
        // full-value ADD, while the vanished old items were never refunded. The
        // master specified_name survives the id churn, so map
        // specified_coverage_id → name and use it ONLY as a 1:1 unambiguous
        // fallback in the loop — it can never mis-pair rows. Mirrors the
        // policy_coverage_detail stable-code fallback ($detailCodeById) above.
        $specNameById = [];
        if ($specColumnExists) {
            $allSpecCovIds = [];
            foreach ($newSpecsByPc as $rows) foreach ($rows as $r) if (!empty($r->specified_coverage_id)) $allSpecCovIds[(int) $r->specified_coverage_id] = true;
            foreach ($prevSpecsByPc as $rows) foreach ($rows as $r) if (!empty($r->specified_coverage_id)) $allSpecCovIds[(int) $r->specified_coverage_id] = true;
            if (!empty($allSpecCovIds) && \Schema::hasTable('specified_coverage_items')) {
                foreach (DB::table('specified_coverage_items')->whereIn('id', array_keys($allSpecCovIds))->get(['id', 'specified_name']) as $m) {
                    $nm = trim((string) ($m->specified_name ?? ''));
                    if ($nm !== '') $specNameById[(int) $m->id] = $nm;
                }
            }
        }

        // motor_traders / motor_traders_internal — one row per pc, 14 premium
        // columns. Prefetch both tables grouped by policy_coverage_id so the
        // per-pc loop below can diff in O(1) without per-row DB hits.
        $mtCols = array_merge(
            ['id', 'policy_coverage_id', 'deleted_at'],
            self::MOTOR_TRADERS_PREMIUM_COLUMNS
        );
        $mtHasProRate = \Schema::hasColumn('motor_traders', 'pro_rate_premium');
        $mtIntHasProRate = \Schema::hasColumn('motor_traders_internal', 'pro_rate_premium');
        if ($mtHasProRate) $mtCols[] = 'previousActionIdCov';
        $newMtByPc = ($mtHasProRate && !empty($allCoverageIds))
            ? DB::table('motor_traders')
                ->whereIn('policy_coverage_id', $allCoverageIds)
                ->get($mtCols)
                ->groupBy('policy_coverage_id')
            : collect();
        // Same phantom-exclusion guard as $prevDetailsByPc / $prevMotorValByReg:
        // a row sitting under a PRIOR issued coverage but stamped with the
        // CURRENT action's id was forward-propagated there by this endorse. It
        // already equals the current value, so using it as the baseline
        // collapses a genuine delta to 0 (the MT edit reads as "no change" and
        // the endorse charges nothing). Genuine prior state carries an older /
        // null / different action id.
        $prevMtByPc = ($mtHasProRate && !empty($prevPcIds))
            ? DB::table('motor_traders')
                ->whereIn('policy_coverage_id', $prevPcIds)->whereNull('deleted_at')
                ->where(function ($q) use ($actionId) {
                    $q->whereNull('previousActionIdCov')
                      ->orWhere('previousActionIdCov', '!=', $actionId);
                })
                ->get(array_merge(['policy_coverage_id'], self::MOTOR_TRADERS_PREMIUM_COLUMNS))
                ->groupBy('policy_coverage_id')
            : collect();
        $mtIntCols = array_merge(
            ['id', 'policy_coverage_id', 'deleted_at'],
            self::MOTOR_TRADERS_PREMIUM_COLUMNS
        );
        if ($mtIntHasProRate) $mtIntCols[] = 'previousActionIdCov';
        $newMtIntByPc = ($mtIntHasProRate && !empty($allCoverageIds))
            ? DB::table('motor_traders_internal')
                ->whereIn('policy_coverage_id', $allCoverageIds)
                ->get($mtIntCols)
                ->groupBy('policy_coverage_id')
            : collect();
        $prevMtIntByPc = ($mtIntHasProRate && !empty($prevPcIds))
            ? DB::table('motor_traders_internal')
                ->whereIn('policy_coverage_id', $prevPcIds)->whereNull('deleted_at')
                ->where(function ($q) use ($actionId) {   // phantom guard — see $prevMtByPc
                    $q->whereNull('previousActionIdCov')
                      ->orWhere('previousActionIdCov', '!=', $actionId);
                })
                ->get(array_merge(['policy_coverage_id'], self::MOTOR_TRADERS_PREMIUM_COLUMNS))
                ->groupBy('policy_coverage_id')
            : collect();

        // Sum the 14 _calculated_value columns of one row.
        $sumMtRow = function ($row): float {
            $total = 0.0;
            foreach (self::MOTOR_TRADERS_PREMIUM_COLUMNS as $col) {
                $total += (float) ($row->$col ?? 0);
            }
            return $total;
        };

        foreach ($newCoverages as $nc) {
            $key = $nc->coverage_id . '|' . trim((string) ($nc->address_name ?? ''));
            $prevPcId = $prevPcIdByKey[$key] ?? null;

            // ── policy_coverage_detail ────────────────────────────
            // Walk BOTH new (active) AND new (soft-deleted) rows so CANCEL
            // semantics work — when operator removes a sub-coverage in the
            // wizard, the row gets soft-deleted in the new action. The PDF
            // spec (CANCEL: pro_rata = -baseline × factor) needs us to stamp
            // negative pro_rate_premium on those deleted rows.
            // Only stamp pro_rate_premium on rows the wizard explicitly
            // flagged via previousActionIdCov = $actionId. Rows we
            // didn't-touch keep pro_rate_premium = 0 from the bulk reset.
            $newDetails = $newDetailsByPc->get($nc->id, collect());
            $prevDetailsByKey = [];
            $prevValByCode = [];   // stable code => baseline value (1:1 fallback)
            $prevCodeCount = [];   // stable code => occurrences in prev (enforce 1:1)
            if ($prevPcId) {
                foreach ($prevDetailsByPc->get($prevPcId, collect()) as $r) {
                    // newest active wins — rows arrive id-desc, keep the first
                    // occurrence of each coverage_id (same tie-break as the
                    // motor $prevMotorValByReg build above).
                    if (!array_key_exists($r->coverage_id, $prevDetailsByKey)) {
                        $prevDetailsByKey[$r->coverage_id] = (float) $r->calculated_value;
                    }
                    $c = $detailCodeById[(int) $r->coverage_id] ?? null;
                    if ($c !== null) {
                        $prevCodeCount[$c] = ($prevCodeCount[$c] ?? 0) + 1;
                        if (!array_key_exists($c, $prevValByCode)) {
                            $prevValByCode[$c] = (float) $r->calculated_value;
                        }
                    }
                }
            }
            // Count stable codes among the NEW details so the fallback fires only
            // on a true 1:1 (no double-mapping when a code repeats on either side).
            $newCodeCount = [];
            foreach ($newDetails as $r) {
                $c = $detailCodeById[(int) $r->coverage_id] ?? null;
                if ($c !== null) $newCodeCount[$c] = ($newCodeCount[$c] ?? 0) + 1;
            }
            foreach ($newDetails as $nd) {
                $stampedThisAction = (int) ($nd->previousActionIdCov ?? 0) === (int) $actionId;
                // Self-heal a lost wizard stamp. A genuine sub-coverage edit can
                // lose its previousActionIdCov when a LATER same-action save
                // re-submits it as changed:false (the FE flag is per-editing-
                // session), leaving the row un-stamped (0) even though it still
                // differs from the committed baseline. Re-price it here so a
                // Rate click alone recovers it — no manual re-stamp — BUT only
                // for an ACTIVE row that matched a reliable baseline for its
                // parent coverage ($prevPcId, keyed by coverage_id + risk-address
                // name). With a real baseline an unchanged carry-forward nets
                // delta 0 and is skipped below, so nothing is over-charged.
                // When there is NO baseline match ($prevPcId null — new branch /
                // renamed address / prev CANCEL) OR the row is a cancel
                // (soft-deleted), we STILL require the wizard stamp: that keeps
                // replicated rows whose lookup failed from being charged their
                // full value, and keeps refunds wizard-driven.
                if (!$stampedThisAction && ($prevPcId === null || $nd->deleted_at !== null)) continue;
                $prevVal = $prevDetailsByKey[$nd->coverage_id] ?? null;
                if ($prevVal === null) {
                    // Exact surrogate coverage_id miss → try the stable-code 1:1
                    // fallback (see $detailCodeById above). Only when the code is
                    // unambiguous on BOTH sides; otherwise keep baseline 0 (the
                    // pre-existing behaviour), so nothing can be mis-paired.
                    $cCode = $detailCodeById[(int) $nd->coverage_id] ?? null;
                    $prevVal = ($cCode !== null && ($prevCodeCount[$cCode] ?? 0) === 1 && ($newCodeCount[$cCode] ?? 0) === 1)
                        ? $prevValByCode[$cCode]
                        : 0.0;
                }
                $newVal = $nd->deleted_at !== null ? 0.0 : (float) $nd->calculated_value;
                $delta  = round($newVal - $prevVal, 2);
                // DIAGNOSTIC (temporary, NO behaviour change): a user-touched
                // sub-coverage priced at its FULL value means the baseline
                // resolved to 0 — the prior line wasn't matched, so an *increase*
                // is over-charged as a brand-new ADD (policy 130274 Fire). Log the
                // ids so the exact match break can be identified from prod logs
                // without DB access: parent_prev_pc_matched=null ⇒ the parent Fire
                // coverage_id (or address) differs; a matched parent whose
                // prev_detail_coverage_ids omits detail_coverage_id ⇒ the
                // sub-coverage was re-cloned with a new coverage_id.
                $cCodeDbg = $detailCodeById[(int) $nd->coverage_id] ?? null;
                if ($stampedThisAction && $newVal > 0.009 && abs($prevVal) < 0.01
                    && $prevPcId !== null && $cCodeDbg !== null && ($prevCodeCount[$cCodeDbg] ?? 0) > 0) {
                    // The parent matched AND this sub-coverage's TYPE exists in the
                    // prior state, yet the baseline is still 0 — i.e. the stable-code
                    // 1:1 fallback couldn't pair it (ambiguous / duplicate code). This
                    // is a genuine over-charge suspicion worth tracing; a legitimate
                    // brand-new line (code absent from prior) never logs here.
                    \Log::warning('proRata: sub-coverage baseline=0 after code fallback (possible over-charge)', [
                        'policy_id'                => $policyId,
                        'action_id'                => $actionId,
                        'prev_action_id'           => $prev->id ?? null,
                        'pc_id'                    => $nc->id,
                        'parent_coverage_id'       => $nc->coverage_id,
                        'address'                  => $nc->address_name,
                        'detail_coverage_id'       => $nd->coverage_id,
                        'stable_code'              => $cCodeDbg,
                        'prev_code_count'          => $prevCodeCount[$cCodeDbg] ?? 0,
                        'new_code_count'           => $newCodeCount[$cCodeDbg] ?? 0,
                        'new_val'                  => $newVal,
                    ]);
                }
                if (abs($delta) < 0.01) continue;
                // Cancel guard — soft-deleted sub-coverage must produce a
                // negative pro_rate_premium (refund). If prev was already
                // negative (chained cancel-reinstate-cancel), delta could
                // flip positive; collapse with -abs().
                if ($nd->deleted_at !== null) {
                    $delta = -abs($delta);
                }
                // Restore the gate on a self-healed row so the change summary
                // and banner include it (both filter on previousActionIdCov =
                // this action). Already-stamped rows are left untouched.
                $healStamp = $stampedThisAction ? [] : [
                    'previousActionIdCov' => $actionId,
                    'endors_flag'         => 1,
                ];
                DB::table('policy_coverage_detail')->where('id', $nd->id)->update(array_merge([
                    'pro_rate_premium' => $delta,
                    'updated_at'       => now(),
                ], $healStamp));
            }

            // ── motor (per-vehicle) ───────────────────────────────
            // Total premium per vehicle = calculated_value + sum of every
            // premium_* extension column. Pro-rata delta compares totals
            // so a change to any extension produces a delta even when
            // calculated_value itself is unchanged.
            //
            // Wizard-gate is the SOLE authority: only motors the wizard
            // explicitly stamped (addMotorVehicle / updateMotorVehicle /
            // deleteMotorVehicle set previousActionIdCov = $actionId) get
            // their pro_rate_premium written here. Replicated rows
            // untouched in this action stay at 0 from the bulk reset.
            //
            // Previously the gate was looser — "skip only if has prev-match
            // AND not wizard-touched" — which meant rows whose prev-match
            // lookup failed (e.g. risk_address rename, prev action is a
            // CANCEL with no coverages) were treated as NEW and stamped
            // with their full calculated_value, blowing up the banner pro-
            // rata sum across every replicated vehicle on the policy.
            //
            // Behaviour matrix:
            //   wizard-added (addMotorVehicle stamped it):  delta = full new total (prev=0)
            //   wizard-edited (updateMotorVehicle stamped): delta = new total - prev total
            //   wizard-cancelled (deleteMotorVehicle):      delta = -prev total
            //   not wizard-touched (replicated drift):      skip
            $newMotors = $newMotorsByPc->get($nc->id, collect());
            // prevVal is sourced from $prevMotorValByReg — the last NON-DELETED
            // value of each registration across prior ISSUED actions (built
            // above). Keyed by registration_no, so it is independent of the
            // matched parent pc and never reads a deleted row as the baseline.
            foreach ($newMotors as $nm) {
                if ((int) ($nm->previousActionIdCov ?? 0) !== (int) $actionId) continue;
                $regNo   = (string) $nm->registration_no;
                // No history under this plate → it may be the SAME vehicle with
                // an amended registration; $renameBaseValByMotorId carries the
                // old plate's value across so the correction rates at zero.
                $prevVal = $prevMotorValByReg[$regNo]
                    ?? ($renameBaseValByMotorId[(int) $nm->id] ?? 0.0);
                // Different-action reinstate → charge as a brand-new add.
                // When this registration's committed state (newest prior-ISSUED
                // occurrence) is CANCELLED, an active row here means the vehicle
                // was cancelled in an earlier issued endorse and is now being
                // reinstated. The pre-cancel value must NOT be the baseline
                // (that nets delta ≈ 0 — the reported "no pro-rata" bug); force
                // baseline 0 so the full new total is pro-rated for the period.
                // Guarded to ACTIVE rows only — a soft-deleted (cancel) row keeps
                // its last-active baseline so genuine cancel refunds are intact.
                if ($nm->deleted_at === null && !empty($regCurrentlyCancelled[$regNo])) {
                    $prevVal = 0.0;
                }
                // Cross-TERM re-add → charge as a brand-new add. The baseline
                // above takes the newest active row for this plate anywhere in
                // prior issued history; when the current term's own schedule
                // never carried the plate (the ANNIVERSARY-RENEW dropped it, or
                // it was cancelled just before the renewal so no row was
                // replicated at all), that baseline is last term's value. The
                // vehicle is not on cover in this term, so re-adding it must be
                // rated at its full new total for the remaining period, not
                // netted to ≈ 0 against a premium the customer no longer pays.
                //
                // Active rows only, mirroring the reinstate override above, so a
                // genuine cancel keeps reading its last-active baseline and still
                // produces its refund. Rename corrections are skipped too — the
                // old plate's value is carried over deliberately to keep a
                // registration-only amendment premium-neutral.
                if ($nm->deleted_at === null
                    && $currentTermStart !== null
                    && !isset($renameBaseValByMotorId[(int) $nm->id])
                    && !empty($prevMotorActionEffByReg[$regNo])
                    && $prevMotorActionEffByReg[$regNo] < $currentTermStart) {
                    $prevVal = 0.0;
                }
                // Cancelled rows contribute 0 (refund baseline = -prev).
                // Active rows contribute total = calc + sum(extensions).
                $newVal = $nm->deleted_at !== null
                    ? 0.0
                    : ((float) ($nm->calculated_value ?? 0) + self::sumMotorExtensionPremiums($nm));
                $delta  = round($newVal - $prevVal, 2);
                if (abs($delta) < 0.01) continue;
                // Cancel guard — vehicle Cancel must produce a negative
                // pro_rate_premium (refund). Collapse with -abs() in case
                // prev was already negative.
                if ($nm->deleted_at !== null) {
                    $delta = -abs($delta);
                }
                DB::table('motor')->where('id', $nm->id)->update([
                    'pro_rate_premium' => $delta,
                    'updated_at'       => now(),
                ]);
            }

            // ── policy_extention_detail ──────────────────────────
            if ($extColumnExists) {
                $newExts = $newExtsByPc->get($nc->id, collect());
                $prevExtsByKey = [];
                if ($prevPcId) {
                    foreach ($prevExtsByPc->get($prevPcId, collect()) as $r) {
                        $extK = $r->s_ParentCoverageID . '|' . $r->extentions_id . '|' . ($r->type ?? '');
                        // newest active wins — rows arrive id-desc.
                        if (!array_key_exists($extK, $prevExtsByKey)) {
                            $prevExtsByKey[$extK] = (float) $r->extention_calculated_value;
                        }
                    }
                }
                foreach ($newExts as $ne) {
                    if ((int) ($ne->previousActionIdCov ?? 0) !== (int) $actionId) continue;
                    $extKey = $ne->s_ParentCoverageID . '|' . $ne->extentions_id . '|' . ($ne->type ?? '');
                    $prevVal = $prevExtsByKey[$extKey] ?? 0.0;
                    $newVal = $ne->deleted_at !== null ? 0.0 : (float) $ne->extention_calculated_value;
                    $delta  = round($newVal - $prevVal, 2);
                    if (abs($delta) < 0.01) continue;
                    // Cancel guard — extension Cancel must produce a negative
                    // pro_rate_premium (refund).
                    if ($ne->deleted_at !== null) {
                        $delta = -abs($delta);
                    }
                    DB::table('policy_extention_detail')->where('id', $ne->id)->update([
                        'pro_rate_premium' => $delta,
                        'updated_at'       => now(),
                    ]);
                }
            }

            // ── policy_specified_items ───────────────────────────
            // Same wizard-gate as detail/motor/ext: only stamp
            // pro_rate_premium on rows the wizard already marked with
            // previousActionIdCov = $actionId.
            if ($specColumnExists) {
                $newSpecs = $newSpecsByPc->get($nc->id, collect());
                $prevSpecsByKey = [];
                $prevValByName  = [];   // reg|name => baseline value (1:1 fallback)
                $prevNameCount  = [];   // reg|name => occurrences in prev
                if ($prevPcId) {
                    foreach ($prevSpecsByPc->get($prevPcId, collect()) as $r) {
                        $reg = trim((string) ($r->registration_no ?? ''));
                        $sci = (string) ($r->specified_coverage_id ?? '');
                        $cn  = $hasCustomNameCol ? trim((string) ($r->custom_name ?? '')) : '';
                        $k   = $reg . '|' . $sci . '|' . $cn;
                        // newest active wins — rows arrive id-desc, keep the
                        // first occurrence of each key (same tie-break as the
                        // detail / motor baselines).
                        if (!array_key_exists($k, $prevSpecsByKey)) {
                            $prevSpecsByKey[$k] = (float) $r->calculated_value;
                        }
                        $nm = $specNameById[(int) ($r->specified_coverage_id ?? 0)] ?? '';
                        if ($nm !== '') {
                            $nk = $reg . '|' . $nm;
                            $prevNameCount[$nk] = ($prevNameCount[$nk] ?? 0) + 1;
                            if (!array_key_exists($nk, $prevValByName)) $prevValByName[$nk] = (float) $r->calculated_value;
                        }
                    }
                }
                // Count master names among the NEW specs so the fallback fires
                // only on a true 1:1 (no double-mapping when a name repeats).
                $newNameCount = [];
                foreach ($newSpecs as $r) {
                    $reg = trim((string) ($r->registration_no ?? ''));
                    $nm  = $specNameById[(int) ($r->specified_coverage_id ?? 0)] ?? '';
                    if ($nm !== '') { $nk = $reg . '|' . $nm; $newNameCount[$nk] = ($newNameCount[$nk] ?? 0) + 1; }
                }
                foreach ($newSpecs as $ns) {
                    if ((int) ($ns->previousActionIdCov ?? 0) !== (int) $actionId) continue;
                    $reg = trim((string) ($ns->registration_no ?? ''));
                    $sci = (string) ($ns->specified_coverage_id ?? '');
                    $cn  = $hasCustomNameCol ? trim((string) ($ns->custom_name ?? '')) : '';
                    $k   = $reg . '|' . $sci . '|' . $cn;
                    $prevVal = $prevSpecsByKey[$k] ?? null;
                    if ($prevVal === null) {
                        // Exact specified_coverage_id miss → 1:1 specified_name
                        // fallback (see $specNameById). Only when the name is
                        // unambiguous on BOTH sides; otherwise baseline 0 (the
                        // pre-existing behaviour), so nothing can be mis-paired.
                        $nm = $specNameById[(int) ($ns->specified_coverage_id ?? 0)] ?? '';
                        $nk = $reg . '|' . $nm;
                        $prevVal = ($nm !== '' && ($prevNameCount[$nk] ?? 0) === 1 && ($newNameCount[$nk] ?? 0) === 1)
                            ? $prevValByName[$nk]
                            : 0.0;
                    }
                    $newVal = $ns->deleted_at !== null ? 0.0 : (float) $ns->calculated_value;
                    $delta = round($newVal - $prevVal, 2);
                    // DIAGNOSTIC (bounded, NO behaviour change): a misc item the
                    // wizard touched in THIS action that nets delta 0 is the
                    // reported "premium changed but pro-rata is P0" case — the
                    // baseline resolved to the current value (stale duplicate /
                    // forward-propagated row in the prior action). Only
                    // wizard-stamped rows reach here, so this logs a handful of
                    // lines per endorse, not the whole policy.
                    if (abs($delta) < 0.01 && $ns->deleted_at === null && $newVal > 0.009) {
                        \Log::info('proRata: misc item wizard-touched but delta=0 (no pro-rata)', [
                            'policy_id'      => $policyId,
                            'action_id'      => $actionId,
                            'prev_action_id' => $prev->id ?? null,
                            'pc_id'          => $nc->id,
                            'prev_pc_id'     => $prevPcId,
                            'psi_id'         => $ns->id,
                            'match_key'      => $k,
                            'prev_val'       => $prevVal,
                            'new_val'        => $newVal,
                        ]);
                    }
                    if (abs($delta) < 0.01) continue;
                    // Cancel guard — specified-item Cancel must produce a
                    // negative pro_rate_premium (refund).
                    if ($ns->deleted_at !== null) {
                        $delta = -abs($delta);
                    }
                    DB::table('policy_specified_items')->where('id', $ns->id)->update([
                        'pro_rate_premium' => $delta,
                        'updated_at'       => now(),
                    ]);
                }
            }

            // ── motor_traders (External) ──────────────────────────
            // One row per pc; total premium = sum of 14 _calculated_value cols.
            // delta = newSum − prevSum. Stamp only when previousActionIdCov
            // marks the row as wizard-touched in this action.
            if ($mtHasProRate) {
                $newMtRows = $newMtByPc->get($nc->id, collect());
                $prevMtRows = $prevPcId ? $prevMtByPc->get($prevPcId, collect()) : collect();
                $prevMtSum = 0.0;
                foreach ($prevMtRows as $r) { $prevMtSum += $sumMtRow($r); }
                foreach ($newMtRows as $nm) {
                    if ((int) ($nm->previousActionIdCov ?? 0) !== (int) $actionId) continue;
                    $newSum = $nm->deleted_at !== null ? 0.0 : $sumMtRow($nm);
                    $delta  = round($newSum - $prevMtSum, 2);
                    if (abs($delta) < 0.01) continue;
                    if ($nm->deleted_at !== null) $delta = -abs($delta);
                    DB::table('motor_traders')->where('id', $nm->id)->update([
                        'pro_rate_premium' => $delta,
                        'updated_at'       => now(),
                    ]);
                }
            }

            // ── motor_traders_internal ─────────────────────────────
            if ($mtIntHasProRate) {
                $newMtIntRows = $newMtIntByPc->get($nc->id, collect());
                $prevMtIntRows = $prevPcId ? $prevMtIntByPc->get($prevPcId, collect()) : collect();
                $prevMtIntSum = 0.0;
                foreach ($prevMtIntRows as $r) { $prevMtIntSum += $sumMtRow($r); }
                foreach ($newMtIntRows as $nm) {
                    if ((int) ($nm->previousActionIdCov ?? 0) !== (int) $actionId) continue;
                    $newSum = $nm->deleted_at !== null ? 0.0 : $sumMtRow($nm);
                    $delta  = round($newSum - $prevMtIntSum, 2);
                    if (abs($delta) < 0.01) continue;
                    if ($nm->deleted_at !== null) $delta = -abs($delta);
                    DB::table('motor_traders_internal')->where('id', $nm->id)->update([
                        'pro_rate_premium' => $delta,
                        'updated_at'       => now(),
                    ]);
                }
            }
        }
    }

    /**
     * Coverage families that may have at most ONE row per (risk_address, action).
     * Map of display label → list of `s_CoverageCode` strings considered
     * equivalent. Used by addCoverage and reinstateCoverage to block duplicates.
     */
    public static function singletonCoverageFamilies(): array
    {
        return [
            'EAR'                      => ['ERECTIONALLRISKS', 'EAR'],
            'CAR'                      => ['CONTRACTORSALLRISKS', 'CAR'],
            'PAR'                      => ['PLANTALLRISKS', 'PAR'],
            'Machinery Breakdown'      => ['MACHINERYBREAKDOWN'],
            'Medical Malpractice'      => ['MEDICAMALPRACTICEINSURANCE'],
            'Professional Indemnity'   => ['PROFESSIONALINDEMNITY'],
            'Directors & Officers'     => ['DIRECTORSOFFICERSLIABILITY', 'MARINEDIRECTORSOFFICERS'],
            'Marine Open Cover'        => ['MARINEOPENCOVER'],
            'Marine Once-Off Cover'    => ['MARINEONCEOFFCOVER', 'MARINECARGOONCEOFF'],
            'Travel Insurance'         => ['TRAVELINSURANCE', 'TRAVEL'],
        ];
    }

    /**
     * May an EDIT endpoint re-stamp this action's premium?
     *
     * Only a QUOTE may be re-priced from the wizard: an ISSUED transaction has
     * already been invoiced, so rewriting premium / annual_premium and every
     * line's pro_rate_premium silently desyncs the policy from the invoice and
     * the ledger (#1736 review, blocker 1). Blank status = legacy row, treated
     * as editable — same rule as ensureCoverageEditable.
     *
     * Deliberately NOT applied inside recomputeActionTotals: endorse
     * propagation (FUTURE_STATUSES = QUOTE + ISSUED) and calculatePremiumRenew
     * re-price ISSUED downstream batches on purpose, and gating there would
     * silently stop Refresh Endorsement and the renew crons.
     */
    private static function actionRepriceable($actionId): bool
    {
        if (!$actionId) return false;
        $status = \AlphaDirect\Models\PolicyAction::where('id', $actionId)->value('status');
        return empty($status) || $status === 'QUOTE';
    }

    /**
     * Same lock as ensureCoverageEditable, but keyed on the action itself —
     * used by the risk-address endpoints, which own no coverage row. Only a
     * QUOTE action may be edited: an ISSUED / APPROVED transaction is frozen,
     * so the operator must Unissue it or raise a new endorsement. A blank
     * status (legacy imports) stays editable, matching actionRepriceable.
     */
    /**
     * @param string $what what the caller is about to write, for the message —
     *                     the rule is one predicate for every wizard write, so
     *                     only the noun changes.
     */
    private function ensureActionEditable(?int $actionId, string $what = 'Risk addresses'): ?JsonResponse
    {
        if (!$actionId) return null;
        $status = \AlphaDirect\Models\PolicyAction::where('id', $actionId)->value('status');
        if ($status && $status !== 'QUOTE') {
            return response()->json([
                'error' => "{$what} on a {$status} action cannot be changed. Unissue the action (status → QUOTE) or create a new Endorsement to make changes.",
                'action_status' => $status,
            ], 409);
        }
        return null;
    }

    private function ensureCoverageEditable(int $coverageId): ?JsonResponse
    {
        $coverage = PolicyCoverage::find($coverageId);
        if (!$coverage || !$coverage->action_id) return null;
        $status = \AlphaDirect\Models\PolicyAction::where('id', $coverage->action_id)->value('status');
        if ($status && $status !== 'QUOTE') {
            return response()->json([
                'error' => "Coverages on a {$status} action cannot be edited. Unissue the action (status → QUOTE) or create a new Endorsement to make changes.",
                'action_status' => $status,
            ], 409);
        }
        return null;
    }

    /**
     * May this risk address be edited? Same rule as ensureCoverageEditable:
     * only a QUOTE is editable from the wizard.
     *
     * An ISSUED action has already been printed on a schedule and invoiced, and
     * IN_APPROVAL / APPROVED are awaiting sign-off — rewriting the risk detail
     * underneath any of them silently desyncs the issued document from the data
     * it was rated on. Blank status = legacy row, treated as editable.
     */
    private function ensureRiskAddressEditable(RiskAddress $riskAddress): ?JsonResponse
    {
        return $this->ensureActionEditable($riskAddress->action_id ? (int) $riskAddress->action_id : null);
    }

    /**
     * COM/DOM endorsement pro-rata day factor.
     * factor = remainingDaysInCurrentBillingPeriod / periodDays(by freq)
     * freq codes: 1=Monthly(30) 5=Quarterly(91) 6=SemiAnnual(182) 3=Annual(365)
     */
    private function extProRataDayFactor($policy, $action): float
    {
        $freq = (int) ($policy->premium_freq ?? 3);
        $periodDays = match ($freq) {
            1 => 30,
            5 => 91,
            6 => 182,
            default => 365,
        };

        $term = \AlphaDirect\PolicyTerm::where('policy_id', $policy->id)->orderByDesc('id')->first();
        if (!$term) return 1.0;

        try {
            $eff       = \Carbon\Carbon::parse($action->effective_from ?? $term->term_start_date);
            $termStart = \Carbon\Carbon::parse($term->term_start_date);
            $termEnd   = \Carbon\Carbon::parse($term->term_end_date);
        } catch (\Throwable $e) {
            return 1.0;
        }

        if ($eff->lt($termStart)) $eff = $termStart->copy();
        if ($eff->gt($termEnd))   $eff = $termEnd->copy();

        $periodStart = $termStart->copy();
        while ($periodStart->copy()->addDays($periodDays)->lte($eff)) {
            $periodStart->addDays($periodDays);
        }
        $periodEnd = $periodStart->copy()->addDays($periodDays);
        if ($periodEnd->gt($termEnd)) $periodEnd = $termEnd->copy();

        $remaining = $eff->diffInDays($periodEnd) + 1;
        if ($remaining < 0) $remaining = 0;
        if ($remaining > $periodDays) $remaining = $periodDays;

        return $periodDays > 0 ? round($remaining / $periodDays, 6) : 1.0;
    }

    public function updateCoverage(Request $request, int $policyId, int $coverageId): JsonResponse
    {
        if ($r = $this->ensureCoverageEditable($coverageId)) return $r;
        $policy = Policy::findOrFail($policyId);
        $coverage = PolicyCoverage::where('policy_id', $policyId)->findOrFail($coverageId);

        $this->normalizeExcessNumerics($request);
        $validated = $request->validate([
            'coverage_value'             => 'sometimes|numeric|min:0',
            'rate'                       => 'nullable|numeric|min:0',
            'calculated_value'           => 'nullable|numeric|min:0',
            'type_string'                => 'nullable|string|max:50',
            'type_value'                 => 'nullable|numeric',
            'details'                    => 'nullable|array',
            'details.*.coverage_id'      => 'nullable|integer',
            'details.*.sub_coverage_id'  => 'nullable|integer',
            'details.*.description'      => 'nullable|string',
            'details.*.coverage_value_string' => 'nullable|string',
            // DROPDOWN / RADIO second-field pick (tb_cvgpclimits.n_PCLimitId_PK).
            // Declared for the length cap + self-documentation; the `details`
            // array rule already carries nested keys through validated(), so
            // this is not what gated the value — the upsert below is.
            'details.*.limit_id'         => 'nullable|string|max:255',
            'details.*.coverage_value'   => 'nullable|numeric|min:0',
            'details.*.rate'             => 'nullable|numeric|min:0',
            'details.*.calculated_value' => 'nullable|numeric|min:0',
            // Endorse pro-rata gate — false when the wizard is certain this
            // carried-forward sub-coverage row was left untouched this session.
            'details.*.changed'          => 'nullable|boolean',
            // Workers Compensation per-row fields (mirror addCoverage). Without
            // these, edits to an existing WC coverage silently dropped every
            // ratefactor + discount value because updateCoverage's validator
            // stripped unknown keys.
            'details.*.ratefactor_type'           => 'nullable|string',
            'details.*.ratefactor_value'          => 'nullable|string',
            'details.*.ratefactor_value_check'    => 'nullable|string|max:255',
            'details.*.ratefactor_AnnualWages'    => 'nullable|numeric',
            'details.*.ratefactor_deposit_min_pre' => 'nullable|numeric',
            'details.*.discount_surcharge'        => 'nullable|string|in:Discount,Surcharge,None',
            'details.*.discount_surcharge_type'   => 'nullable|string|in:Flat,Percentage',
            'details.*.discount_surcharge_value'  => 'nullable|numeric',
            // Extensions
            'extensions'                              => 'nullable|array',
            'extensions.*.extentions_id'              => 'nullable|integer',
            'extensions.*.s_ScreenName'               => 'nullable|string|max:255',
            'extensions.*.extention_coverage_value'   => 'nullable|numeric',
            'extensions.*.extention_text_value'       => 'nullable|string',
            'extensions.*.extention_limit_id'         => 'nullable|integer',
            'extensions.*.extention_excess_min_value' => 'nullable|numeric',
            'extensions.*.extention_excess_max_value' => 'nullable|numeric',
            'extensions.*.extention_calculated_value' => 'nullable|numeric',
            'extensions.*.extention_sum_insured'      => 'nullable|numeric',
            'extensions.*.type'                       => 'nullable|string',
            // Specified Items — master pick or custom free-text (legacy parity)
            'specified_items'                          => 'nullable|array',
            'specified_items.*.id'                     => 'nullable|integer',
            'specified_items.*.specified_coverage_id'  => 'nullable|integer',
            'specified_items.*.name'                   => 'nullable|string|max:255',
            'specified_items.*.sum_insured'            => 'nullable|numeric',
            'specified_items.*.rate'                   => 'nullable|numeric',
            'specified_items.*.calculated_value'       => 'nullable|numeric',
            // Fidelity Guarantee (policy_coverages_data)
            'fidelity_data'                           => 'nullable|array',
            'fidelity_data.*.cover_type'              => 'nullable|string|max:255',
            'fidelity_data.*.cover_area'              => 'nullable|string|max:255',
            'fidelity_data.*.name_and_position'       => 'nullable|string|max:255',
            'fidelity_data.*.designation'             => 'nullable|string|max:255',
            'fidelity_data.*.length_of_service'       => 'nullable|string|max:255',
            'fidelity_data.*.amount_to_be_guaranteed' => 'nullable|numeric',
            'fidelity_data.*.premium'                 => 'nullable|numeric',
            // Excesses for Theft, Electronics Equipment, Business All Risks, etc.
            'excesses'                                => 'nullable|array',
            'excesses.*.excesses'                     => 'nullable|string',
            'excesses.*.min_percent'                  => 'nullable|numeric',
            'excesses.*.min_amt'                      => 'nullable|numeric',
            'excesses.*.discount_surcharge'           => 'nullable|string|in:Discount,Surcharge',
            'excesses.*.discount_surcharge_type'      => 'nullable|string|in:Flat,Percentage',
            'excesses.*.discount_surcharge_value'     => 'nullable|numeric',
            'excesses.*.premium'                      => 'nullable|numeric',
            // Theft General Questions
            'theft_questions'                         => 'nullable|array',
            'theft_questions.physical_protection_implemented' => 'nullable|string|max:255',
            'theft_questions.premises_alarmed'        => 'nullable|string|max:255',
            'theft_questions.subscribe_armed_security' => 'nullable|string|max:255',
            'theft_questions.security_company'        => 'nullable|string|max:255',
            'theft_questions.maintenance_contract'    => 'nullable|string|max:255',
            'theft_questions.alarmed_installed_date'  => 'nullable|date',
            'theft_questions.opening_closing_signals' => 'nullable|string|max:255',
            // Goods In Transit field (policy_coverages table)
            'property_business_being'                 => 'nullable|string',
            // Office Content: Burglar Alarm Warranty field (policy_coverages table)
            'burglar_alarm_warranty'                  => 'nullable|string',
            // Stated Benefits for Employees Liability / Workers Compensation
            'stated_benefits'                         => 'nullable|string',
            // Money coverage fields (stored in policy_coverage_notes table)
            'memoranda_warranty'                      => 'nullable|string',
            'cash_warranty'                           => 'nullable|string',
            // Notes
            'notes'                                   => 'nullable|string',
        ]);

        // Check if this is a Fidelity Guarantee coverage (stores data in policy_coverages_data, not policy_coverage_detail)
        $coverageMaster = CoverageMaster::find($coverage->coverage_id);
        $isFidelityGuarantee = $coverageMaster && strtoupper($coverageMaster->s_CoverageCode ?? '') === 'FIDELITYGUARANTEE';

        // Same no-detail rule as addCoverage: motor + motor-traders coverages
        // don't use policy_coverage_detail (data lives in motor / motor_traders /
        // motor_traders_internal). Suppress the upsert loop so edits to these
        // coverages don't recreate phantom Main rows.
        $covCodeUpper = strtoupper($coverageMaster?->s_CoverageCode ?? '');
        $skipDetailUpserts = in_array($covCodeUpper, ['MOTORTRADERSEXTERNAL', 'MOTORTRADERSINTERNAL', 'COMMERCIALMOTOR', 'DOMMOTOR'], true);

        // ENDORSE "Cancel Sub Coverage": on an endorsement whose reason is
        // "Cancel Sub Coverage", a subcoverage row with Sum Insured AND Premium
        // both 0 should be persisted as 0 (zeroing the cover so the pro-rata
        // refund computes) rather than skipped as an empty row. Scoped tightly:
        // ENDORSE transaction_type AND that exact reason only — every other
        // action type / reason keeps the "skip empty rows" behaviour untouched.
        // A 0/0 row is only written when a persisted detail row already exists
        // for it (the cancel case); we never create a phantom 0 row from an
        // untouched master-template blank.
        // transaction_reason stores the subtype CODE ("SUBCOVCANCEL"), not the
        // display label ("Cancel Sub Coverage"). Accept either, normalized.
        $editAction = \AlphaDirect\Models\PolicyAction::where('id', $coverage->action_id ?? 0)->first()
            ?? \AlphaDirect\Models\PolicyAction::where('policy_id', $policyId)->orderByDesc('id')->first();
        // Scoped to DomCom products (7, 8) only.
        $normalizeReason = fn($r) => strtolower(preg_replace('/\s+/', '', (string) $r));
        $isEndorseAction = $editAction
            && in_array((int) $policy->product_id, [7, 8], true)
            && $editAction->transaction_type === 'ENDORSE'
            && in_array($normalizeReason($editAction->transaction_reason), ['subcovcancel', 'cancelsubcoverage'], true);

        // If subcoverage details provided, upsert each row (don't delete — preserves data)
        if (!$skipDetailUpserts && !empty($validated['details'])) {
            $totalCovVal = 0;
            $totalCalc   = 0;
            // Action-id this coverage belongs to → marker for "wizard touched
            // this row in this action" (drives Rate's pro-rata sum).
            $covActionId = $coverage->action_id ?? null;
            foreach ($validated['details'] as $det) {
                $covVal  = (float) ($det['coverage_value']   ?? 0);
                $rate    = (float) ($det['rate']             ?? 0);
                $calcVal = (float) ($det['calculated_value'] ?? round($covVal * $rate / 100, 2));

                // WC rows can carry meaningful data without coverage_value or
                // calculated_value (e.g. operator types only Annual Wages or
                // a Description override). Mirror the addCoverage filter so
                // those edits aren't dropped.
                $hasWcContent = (
                    !empty($det['coverage_value_string'])
                    || !empty($det['ratefactor_value'])
                    || !empty($det['ratefactor_AnnualWages'])
                    || !empty($det['ratefactor_value_check'])
                    || !empty($det['ratefactor_deposit_min_pre'])
                    || !empty($det['discount_surcharge'])
                    // A DROPDOWN/RADIO-only row carries no SI/premium/free-text.
                    || !empty($det['limit_id'])
                );
                // Use coverage_id directly (already cloned on frontend when "+" was clicked)
                $detailCoverageId = $det['coverage_id'] ?? $coverage->coverage_id;

                // Zeroing an EXISTING subcoverage must persist on ANY action
                // (quote / renewal / endorsement), not only Cancel Sub Coverage
                // endorses — a 0 is just another value edit (same as 50,000 →
                // 20,000, which already saves everywhere). We still NEVER create
                // a brand-new 0 row: if there's no already-saved row to update,
                // the empty row is skipped so no phantom 0 rows are inserted.
                $isZeroRow = !($covVal > 0 || $calcVal > 0 || $hasWcContent);
                if ($isZeroRow) {
                    $existingZeroTarget = PolicyCoverageDetail::where('policy_coverage_id', $coverageId)
                        ->where('coverage_id', $detailCoverageId)
                        ->whereNull('deleted_at')
                        ->first();
                    if (!$existingZeroTarget) continue;
                }

                $totalCovVal += $covVal;
                $totalCalc   += $calcVal;

                // Wizard-gate + pro-rata pre-compute: same Case 1/2/3/4/5
                // logic as motor (computeRowProRataCase). Stamps
                // pro_rate_premium with the signed delta vs the previous
                // action's row, and sets endors_flag/previousActionIdCov
                // only when the value actually changed. Pre-computing the
                // delta at write time means the V2 Quote Sheet shows the
                // correct per-row pro-rata immediately, without needing a
                // Rate click.
                $detailCase = self::computeRowProRataCase(
                    $policyId,
                    $coverageId,
                    (int) ($covActionId ?? 0),
                    'policy_coverage_detail',
                    'calculated_value',
                    ['coverage_id' => $detailCoverageId],
                    $calcVal
                );

                // Endorse-only: when the wizard explicitly reports this row was
                // left UNTOUCHED this session (changed === false), don't stamp it
                // as a wizard edit — clear the pro-rata gate so writeLineLevelProRata
                // and the banner sum skip it. This is what enforces "only the line
                // the operator actually added/edited is pro-rated": a carried-forward
                // sub-coverage whose value equals what was loaded is still saved
                // (annual premium unchanged), but contributes 0 to the endorse
                // pro-rata. Only a signal of certainty (changed === false) suppresses
                // the stamp — a real add/edit (changed true) or an absent flag keeps
                // the existing computeRowProRataCase behaviour, so nothing else and
                // no other action type changes.
                $rowUntouchedEndorse = ($editAction && $editAction->transaction_type === 'ENDORSE')
                    && array_key_exists('changed', $det) && $det['changed'] === false;

                // …EXCEPT when this row was already edited on an EARLIER submit
                // of the SAME endorse action. The FE's `changed` flag is
                // per-editing-session, so a line the operator changed on submit
                // #1 is reported changed:false on submit #2 (when they edit a
                // different line). Wiping its gate here discards the first
                // edit's pro-rata on the next Rate. A row still stamped with the
                // current action id is a genuine same-action edit — keep it, and
                // let computeRowProRataCase (Case 2) re-derive the delta against
                // the true previous-action baseline.
                if ($rowUntouchedEndorse && $covActionId
                    && PolicyCoverageDetail::where('policy_coverage_id', $coverageId)
                        ->where('coverage_id', $detailCoverageId)
                        ->whereNull('deleted_at')
                        ->where('previousActionIdCov', $covActionId)
                        ->exists()
                ) {
                    $rowUntouchedEndorse = false;
                }

                $updateData = [
                    'coverage_value'      => $covVal,
                    'rate'                => $rate,
                    'calculated_value'    => $calcVal,
                    // Use coverage_value_string as sent by frontend. Don't fall back to
                    // description — if user clears the free text field, it should stay cleared.
                    // Frontend now explicitly sends this field (even if empty) so we should
                    // respect the user's edit. Convert empty strings to null for clean storage.
                    'coverage_value_string' => (($det['coverage_value_string'] ?? '') === '') ? null : $det['coverage_value_string'],
                    'pro_rate_premium'    => $rowUntouchedEndorse ? 0 : $detailCase['pro_rate_premium'],
                    'endors_flag'         => $rowUntouchedEndorse ? 0 : $detailCase['endors_flag'],
                    'previousActionIdCov' => $rowUntouchedEndorse ? 0 : $detailCase['previousActionIdCov'],
                    'deleted_at'          => null,  // Restore if soft-deleted
                ];
                // Workers Compensation per-row fields. Schema-gated so older
                // envs without the columns don't 500 on Unknown column. Always
                // update these fields when the FE sends them, to support clearing
                // values (empty strings → null). When the FE sends a field, it means
                // the user edited it, and we should persist that edit including
                // clearing if they removed the value.
                // `limit_id` rides the same treatment: it is the DROPDOWN/RADIO
                // second-field pick, only written when the FE sends the key, and
                // cleared to null when the operator resets the select.
                foreach ([
                    'ratefactor_type',
                    'ratefactor_value',
                    'ratefactor_value_check',
                    'ratefactor_AnnualWages',
                    'ratefactor_deposit_min_pre',
                    'limit_id',
                ] as $rfCol) {
                    if (array_key_exists($rfCol, $det) && \Schema::hasColumn('policy_coverage_detail', $rfCol)) {
                        $val = $det[$rfCol];
                        // Strip thousands-separators from numeric ratefactor
                        // columns (legacy mirror — see ManageCoverages submit).
                        if (in_array($rfCol, ['ratefactor_AnnualWages', 'ratefactor_deposit_min_pre'], true) && is_string($val)) {
                            $val = str_replace(',', '', $val);
                        }
                        // Convert empty strings to null so cleared values are saved as null
                        $updateData[$rfCol] = (is_string($val) && $val === '') || $val === null ? null : $val;
                    }
                }
                if (array_key_exists('discount_surcharge', $det) && \Schema::hasColumn('policy_coverage_detail', 'discount_surcharge')) {
                    $ds = $det['discount_surcharge'];
                    // Clear if set to 'None' or empty string
                    $updateData['discount_surcharge'] = ($ds === 'None' || $ds === '' || $ds === null) ? null : $ds;
                }
                if (array_key_exists('discount_surcharge_type', $det) && \Schema::hasColumn('policy_coverage_detail', 'discount_surcharge_type')) {
                    $dst = $det['discount_surcharge_type'];
                    // Clear if empty string or null
                    $updateData['discount_surcharge_type'] = ($dst === '' || $dst === null) ? null : $dst;
                }
                if (array_key_exists('discount_surcharge_value', $det) && \Schema::hasColumn('policy_coverage_detail', 'discount_surcharge_value')) {
                    // Allow 0 as a valid value; only clear if null
                    $updateData['discount_surcharge_value'] = $det['discount_surcharge_value'] !== null ? (float) ($det['discount_surcharge_value'] ?? 0) : null;
                }

                // Use updateOrCreate to preserve existing rows (don't create duplicates)
                // Matches GraphiteBWV8 submit() logic
                PolicyCoverageDetail::withTrashed()->updateOrCreate(
                    [
                        'policy_coverage_id' => $coverageId,
                        'coverage_id'        => $detailCoverageId,
                    ],
                    $updateData
                );
            }
            // Per UW requirement (2026-06): no "Main"/total-premium row is
            // written to policy_coverage_detail for the parent coverage_id.
            // Premium now comes ONLY from sub-coverage detail rows (+ extensions
            // / specified items via recomputeActionTotals). NOTE: coverages that
            // previously carried their whole premium on this Main row (e.g.
            // Houseowner-Buildings, Fire, Workers Compensation hand-entered
            // total) will show 0 unless that premium is entered on a sub-row.
            // Any stale Main rows already in the table are cleaned below.
            $this->deleteMainCoverageDetailRow($coverageId, $coverage->coverage_id);

            // Drop any second LIVE row for a sub-coverage this coverage already
            // holds (historic double-replication). It is unreachable by the
            // wizard but doubles the premium in every recipe — including the
            // parent total re-derived on the next line. See
            // collapseDuplicateDetailRows.
            self::collapseDuplicateDetailRows($coverageId);

            // Recalculate parent totals from ALL detail rows (not just the ones sent)
            $allDetails = PolicyCoverageDetail::where('policy_coverage_id', $coverageId)->whereNull('deleted_at')->get();
            $validated['coverage_value']   = round($allDetails->sum('coverage_value'), 2);
            $validated['calculated_value'] = round($allDetails->sum('calculated_value'), 2);
        }
        // COM/DOM (product 7/8): per UW, never keep a coverage-wise "Main"
        // policy_coverage_detail row even when no detail rows are sent — strip
        // any existing one and skip the simple-coverage upsert below. Premium
        // for these products comes only from per-row (sub-coverage) data.
        elseif ($this->isDomComProduct($policy)) {
            $this->deleteMainCoverageDetailRow($coverageId, $coverage->coverage_id);
        }
        // Specialist / Fidelity covers: premium lives in their own table, which
        // the annual recipe sums separately — a Main row here would be counted
        // twice (see OWN_PREMIUM_TABLE_COVERAGE_CODES). Strip any row written
        // before this guard existed so re-saving the coverage repairs the policy.
        elseif (self::isOwnPremiumTableCoverage($coverage->coverage_id)) {
            $this->deleteMainCoverageDetailRow($coverageId, $coverage->coverage_id);
        }
        // If no details sent but top-level coverage_value provided (simple coverages without
        // subcoverages — specialist products, basic single-value coverages), upsert a single
        // detail row using the coverage's own coverage_id as the sub-coverage key. This is
        // how graphiteBWV8 stores simple coverage values — on policy_coverage_detail, not
        // policy_coverages (which has no value columns).
        // EXCEPT: Fidelity Guarantee coverages store data in policy_coverages_data, not
        // policy_coverage_detail — skip this block for Fidelity Guarantee.
        elseif (!$isFidelityGuarantee && (isset($validated['coverage_value']) || isset($validated['rate']) || isset($validated['calculated_value']))) {
            $covVal  = (float) ($validated['coverage_value']   ?? 0);
            $rate    = (float) ($validated['rate']             ?? 0);
            $calcVal = (float) ($validated['calculated_value'] ?? round($covVal * $rate / 100, 2));

            $existing = PolicyCoverageDetail::where('policy_coverage_id', $coverageId)
                ->where('coverage_id', $coverage->coverage_id)
                ->whereNull('deleted_at')
                ->first();

            // Wizard-gate: stamp previousActionIdCov + endors_flag so
            // writeLineLevelProRata recognises this row as user-touched in
            // the current ENDORSE and writes the (new − prev) delta.
            // pro_rate_premium itself is set by Rate, not here.
            $covActionId = $coverage->action_id ?? null;
            $wizardStamps = [
                'endors_flag'         => ($covActionId ? 1 : 0),
                'previousActionIdCov' => ($covActionId ?: 0),
            ];

            if ($existing) {
                $existing->update(array_merge([
                    'coverage_value'   => $covVal,
                    'rate'             => $rate,
                    'calculated_value' => $calcVal,
                ], $wizardStamps));
            } elseif ($covVal > 0 || $calcVal > 0) {
                PolicyCoverageDetail::create(array_merge([
                    'policy_coverage_id'  => $coverageId,
                    'coverage_id'         => $coverage->coverage_id,
                    'coverage_value'      => $covVal,
                    'rate'                => $rate,
                    'calculated_value'    => $calcVal,
                ], $wizardStamps));
            }
        }

        // Save extensions — smart-sync (no clear-all-then-insert).
        //
        // BACKGROUND: previously this block did "soft-delete all rows for
        // policy_coverage_id, then insert each payload extension". Every
        // edit accumulated trashed rows (7+ rows for one extension after
        // a few saves) AND skipped previousActionIdCov entirely, so
        // writeLineLevelProRata's wizard-gate filtered every row out and
        // the Rate banner saw no extension delta.
        //
        // FIX: match each payload extension to an existing active row by
        // identity (id → extentions_id → custom_name for free-text), then
        // update in place. Insert only when no match. Soft-delete only
        // rows the operator actually removed. Stamp previousActionIdCov
        // on every wizard-touched row so writeLineLevelProRata picks them
        // up. Pro-rata DELTAS + factor are computed by writeLineLevelProRata
        // (annual delta) and applied via the banner factor (line 2035) —
        // we do NOT pre-factor pro_rate_premium here (it gets reset to 0
        // and recomputed by writeLineLevelProRata on Rate anyway).
        // Convert excesses to extensions format before saving — SAME as
        // addCoverage. Without this, editing a coverage dropped the separate
        // `excesses` payload entirely (it was validated but never merged into
        // extensions), so excesses "didn't save at all" on Update Coverage.
        // Stored as type='Excess' rows in policy_extention_detail (V1 parity);
        // the loop below add/edit/removes them via the custom_name match.
        if (!empty($validated['excesses'])) {
            foreach ($validated['excesses'] as $exc) {
                if (!empty($exc['excesses']) || !empty($exc['min_percent']) || !empty($exc['min_amt']) || !empty($exc['discount_surcharge']) || !empty($exc['premium'])) {
                    $validated['extensions'][] = [
                        'type' => 'Excess',
                        's_ScreenName' => $exc['excesses'] ?? 'Excess',
                        'extention_text_value' => $exc['excesses'] ?? null,
                        'extention_excess_min_value' => $exc['min_percent'] ?? 0,
                        'extention_excess_max_value' => $exc['min_amt'] ?? 0,
                        'extention_discount_surcharge' => $exc['discount_surcharge'] ?? '',
                        'extention_discount_surcharge_type' => $exc['discount_surcharge_type'] ?? '',
                        'extention_discount_surcharge_value' => $exc['discount_surcharge_value'] ?? 0,
                        'extention_calculated_value' => $exc['premium'] ?? 0,
                        'extention_coverage_value' => 0,
                        'extention_sum_insured' => null,
                    ];
                }
            }
        }

        if (array_key_exists('extensions', $validated) && is_array($validated['extensions'])) {
            $master         = CoverageMaster::find($coverage->coverage_id);
            $hasCustomName  = \Schema::hasColumn('policy_extention_detail', 'custom_name');

            $action = \AlphaDirect\Models\PolicyAction::where('id', $coverage->action_id ?? 0)->first()
                ?? \AlphaDirect\Models\PolicyAction::where('policy_id', $policyId)->orderByDesc('id')->first();
            $isEndorse = $action && $action->transaction_type === 'ENDORSE';

            // DomCom (product 7/8) only: a coverage must save ONLY its own
            // extensions. A payload extension whose master (extentions row)
            // belongs to a DIFFERENT coverage is mis-attached — skip writing it
            // below (and the replace-loop then soft-deletes any existing such
            // row), so foreign extensions can't be carried forward/re-saved.
            $enforceOwnExtensions = in_array((int) ($policy->product_id ?? 0), [7, 8], true);

            $existingActive = \AlphaDirect\Models\PolicyExtentionDetails::where('policy_coverage_id', $coverageId)
                ->whereNull('deleted_at')
                ->get()
                ->keyBy('id');
            $keptIds = [];

            foreach ($validated['extensions'] as $ext) {
                // Only save if extension has actual values (following old project pattern)
                // Include s_ScreenName/custom_name check for Theft excesses which may only have a name
                // Include excess min/max values for Excess type
                $hasValue = !empty($ext['extention_coverage_value']) || !empty($ext['extention_text_value'])
                    || !empty($ext['extention_limit_id']) || !empty($ext['extention_discount_surcharge_value'])
                    || !empty($ext['extention_calculated_value']) || !empty($ext['extention_sum_insured'])
                    || !empty($ext['s_ScreenName']) || !empty($ext['custom_name'])
                    || !empty($ext['extention_excess_min_value']) || !empty($ext['extention_excess_max_value']);
                if (!$hasValue) continue;

                // Fetch extension master record to get all the metadata columns
                $extMaster = !empty($ext['extentions_id'])
                    ? DB::table('extentions')->where('id', $ext['extentions_id'])->first()
                    : null;

                // DomCom 7/8: skip extensions that belong to another coverage.
                // Determined from the authoritative master (extentions.s_ParentCoverageID)
                // vs this coverage's master id. Excess rows / custom rows carry no
                // extentions_id (extMaster null) and rows whose master has no parent
                // are kept — only a resolvable, different parent is treated as foreign.
                if ($enforceOwnExtensions && $extMaster && !empty($extMaster->s_ParentCoverageID)
                    && (int) $extMaster->s_ParentCoverageID !== (int) $coverage->coverage_id) {
                    continue;
                }

                $row = [
                    'policy_coverage_id'                    => $coverageId,
                    'extentions_id'                         => $ext['extentions_id'] ?? null,
                    's_ParentCoverageID'                    => $extMaster?->s_ParentCoverageID ?? ($master?->s_ParentCoverageID ?: $master?->id),
                    's_ParentCoverageCode'                  => $extMaster?->s_ParentCoverageCode ?? ($master?->s_CoverageCode ?? null),
                    'type'                                  => $ext['type'] ?? 'Extention',
                    'extention_coverage_value'              => $ext['extention_coverage_value'] ?? 0,
                    'extention_text_value'                  => $ext['extention_text_value'] ?? null,
                    'extention_limit_id'                    => $ext['extention_limit_id'] ?? null,
                    'extention_excess_min_value'            => $ext['extention_excess_min_value'] ?? 0,
                    'extention_excess_max_value'            => $ext['extention_excess_max_value'] ?? 0,
                    'extention_discount_surcharge'          => $ext['extention_discount_surcharge'] ?? '',
                    'extention_discount_surcharge_type'     => $ext['extention_discount_surcharge_type'] ?? '',
                    'extention_discount_surcharge_value'    => $ext['extention_discount_surcharge_value'] ?? 0,
                    'extention_calculated_value'            => $ext['extention_calculated_value'] ?? 0,
                    // extention_sum_insured is NOT NULL with no DB default —
                    // coalesce to 0 (the value the FE/excess path implies when
                    // the field is absent). The Excess→extension conversion
                    // sends null here, which 1048'd the whole Update/Add
                    // Coverage save ("Column 'extention_sum_insured' cannot be
                    // null") on coverages carrying an excess (e.g. Electronic
                    // Equipment). Existing excess rows store 0.
                    'extention_sum_insured'                 => $ext['extention_sum_insured'] ?? 0,
                ];

                // Add optional master metadata columns only if they exist in schema
                if ($extMaster) {
                    $optionalCols = ['s_CoverageName', 's_CoverageCode', 's_ScreenName', 's_CoverageDesc', 's_ExtensionsGroupName',
                                     'n_DisplaySequence', 'extention_type', 'rate', 'd_EffectiveDt', 'd_ExpirationDt', 's_RatingMethod', 's_DISPLAYTOUSER'];
                    foreach ($optionalCols as $col) {
                        if (\Schema::hasColumn('policy_extention_detail', $col)) {
                            $row[$col] = $extMaster->$col ?? null;
                        }
                    }
                }

                if ($hasCustomName && !empty($ext['s_ScreenName'])) {
                    if ($extMaster && $ext['s_ScreenName'] !== $extMaster->s_ScreenName) {
                        $row['custom_name'] = $ext['s_ScreenName'];
                    } else if (!$extMaster && ($ext['type'] ?? '') === 'Excess') {
                        // For Excess type without master, use s_ScreenName as custom_name
                        $row['custom_name'] = $ext['s_ScreenName'];
                    }
                }

                $match = null;
                if (!empty($ext['id']) && isset($existingActive[$ext['id']])) {
                    $match = $existingActive[$ext['id']];
                }
                if (!$match) {
                    foreach ($existingActive as $existing) {
                        if ($keptIds[$existing->id] ?? false) continue;
                        $sameMaster = !empty($ext['extentions_id'])
                            && (int) $existing->extentions_id === (int) $ext['extentions_id'];
                        $sameCustom = empty($ext['extentions_id'])
                            && $hasCustomName
                            && trim((string) ($existing->custom_name ?? '')) === trim((string) ($ext['s_ScreenName'] ?? ''));
                        if ($sameMaster || $sameCustom) { $match = $existing; break; }
                    }
                }

                // Wizard-gate: stamp previousActionIdCov so writeLineLevelProRata
                // recognises this row as user-touched in the current ENDORSE.
                if ($isEndorse) {
                    $row['previousActionIdCov'] = $action->id;
                    $row['endors_flag']         = 1;
                }

                if ($match) {
                    $match->forceFill(array_merge($row, ['updated_at' => now()]))->save();
                    $keptIds[$match->id] = true;
                } else {
                    $row['created_at'] = now();
                    $row['updated_at'] = now();
                    $extModel = new \AlphaDirect\Models\PolicyExtentionDetails();
                    $extModel->forceFill($row)->save();
                    $keptIds[$extModel->id] = true;
                }
            }

            // Soft-delete extensions the operator removed. Stamp the wizard-gate
            // on the deleted row too so writeLineLevelProRata writes the
            // negative-delta refund (newVal=0 because deleted_at!=null,
            // delta = -prevVal).
            foreach ($existingActive as $existing) {
                if (!empty($keptIds[$existing->id])) continue;
                if ($isEndorse) {
                    $existing->forceFill([
                        'previousActionIdCov' => $action->id,
                        'endors_flag'         => 1,
                    ])->save();
                }
                $existing->delete();
            }
        }

        // Save specified items — smart sync (legacy graphiteBWV8 behaviour).
        //
        // BACKGROUND: previously this block did "soft-delete all coverage-level
        // items, then insert each payload item". Every save accumulated a
        // soft-deleted row stamped with the same action_id, so on policies
        // with several saves the V2 Quote Sheet's WC Misc list rendered
        // 4× duplicates of the same line item — the blade intentionally
        // surfaces same-action soft-deletes as "cancelled in this
        // endorsement", and our save path was minting those phantoms on
        // every legitimate edit.
        //
        // FIX: match each payload item against an existing active row by
        // identity, update in place; insert only when no match exists. Drop
        // (soft-delete) only the active rows the operator actually removed
        // from the FE list. Mirrors graphiteBWV8 ManageCoverages submit()
        // line 3789-3820 which also matches on (specified_coverage_id,
        // policy_coverage_id, motor_id IS NULL) before creating.
        if (array_key_exists('specified_items', $validated) && is_array($validated['specified_items'])) {
            // Resolve the action from the COVERAGE being edited — NOT the
            // policy's latest action by id. On a back-dated / non-latest
            // endorse the newest action by id can be a *different* ISSUED
            // endorse; stamping misc items with its id leaves
            // previousActionIdCov pointing at the wrong action, so Rate's
            // writeLineLevelProRata gate (previousActionIdCov = rated action)
            // skips them and the item shows P0 pro-rata while still moving
            // annual. Mirrors the extensions block above (L4478) + addCoverage.
            $action = \AlphaDirect\Models\PolicyAction::where('id', $coverage->action_id ?? 0)->first()
                ?? \AlphaDirect\Models\PolicyAction::where('policy_id', $policyId)->orderBy('id', 'desc')->first();
            $term = ($action && $action->term_id)
                ? PolicyTerm::find($action->term_id)
                : PolicyTerm::where('policy_id', $policyId)->orderBy('id', 'desc')->first();
            $hasCustomNameCol  = \Schema::hasColumn('policy_specified_items', 'custom_name');
            $hasPrevActionCol  = \Schema::hasColumn('policy_specified_items', 'previousActionIdCov');
            $isEndorse         = $action && $action->transaction_type === 'ENDORSE';

            // Pre-load existing active rows for this coverage so we can match
            // payload items by id or identity (smart-sync). Anything not
            // matched at the end of the loop is soft-deleted.
            // Coverage-level rows are motor_id NULL (V2) OR 0 (legacy/cron,
            // when the column was NOT NULL DEFAULT 0 before the nullable
            // migration). Matching only whereNull('motor_id') missed the
            // legacy/replicated 0-rows, so an unchanged misc item carried into
            // an anniversary-renew coverage failed to match and a duplicate
            // NULL row was inserted on every save. Mirror the null/0 read
            // convention used elsewhere (e.g. the per-vehicle SI query and the
            // coverage-level note filter) so we update in place instead.
            // Motor-attached specified items only exist on motor coverages
            // (master coverage_id 22 / 27). On every other coverage motor_id is
            // meaningless — treat 0 and NULL as the same coverage-level pool and
            // don't filter or skip by motor_id at all, so an unchanged misc item
            // (e.g. carried in with motor_id 0) matches in place instead of
            // duplicating. On motor coverages keep loading coverage-level rows
            // only (NULL or legacy 0); motor-attached rows are owned by the
            // per-motor endpoints.
            $isMotorCoverage = in_array((int) $coverage->coverage_id, [22, 27], true);
            $existingActive = \AlphaDirect\Models\PolicySpecifiedItem::where('policy_coverage_id', $coverageId)
                ->whereNull('deleted_at')
                ->when($isMotorCoverage, function ($q) {
                    $q->where(function ($m) {
                        $m->whereNull('motor_id')->orWhere('motor_id', 0);
                    });
                })
                ->get()
                ->keyBy('id');
            $keptIds = [];

            foreach ($validated['specified_items'] as $item) {
                // Skip motor-attached items — owned by per-motor endpoints —
                // but only on motor coverages (22/27). On a non-motor coverage a
                // motor_id is meaningless, so don't skip: treat the item as
                // coverage-level (0 / NULL / any are the same pool).
                if ($isMotorCoverage && !empty($item['motor_id'])) continue;

                // Skip soft-deleted items (don't update or re-insert them)
                if (!empty($item['deleted_at'])) continue;

                // Normalize motor_id: frontend may send 0 (or omit it entirely on
                // non-motor coverages like Fire), but DB should store NULL for
                // coverage-level items. Use null-coalescing so a missing key
                // doesn't raise "Undefined array key 'motor_id'".
                if (($item['motor_id'] ?? null) === 0 || ($item['motor_id'] ?? null) === '0') {
                    $item['motor_id'] = null;
                }

                $hasPayload = !empty($item['sum_insured']) || !empty($item['calculated_value']);
                $hasIdentity = !empty($item['specified_coverage_id']) || !empty($item['name']);

                // Only process items that have both payload AND identity, OR existing items being preserved
                if (!$hasIdentity) continue;

                // If no payload, try to find existing item to preserve it (don't create new ones)
                if (!$hasPayload && empty($item['id'])) {
                    // Look for existing item by identity to preserve it
                    $existingByIdentity = null;
                    foreach ($existingActive as $existing) {
                        if (!empty($keptIds[$existing->id])) continue;
                        $sameMaster = !empty($item['specified_coverage_id'])
                            && (int) $existing->specified_coverage_id === (int) $item['specified_coverage_id'];
                        $sameCustom = empty($item['specified_coverage_id'])
                            && $hasCustomNameCol
                            && trim((string) ($existing->custom_name ?? '')) === trim((string) ($item['name'] ?? ''));
                        if ($sameMaster || $sameCustom) {
                            $existingByIdentity = $existing;
                            break;
                        }
                    }
                    if ($existingByIdentity) {
                        // Mark as kept so it won't be soft-deleted
                        $keptIds[$existingByIdentity->id] = true;
                    }
                    continue;
                }

                if (!$hasPayload) continue;

                $calcVal = ($item['sum_insured'] ?? 0) * ($item['rate'] ?? 0) / 100;
                $row = array_merge([
                    'policy_coverage_id'    => $coverageId,
                    'specified_coverage_id' => $item['specified_coverage_id'] ?? null,
                    'sum_insured'           => $item['sum_insured'] ?? 0,
                    'rate'                  => $item['rate'] ?? 0,
                    'calculated_value'      => $item['calculated_value'] ?? round($calcVal, 2),
                    'term_id'               => $term?->id,
                    'action_id'             => $action?->id,
                ], $this->auditStamps('policy_specified_items'));

                if ($hasCustomNameCol && empty($item['specified_coverage_id']) && !empty($item['name'])) {
                    $row['custom_name'] = $item['name'];
                }

                $match = null;
                if (!empty($item['id'])) {
                    $match = $existingActive[$item['id']] ?? null;
                }
                if (!$match) {
                    foreach ($existingActive as $existing) {
                        if ($keptIds[$existing->id] ?? false) continue;

                        // Match 1: by specified_coverage_id (master picks)
                        $sameMaster = !empty($item['specified_coverage_id'])
                            && (int) $existing->specified_coverage_id === (int) $item['specified_coverage_id'];

                        // Match 2: by custom_name (free-text items)
                        $sameCustom = empty($item['specified_coverage_id'])
                            && $hasCustomNameCol
                            && trim((string) ($existing->custom_name ?? '')) === trim((string) ($item['name'] ?? ''));

                        // Match 3: by values (sum_insured + rate) as fallback for amendments/renewals
                        // where identity fields might not be sent but values are unchanged
                        $sameValues = (float) ($item['sum_insured'] ?? 0) === (float) ($existing->sum_insured ?? 0)
                            && (float) ($item['rate'] ?? 0) === (float) ($existing->rate ?? 0)
                            && $item['sum_insured'] !== null  // Must have actual values, not just defaults
                            && $item['sum_insured'] > 0;

                        if ($sameMaster || $sameCustom || $sameValues) { $match = $existing; break; }
                    }
                }

                // Wizard-gate + pro-rata pre-compute via the same Case
                // 1/2/3/4/5 logic motor uses. Identity for misc items is
                // (specified_coverage_id) for master picks, (custom_name)
                // for free-text rows. motor_id is null here — coverage-level
                // misc only (motor-attached items go through per-motor
                // endpoints).
                // Stamp the wizard-gate so Rate's writeLineLevelProRata
                // evaluates this row. Mirror the CANCEL branch below and
                // addCoverage/addSpecifiedItem: stamp previousActionIdCov =
                // THIS coverage's action directly, NOT via computeRowProRataCase.
                // The Case helper derives its baseline from the latest
                // same-coverage row, so a misc item carried forward by
                // replication (or a duplicate) self-references to delta 0 and
                // the helper then *preserves the stale* previousActionIdCov —
                // leaving an ADDCOVG item permanently un-rated. The
                // authoritative delta (vs the previous ACTION) is computed by
                // writeLineLevelProRata on Rate/recompute, which zeroes
                // genuinely unchanged rows, so a direct stamp can't over-charge.
                if ($isEndorse && $hasPrevActionCol) {
                    $row['previousActionIdCov'] = $action->id;
                    $row['endors_flag']         = '1';
                }

                // Dedup duplicate MASTER picks: a master specified item
                // (specified_coverage_id) can exist at most once per coverage.
                // If the FE sent the carried-forward row AND a freshly-added
                // line for the same master item, the first claimed the existing
                // row (marked in $keptIds) and the second fell through to
                // INSERT — leaving two active rows for one master item, and the
                // carried-forward original kept its stale previousActionIdCov so
                // writeLineLevelProRata skipped it (pro-rata wrong / 0). Merge
                // the duplicate entry into that already-kept row (last value
                // wins) and let the stamp below re-point previousActionIdCov to
                // the current action. Master picks only — custom free-text rows
                // (no specified_coverage_id) are matched by exact custom_name
                // above and may legitimately repeat under different names.
                if (!$match && !empty($item['specified_coverage_id'])) {
                    foreach ($existingActive as $existing) {
                        if ((int) $existing->specified_coverage_id === (int) $item['specified_coverage_id']) {
                            $match = $existing;
                            break;
                        }
                    }
                }

                // Reinstate-in-place: if there's no ACTIVE match but a
                // soft-deleted row of the same identity exists in this coverage
                // (the item was cancelled then re-added/edited within the same
                // endorse), revive and update THAT row instead of inserting a
                // duplicate. $existingActive is built whereNull('deleted_at'),
                // so without this a cancel→reinstate+edit always spawned a
                // second MISC row — and the duplicate corrupts the pro-rata
                // baseline (writeLineLevelProRata then nets to 0). Coverage-
                // level pool only; motor-attached 22/27 rows are owned by the
                // per-motor endpoints and never reach this loop.
                if (!$match) {
                    $trashedMatch = \AlphaDirect\Models\PolicySpecifiedItem::onlyTrashed()
                        ->where('policy_coverage_id', $coverageId)
                        ->when($isMotorCoverage, function ($q) {
                            $q->where(fn($m) => $m->whereNull('motor_id')->orWhere('motor_id', 0));
                        });
                    if (!empty($item['specified_coverage_id'])) {
                        $trashedMatch->where('specified_coverage_id', $item['specified_coverage_id']);
                    } elseif ($hasCustomNameCol && !empty($item['name'])) {
                        $trashedMatch->whereNull('specified_coverage_id')
                            ->where('custom_name', $item['name']);
                    } else {
                        $trashedMatch = null;
                    }
                    if ($trashedMatch && ($revive = $trashedMatch->orderByDesc('id')->first())) {
                        $match = $revive;
                        $row['deleted_at'] = null; // bring the row back in place
                    }
                }

                if ($match) {
                    $match->forceFill(array_merge($row, [
                        'specified_coverage_id' => $item['specified_coverage_id'] ?? null,
                    ], $this->auditStamps('policy_specified_items')))->save();
                    $keptIds[$match->id] = true;
                } else {
                    $siModel = new \AlphaDirect\Models\PolicySpecifiedItem();
                    $siModel->forceFill($row)->save();
                    $keptIds[$siModel->id] = true;
                }
            }
            // Soft-delete the rows the operator removed from the FE list.
            // Stamp the wizard-gate FIRST so writeLineLevelProRata writes the
            // refund delta = -prev_value when this row's deleted_at!=null
            // (newVal=0, prevVal=row.calculated_value → delta = -prevVal).
            foreach ($existingActive as $existing) {
                if (!empty($keptIds[$existing->id])) continue;
                if ($isEndorse && $hasPrevActionCol) {
                    $existing->forceFill([
                        'previousActionIdCov' => $action->id,
                        'endors_flag'         => '1',
                    ])->save();
                }
                $existing->delete();
            }
        }

        // Save Fidelity Guarantee data (policy_coverages_data) — update/insert semantics
        if (array_key_exists('fidelity_data', $validated) && is_array($validated['fidelity_data'])) {
            Log::info('Saving fidelity_data for coverage', [
                'coverageId' => $coverageId,
                'policyId' => $policyId,
                'fidelity_count' => count($validated['fidelity_data']),
                'fidelity_data' => $validated['fidelity_data'],
            ]);
            // Load existing fidelity rows for this coverage
            $existingFidelity = \AlphaDirect\Models\PolicyCoveragesData::where('policyCoverageID', $coverageId)
                ->where('policy_id', $policyId)
                ->get();
            $keptFidelityIds = [];

            foreach ($validated['fidelity_data'] as $fid) {
                Log::info('Processing fidelity row', ['id' => $fid['id'] ?? null, 'data' => $fid]);

                // Skip if soft-deleted
                if (!empty($fid['deleted_at'])) {
                    Log::info('Skipping soft-deleted row', ['id' => $fid['id'] ?? null]);
                    continue;
                }

                // Skip empty rows — must have at least one field filled (matches frontend filter)
                if (empty($fid['cover_type']) && empty($fid['cover_area']) && empty($fid['name_and_position'])
                    && empty($fid['designation']) && empty($fid['length_of_service'])
                    && empty($fid['amount_to_be_guaranteed']) && empty($fid['premium'])) {
                    Log::info('Skipping empty row', ['id' => $fid['id'] ?? null]);
                    continue;
                }

                $payload = [
                    'cover_type'                  => $fid['cover_type'] ?? '',
                    'cover_area'                  => $fid['cover_area'] ?? '',
                    'name_and_position'           => $fid['name_and_position'] ?? '',
                    'designation'                 => $fid['designation'] ?? '',
                    'length_of_service'           => $fid['length_of_service'] ?? '',
                    'amount_to_be_guaranteed'     => $fid['amount_to_be_guaranteed'] ?? 0,
                    'premium'                     => $fid['premium'] ?? 0,
                ];

                // If item has ID, update it; otherwise insert it
                if (!empty($fid['id'])) {
                    \AlphaDirect\Models\PolicyCoveragesData::where('id', $fid['id'])
                        ->update(array_merge($payload, ['updated_at' => now()]));
                    Log::info('Updated fidelity row', ['id' => $fid['id']]);
                    $keptFidelityIds[] = $fid['id'];
                } else {
                    $fidModel = new \AlphaDirect\Models\PolicyCoveragesData();
                    $fidModel->forceFill(array_merge([
                        'policyCoverageID' => $coverageId,
                        'policy_id'        => $policyId,
                        'risk_address'     => $coverage->risk_address_id,
                    ], $payload))->save();
                    Log::info('Inserted fidelity row', ['id' => $fidModel->id]);
                    $keptFidelityIds[] = $fidModel->id;
                }
            }

            // Soft-delete fidelity rows that weren't in the request
            foreach ($existingFidelity as $existing) {
                if (!in_array($existing->id, $keptFidelityIds)) {
                    $existing->delete();
                }
            }
        }

        // Update Goods In Transit field if provided (stored in policy_coverages table)
        if (array_key_exists('property_business_being', $validated)) {
            $coverage->update(['property_business_being' => $validated['property_business_being'] ?? null]);
        }

        // Update Burglar Alarm Warranty field if provided (stored in policy_coverages table)
        if (array_key_exists('burglar_alarm_warranty', $validated)) {
            $coverage->update(['burglar_alarm_warranty' => $validated['burglar_alarm_warranty'] ?? null]);
        }

        // Update Stated Benefits field if provided (stored in policy_coverages table)
        if (array_key_exists('stated_benefits', $validated)) {
            $coverage->update(['stated_benefits' => $validated['stated_benefits'] ?? null]);
        }

        // Save coverage note. Same present-vs-non-empty distinction: if
        // the request omits `notes` entirely we leave the existing note
        // alone; if it sends an empty string the operator cleared the
        // field, so we delete the row. Previously an empty string
        // preserved the stale note because of the `!== ''` guard.
        if (array_key_exists('notes', $validated)) {
            $noteText = (string) ($validated['notes'] ?? '');
            // Coverage-level note = exactly ONE row per policy_coverage_id with
            // motor_id IS NULL (motor notes, coverage 22/27, are keyed by
            // motor_id and untouched here). Update the earliest such row and
            // drop any duplicates so repeated edits never stack new rows
            // (matches V1 ManageCoverages). Empty text clears the note.
            // Eloquent so PolicyCoverageNote Auditable fires per change.
            $covNotes = \AlphaDirect\Models\PolicyCoverageNote::where('policy_coverage_id', $coverageId)
                ->coverageLevel()->orderBy('id')->get();
            $keep = $covNotes->shift();
            // Duplicates are debris from the old warranty lookup and can be the
            // ONLY carrier of the Money / burglar / endorsement text, so pull
            // that across before binning them.
            if ($keep) {
                $this->absorbDuplicateCoverageNotes($keep, $covNotes);
            }
            if ($noteText === '') {
                // Clearing the note must NOT drop the row when it also carries
                // the Money warranties / WC benefits text — those columns live
                // on this same row and are written by the blocks below. Blank
                // the note in place and only bin the row when nothing else is
                // on it, otherwise "clear the note" silently wiped the Money
                // Memoranda + Cash Carrying Warranty as well.
                if ($keep) {
                    $this->coverageNoteCarriesOtherText($keep)
                        ? $keep->forceFill(['note' => ''])->save()
                        : $keep->delete();
                }
            } else {
                $keep = $keep ?? new \AlphaDirect\Models\PolicyCoverageNote(['policy_coverage_id' => $coverageId]);
                $keep->forceFill(['note' => $noteText])->save();
            }
            $covNotes->each(fn($n) => $n->delete());
        }

        // Update Money coverage fields (memoranda_warranty, cash_warranty) —
        // stored on the SAME coverage-level policy_coverage_notes row as
        // `note`. Resolve that row with coverageLevel() (motor_id NULL *or*
        // 0), not whereNull('motor_id'): legacy/replicated rows carry
        // motor_id = 0, so the NULL-only lookup missed them and inserted a
        // second coverage-level row per save. Both read paths take the
        // newest coverage-level row, so that blank-note extra row shadowed
        // the real one and the operator's Money "Coverage Notes" vanished
        // on the next load.
        if (array_key_exists('memoranda_warranty', $validated) && !empty(trim($validated['memoranda_warranty'] ?? ''))) {
            $this->coverageLevelNoteRow($coverageId)
                ->forceFill(['memoranda_warranty' => $validated['memoranda_warranty']])->save();
        }

        if (array_key_exists('cash_warranty', $validated) && !empty(trim($validated['cash_warranty'] ?? ''))) {
            $this->coverageLevelNoteRow($coverageId)
                ->forceFill(['cash_warranty' => $validated['cash_warranty']])->save();
        }

        // "Benefits for the circumstances" (WC / Stated Benefits) — V1 stores
        // this in policy_coverage_notes.benefits_note (the obsolete
        // policy_coverages.stated_benefits column does not exist, so that
        // update above is a silent no-op). The FE sends the text as
        // `stated_benefits`; persist it on the coverage-level note row so
        // $coverage->note->benefits_note renders it on the V2 Quote/Doc.
        // Requires migration 2026_06_03_000001 (benefits_note column).
        if (array_key_exists('stated_benefits', $validated)
            && \Schema::hasColumn('policy_coverage_notes', 'benefits_note')) {
            $benefitsText = (string) ($validated['stated_benefits'] ?? '');
            $covNote = $this->coverageLevelNoteRow($coverageId);
            if ($benefitsText !== '') {
                $covNote->forceFill(['benefits_note' => $benefitsText])->save();
            } elseif ($covNote->exists && $covNote->benefits_note !== null) {
                $covNote->forceFill(['benefits_note' => null])->save();
            }
        }

        // Save Theft General Questions (theft_general_questions)
        if (array_key_exists('theft_questions', $validated) && is_array($validated['theft_questions'])) {
            Log::info('Saving theft_questions in updateCoverage', [
                'coverage_id'      => $coverageId,
                'policy_id'        => $policyId,
            ]);
            $theftData = $validated['theft_questions'];

            // Check if any data exists
            if (!empty($theftData['physical_protection_implemented']) || !empty($theftData['premises_alarmed']) ||
                !empty($theftData['subscribe_armed_security']) || !empty($theftData['security_company']) ||
                !empty($theftData['maintenance_contract']) || !empty($theftData['alarmed_installed_date']) ||
                !empty($theftData['opening_closing_signals'])) {

                \AlphaDirect\Models\TheftGeneralQuestions::updateOrCreate(
                    [
                        'policy_coverage_id' => $coverageId,
                    ],
                    [
                        'coverage_id'                      => $coverage->coverage_id,
                        'physical_protection_implemented'  => $theftData['physical_protection_implemented'] ?? '',
                        'premises_alarmed'                 => $theftData['premises_alarmed'] ?? '',
                        'subscribe_armed_security'         => $theftData['subscribe_armed_security'] ?? '',
                        'security_company'                 => $theftData['security_company'] ?? '',
                        'maintenance_contract'             => $theftData['maintenance_contract'] ?? '',
                        'alarmed_installed_date'           => $theftData['alarmed_installed_date'] ?? null,
                        'opening_closing_signals'          => $theftData['opening_closing_signals'] ?? '',
                    ]
                );
                Log::info('Inserted theft questions in updateCoverage', ['coverage_id' => $coverageId]);
            }
        }

        // Update retroactive date for Public Liability coverage.
        // NOTE: the global ConvertEmptyStringsToNull middleware rewrites the
        // edit form's blank ('') to null before we see it, so we cannot use
        // `input() !== null` to tell "field cleared" from "field not sent" —
        // both look like null. Detect that the key was SENT via has() (the key
        // survives the conversion, only its value becomes null) and treat a
        // null/empty value as an explicit clear so blanking the date wipes
        // publicliability_date instead of leaving the old value in place.
        if ($request->has('retroactive_date')) {
            $retroactiveDate = $request->input('retroactive_date');
            try {
                if ($retroactiveDate !== null && $retroactiveDate !== '') {
                    $date = \Carbon\Carbon::createFromFormat('Y-m-d', $retroactiveDate);
                    $coverage->update(['publicliability_date' => $date->format('Y-m-d')]);
                } else {
                    $coverage->update(['publicliability_date' => null]);
                }
            } catch (\Exception $e) {
                // Invalid date format, skip updating
                $coverage->touch();
            }
        } else {
            // Touch updated_at on the parent coverage row (coverage_value/rate live on detail rows,
            // not policy_coverages — nothing else to update at the parent level).
            $coverage->touch();
        }

        activity('Coverage')
            ->performedOn($policy)
            ->causedBy(auth()->user())
            ->log('Coverage Updated');

        // Return fresh data with all child rows populated so the frontend can re-render
        $fresh = $coverage->fresh();
        $details = PolicyCoverageDetail::where('policy_coverage_id', $coverageId)->whereNull('deleted_at')->get();
        $totalCoverageValue = $details->sum('coverage_value');
        $totalPremium = $details->sum('calculated_value');

        return response()->json([
            'data'    => $fresh,
            'details' => $details,
            'totals'  => [
                'coverage_value'   => round($totalCoverageValue, 2),
                'calculated_value' => round($totalPremium, 2),
                'detail_count'     => $details->count(),
            ],
            'message' => 'Coverage updated successfully.',
        ]);
    }

    /**
     * Update a coverage detail row (subcoverage).
     */
    public function updateCoverageDetail(Request $request, int $policyId, int $coverageId, int $detailId): JsonResponse
    {
        if ($r = $this->ensureCoverageEditable($coverageId)) return $r;
        Policy::findOrFail($policyId);
        $detail = \AlphaDirect\Models\PolicyCoverageDetail::where('policy_coverage_id', $coverageId)->findOrFail($detailId);

        $validated = $request->validate([
            'coverage_value'   => 'sometimes|numeric|min:0',
            'rate'             => 'sometimes|numeric|min:0',
            'calculated_value' => 'sometimes|numeric|min:0',
        ]);

        if (isset($validated['coverage_value']) && isset($validated['rate']) && !isset($validated['calculated_value'])) {
            $validated['calculated_value'] = round(($validated['coverage_value'] * $validated['rate']) / 100, 2);
        }

        // Wizard-touched: mark for Rate's pro-rata sum.
        $coverage = PolicyCoverage::find($coverageId);
        if ($coverage && $coverage->action_id) {
            $validated['endors_flag']         = 1;
            $validated['previousActionIdCov'] = $coverage->action_id;
        }

        $detail->update($validated);

        return response()->json(['data' => $detail->fresh(), 'message' => 'Detail updated.']);
    }

    /**
     * Delete a coverage.
     */
    public function deleteCoverage(int $policyId, int $coverageId): JsonResponse
    {
        $policy = Policy::findOrFail($policyId);
        $coverage = PolicyCoverage::where('policy_id', $policyId)->findOrFail($coverageId);

        // CANCEL semantics — soft-delete the whole coverage AND every
        // premium-bearing child row (detail / motor / ext / specified
        // items / motor-specified items). Stamp endors_flag = 1 and
        // previousActionIdCov = action_id on each child first so Rate's
        // pro-rata sum picks them up as CANCELs (delta = -prev value).
        // No row is removed from the DB — operator can reinstate later.
        $actionId = $coverage->action_id;

        if ($actionId) {
            DB::table('policy_coverage_detail')
                ->where('policy_coverage_id', $coverageId)
                ->whereNull('deleted_at')
                ->update([
                    'endors_flag'         => 1,
                    'previousActionIdCov' => $actionId,
                    'updated_at'          => now(),
                ]);
            DB::table('motor')
                ->where('policy_coverage_id', $coverageId)
                ->whereNull('deleted_at')
                ->update([
                    'endors_flag'         => 1,
                    'previousActionIdCov' => $actionId,
                    'updated_at'          => now(),
                ]);
            if (\Schema::hasColumn('policy_extention_detail', 'endors_flag')) {
                DB::table('policy_extention_detail')
                    ->where('policy_coverage_id', $coverageId)
                    ->whereNull('deleted_at')
                    ->update([
                        'endors_flag'         => 1,
                        'previousActionIdCov' => $actionId,
                        'updated_at'          => now(),
                    ]);
            }
            if (\Schema::hasColumn('policy_specified_items', 'endors_flag')) {
                DB::table('policy_specified_items')
                    ->where('policy_coverage_id', $coverageId)
                    ->whereNull('deleted_at')
                    ->update([
                        'endors_flag'         => '1',
                        'previousActionIdCov' => $actionId,
                        'updated_at'          => now(),
                    ]);
            }
            // Motor Traders External / Internal carry their WHOLE premium in
            // one row per coverage (14 _calculated_value columns) — they have
            // no policy_coverage_detail rows at all. writeLineLevelProRata's
            // MT loop only rates rows marked previousActionIdCov = actionId,
            // so without this stamp cancelling a Motor Traders section on an
            // endorse produced a pro-rata refund of ZERO while the premium
            // silently dropped out of the annual.
            foreach (['motor_traders', 'motor_traders_internal'] as $mtTbl) {
                if (!\Schema::hasTable($mtTbl) || !\Schema::hasColumn($mtTbl, 'endors_flag')) continue;
                DB::table($mtTbl)
                    ->where('policy_coverage_id', $coverageId)
                    ->whereNull('deleted_at')
                    ->update([
                        'endors_flag'         => 1,
                        'previousActionIdCov' => $actionId,
                        'updated_at'          => now(),
                    ]);
            }
        }

        // Soft-delete the children, then the parent. SoftDeletes trait sets
        // deleted_at = now() — physical row stays for reinstate.
        PolicyCoverageDetail::where('policy_coverage_id', $coverageId)->delete();
        DB::table('motor')->where('policy_coverage_id', $coverageId)->whereNull('deleted_at')->update(['deleted_at' => now()]);
        DB::table('policy_extention_detail')->where('policy_coverage_id', $coverageId)->whereNull('deleted_at')->update(['deleted_at' => now()]);
        DB::table('policy_specified_items')->where('policy_coverage_id', $coverageId)->whereNull('deleted_at')->update(['deleted_at' => now()]);
        // Explicit like the siblings above (the PolicyCoverage `deleting` hook
        // also cascades these) so the cancel does not depend on the hook.
        foreach (['motor_traders', 'motor_traders_internal'] as $mtTbl) {
            if (!\Schema::hasTable($mtTbl)) continue;
            DB::table($mtTbl)->where('policy_coverage_id', $coverageId)->whereNull('deleted_at')->update(['deleted_at' => now()]);
        }

        $coverage->delete();

        // Auto-recompute action totals so the Rate banner, V2 Quote totals,
        // and the Total Coverage Premium all see the same numbers without
        // requiring an explicit Rate click after every cancel.
        if ($actionId) {
            if (self::actionRepriceable($actionId)) self::recomputeActionTotals($policyId, $actionId);
        }

        activity('Coverage')
            ->performedOn($policy)
            ->causedBy(auth()->user())
            ->log('Coverage Cancelled');

        return response()->json([
            'message' => 'Coverage cancelled successfully.',
        ]);
    }

    /**
     * @deprecated Replaced by AlphaDirect\Services\BackdatedEndorse\BackdatedEndorseRefresher
     *             which implements universal edit protection + ledger_adjustments audit.
     *             Kept temporarily for any external callers; remove after one release.
     */
    private static function copyCoverageValuesAcrossActions(int $policyId, int $sourceActionId, int $targetActionId): void
    {
        // Build (coverage_id|address_name) → pc_id map for source + target.
        $sourcePcs = DB::table('policy_coverages as pc')
            ->leftJoin('risk_address as ra', 'ra.id', '=', 'pc.risk_address_id')
            ->where('pc.policy_id', $policyId)
            ->where('pc.action_id', $sourceActionId)
            ->get(['pc.id', 'pc.coverage_id', 'pc.coverage_value', 'pc.calculated_value', 'pc.rate', 'ra.address_name']);
        $targetPcs = DB::table('policy_coverages as pc')
            ->leftJoin('risk_address as ra', 'ra.id', '=', 'pc.risk_address_id')
            ->where('pc.policy_id', $policyId)
            ->where('pc.action_id', $targetActionId)
            ->get(['pc.id', 'pc.coverage_id', 'ra.address_name']);

        $sourceByKey = [];
        foreach ($sourcePcs as $sp) {
            $sourceByKey[$sp->coverage_id . '|' . trim((string) ($sp->address_name ?? ''))] = $sp;
        }

        foreach ($targetPcs as $tp) {
            $key = $tp->coverage_id . '|' . trim((string) ($tp->address_name ?? ''));
            if (!isset($sourceByKey[$key])) continue;
            $sp = $sourceByKey[$key];

            // 1) Parent policy_coverages — copy sum-insured / rate / calc-value
            DB::table('policy_coverages')->where('id', $tp->id)->update([
                'coverage_value'   => $sp->coverage_value,
                'rate'             => $sp->rate,
                'calculated_value' => $sp->calculated_value,
                'updated_at'       => now(),
            ]);

            // 2) policy_coverage_detail — match by coverage_id within the pc.
            $sourceDetails = DB::table('policy_coverage_detail')
                ->where('policy_coverage_id', $sp->id)->whereNull('deleted_at')->get();
            foreach ($sourceDetails as $sd) {
                DB::table('policy_coverage_detail')
                    ->where('policy_coverage_id', $tp->id)
                    ->where('coverage_id', $sd->coverage_id)
                    ->whereNull('deleted_at')
                    ->update([
                        'coverage_value'   => $sd->coverage_value,
                        'rate'             => $sd->rate,
                        'calculated_value' => $sd->calculated_value,
                        'updated_at'       => now(),
                    ]);
            }

            // 3) motor — per-vehicle match by registration_no.
            $sourceMotors = DB::table('motor')
                ->where('policy_coverage_id', $sp->id)->whereNull('deleted_at')->get();
            foreach ($sourceMotors as $sm) {
                $sync = ['calculated_value' => $sm->calculated_value, 'updated_at' => now()];
                foreach (self::MOTOR_EXTENSION_PREMIUM_COLUMNS as $extCol) {
                    if (property_exists($sm, $extCol)) {
                        $sync[$extCol] = $sm->{$extCol};
                    }
                }
                DB::table('motor')
                    ->where('policy_coverage_id', $tp->id)
                    ->where('registration_no', $sm->registration_no)
                    ->whereNull('deleted_at')
                    ->update($sync);
            }

            // 4) motor_traders + motor_traders_internal — one row per pc; copy
            //    all 14 SI + 14 premium columns wholesale.
            foreach (['motor_traders', 'motor_traders_internal'] as $mtTbl) {
                if (!\Schema::hasTable($mtTbl)) continue;
                $sMt = DB::table($mtTbl)
                    ->where('policy_coverage_id', $sp->id)->whereNull('deleted_at')->first();
                if (!$sMt) continue;
                $cols = array_merge(self::MOTOR_TRADERS_COVERAGE_COLUMNS, self::MOTOR_TRADERS_PREMIUM_COLUMNS);
                $sync = ['updated_at' => now()];
                foreach ($cols as $c) {
                    if (property_exists($sMt, $c)) {
                        $sync[$c] = $sMt->{$c};
                    }
                }
                DB::table($mtTbl)
                    ->where('policy_coverage_id', $tp->id)
                    ->whereNull('deleted_at')
                    ->update($sync);
            }

            // 5) policy_extention_detail — match by (extentions_id, type).
            if (\Schema::hasTable('policy_extention_detail')) {
                $sourceExts = DB::table('policy_extention_detail')
                    ->where('policy_coverage_id', $sp->id)->whereNull('deleted_at')->get();
                foreach ($sourceExts as $se) {
                    DB::table('policy_extention_detail')
                        ->where('policy_coverage_id', $tp->id)
                        ->where('extentions_id', $se->extentions_id)
                        ->where('type', $se->type)
                        ->whereNull('deleted_at')
                        ->update([
                            'extention_coverage_value'   => $se->extention_coverage_value,
                            'extention_calculated_value' => $se->extention_calculated_value,
                            'extention_sum_insured'      => $se->extention_sum_insured ?? null,
                            'updated_at'                 => now(),
                        ]);
                }
            }

            // 6) policy_specified_items — match by specified_coverage_id (+
            //    motor_id when present, since one specified-item set can hang
            //    off a specific vehicle for motor coverages).
            if (\Schema::hasTable('policy_specified_items')) {
                $sourceSpecs = DB::table('policy_specified_items')
                    ->where('policy_coverage_id', $sp->id)->whereNull('deleted_at')->get();
                foreach ($sourceSpecs as $ss) {
                    DB::table('policy_specified_items')
                        ->where('policy_coverage_id', $tp->id)
                        ->where('specified_coverage_id', $ss->specified_coverage_id)
                        ->whereNull('deleted_at')
                        ->when($ss->motor_id ?? null, function ($q) use ($ss) {
                            $q->where('motor_id', $ss->motor_id);
                        })
                        ->update([
                            'sum_insured'      => $ss->sum_insured,
                            'rate'             => $ss->rate ?? null,
                            'calculated_value' => $ss->calculated_value,
                            'updated_at'       => now(),
                        ]);
                }
            }
        }
    }

    /**
     * Recompute policy_actions.annual_premium + .premium (pro-rata for
     * ENDORSE) so it always reflects the current row state. Called after
     * cancel / reinstate so the Total Coverage Premium / V2 Quote / Rate
     * banner stay in sync without an explicit Rate click.
     */
    private static function recomputeActionTotals(int $policyId, int $actionId): void
    {
        $action = \AlphaDirect\Models\PolicyAction::find($actionId);
        if (!$action) return;

        // NOTE — do NOT add a "QUOTE only" guard here. This method is also
        // invoked by reflection from PolicyAction::calculatePremiumRenew and
        // BackdatedEndorse\BackdatedEndorseRefresher, which re-price ISSUED
        // downstream batches on purpose (FUTURE_STATUSES = QUOTE + ISSUED) —
        // that is what Refresh Endorsement and the renew crons do. Blocking
        // issued actions here silently stops propagation. The issued-edit hole
        // (#1736 review, blocker 1) is closed at the EDIT endpoints instead,
        // via ensureCoverageEditable / ensureActionEditable.

        // Two pcIds sets:
        //   $activePcIds → annual_premium uses ONLY non-cancelled coverages
        //   $allPcIds    → pro-rata sum needs cancelled ones too (their
        //                  child rows hold the negative-delta refund)
        $activePcIds = DB::table('policy_coverages')
            ->where('policy_id', $policyId)
            ->where('action_id', $actionId)
            ->whereNull('deleted_at')
            ->pluck('id');
        $allPcIds = DB::table('policy_coverages')
            ->where('policy_id', $policyId)
            ->where('action_id', $actionId)
            ->pluck('id');

        // Motor isolation applies only to coverage_id 22 (Commercial Motor)
        // and 27 (Personal Motor) — same scope as legacy graphiteBWV8
        // ManageCoverages.php:3384. Motor Traders / other motor variants
        // continue to sum all 4 buckets normally.
        $motorCoverageIds = [22, 27];
        $motorPcIds = $activePcIds->isEmpty()
            ? collect()
            : DB::table('policy_coverages')
                ->whereIn('id', $activePcIds)
                ->whereIn('coverage_id', $motorCoverageIds)
                ->pluck('id');
        $nonMotorPcIds = $activePcIds->diff($motorPcIds);

        // policy_coverage_detail — only summed for non-motor coverages. Minus any
        // stale "Main" row on a specialist / Fidelity coverage, which the
        // $specialist / $covData buckets below already count — same subtraction
        // calculatePremium makes, so the two writers stay identical.
        $detail = $nonMotorPcIds->isEmpty()
            ? 0.0
            : (float) DB::table('policy_coverage_detail')->whereIn('policy_coverage_id', $nonMotorPcIds)->whereNull('deleted_at')->sum('calculated_value')
              - self::sumDuplicateMainPremiumRows($nonMotorPcIds);

        // motor — calculated_value (OD) + every premium_* extension column.
        $motor  = 0.0;
        if ($activePcIds->isNotEmpty()) {
            $motorRows = DB::table('motor')
                ->whereIn('policy_coverage_id', $activePcIds)
                ->whereNull('deleted_at')
                ->get();
            foreach ($motorRows as $m) {
                $motor += (float) ($m->calculated_value ?? 0)
                       + self::sumMotorExtensionPremiums($m);
            }
        }

        // policy_extention_detail — only summed for non-motor coverages
        // (motor extensions live in motor.premium_*, not here). Sum ALL
        // extension types (not just 'Extention') — extention_calculated_value
        // is the premium column and other types (Excess, BurglarAlarmWarranty)
        // can carry premium too. Mirrors calculatePremium's annual recipe and
        // the FE per-coverage Premium, so recompute keeps annual_premium in
        // sync with what the operator sees per coverage.
        // DomCom (product 7/8) ONLY: count ONLY type='Extention' — all other
        // types (Excess, etc.) are excluded (mirrors calculatePremium above).
        $productId = (int) DB::table('policies')->where('id', $policyId)->value('product_id');
        $isDomCom = in_array($productId, [7, 8], true);
        $ext    = $nonMotorPcIds->isEmpty()
            ? 0.0
            : (float) DB::table('policy_extention_detail')->whereIn('policy_coverage_id', $nonMotorPcIds)->whereNull('deleted_at')->when($isDomCom, fn ($q) => $q->where('type', 'Extention'))->sum('extention_calculated_value');

        // policy_specified_items — summed for both (motor-attached items
        // like accessories are valid premium contributions).
        $spec   = (float) DB::table('policy_specified_items')->whereIn('policy_coverage_id', $activePcIds)->whereNull('deleted_at')->sum('calculated_value');
        // policy_coverages_data — Fidelity Guarantee ONLY. Earlier code
        // summed across all pcs, which picked up stale rows from
        // non-Fidelity coverages (e.g. policy 213363 had a 2,983 phantom
        // dragging the Total to 7,037 vs the visible 4,054 motor sum).
        // Match the V2 Quote Index map: only sum for the Fidelity pc.
        $fidelityPcIds = $activePcIds->isEmpty()
            ? collect()
            : DB::table('policy_coverages as pc')
                ->join('tb_cvgpccoverages as cv', 'cv.id', '=', 'pc.coverage_id')
                ->whereIn('pc.id', $activePcIds)
                ->where('cv.s_CoverageCode', 'FIDELITYGUARANTEE')
                ->pluck('pc.id');
        $covData = (\Schema::hasTable('policy_coverages_data') && $fidelityPcIds->isNotEmpty())
            ? (float) DB::table('policy_coverages_data')->whereIn('policyCoverageID', $fidelityPcIds)->where('policy_id', $policyId)->sum('premium')
            : 0;
        // Motor Traders Ext/Int premiums — see sumMotorTradersPremium docblock.
        $motorTraders = self::sumMotorTradersPremium($activePcIds);
        // Specialist tables (CAR/PAR/EAR/Travel/PI/MM/Marine/Machinery/Bonds/
        // Crime/Environmental/MedEvac) hold their premium in their OWN tables,
        // so they appear in none of the six buckets above. Omitting them here
        // meant every non-Rate coverage edit on a specialist policy overwrote
        // a correct annual with one short by the whole specialist premium —
        // the Rate banner and the Added Coverages "Total Premium" read this
        // column verbatim and went wrong, while the V2 Quote stayed right off
        // its own per-section sum. Same helper (and product guard) as
        // calculatePremium so the two writers can no longer drift.
        $specialist = self::sumSpecialistPremium($activePcIds, $policyId, $actionId, $productId);
        $annual = round($detail + $motor + $ext + $spec + $covData + $motorTraders + $specialist, 2);

        $billable = $annual;
        if ($action->transaction_type === 'ENDORSE' && $action->effective_from && $action->effective_to) {
            $newDays  = \Carbon\Carbon::parse($action->effective_from)->diffInDays(\Carbon\Carbon::parse($action->effective_to)) + 1;
            $stateTypes = ['NEWBUSINESS', 'ANNIVERSARY-RENEW', 'RENEW', 'REINSTATE', 'REISSUE'];
            $prev = \AlphaDirect\Models\PolicyAction::where('policy_id', $policyId)->where('id', '<', $actionId)
                ->whereIn('transaction_type', $stateTypes)->where('effective_to', $action->effective_to)
                ->orderByDesc('id')->first();
            if (!$prev) {
                $prev = \AlphaDirect\Models\PolicyAction::where('policy_id', $policyId)->where('id', '<', $actionId)
                    ->whereIn('transaction_type', $stateTypes)->where('effective_from', '<=', $action->effective_from)
                    ->where('effective_to', '>=', $action->effective_from)->orderByDesc('id')->first();
            }
            if (!$prev) {
                $prev = \AlphaDirect\Models\PolicyAction::where('policy_id', $policyId)->where('id', '<', $actionId)
                    ->whereIn('transaction_type', $stateTypes)->orderByDesc('id')->first();
            }
            $prevDays = ($prev && $prev->effective_from && $prev->effective_to)
                ? (\Carbon\Carbon::parse($prev->effective_from)->diffInDays(\Carbon\Carbon::parse($prev->effective_to)) + 1)
                : 365;
            // Pro-rata factor per Endorsement Spec (Step 3 / Apply formula):
            //   Annual    → premium × (unused_days / 365)
            //   Quarterly → premium × (unused_days_in_qtr / days_in_qtr)
            //   Monthly   → premium × (unused_days_in_mth / days_in_mth)
            // motor.calculated_value (and the *_main / premium_* columns)
            // already represent the per-period premium UW saved against this
            // action — Quarterly stores 1/4 of annual, Monthly stores 1/12.
            // So we MUST NOT divide by 4 or 12 here. $prevDays = days of the
            // source state-action (90/30/365 etc.) gives the correct
            // per-period denominator on its own.
            $factor = $prevDays > 0 ? ($newDays / $prevDays) : 1.0;

            // Re-stamp per-line pro_rate_premium so the pro-rata sum is fresh.
            self::writeLineLevelProRata($policyId, $actionId, $factor);
            // Split detail/ext sums to non-motor pcs only — same scope as the
            // annual_premium recipe above. Otherwise drift rows under motor pcs
            // would inflate the pro-rata without contributing to annual.
            $allMotorPcIds    = DB::table('policy_coverages')->whereIn('id', $allPcIds)->whereIn('coverage_id', [22, 27])->pluck('id');
            $allNonMotorPcIds = $allPcIds->diff($allMotorPcIds);
            $deltaDetail = $allNonMotorPcIds->isEmpty() ? 0.0 : (float) DB::table('policy_coverage_detail')->whereIn('policy_coverage_id', $allNonMotorPcIds)->where('previousActionIdCov', $actionId)->sum('pro_rate_premium');
            $deltaMotor  = (float) DB::table('motor')->whereIn('policy_coverage_id', $allPcIds)->where('previousActionIdCov', $actionId)->sum('pro_rate_premium');
            $deltaExt    = (\Schema::hasColumn('policy_extention_detail', 'pro_rate_premium') && $allNonMotorPcIds->isNotEmpty())
                ? (float) DB::table('policy_extention_detail')->whereIn('policy_coverage_id', $allNonMotorPcIds)->where('previousActionIdCov', $actionId)->sum('pro_rate_premium') : 0;
            $deltaSpec   = \Schema::hasColumn('policy_specified_items', 'pro_rate_premium')
                ? (float) DB::table('policy_specified_items')->whereIn('policy_coverage_id', $allPcIds)->where('previousActionIdCov', $actionId)->sum('pro_rate_premium') : 0;
            // Motor Traders Ext/Int — same wizard-stamp rule as the other buckets.
            $deltaMt     = \Schema::hasColumn('motor_traders', 'pro_rate_premium')
                ? (float) DB::table('motor_traders')->whereIn('policy_coverage_id', $allPcIds)->where('previousActionIdCov', $actionId)->sum('pro_rate_premium') : 0;
            $deltaMtInt  = \Schema::hasColumn('motor_traders_internal', 'pro_rate_premium')
                ? (float) DB::table('motor_traders_internal')->whereIn('policy_coverage_id', $allPcIds)->where('previousActionIdCov', $actionId)->sum('pro_rate_premium') : 0;
            // Specialist delta — same reason the annual needs $specialist above:
            // these tables appear in none of the six line buckets, so a
            // specialist-only endorse netted a pro-rata of 0 here even though
            // the Rate click computed it correctly. Mirrors calculatePremium's
            // $deltaSpecialist exactly: this action's specialist annual minus
            // the immediately-previous action's, both action-scoped, with
            // soft-deleted rows dropping out so a cancel yields a negative
            // (refund).
            $deltaSpecialist = 0.0;
            if (in_array($productId, self::SPECIALIST_PRODUCT_IDS, true) && $action->term_id) {
                // Same ISSUED-chronology baseline as calculatePremium's
                // $deltaSpecialist — see SpecialistEndorseCalculator::baselineActionFor.
                $specPrev = SpecialistEndorseCalculator::baselineActionFor($policyId, $action);
                $deltaSpecialist =
                    SpecialistEndorseCalculator::sumAnnualForAction((int) $actionId, (int) $action->term_id, $policyId)
                    - ($specPrev && $specPrev->term_id
                        ? SpecialistEndorseCalculator::sumAnnualForAction((int) $specPrev->id, (int) $specPrev->term_id, $policyId)
                        : 0.0);
            }
            $billable = round(($deltaDetail + $deltaMotor + $deltaExt + $deltaSpec + $deltaMt + $deltaMtInt + $deltaSpecialist) * $factor, 2);
        }

        $updates = ['premium' => $billable];
        if (\Schema::hasColumn('policy_actions', 'annual_premium')) {
            $updates['annual_premium'] = $annual;
        }
        $action->update($updates);
    }

    /**
     * Reinstate (un-cancel) a coverage and all its child rows. Mirrors
     * deleteCoverage but in reverse: clears deleted_at and stamps
     * endors_flag + previousActionIdCov on the children so Rate's
     * pro-rata picks it up as a positive delta when reinstating in a
     * later transaction. If the cancel happened in the SAME action,
     * the previous action's state still has the row active → delta = 0
     * (no pro-rata). If a later action reinstates, the immediately-
     * previous action has it deleted → delta = +full value (charge).
     */
    public function reinstateCoverage(int $policyId, int $coverageId): JsonResponse
    {
        $policy = Policy::findOrFail($policyId);
        $coverage = PolicyCoverage::onlyTrashed()->where('policy_id', $policyId)->where('id', $coverageId)->first();
        if (!$coverage) {
            $coverage = PolicyCoverage::where('policy_id', $policyId)->findOrFail($coverageId);
            if ($coverage->deleted_at === null) {
                return response()->json(['error' => 'Coverage is not cancelled — nothing to reinstate.'], 422);
            }
        }
        $actionId = $coverage->action_id;

        // Block reinstating a singleton-family coverage if a live row already
        // occupies the (action, risk_address, coverage-family) slot. Without
        // this guard, an operator who cancelled the original row, added a
        // replacement, then reinstated the original would end up with two
        // active singletons on the same risk — the very state addCoverage
        // refuses to create.
        $masterForGuard = CoverageMaster::find($coverage->coverage_id);
        $codeUpper = strtoupper($masterForGuard?->s_CoverageCode ?? '');
        foreach (self::singletonCoverageFamilies() as $family => $codes) {
            if (!in_array($codeUpper, $codes, true)) continue;
            $familyCodeIds = CoverageMaster::whereIn('s_CoverageCode', $codes)->pluck('id')->all();
            $duplicate = PolicyCoverage::where('policy_id', $policy->id)
                ->where('risk_address_id', $coverage->risk_address_id)
                ->whereIn('coverage_id', $familyCodeIds)
                ->when($actionId, fn($q) => $q->where('action_id', $actionId))
                ->where('id', '!=', $coverageId)
                ->whereNull('deleted_at')
                ->exists();
            if ($duplicate) {
                return response()->json([
                    'error'   => "This risk address already has an active {$family} coverage. Cancel the replacement first if you want to reinstate this one.",
                    'message' => "This risk address already has an active {$family} coverage. Cancel the replacement first if you want to reinstate this one.",
                ], 422);
            }
            break;
        }

        // Restore parent + children. Soft-deleted means deleted_at != null.
        $coverage->restore();
        DB::table('policy_coverage_detail')->where('policy_coverage_id', $coverageId)->whereNotNull('deleted_at')->update(['deleted_at' => null]);
        DB::table('motor')->where('policy_coverage_id', $coverageId)->whereNotNull('deleted_at')->update(['deleted_at' => null]);
        DB::table('policy_extention_detail')->where('policy_coverage_id', $coverageId)->whereNotNull('deleted_at')->update(['deleted_at' => null]);
        DB::table('policy_specified_items')->where('policy_coverage_id', $coverageId)->whereNotNull('deleted_at')->update(['deleted_at' => null]);
        // Motor Traders Ext/Int hold the whole section premium in one row per
        // coverage. Omitting them here meant a reinstated Motor Traders
        // section came back with the parent active but its premium row still
        // soft-deleted — every SI / premium field rendered blank and both the
        // annual and the pro-rata read P 0.
        foreach (['motor_traders', 'motor_traders_internal'] as $mtTbl) {
            if (!\Schema::hasTable($mtTbl)) continue;
            DB::table($mtTbl)->where('policy_coverage_id', $coverageId)->whereNotNull('deleted_at')->update(['deleted_at' => null]);
        }

        // Stamp wizard markers so Rate sums these in the pro-rata for
        // this action. Rate compares against the immediately-previous
        // action — if it had the row deleted, delta = +X. If it had the
        // row active (same-action cancel-then-reinstate), delta = 0.
        if ($actionId) {
            DB::table('policy_coverage_detail')->where('policy_coverage_id', $coverageId)->update(['endors_flag' => 1, 'previousActionIdCov' => $actionId, 'updated_at' => now()]);
            DB::table('motor')->where('policy_coverage_id', $coverageId)->update(['endors_flag' => 1, 'previousActionIdCov' => $actionId, 'updated_at' => now()]);
            if (\Schema::hasColumn('policy_extention_detail', 'endors_flag')) {
                DB::table('policy_extention_detail')->where('policy_coverage_id', $coverageId)->update(['endors_flag' => 1, 'previousActionIdCov' => $actionId, 'updated_at' => now()]);
            }
            if (\Schema::hasColumn('policy_specified_items', 'endors_flag')) {
                DB::table('policy_specified_items')->where('policy_coverage_id', $coverageId)->update(['endors_flag' => '1', 'previousActionIdCov' => $actionId, 'updated_at' => now()]);
            }
            foreach (['motor_traders', 'motor_traders_internal'] as $mtTbl) {
                if (!\Schema::hasTable($mtTbl) || !\Schema::hasColumn($mtTbl, 'endors_flag')) continue;
                DB::table($mtTbl)->where('policy_coverage_id', $coverageId)->update(['endors_flag' => 1, 'previousActionIdCov' => $actionId, 'updated_at' => now()]);
            }
        }

        // Auto-recompute action totals so all three (Rate banner / V2 Quote /
        // Total Coverage Premium) reflect the reinstate without an explicit
        // Rate click.
        if ($actionId) {
            if (self::actionRepriceable($actionId)) self::recomputeActionTotals($policyId, $actionId);
        }

        activity('Coverage')
            ->performedOn($policy)
            ->causedBy(auth()->user())
            ->log('Coverage Reinstated');

        return response()->json(['message' => 'Coverage reinstated successfully.']);
    }

    /**
     * Reinstate a single soft-deleted sub-coverage detail row.
     */
    public function reinstateCoverageDetail(int $policyId, int $coverageId, int $detailId): JsonResponse
    {
        if ($r = $this->ensureCoverageEditable($coverageId)) return $r;
        Policy::findOrFail($policyId);
        $detail = \AlphaDirect\Models\PolicyCoverageDetail::onlyTrashed()
            ->where('policy_coverage_id', $coverageId)
            ->where('id', $detailId)
            ->first();
        if (!$detail) {
            return response()->json(['error' => 'Detail row not found or not cancelled.'], 404);
        }
        $detail->restore();

        $coverage = PolicyCoverage::find($coverageId);
        if ($coverage && $coverage->action_id) {
            $detail->endors_flag = 1;
            $detail->previousActionIdCov = $coverage->action_id;
            $detail->save();
            self::recomputeActionTotals($policyId, $coverage->action_id);
        }
        return response()->json(['message' => 'Detail reinstated.']);
    }

    /**
     * Delete a coverage detail row.
     */
    public function deleteCoverageDetail(int $policyId, int $coverageId, int $detailId): JsonResponse
    {
        if ($r = $this->ensureCoverageEditable($coverageId)) return $r;
        Policy::findOrFail($policyId);
        $detail = \AlphaDirect\Models\PolicyCoverageDetail::where('policy_coverage_id', $coverageId)->findOrFail($detailId);

        // Mark wizard-touched BEFORE soft-delete so Rate's pro-rata sum
        // counts this CANCEL (delta = -prev value).
        $coverage = PolicyCoverage::find($coverageId);
        if ($coverage && $coverage->action_id) {
            $detail->endors_flag = 1;
            $detail->previousActionIdCov = $coverage->action_id;
            $detail->save();
        }

        $detail->delete();

        if ($coverage && $coverage->action_id) {
            self::recomputeActionTotals($policyId, $coverage->action_id);
        }
        return response()->json(['message' => 'Detail deleted.']);
    }

    /**
     * Delete an extension detail row.
     */
    public function deleteExtension(int $policyId, int $coverageId, int $extId): JsonResponse
    {
        Policy::findOrFail($policyId);
        // Same gate as the sibling deleteCoverageDetail / deleteSpecifiedItem
        // endpoints. Without it this was a raw soft-delete of a premium-bearing
        // row on an ISSUED action — no cancel semantics, no pro-rata refund, no
        // way for the operator to see what had gone.
        if ($r = $this->ensureCoverageEditable($coverageId)) return $r;
        $coverage = PolicyCoverage::find($coverageId);
        $actionId = $coverage?->action_id;
        if ($actionId && \Schema::hasColumn('policy_extention_detail', 'previousActionIdCov')) {
            DB::table('policy_extention_detail')->where('policy_coverage_id', $coverageId)->where('id', $extId)
                ->update(['endors_flag' => 1, 'previousActionIdCov' => $actionId, 'updated_at' => now()]);
        }
        DB::table('policy_extention_detail')->where('policy_coverage_id', $coverageId)->where('id', $extId)->update(['deleted_at' => now()]);
        if (self::actionRepriceable($actionId)) self::recomputeActionTotals($policyId, $actionId);
        return response()->json(['message' => 'Extension deleted.']);
    }

    /**
     * List specified items attached to a policy coverage (coverage-level rows
     * only — motor-attached rows are surfaced via the motor endpoints).
     *
     * Used by the standalone Travel Insurance Schedule page so the section can
     * load + render its rows without re-fetching the entire policy.
     */
    public function listSpecifiedItems(int $policyId, int $coverageId): JsonResponse
    {
        Policy::findOrFail($policyId);
        $coverageMasterId = (int) (PolicyCoverage::where('id', $coverageId)->value('coverage_id') ?? 0);
        $hasCustomNameCol = \Schema::hasColumn('policy_specified_items', 'custom_name');
        $rows = DB::table('policy_specified_items as psi')
            ->leftJoin('specified_coverage_items as sci', 'sci.id', '=', 'psi.specified_coverage_id')
            ->where('psi.policy_coverage_id', $coverageId)
            // Coverage-level rows are motor_id NULL (V2) OR 0 (legacy/cron,
            // pre-dating the nullable migration) — same convention as the
            // bulk specified-items save matcher and the pro-rata Case helper
            // above. whereNull-only here silently dropped every legacy 0-row,
            // which is why operators saw "Miscellaneous Items" present in the
            // DB but missing on the Capturing Stage for CAR/PAR/EAR/Medical
            // Malpractice/PI/Travel/D&O/Marine Cargo/Machinery Breakdown.
            ->where(fn($q) => $q->whereNull('psi.motor_id')->orWhere('psi.motor_id', 0))
            ->select(
                'psi.id',
                'psi.specified_coverage_id',
                'psi.sum_insured',
                'psi.rate',
                'psi.calculated_value',
                'psi.deleted_at',
                'sci.specified_name as master_name',
                $hasCustomNameCol ? 'psi.custom_name' : DB::raw('NULL as custom_name')
            )
            ->orderBy('psi.id')
            ->get()
            ->map(fn($r) => [
                'id'                    => $r->id,
                'specified_coverage_id' => $r->specified_coverage_id,
                'name'                  => $r->master_name ?? ($r->custom_name ?? ''),
                'isCustom'              => empty($r->specified_coverage_id),
                'sum_insured'           => (string) ($r->sum_insured ?? ''),
                'rate'                  => (string) ($r->rate ?? ''),
                'calculated_value'      => (string) ($r->calculated_value ?? ''),
                'deleted_at'            => $r->deleted_at,
            ])
            ->values();

        return response()->json([
            'data'        => $rows,
            'coverage_id' => $coverageMasterId,
        ]);
    }

    /**
     * Create a coverage-level specified item (no motor attachment).
     *
     * Mirrors addMotorSpecifiedItem minus the motor_id linkage so the Travel
     * Insurance Schedule page can add rows without going through the full
     * coverage bulk-save endpoint.
     */
    public function addSpecifiedItem(Request $request, int $policyId, int $coverageId): JsonResponse
    {
        if ($r = $this->ensureCoverageEditable($coverageId)) return $r;
        $validated = $request->validate([
            'specified_coverage_id' => 'nullable|integer',
            'name'                  => 'nullable|string|max:255',
            'sum_insured'           => 'required|numeric|min:0',
            'rate'                  => 'nullable|numeric|min:0',
            'calculated_value'      => 'nullable|numeric|min:0',
        ]);

        $customName = $validated['name'] ?? null;
        if (empty($validated['specified_coverage_id']) && empty($customName)) {
            return response()->json(['error' => 'Provide a master item (specified_coverage_id) or a custom name.'], 422);
        }

        Policy::findOrFail($policyId);
        $coverage = PolicyCoverage::find($coverageId);
        if (!$coverage) {
            return response()->json(['error' => 'Policy coverage not found.'], 404);
        }

        $covActionId = (int) ($coverage->action_id ?? 0);
        $action = $covActionId
            ? \AlphaDirect\Models\PolicyAction::find($covActionId)
            : \AlphaDirect\Models\PolicyAction::where('policy_id', $policyId)->orderBy('id', 'desc')->first();
        $term = $action?->term_id
            ? PolicyTerm::find($action->term_id)
            : PolicyTerm::where('policy_id', $policyId)->orderBy('id', 'desc')->first();

        $hasCustomNameCol = \Schema::hasColumn('policy_specified_items', 'custom_name');
        $sum  = (float) $validated['sum_insured'];
        $rate = (float) ($validated['rate'] ?? 0);
        $finalCalc = (float) ($validated['calculated_value'] ?? round($sum * $rate / 100, 2));

        try {
            $row = [
                'policy_coverage_id'    => $coverageId,
                'motor_id'              => null,
                'specified_coverage_id' => $validated['specified_coverage_id'] ?? null,
                'sum_insured'           => $sum,
                'rate'                  => $rate,
                'calculated_value'      => $finalCalc,
                'created_at'            => now(),
                'updated_at'            => now(),
            ];
            if (\Schema::hasColumn('policy_specified_items', 'term_id'))   $row['term_id']   = $term?->id;
            if (\Schema::hasColumn('policy_specified_items', 'action_id')) $row['action_id'] = $action?->id;
            if ($hasCustomNameCol && empty($validated['specified_coverage_id']) && !empty($customName)) {
                $row['custom_name'] = $customName;
            }

            // Wizard-gate for ENDORSE so the added Miscellaneous Item gets
            // pro-rated. Without previousActionIdCov, writeLineLevelProRata's
            // specified-items gate (previousActionIdCov === actionId) skips the
            // row → pro_rate_premium stays 0 → it drops out of $deltaSpec in
            // BOTH recomputeActionTotals and the Rate banner / V2 Quote pro-rata.
            // The annual still rises (via $specifiedPremium, which sums every
            // row unconditionally), so the symptom is exactly "annual moves,
            // pro-rata stays flat". recomputeActionTotals() below re-runs
            // writeLineLevelProRata, which stamps pro_rate_premium = the delta.
            // Mirrors deleteSpecifiedItem / updateSpecifiedItem / the updateCoverage
            // smart-sync. This granular endpoint is specialist/engineering-only
            // (COM/DOM saves misc through updateCoverage), so COM/DOM is untouched.
            if ($action && $action->transaction_type === 'ENDORSE') {
                if (\Schema::hasColumn('policy_specified_items', 'previousActionIdCov')) {
                    $row['previousActionIdCov'] = $action->id;
                }
                if (\Schema::hasColumn('policy_specified_items', 'endors_flag')) {
                    $row['endors_flag'] = '1';
                }
            }

            $siModel = new \AlphaDirect\Models\PolicySpecifiedItem();
            $siModel->forceFill(array_merge($row, $this->auditStamps('policy_specified_items')))->save();
            $id = $siModel->id;

            $item = DB::table('policy_specified_items as psi')
                ->leftJoin('specified_coverage_items as sci', 'sci.id', '=', 'psi.specified_coverage_id')
                ->where('psi.id', $id)
                ->select('psi.*', 'sci.specified_name as master_name')
                ->first();

            if ($covActionId) self::recomputeActionTotals($policyId, $covActionId);

            return response()->json([
                'data' => [
                    'id'                    => $item->id,
                    'specified_coverage_id' => $item->specified_coverage_id,
                    'name'                  => $item->master_name ?? ($item->custom_name ?? $customName ?? 'Item #' . $id),
                    'isCustom'              => empty($item->specified_coverage_id),
                    'sum_insured'           => (string) $item->sum_insured,
                    'rate'                  => (string) $item->rate,
                    'calculated_value'      => (string) $item->calculated_value,
                    'deleted_at'            => $item->deleted_at,
                ],
                'message' => 'Specified item added.',
            ], 201);
        } catch (\Throwable $e) {
            \Log::error('addSpecifiedItem failed', [
                'policy_id'   => $policyId,
                'coverage_id' => $coverageId,
                'payload'     => $request->all(),
                'message'     => $e->getMessage(),
            ]);
            return response()->json(['error' => 'Could not save specified item: ' . $e->getMessage()], 500);
        }
    }

    /**
     * Delete a specified item row.
     */
    public function deleteSpecifiedItem(int $policyId, int $coverageId, int $itemId): JsonResponse
    {
        if ($r = $this->ensureCoverageEditable($coverageId)) return $r;
        Policy::findOrFail($policyId);
        $coverage = PolicyCoverage::find($coverageId);
        $actionId = $coverage?->action_id;
        if ($actionId && \Schema::hasColumn('policy_specified_items', 'previousActionIdCov')) {
            DB::table('policy_specified_items')->where('policy_coverage_id', $coverageId)->where('id', $itemId)
                ->update(['endors_flag' => '1', 'previousActionIdCov' => $actionId, 'updated_at' => now()]);
        }
        DB::table('policy_specified_items')->where('policy_coverage_id', $coverageId)->where('id', $itemId)->update(['deleted_at' => now()]);
        if ($actionId) self::recomputeActionTotals($policyId, $actionId);
        return response()->json(['message' => 'Specified item deleted.']);
    }

    /**
     * Update a specified item (soft-delete or reinstate).
     */
    public function updateSpecifiedItem(int $policyId, int $coverageId, int $itemId, Request $request): JsonResponse
    {
        if ($r = $this->ensureCoverageEditable($coverageId)) return $r;
        Policy::findOrFail($policyId);
        $coverage = PolicyCoverage::find($coverageId);
        $actionId = $coverage?->action_id;

        // Handle deleted_at field — can be null (reinstate) or ISO 8601 date (soft-delete)
        $updates = [];
        if ($request->has('deleted_at')) {
            $deletedAt = $request->input('deleted_at');

            if ($deletedAt === null || $deletedAt === '' || $deletedAt === 'null') {
                // Reinstate: clear the deleted_at field
                $updates['deleted_at'] = null;
            } else {
                // Soft-delete: parse the ISO 8601 date
                try {
                    $updates['deleted_at'] = \Carbon\Carbon::createFromFormat('Y-m-d\TH:i:s.uP', $deletedAt);
                } catch (\Exception $e) {
                    return response()->json(['message' => 'Invalid date format for deleted_at'], 422);
                }
            }

            // Set endors_flag if deleting (adding deleted_at) and column exists
            if ($deletedAt !== null && $deletedAt !== '' && $deletedAt !== 'null' && \Schema::hasColumn('policy_specified_items', 'endors_flag')) {
                $updates['endors_flag'] = '1';
            }
        }

        // Set previousActionIdCov if column exists and action_id is set
        if (\Schema::hasColumn('policy_specified_items', 'previousActionIdCov') && $actionId) {
            $updates['previousActionIdCov'] = $actionId;
        }

        // Always update updated_at
        $updates['updated_at'] = now();

        DB::table('policy_specified_items')
            ->where('policy_coverage_id', $coverageId)
            ->where('id', $itemId)
            ->update($updates);

        if ($actionId) self::recomputeActionTotals($policyId, $actionId);
        return response()->json(['message' => 'Specified item updated successfully.']);
    }

    /**
     * Get risk addresses with their coverages for a policy.
     */
    // ── Motor Vehicle Management (COMMERCIALMOTOR / PERSONALMOTOR) ─────────

    /**
     * List motor vehicles for a coverage.
     */
    public function listMotorVehicles(int $policyId, int $coverageId): JsonResponse
    {
        // If current coverage has no motors, fall back to most recent previous
        // action's coverage that has motors. Single aggregate query instead of
        // N COUNT calls — critical for policies with many historical actions.
        $pcId = $coverageId;
        // Only borrow the previous action's vehicles when THIS coverage has
        // NO motor rows at all. If the coverage's only vehicle was cancelled
        // in this action it still has a (soft-deleted) motor row — keep it so
        // the wizard renders the Reinstate affordance. The old check counted
        // active rows only, so cancelling the last vehicle hit count==0 and
        // fell back to the prior action's still-active copy, which the FE then
        // showed as "Cancel" again instead of "Reinstate".
        $activeMotorCount = DB::table('motor')->where('policy_coverage_id', $pcId)->whereNull('deleted_at')->count();
        $anyMotorCount    = DB::table('motor')->where('policy_coverage_id', $pcId)->count();
        if ($activeMotorCount == 0 && $anyMotorCount == 0) {
            $covMasterId = PolicyCoverage::find($coverageId)?->coverage_id;
            if ($covMasterId) {
                $prevPcId = DB::table('policy_coverages as pc')
                    ->join('motor as m', function ($j) {
                        $j->on('m.policy_coverage_id', '=', 'pc.id')->whereNull('m.deleted_at');
                    })
                    ->where('pc.policy_id', $policyId)
                    ->where('pc.coverage_id', $covMasterId)
                    ->where('pc.id', '!=', $coverageId)
                    ->whereNull('pc.deleted_at')
                    ->orderByDesc('pc.id')
                    ->value('pc.id');
                if ($prevPcId) $pcId = $prevPcId;
            }
        }

        // Include soft-deleted motors so the wizard can render them as
        // cancelled rows with a Reinstate option (mirrors coverage-level
        // cancel/reinstate flow). Frontend keys off `deleted_at` to grey
        // out the row + swap Cancel for Reinstate.
        $motors = DB::table('motor')->where('policy_coverage_id', $pcId)
            ->get()->map(fn($m) => (array) $m);

        // Attach per-motor notes (graphiteBWV8 ManageCoverages stores a note per motor)
        $motorIds = $motors->pluck('id')->filter()->all();
        // Exclude soft-deleted notes (DB::table bypasses the SoftDeletes
        // scope) and order by id so pluck keeps the live latest per motor.
        $notesByMotor = empty($motorIds) ? collect() : DB::table('policy_coverage_notes')
            ->whereIn('motor_id', $motorIds)
            ->whereNull('deleted_at')
            ->orderBy('id')
            ->pluck('note', 'motor_id');
        $motors = $motors->map(function ($m) use ($notesByMotor) {
            $m['note'] = $notesByMotor[$m['id']] ?? '';
            return $m;
        });

        return response()->json(['data' => $motors]);
    }

    /**
     * Compute motor pro-rata at wizard insert/update time, mirroring the
     * 5-case logic from legacy graphiteBWV8 ManageCoverages::submit() motor
     * branch. Returns ['pro_rate_premium', 'previousActionIdCov', 'endors_flag']
     * stamped on every wizard write so Rate's later sum already has the
     * correct delta in motor.pro_rate_premium for each row.
     *
     *   Case 1 — No existing row for (current pc, reg_no):
     *            NEW vehicle in this action → pro_rate = currentValue (full)
     *   Case 2 — Existing row, same-action multi-edit
     *            (past.previousActionIdCov == currentActionId):
     *            baseline = TRUE previous action's calculated_value for the
     *            same reg_no on the same risk_address.address_name.
     *   Case 3 — Existing row, cross-action edit:
     *            baseline = past.calculated_value
     *   Case 4 / 5 — currentValue == baseline → no change → pro_rate = 0,
     *                preserve the row's existing previousActionIdCov / flag.
     *
     *   For non-ENDORSE actions (NEWBUSINESS / RENEW / etc.) the legacy
     *   "just take full premium" path applies: pro_rate = currentValue,
     *   endors_flag = 0.
     *
     * Cancel-in-last-then-reinstate handling: previously-cancelled rows
     * have deleted_at != NULL, so the lookup filters them out and the
     * row falls into Case 1 → treated as NEW (matches user spec rule 4).
     */
    /**
     * Registration-independent identity of a motor row: engine + chassis number.
     *
     * Used only to recognise a vehicle whose registration was amended, so the
     * pro-rata baseline follows the vehicle rather than the plate. Returns ''
     * when the row carries neither number (common on trailers and older COM
     * fleets) — callers then fall back to a strict 1:1 count instead.
     */
    private static function motorIdentityKey($row): string
    {
        $eng  = strtoupper(preg_replace('/\s+/', '', (string) ($row->engine_number ?? '')));
        $chas = strtoupper(preg_replace('/\s+/', '', (string) ($row->chassis_number ?? '')));
        return ($eng === '' && $chas === '') ? '' : $eng . '|' . $chas;
    }

    /**
     * Make + model of a motor row, normalised for comparison.
     *
     * Second-line evidence for the registration-correction pairing when the
     * vehicle carries no engine/chassis number: two rows may only be treated as
     * the same vehicle under a corrected plate if they describe the same make
     * and model. Returns '' when neither is recorded, which blocks pairing.
     */
    private static function motorMakeModelKey($row): string
    {
        $make  = strtoupper(trim(preg_replace('/\s+/', ' ', (string) ($row->make ?? ''))));
        $model = strtoupper(trim(preg_replace('/\s+/', ' ', (string) ($row->model ?? ''))));
        return ($make === '' && $model === '') ? '' : $make . '|' . $model;
    }

    private static function computeMotorProRataCase(
        int $policyId,
        int $coverageId,
        int $currentActionId,
        string $registrationNo,
        float $currentValue
    ): array {
        $action = \AlphaDirect\Models\PolicyAction::find($currentActionId);
        if (!$action) {
            return ['pro_rate_premium' => 0.0, 'previousActionIdCov' => 0, 'endors_flag' => 0];
        }

        // Non-ENDORSE: full premium, no flag (legacy line 3461-3465).
        if ($action->transaction_type !== 'ENDORSE') {
            return [
                'pro_rate_premium'    => round($currentValue, 2),
                'previousActionIdCov' => $currentActionId,
                'endors_flag'         => 0,
            ];
        }

        // Find existing motor row in current coverage for this reg_no.
        // Filter deleted_at so a previously-cancelled row falls into Case 1
        // (treated as NEW), implementing the cancel-then-reinstate spec.
        // Select calculated_value AND every premium_* extension column so
        // the past total = OD + sum(extensions) — pro-rata reflects ANY
        // change to the row, not just calculated_value.
        $motorSelect = array_merge(
            ['motor.id', 'motor.calculated_value', 'motor.previousActionIdCov', 'motor.endors_flag'],
            array_map(fn($c) => 'motor.' . $c, self::MOTOR_EXTENSION_PREMIUM_COLUMNS),
            ['risk_address.address_name as risk_address_name']
        );
        $past = DB::table('motor')
            ->join('policy_coverages', 'motor.policy_coverage_id', '=', 'policy_coverages.id')
            ->join('policy_actions', 'policy_coverages.action_id', '=', 'policy_actions.id')
            ->leftJoin('risk_address', 'policy_coverages.risk_address_id', '=', 'risk_address.id')
            ->where('policy_actions.policy_id', $policyId)
            ->where('motor.registration_no', $registrationNo)
            ->where('motor.policy_coverage_id', $coverageId)
            ->whereNull('policy_actions.deleted_at')
            ->whereNull('motor.deleted_at')
            ->whereNull('policy_coverages.deleted_at')
            ->orderByDesc('motor.id')
            ->select($motorSelect)
            ->first();

        // Case 1: No existing row → new vehicle → full pro-rata.
        if (!$past) {
            return [
                'pro_rate_premium'    => round($currentValue, 2),
                'previousActionIdCov' => $currentActionId,
                'endors_flag'         => 1,
            ];
        }

        // Past total = own-damage + sum of all extensions on the past row.
        // currentValue (from caller) is also a total — caller pre-merges
        // extensions so single-field edits still register the right delta.
        $oldValue = (float) ($past->calculated_value ?? 0)
            + self::sumMotorExtensionPremiums($past);

        // Case 2 vs 3: pick baseline.
        if ((int) $past->previousActionIdCov === $currentActionId) {
            // Case 2: same-action multi-edit. Walk to TRUE previous action,
            // ordered by effective_from (chronological).
            $currentAction = \AlphaDirect\Models\PolicyAction::find($currentActionId);
            $previousAction = $currentAction
                ? \AlphaDirect\Models\PolicyAction::where('policy_id', $policyId)
                    ->where('id', '!=', $currentActionId)
                    ->when($currentAction->effective_from, fn($q) =>
                        $q->where('effective_from', '<=', $currentAction->effective_from))
                    ->orderByDesc('effective_from')
                    ->orderByDesc('id')
                    ->first()
                : null;
            $previousDetail = $previousAction
                ? DB::table('motor')
                    ->join('policy_coverages', 'motor.policy_coverage_id', '=', 'policy_coverages.id')
                    ->join('policy_actions', 'policy_coverages.action_id', '=', 'policy_actions.id')
                    ->leftJoin('risk_address', 'policy_coverages.risk_address_id', '=', 'risk_address.id')
                    ->where('policy_actions.policy_id', $policyId)
                    ->where('motor.registration_no', $registrationNo)
                    ->when($past->risk_address_name !== null, fn($q) => $q->where('risk_address.address_name', $past->risk_address_name))
                    ->whereNull('policy_actions.deleted_at')
                    ->whereNull('policy_coverages.deleted_at')
                    ->where('policy_actions.id', $previousAction->id)
                    // Ignore forward-propagated phantoms: a row sitting under a
                    // PRIOR action but stamped with the CURRENT action's id was
                    // replicated INTO that action by this endorse's propagation
                    // (BackdatedEndorseRefresher). It mirrors the current value,
                    // so using it as the baseline collapses the delta to 0 and a
                    // genuinely-added vehicle shows P0 pro-rata. Genuine prior
                    // state carries an older (or null/0) action id.
                    ->where(function ($q) use ($currentActionId) {
                        $q->whereNull('motor.previousActionIdCov')
                          ->orWhere('motor.previousActionIdCov', '!=', $currentActionId);
                    })
                    ->orderByDesc('motor.id')
                    ->select(array_merge(
                        ['motor.calculated_value'],
                        array_map(fn($c) => 'motor.' . $c, self::MOTOR_EXTENSION_PREMIUM_COLUMNS)
                    ))
                    ->first()
                : null;
            $baseValue = $previousDetail
                ? (float) $previousDetail->calculated_value + self::sumMotorExtensionPremiums($previousDetail)
                : 0.0;
        } else {
            // Case 3: cross-action edit → use past row's total premium.
            $baseValue = $oldValue;
        }

        $delta = round($currentValue - $baseValue, 2);

        // Case 4 / 5: no change. Preserve flags.
        if (abs($delta) < 0.01) {
            return [
                'pro_rate_premium'    => 0.0,
                'previousActionIdCov' => (int) ($past->previousActionIdCov ?? 0),
                'endors_flag'         => (int) ($past->endors_flag ?? 0),
            ];
        }

        // Case 3 (changed): stamp signed delta + mark wizard-touched.
        return [
            'pro_rate_premium'    => $delta,
            'previousActionIdCov' => $currentActionId,
            'endors_flag'         => 1,
        ];
    }

    /**
     * Pro-rata case logic for policy_coverage_detail / policy_specified_items
     * rows. Mirrors computeMotorProRataCase but for tables keyed by an
     * arbitrary identity (not registration_no).
     *
     * Cases (same semantics as motor):
     *   1. No row in this coverage with this identity → NEW → full pro-rata
     *   2. Same-action multi-edit (past row's previousActionIdCov already
     *      equals current) → walk to TRUE previous action, baseline =
     *      that action's row value (or 0 if not present there)
     *   3. Cross-action edit (first touch in this action) → baseline =
     *      past row's calculated_value (replicated from source)
     *   4/5. No actual change → preserve existing flags, pro_rate_premium = 0
     *
     * @param string $table         e.g. 'policy_coverage_detail'
     * @param string $valueColumn   column holding the row's premium value
     * @param array  $identityWhere extra WHERE clauses to identify the row
     *                              (e.g. ['coverage_id' => 5])
     * @return array{pro_rate_premium: float, previousActionIdCov: int, endors_flag: int}
     */
    private static function computeRowProRataCase(
        int $policyId,
        int $coverageId,
        int $currentActionId,
        string $table,
        string $valueColumn,
        array $identityWhere,
        float $currentValue
    ): array {
        $action = \AlphaDirect\Models\PolicyAction::find($currentActionId);
        if (!$action) {
            return ['pro_rate_premium' => 0.0, 'previousActionIdCov' => 0, 'endors_flag' => 0];
        }

        // Non-ENDORSE: full premium, no flag.
        if ($action->transaction_type !== 'ENDORSE') {
            return [
                'pro_rate_premium'    => round($currentValue, 2),
                'previousActionIdCov' => $currentActionId,
                'endors_flag'         => 0,
            ];
        }

        $applyIdentity = function ($q) use ($identityWhere) {
            foreach ($identityWhere as $col => $val) {
                if ($val === null) {
                    $q->whereNull($col);
                } else {
                    $q->where($col, $val);
                }
            }
            return $q;
        };

        $past = $applyIdentity(DB::table($table)
            ->where('policy_coverage_id', $coverageId)
            ->whereNull('deleted_at')
        )->orderByDesc('id')
        ->select(['id', $valueColumn, 'previousActionIdCov', 'endors_flag'])
        ->first();

        // Case 1: no active row for this identity in THIS action's coverage
        // yet. Before charging the line its full premium as "brand new",
        // check the baseline carried by the previous ISSUED action's matching
        // coverage. On an ENDORSE the new action's coverage row starts empty
        // (sub-coverage details are NOT pre-replicated into it), so EVERY line
        // the operator re-submits — including ones that simply carry forward
        // unchanged — lands here. Returning the full value for all of them
        // stamped a non-zero pro-rata on sub-coverages that didn't change,
        // inflating the endorse pro-rata (e.g. adding ONE item under
        // Electronic Equipment rated all three existing lines instead of just
        // the added computer). Mirror writeLineLevelProRata's prev-state
        // lookup: match the previous action's coverage by (coverage_id,
        // risk-address name) and read the same identity row's value as the
        // baseline. A genuinely new line (no prev match) keeps the full-value
        // behaviour (baseline 0 → delta = full).
        if (!$past) {
            $baseValue = self::previousActionLineValue(
                $policyId, $coverageId, $action, $table, $valueColumn, $applyIdentity
            );
            $delta = round($currentValue - $baseValue, 2);
            // Unchanged carry-forward → not an endorsement edit. Leave the row
            // un-flagged so neither this pre-compute nor Rate counts it.
            if (abs($delta) < 0.01) {
                return ['pro_rate_premium' => 0.0, 'previousActionIdCov' => 0, 'endors_flag' => 0];
            }
            return [
                'pro_rate_premium'    => $delta,
                'previousActionIdCov' => $currentActionId,
                'endors_flag'         => 1,
            ];
        }

        $oldValue = (float) ($past->$valueColumn ?? 0);

        if ((int) $past->previousActionIdCov === $currentActionId) {
            // Case 2: same-action multi-edit. The row was already touched in
            // THIS action (e.g. re-submitting a coverage, or a value left over
            // from a buggy earlier save), so its own value is NOT the baseline.
            // Walk to the TRUE previous action and read THIS coverage's value
            // there. previousActionLineValue resolves the previous action's
            // MATCHING coverage by (coverage_id, risk-address name) — the prior
            // logic grabbed an arbitrary pc (max id) of the previous action,
            // which on a multi-coverage policy is the wrong coverage, so the
            // baseline collapsed to 0 and every re-submitted line was charged
            // its full value again.
            $baseValue = self::previousActionLineValue(
                $policyId, $coverageId, $action, $table, $valueColumn, $applyIdentity
            );
        } else {
            // Case 3: cross-action edit → past row's value is the baseline.
            $baseValue = $oldValue;
        }

        $delta = round($currentValue - $baseValue, 2);

        // Case 4 / 5: no change → preserve flags.
        if (abs($delta) < 0.01) {
            return [
                'pro_rate_premium'    => 0.0,
                'previousActionIdCov' => (int) ($past->previousActionIdCov ?? 0),
                'endors_flag'         => (int) ($past->endors_flag ?? 0),
            ];
        }

        return [
            'pro_rate_premium'    => $delta,
            'previousActionIdCov' => $currentActionId,
            'endors_flag'         => 1,
        ];
    }

    /**
     * Baseline value for a single sub-coverage / child line, read from the
     * PREVIOUS action's matching coverage. Used by computeRowProRataCase's
     * Case 1 so a line carried forward unchanged into a fresh ENDORSE coverage
     * (whose detail rows aren't pre-replicated) compares against the committed
     * state instead of being treated as brand-new. Mirrors the prev-state
     * lookup writeLineLevelProRata performs at Rate time:
     *   prev action = latest ISSUED before this one (the replication source),
     *                 falling back to the immediately-previous action of any
     *                 status when no ISSUED ancestor exists.
     *   prev coverage = same (coverage_id, risk-address NAME) — surrogate ids
     *                   change across replication, the address name survives.
     * Returns 0.0 when there is no prior action / coverage / matching row
     * (i.e. a genuinely new line), which yields delta = full value upstream.
     */
    private static function previousActionLineValue(
        int $policyId,
        int $currentPcId,
        \AlphaDirect\Models\PolicyAction $currentAction,
        string $table,
        string $valueColumn,
        callable $applyIdentity
    ): float {
        $prev = \AlphaDirect\Models\PolicyAction::where('policy_id', $policyId)
            ->where('id', '<', $currentAction->id)
            ->where('status', 'ISSUED')
            ->orderByDesc('id')
            ->first()
            ?? \AlphaDirect\Models\PolicyAction::where('policy_id', $policyId)
                ->where('id', '<', $currentAction->id)
                ->orderByDesc('id')
                ->first();
        if (!$prev) return 0.0;

        // Identity of the coverage being edited (coverage_id + address name).
        $cur = DB::table('policy_coverages as pc')
            ->leftJoin('risk_address as ra', 'ra.id', '=', 'pc.risk_address_id')
            ->where('pc.id', $currentPcId)
            ->first(['pc.coverage_id', 'ra.address_name']);
        if (!$cur) return 0.0;
        $targetName = trim((string) ($cur->address_name ?? ''));

        // Match the previous action's coverage by coverage_id, then resolve the
        // address-name tie in PHP (avoids SQL NULL/'' comparison subtleties).
        $prevPcId = null;
        $candidates = DB::table('policy_coverages as pc')
            ->leftJoin('risk_address as ra', 'ra.id', '=', 'pc.risk_address_id')
            ->where('pc.policy_id', $policyId)
            ->where('pc.action_id', $prev->id)
            ->where('pc.coverage_id', $cur->coverage_id)
            ->whereNull('pc.deleted_at')
            ->orderByDesc('pc.id')
            ->get(['pc.id', 'ra.address_name']);
        foreach ($candidates as $c) {
            if (trim((string) ($c->address_name ?? '')) === $targetName) {
                $prevPcId = $c->id;
                break;
            }
        }
        if (!$prevPcId) return 0.0;

        $val = $applyIdentity(
            DB::table($table)
                ->where('policy_coverage_id', $prevPcId)
                ->whereNull('deleted_at')
        )->orderByDesc('id')->value($valueColumn);

        return (float) ($val ?? 0);
    }

    /**
     * Add a motor vehicle to a coverage.
     */
    public function addMotorVehicle(Request $request, int $policyId, int $coverageId): JsonResponse
    {
        if ($r = $this->ensureCoverageEditable($coverageId)) return $r;
        $validated = $request->validate([
            'vehicle_id'       => 'nullable|integer',
            // For creating new vehicle inline
            'vehicle_plate'    => 'nullable|string|max:20',
            'make_id'          => 'nullable|integer',
            'model_id'         => 'nullable|integer',
            'make'             => 'nullable|string|max:100',
            'model'            => 'nullable|string|max:100',
            'year'             => 'nullable|string|max:10',
            'engine_number'    => 'nullable|string|max:100',
            'chassis_number'   => 'nullable|string|max:100',
            'estimated_value'  => 'nullable|numeric|min:0',
            'is_imported'      => 'nullable|boolean',
            // Motor coverage fields
            'type_of_cover'    => 'nullable|string',
            'use'              => 'nullable|string',
            'coverage_value'   => 'nullable|numeric|min:0',
            'calculated_value' => 'nullable|numeric|min:0',
        ]);

        $policy = Policy::findOrFail($policyId);
        $action = \AlphaDirect\Models\PolicyAction::where('policy_id', $policyId)->orderBy('id', 'desc')->first();
        $term = PolicyTerm::where('policy_id', $policyId)->orderBy('id', 'desc')->first();

        // Resolve make/model names from master table if IDs provided
        $makeName = $validated['make'] ?? '';
        $modelName = $validated['model'] ?? '';
        if (!empty($validated['make_id'])) {
            $mm = DB::table('tb_prmotormakemodels')->find($validated['make_id']);
            if ($mm) $makeName = $mm->s_Make;
        }
        if (!empty($validated['model_id'])) {
            $mm = DB::table('tb_prmotormakemodels')->find($validated['model_id']);
            if ($mm) $modelName = $mm->s_Variant;
        }

        $plate = $validated['vehicle_plate'] ?? '';
        $engineNo = $validated['engine_number'] ?? '';
        $chassisNo = $validated['chassis_number'] ?? '';
        $estValue = $validated['estimated_value'] ?? 0;

        // If vehicle_id provided, use existing vehicle
        if (!empty($validated['vehicle_id'])) {
            $vehicle = DB::table('vehicle')->find($validated['vehicle_id']);
            if ($vehicle) {
                $plate = $vehicle->vehiclePlate ?? $plate;
                $makeName = $makeName ?: ($vehicle->make ?? '');
                $modelName = $modelName ?: ($vehicle->model ?? '');
                $engineNo = $vehicle->engineNo ?? $engineNo;
                $chassisNo = $vehicle->chassisNo ?? $chassisNo;
                $estValue = $vehicle->estimated_value ?? $estValue;
            }
        } else {
            // Create new vehicle record
            $riskAddress = DB::table('risk_address')->where('policy_id', $policyId)->whereNull('deleted_at')->first();
            $vehicleId = DB::table('vehicle')->insertGetId([
                'policy_id'       => $policyId,
                'customer_id'     => $policy->customer_id,
                'term_id'         => $term?->id,
                'action_id'       => $action?->id,
                'risk_id'         => $riskAddress?->id,
                'vehiclePlate'    => $plate,
                'make'            => $makeName,
                'model'           => $modelName,
                'year'            => $validated['year'] ?? null,
                'engineNo'        => $engineNo,
                'chassisNo'       => $chassisNo,
                'estimated_value' => $estValue,
                'is_imported'     => $validated['is_imported'] ?? 0,
                'seats'           => 2,
                'created_at'      => now(),
                'updated_at'      => now(),
            ]);
        }

        // Registration number is required to uniquely key a motor row per
        // coverage — legacy submit() uses (policy_coverage_id, registration_no)
        // as the updateOrCreate key, which scopes per-motor specified_items
        // and notes. Without a plate there's no way to safely target them.
        if (trim($plate) === '') {
            return response()->json(['error' => 'Registration number (vehicle plate) is required.'], 422);
        }

        // updateOrCreate pattern: same (policy_coverage_id, registration_no)
        // reuses the existing row instead of creating duplicates. Mirrors
        // legacy graphiteBWV8 ManageCoverages::submit() Motor::updateOrCreate.
        $existingMotor = DB::table('motor')
            ->where('policy_coverage_id', $coverageId)
            ->where('registration_no', $plate)
            ->first();

        // Compute motor pro-rata BEFORE writing — the helper looks at the
        // existing row (if any) under this pc + reg_no, so we must call it
        // before our own update overwrites the previous values.
        //
        // Total premium per vehicle = calculated_value + sum of every
        // premium_* extension. addMotorVehicle's payload doesn't carry
        // extension premiums (they're set later via updateMotorVehicle),
        // so for a fresh insert the total here equals just the OD value;
        // when extensions are subsequently edited, updateMotorVehicle will
        // re-stamp the row's pro_rate_premium with the new total delta.
        $covActionId = (int) (PolicyCoverage::where('id', $coverageId)->value('action_id') ?? $action?->id ?? 0);
        $newCalc = (float) ($validated['calculated_value'] ?? 0);
        $proRataCase = self::computeMotorProRataCase(
            $policyId, $coverageId, $covActionId, $plate, $newCalc
        );

        // Store the canonical token, never the UI label — the quote sheet,
        // policy schedule and coverage export all match this column on exact
        // strings ('third_party_only', 'Third_fire_and_theft'). See
        // MotorCoverType.
        $coverType = MotorCoverType::normalize($validated['type_of_cover'] ?? null)
            ?: MotorCoverType::COMPREHENSIVE;

        $motorData = [
            'policy_coverage_id'  => $coverageId,
            'vehicle_name'        => trim($makeName . ' ' . $modelName),
            'registration_no'     => $plate,
            'make'                => $makeName,
            'model'               => $modelName,
            'engine_number'       => $engineNo,
            'chassis_number'      => $chassisNo,
            'estimated_value'     => $estValue,
            'use'                 => $validated['use'] ?? '',
            'type_of_cover'       => $coverType,
            'coverage_value'      => $validated['coverage_value'] ?? 0,
            'calculated_value'    => $newCalc,
            'pro_rate_premium'    => $proRataCase['pro_rate_premium'],
            'previousActionIdCov' => $proRataCase['previousActionIdCov'],
            'endors_flag'         => $proRataCase['endors_flag'],
            'updated_at'          => now(),
        ];

        // *_main columns store the baseline (NEWBUSINESS-time) values that
        // recomputeActionTotals' endorsement pro-rata math reads as the
        // "before" snapshot when computing deltas. Without these populated,
        // every endorsement pro-rata comes out as 0. On INSERT seed them
        // from the same input as the regular columns; on UPDATE leave them
        // alone so the original baseline is preserved across endorsements,
        // but backfill if a legacy row has all-NULL *_main.
        $motorMainSeed = [
            'use_main'              => $validated['use'] ?? '',
            'type_of_cover_main'    => $coverType,
            'coverage_value_main'   => $validated['coverage_value'] ?? 0,
            'calculated_value_main' => $validated['calculated_value'] ?? 0,
        ];

        if ($existingMotor) {
            // Eloquent forceFill+save so Motor Auditable fires (un-deletes
            // a previously soft-deleted row + records the diff). DB::table
            // ->update would silently bypass the trait — Logs tab blind.
            $motorModel = \AlphaDirect\Models\Motor::find($existingMotor->id);
            if ($motorModel) {
                $needMainBackfill = empty($existingMotor->use_main)
                    && empty($existingMotor->type_of_cover_main)
                    && empty($existingMotor->coverage_value_main)
                    && empty($existingMotor->calculated_value_main);
                $payload = array_merge($motorData, ['deleted_at' => null]);
                if ($needMainBackfill) {
                    $payload = array_merge($payload, $motorMainSeed);
                }
                $motorModel->forceFill($payload)->save();
                $motorId = $motorModel->id;
            } else {
                // Row was hard-deleted somehow — fall back to a fresh insert.
                $motorModel = new \AlphaDirect\Models\Motor();
                $motorModel->forceFill(array_merge($motorData, $motorMainSeed))->save();
                $motorId = $motorModel->id;
            }
        } else {
            $motorModel = new \AlphaDirect\Models\Motor();
            $motorModel->forceFill(array_merge($motorData, $motorMainSeed))->save();
            $motorId = $motorModel->id;
        }

        activity('Coverage Motor')->performedOn($policy)->causedBy(auth()->user())
            ->log('Motor vehicle added to COM/DOM coverage #' . $coverageId . ($plate !== '' ? " — {$plate}" : ''));

        return response()->json(['data' => DB::table('motor')->find($motorId), 'message' => 'Vehicle added to coverage.'], 201);
    }

    /**
     * Update a motor vehicle record.
     */
    public function updateMotorVehicle(Request $request, int $policyId, int $coverageId, int $motorId): JsonResponse
    {
        if ($r = $this->ensureCoverageEditable($coverageId)) return $r;
        $allowedFields = [
            // Vehicle identity (now editable from the coverage edit form)
            'vehicle_name','registration_no','make','model',
            'type_of_cover','use','coverage_value','calculated_value','engine_number','chassis_number',
            'tracking_device','security_features','estimated_value',
            'wreckage_removal','window_glass','locks_keys','parts_accessories','audio_accessories',
            'riot_strike','car_hire_theft','credit_shortfall','insured_driver','insured_family',
            'medical_expenses','passenger_liability','third_party_liability','specified_accessories',
            'premium_wreckage_removal','premium_window_glass','premium_locks_keys','premium_parts_accessories',
            'premium_audio_accessories','premium_riot_strike','premium_car_hire_theft','premium_credit_shortfall',
            'premium_insured_driver','premium_insured_family','premium_medical_expenses',
            'premium_passenger_liability','premium_third_party_liability','premium_specified_accessories',
            'own_damage','own_damage_minimun_percent','own_damage_minimum_amount',
            'windscreen','windscreen_minimun_percent','windscreen_minimum_amount',
            'loss_of_keys','loss_of_keys_minimun_percent','loss_of_keys_minimum_amount',
            // Per-vehicle note
            'note',
        ];
        $data = collect($request->only($allowedFields))->filter(fn($v) => $v !== null)->toArray();
        // Let the operator actually CLEAR an excess field. A blanked input
        // leaves the FE as '' but never survives to $data above: the global
        // ConvertEmptyStringsToNull middleware rewrites '' -> null before this
        // controller runs, and the ->filter($v !== null) then strips the key
        // entirely — so the column is never written and the old value sticks
        // ("removing doesn't take"). For the six excess columns, re-detect the
        // key via $request->has() (true even when its value was nulled) and,
        // when the sent value is empty/null, force NULL into $data so a cleared
        // field is stored as NULL and reads back blank. Scoped to excess only —
        // these columns are not part of the premium/pro-rata calc, so nulling
        // them is side-effect free.
        foreach ([
            'own_damage_minimun_percent','own_damage_minimum_amount',
            'windscreen_minimun_percent','windscreen_minimum_amount',
            'loss_of_keys_minimun_percent','loss_of_keys_minimum_amount',
        ] as $excessField) {
            if ($request->has($excessField)) {
                $sent = $request->input($excessField);
                if ($sent === null || $sent === '') {
                    $data[$excessField] = null;
                }
            }
        }
        if (!empty($data)) {
            $covActionId = (int) (PolicyCoverage::where('id', $coverageId)->value('action_id') ?? 0);

            // Read the row's current state BEFORE the update so the helper
            // sees the pre-change baseline.
            $existing = DB::table('motor')->where('id', $motorId)->where('policy_coverage_id', $coverageId)->first();

            // Sync *_main columns whenever the operator changes the matching
            // current column (per spec: "if value change calculated_value and
            // coverage_value, it should update coverage_value_main and
            // calculated_value_main"). Done by mirroring the new values into
            // the *_main fields so the V2 Quote Sheet motor schedule and any
            // baseline-display reads always show the latest figures.
            if (array_key_exists('use', $data)) {
                $data['use_main'] = $data['use'];
            }
            if (array_key_exists('type_of_cover', $data)) {
                // Canonical token, not the UI label — see MotorCoverType.
                $data['type_of_cover']      = MotorCoverType::normalize($data['type_of_cover']);
                $data['type_of_cover_main'] = $data['type_of_cover'];
            }
            if (array_key_exists('coverage_value', $data)) {
                $data['coverage_value_main'] = $data['coverage_value'];
            }
            if (array_key_exists('calculated_value', $data)) {
                $data['calculated_value_main'] = $data['calculated_value'];
            }

            // Recompute pro-rata for ANY wizard edit — calculated_value or
            // any premium_* extension. Total premium per vehicle = OD +
            // sum(extensions); changing only an extension still produces a
            // delta because the helper compares totals, not just OD.
            if ($covActionId && $existing) {
                // Baseline lookup key = the plate the row had BEFORE this edit.
                // Other half of the registration-correction fix — see the
                // "Registration correction" block in writeLineLevelProRata for
                // the revert history. Both halves are needed; either one alone
                // still charges an amended plate.
                // When the endorsement is amending the registration itself
                // ("amend B734BHD to B743BHD") the new plate has no history, so
                // keying on it rated the vehicle as a brand-new add and charged
                // its full pro-rata. The row is the same vehicle, so its prior
                // value must be read under its previous plate — a registration-
                // only amendment then comes out at zero. Falls back to the
                // incoming plate when the row had none.
                $regNo = (string) (($existing->registration_no ?? '') !== ''
                    ? $existing->registration_no
                    : ($data['registration_no'] ?? ''));

                // Build the post-update total: payload value when present,
                // else fall back to existing row value. This way a single-
                // field PUT (e.g. {premium_window_glass: 100}) still yields
                // the correct new total without losing the other extensions.
                $newCalc = array_key_exists('calculated_value', $data)
                    ? (float) $data['calculated_value']
                    : (float) ($existing->calculated_value ?? 0);
                $newExtensionsTotal = 0.0;
                foreach (self::MOTOR_EXTENSION_PREMIUM_COLUMNS as $col) {
                    $val = array_key_exists($col, $data)
                        ? (float) $data[$col]
                        : (float) ($existing->$col ?? 0);
                    $newExtensionsTotal += $val;
                }
                $newTotal = $newCalc + $newExtensionsTotal;

                if ($regNo !== '') {
                    $proRataCase = self::computeMotorProRataCase(
                        $policyId, $coverageId, $covActionId, $regNo, $newTotal
                    );
                    $data['pro_rate_premium']    = $proRataCase['pro_rate_premium'];
                    $data['previousActionIdCov'] = $proRataCase['previousActionIdCov'];
                    $data['endors_flag']         = $proRataCase['endors_flag'];
                }
            }
            $data['updated_at'] = now();
            DB::table('motor')->where('id', $motorId)->where('policy_coverage_id', $coverageId)->update($data);
        }
        return response()->json(['data' => (array) DB::table('motor')->find($motorId), 'message' => 'Updated.']);
    }

    /**
     * Delete a motor vehicle record.
     */
    /**
     * Cancel (soft-delete) a single motor vehicle. Mirrors deleteCoverage
     * semantics but at the per-vehicle granularity.
     *
     * Soft-deletes the motor row PLUS every per-vehicle child row keyed on
     * motor_id (specified accessories, vehicle notes). Stamps the wizard
     * gate (endors_flag = 1, previousActionIdCov = action_id) so Rate's
     * pro-rata sum picks the cancel up as a refund.
     *
     * Pro-rata semantics (handled by recomputeActionTotals →
     * writeLineLevelProRata, no explicit pre-stamp needed):
     *   - Cancel in this action            → delta = -prev_total (refund)
     *   - Same-action cancel-then-reinstate → delta = 0 (no charge)
     *   - Different-action reinstate       → delta = +full_total (charge)
     */
    public function deleteMotorVehicle(int $policyId, int $coverageId, int $motorId): JsonResponse
    {
        if ($r = $this->ensureCoverageEditable($coverageId)) return $r;

        $covActionId = (int) (PolicyCoverage::where('id', $coverageId)->value('action_id') ?? 0);

        // Soft-delete motor row. Stamp wizard markers so writeLineLevelProRata
        // computes delta = (newVal=0) - (prevVal=full) = -full × factor.
        DB::table('motor')->where('id', $motorId)->where('policy_coverage_id', $coverageId)->update([
            'deleted_at'          => now(),
            'previousActionIdCov' => $covActionId ?: DB::raw('previousActionIdCov'),
            'endors_flag'         => 1,
            'updated_at'          => now(),
        ]);

        // Soft-delete per-vehicle specified items (motor_id keyed) — these
        // hold accessories premium that's part of the vehicle's economic
        // value. Stamp wizard markers so their delta is captured too.
        if (\Schema::hasColumn('policy_specified_items', 'endors_flag')) {
            DB::table('policy_specified_items')
                ->where('policy_coverage_id', $coverageId)
                ->where('motor_id', $motorId)
                ->whereNull('deleted_at')
                ->update([
                    'deleted_at'          => now(),
                    'previousActionIdCov' => $covActionId ?: DB::raw('previousActionIdCov'),
                    'endors_flag'         => '1',
                    'updated_at'          => now(),
                ]);
        }

        // Soft-delete per-vehicle notes (display-only, no premium effect,
        // but the row should disappear from the UI in lockstep).
        if (\Schema::hasTable('policy_coverage_notes')) {
            DB::table('policy_coverage_notes')
                ->where('policy_coverage_id', $coverageId)
                ->where('motor_id', $motorId)
                ->whereNull('deleted_at')
                ->update(['deleted_at' => now(), 'updated_at' => now()]);
        }

        // Recompute action totals so Rate banner / V2 Quote / Total Coverage
        // Premium reflect the cancel without an explicit Rate click.
        if ($covActionId) {
            self::recomputeActionTotals($policyId, $covActionId);
        }

        activity('Motor Vehicle')
            ->performedOn(Policy::find($policyId))
            ->causedBy(auth()->user())
            ->log('Motor Vehicle Cancelled');

        return response()->json(['message' => 'Motor vehicle cancelled.']);
    }

    /**
     * Reinstate (un-cancel) a soft-deleted motor vehicle and its per-vehicle
     * children. Mirrors reinstateCoverage at the motor-row granularity.
     *
     * writeLineLevelProRata handles the math:
     *   - Same-action cancel-then-reinstate → delta = 0 (prev had it active)
     *   - Different-action reinstate        → delta = +full (prev had it deleted)
     */
    public function reinstateMotorVehicle(int $policyId, int $coverageId, int $motorId): JsonResponse
    {
        if ($r = $this->ensureCoverageEditable($coverageId)) return $r;

        $row = DB::table('motor')->where('id', $motorId)->where('policy_coverage_id', $coverageId)->first();
        if (!$row) {
            return response()->json(['error' => 'Motor vehicle not found.'], 404);
        }
        if ($row->deleted_at === null) {
            return response()->json(['error' => 'Motor vehicle is not cancelled — nothing to reinstate.'], 422);
        }

        $covActionId = (int) (PolicyCoverage::where('id', $coverageId)->value('action_id') ?? 0);

        // Restore motor row + per-vehicle children. Stamp wizard markers so
        // Rate sees the reinstate.
        DB::table('motor')->where('id', $motorId)->where('policy_coverage_id', $coverageId)->update([
            'deleted_at'          => null,
            'previousActionIdCov' => $covActionId ?: DB::raw('previousActionIdCov'),
            'endors_flag'         => 1,
            'updated_at'          => now(),
        ]);
        if (\Schema::hasColumn('policy_specified_items', 'endors_flag')) {
            DB::table('policy_specified_items')
                ->where('policy_coverage_id', $coverageId)
                ->where('motor_id', $motorId)
                ->whereNotNull('deleted_at')
                ->update([
                    'deleted_at'          => null,
                    'previousActionIdCov' => $covActionId ?: DB::raw('previousActionIdCov'),
                    'endors_flag'         => '1',
                    'updated_at'          => now(),
                ]);
        }
        if (\Schema::hasTable('policy_coverage_notes')) {
            DB::table('policy_coverage_notes')
                ->where('policy_coverage_id', $coverageId)
                ->where('motor_id', $motorId)
                ->whereNotNull('deleted_at')
                ->update(['deleted_at' => null, 'updated_at' => now()]);
        }

        if ($covActionId) {
            self::recomputeActionTotals($policyId, $covActionId);
        }

        activity('Motor Vehicle')
            ->performedOn(Policy::find($policyId))
            ->causedBy(auth()->user())
            ->log('Motor Vehicle Reinstated');

        return response()->json(['message' => 'Motor vehicle reinstated.']);
    }

    /**
     * Cancel a specialist (non-motor, non-COM/DOM) coverage row inside the
     * current ENDORSE action. Soft-deletes the row so SpecialistEndorse
     * Calculator::writeProRata stamps a NEGATIVE pro_rate_premium on it the
     * next time the action is rated. Pro-rata refund flows back to the
     * customer through the standard ENDORSE pipeline.
     *
     * $table is validated against SpecialistCoverageRegistry — anything
     * outside the ten known tables returns 422 so this endpoint can never
     * be used to soft-delete motor/COM/DOM rows by accident.
     *
     * Route: POST /policies/{id}/coverages/{covId}/specialist/{table}/{rowId}/cancel
     */
    public function cancelSpecialistCoverage(int $policyId, int $coverageId, string $table, int $rowId): JsonResponse
    {
        if (!\AlphaDirect\Services\SpecialistEndorse\SpecialistCoverageRegistry::isSpecialistTable($table)) {
            return response()->json(['error' => "'{$table}' is not a specialist coverage table."], 422);
        }
        if ($r = $this->ensureCoverageEditable($coverageId)) return $r;

        $row = DB::table($table)->where('id', $rowId)->where('policy_coverage_id', $coverageId)->first();
        if (!$row) {
            return response()->json(['error' => 'Specialist coverage row not found.'], 404);
        }
        if (!empty($row->deleted_at)) {
            return response()->json(['error' => 'Specialist coverage is already cancelled.'], 422);
        }

        $covActionId = (int) (PolicyCoverage::where('id', $coverageId)->value('action_id') ?? 0);

        $ok = \AlphaDirect\Services\SpecialistEndorse\SpecialistEndorseCalculator::cancelSpecialistRow(
            $table, $rowId, $covActionId
        );
        if (!$ok) {
            return response()->json(['error' => 'Cancel failed — table missing deleted_at column.'], 500);
        }

        if ($covActionId) {
            self::recomputeActionTotals($policyId, $covActionId);
        }

        activity('Specialist Coverage')
            ->performedOn(Policy::find($policyId))
            ->causedBy(auth()->user())
            ->log("Specialist row cancelled: {$table}#{$rowId}");

        return response()->json(['message' => 'Specialist coverage cancelled.']);
    }

    /**
     * Reinstate (un-cancel) a soft-deleted specialist coverage row. Mirrors
     * reinstateMotorVehicle at the specialist-row granularity. Next Rate
     * cycle picks the row back up as active and writes positive pro-rata.
     *
     * Route: POST /policies/{id}/coverages/{covId}/specialist/{table}/{rowId}/reinstate
     */
    public function reinstateSpecialistCoverage(int $policyId, int $coverageId, string $table, int $rowId): JsonResponse
    {
        if (!\AlphaDirect\Services\SpecialistEndorse\SpecialistCoverageRegistry::isSpecialistTable($table)) {
            return response()->json(['error' => "'{$table}' is not a specialist coverage table."], 422);
        }
        if ($r = $this->ensureCoverageEditable($coverageId)) return $r;

        $row = DB::table($table)->where('id', $rowId)->where('policy_coverage_id', $coverageId)->first();
        if (!$row) {
            return response()->json(['error' => 'Specialist coverage row not found.'], 404);
        }
        if (empty($row->deleted_at)) {
            return response()->json(['error' => 'Specialist coverage is not cancelled — nothing to reinstate.'], 422);
        }

        $covActionId = (int) (PolicyCoverage::where('id', $coverageId)->value('action_id') ?? 0);

        $ok = \AlphaDirect\Services\SpecialistEndorse\SpecialistEndorseCalculator::reinstateSpecialistRow(
            $table, $rowId, $covActionId
        );
        if (!$ok) {
            return response()->json(['error' => 'Reinstate failed — table missing deleted_at column.'], 500);
        }

        if ($covActionId) {
            self::recomputeActionTotals($policyId, $covActionId);
        }

        activity('Specialist Coverage')
            ->performedOn(Policy::find($policyId))
            ->causedBy(auth()->user())
            ->log("Specialist row reinstated: {$table}#{$rowId}");

        return response()->json(['message' => 'Specialist coverage reinstated.']);
    }

    /**
     * Compute specified-item pro-rata at wizard insert/update time, mirroring
     * the same 5-case logic used for motor rows but keyed for specified items:
     *
     *   Motor-attached (motor_id non-null):
     *      key = (motor.registration_no, specified_coverage_id, custom_name)
     *      — registration_no is the stable cross-action key (motor.id changes
     *        per replication, registration_no survives).
     *
     *   Section-level (motor_id null/0):
     *      key = (specified_coverage_id, custom_name)
     *
     *   Cases:
     *     1. New item (no past row matching key in current pc) → full pro-rata
     *     2. Same-action multi-edit → walk to TRUE previous action, delta vs
     *        the matching row there
     *     3. Cross-action edit → delta vs past row's calculated_value
     *     4/5. No change → 0, preserve flags
     *
     *   Cancel-then-reinstate handled automatically: deleted_at filters strip
     *   cancelled rows, so a re-add falls into Case 1 (full).
     */
    private static function computeSpecifiedItemProRataCase(
        int $policyId,
        int $coverageId,
        int $currentActionId,
        ?int $motorId,
        ?int $specifiedCoverageId,
        ?string $customName,
        float $currentValue
    ): array {
        $action = \AlphaDirect\Models\PolicyAction::find($currentActionId);
        if (!$action) {
            return ['pro_rate_premium' => 0.0, 'previousActionIdCov' => 0, 'endors_flag' => '0'];
        }

        // Non-ENDORSE: full premium, no flag. Note: policy_specified_items
        // .endors_flag is enum-like (legacy stores '0' / '1' as strings —
        // see ManageCoverages.php line 2991); integer 1 gets coerced to 0
        // by MySQL's enum casting. All endors_flag values returned by this
        // helper are strings so the column accepts them.
        if ($action->transaction_type !== 'ENDORSE') {
            return [
                'pro_rate_premium'    => round($currentValue, 2),
                'previousActionIdCov' => $currentActionId,
                'endors_flag'         => '0',
            ];
        }

        $hasCustomNameCol = \Schema::hasColumn('policy_specified_items', 'custom_name');

        // Resolve registration_no for motor-attached items (stable key).
        $registrationNo = null;
        if ($motorId) {
            $registrationNo = DB::table('motor')->where('id', $motorId)->value('registration_no');
        }

        // Closure to apply key filters consistently to both past + previous-action queries.
        $applyKey = function ($q) use ($motorId, $registrationNo, $specifiedCoverageId, $customName, $hasCustomNameCol) {
            if ($motorId && $registrationNo !== null && $registrationNo !== '') {
                $q->whereNotNull('psi.motor_id')->where('m.registration_no', $registrationNo);
            } else {
                $q->where(fn($qq) => $qq->whereNull('psi.motor_id')->orWhere('psi.motor_id', 0));
            }
            if ($specifiedCoverageId !== null) {
                $q->where('psi.specified_coverage_id', $specifiedCoverageId);
            } else {
                $q->whereNull('psi.specified_coverage_id');
            }
            if ($hasCustomNameCol) {
                if ($customName !== null && trim($customName) !== '') {
                    $q->where('psi.custom_name', $customName);
                } else {
                    $q->where(fn($qq) => $qq->whereNull('psi.custom_name')->orWhere('psi.custom_name', ''));
                }
            }
            return $q;
        };

        // Past row in CURRENT pc — pre-update baseline.
        $past = $applyKey(
            DB::table('policy_specified_items as psi')
                ->leftJoin('motor as m', 'm.id', '=', 'psi.motor_id')
                ->where('psi.policy_coverage_id', $coverageId)
                ->whereNull('psi.deleted_at')
        )
            ->orderByDesc('psi.id')
            ->select('psi.id', 'psi.calculated_value', 'psi.previousActionIdCov', 'psi.endors_flag')
            ->first();

        // Case 1: No existing row → new item → full pro-rata.
        if (!$past) {
            return [
                'pro_rate_premium'    => round($currentValue, 2),
                'previousActionIdCov' => $currentActionId,
                'endors_flag'         => '1',
            ];
        }

        $oldValue = (float) ($past->calculated_value ?? 0);

        // Case 2 vs 3: pick baseline.
        if ((int) $past->previousActionIdCov === $currentActionId) {
            // Case 2: same-action multi-edit. Walk to TRUE previous action by
            // effective_from order (insurance-standard chronological).
            $previousAction = \AlphaDirect\Models\PolicyAction::where('policy_id', $policyId)
                ->where('id', '!=', $currentActionId)
                ->when($action->effective_from, fn($q) =>
                    $q->where('effective_from', '<=', $action->effective_from))
                ->orderByDesc('effective_from')
                ->orderByDesc('id')
                ->first();

            $previousDetail = $previousAction
                ? $applyKey(
                    DB::table('policy_specified_items as psi')
                        ->join('policy_coverages as pc', 'pc.id', '=', 'psi.policy_coverage_id')
                        ->leftJoin('motor as m', 'm.id', '=', 'psi.motor_id')
                        ->where('pc.policy_id', $policyId)
                        ->where('pc.action_id', $previousAction->id)
                        ->whereNull('pc.deleted_at')
                        ->whereNull('psi.deleted_at')
                )
                    ->orderByDesc('psi.id')
                    ->select('psi.calculated_value')
                    ->first()
                : null;

            $baseValue = (float) ($previousDetail->calculated_value ?? 0);
        } else {
            // Case 3: cross-action edit → use past row's calculated_value.
            $baseValue = $oldValue;
        }

        $delta = round($currentValue - $baseValue, 2);

        // Case 4 / 5: no change.
        if (abs($delta) < 0.01) {
            return [
                'pro_rate_premium'    => 0.0,
                'previousActionIdCov' => (int) ($past->previousActionIdCov ?? 0),
                'endors_flag'         => (string) ($past->endors_flag ?? '0'),
            ];
        }

        // Case 3 (changed): stamp signed delta + mark wizard-touched.
        return [
            'pro_rate_premium'    => $delta,
            'previousActionIdCov' => $currentActionId,
            'endors_flag'         => '1',
        ];
    }

    /**
     * Add a specified item linked to a specific motor vehicle.
     */
    public function addMotorSpecifiedItem(Request $request, int $policyId, int $coverageId, int $motorId): JsonResponse
    {
        if ($r = $this->ensureCoverageEditable($coverageId)) return $r;
        $validated = $request->validate([
            // Either a master FK…
            'specified_coverage_id' => 'nullable|integer',
            // …or a free-text "custom" name (per-vehicle "+ Add Custom" flow).
            // `item_name` kept as an alias for older callers.
            'name'                  => 'nullable|string|max:255',
            'item_name'             => 'nullable|string|max:255',
            'sum_insured'           => 'required|numeric|min:0',
            'rate'                  => 'nullable|numeric|min:0',
            'calculated_value'      => 'nullable|numeric|min:0',
        ]);

        // At least one of specified_coverage_id / name is required.
        $customName = $validated['name'] ?? $validated['item_name'] ?? null;
        if (empty($validated['specified_coverage_id']) && empty($customName)) {
            return response()->json(['error' => 'Provide a master item (specified_coverage_id) or a custom name.'], 422);
        }

        // Verify motor belongs to this coverage AND has a registration_no.
        // Legacy ManageCoverages::submit() scopes per-vehicle specified items
        // by (policy_coverage_id, registration_no) — without a plate the motor
        // can't be safely re-located on subsequent saves.
        $motor = DB::table('motor')->where('id', $motorId)->where('policy_coverage_id', $coverageId)->whereNull('deleted_at')->first();
        if (!$motor) {
            return response()->json(['error' => 'Motor vehicle not found for this coverage.'], 404);
        }
        if (empty(trim((string) ($motor->registration_no ?? '')))) {
            return response()->json(['error' => 'Motor vehicle must have a registration number before adding specified items.'], 422);
        }

        $calcVal = ($validated['sum_insured'] * ($validated['rate'] ?? 0)) / 100;
        // Resolve the coverage's OWN action — not "latest by id". Edit-policy
        // routes the user to a specific action via ?action_id=… and the
        // coverage row already lives on that action (policy_coverages are
        // action-scoped). Using "latest by id" here stamped the item with a
        // newer action's id when one existed (e.g. an in-progress endorsement
        // sitting in IN_APPROVAL on a higher action_id), and the editData
        // loader's `where action_id = current` filter then hid the item from
        // the very screen that created it. Pull the coverage's action_id
        // first; fall back to latest only if the column is somehow null.
        $covActionId = (int) (PolicyCoverage::where('id', $coverageId)->value('action_id') ?? 0);
        $action = $covActionId
            ? \AlphaDirect\Models\PolicyAction::find($covActionId)
            : \AlphaDirect\Models\PolicyAction::where('policy_id', $policyId)->orderBy('id', 'desc')->first();
        if (!$covActionId) {
            $covActionId = (int) ($action?->id ?? 0);
        }
        // Term — prefer the action's own term; otherwise latest-by-id.
        $term = $action?->term_id
            ? PolicyTerm::find($action->term_id)
            : PolicyTerm::where('policy_id', $policyId)->orderBy('id', 'desc')->first();

        $hasCustomNameCol = \Schema::hasColumn('policy_specified_items', 'custom_name');

        $finalCalc = (float) ($validated['calculated_value'] ?? round($calcVal, 2));

        try {
            // Compute pro-rata via the legacy 5-case helper. Motor-attached items
            // key on (motor.registration_no, specified_coverage_id, custom_name).
            // For brand-new items (no past match) → Case 1 → full pro-rata.
            $proRataCase = self::computeSpecifiedItemProRataCase(
                $policyId,
                $coverageId,
                $covActionId,
                $motorId,
                $validated['specified_coverage_id'] ?? null,
                ($hasCustomNameCol && empty($validated['specified_coverage_id'])) ? $customName : null,
                $finalCalc
            );

            // Build the insert payload column-by-column so envs missing the
            // pro-rata wizard columns (older legacy DBs) don't 500 on Unknown
            // column. Mirrors the Schema::hasColumn gating used elsewhere in
            // this controller for policy_specified_items.
            $row = [
                'policy_coverage_id'    => $coverageId,
                'motor_id'              => $motorId,
                'specified_coverage_id' => $validated['specified_coverage_id'] ?? null,
                'sum_insured'           => $validated['sum_insured'],
                'rate'                  => $validated['rate'] ?? 0,
                'calculated_value'      => $finalCalc,
                'created_at'            => now(),
                'updated_at'            => now(),
            ];
            if (\Schema::hasColumn('policy_specified_items', 'pro_rate_premium')) {
                $row['pro_rate_premium'] = $proRataCase['pro_rate_premium'];
            }
            if (\Schema::hasColumn('policy_specified_items', 'previousActionIdCov')) {
                $row['previousActionIdCov'] = $proRataCase['previousActionIdCov'];
            }
            if (\Schema::hasColumn('policy_specified_items', 'endors_flag')) {
                $row['endors_flag'] = $proRataCase['endors_flag'];
            }
            if (\Schema::hasColumn('policy_specified_items', 'term_id')) {
                $row['term_id'] = $term?->id;
            }
            if (\Schema::hasColumn('policy_specified_items', 'action_id')) {
                $row['action_id'] = $action?->id;
            }
            if ($hasCustomNameCol && empty($validated['specified_coverage_id']) && !empty($customName)) {
                $row['custom_name'] = $customName;
            }

            // Eloquent forceFill+save so PolicySpecifiedItem Auditable fires for
            // the Logs tab. The model's boot() recomputes calculated_value on
            // create; passing it through forceFill is harmless (overwritten).
            $siModel = new \AlphaDirect\Models\PolicySpecifiedItem();
            $siModel->forceFill(array_merge($row, $this->auditStamps('policy_specified_items')))->save();
            $id = $siModel->id;

            // Re-fetch with joined name
            $item = DB::table('policy_specified_items as psi')
                ->leftJoin('specified_coverage_items as sci', 'sci.id', '=', 'psi.specified_coverage_id')
                ->where('psi.id', $id)
                ->select('psi.*', 'sci.specified_name as item_name')
                ->first();

            return response()->json([
                'data' => [
                    'id'             => $item->id,
                    'name'           => $item->item_name ?? ($item->custom_name ?? $customName ?? 'Item #' . $id),
                    'sumInsured'     => $item->sum_insured,
                    'rate'           => $item->rate,
                    'calculatedValue'=> $item->calculated_value,
                    'isCustom'       => empty($item->specified_coverage_id),
                ],
                'message' => 'Specified item added.',
            ], 201);
        } catch (\Throwable $e) {
            \Log::error('addMotorSpecifiedItem failed', [
                'policy_id'   => $policyId,
                'coverage_id' => $coverageId,
                'motor_id'    => $motorId,
                'payload'     => $request->all(),
                'message'     => $e->getMessage(),
            ]);
            return response()->json([
                'error' => 'Could not save specified item: ' . $e->getMessage(),
            ], 500);
        }
    }

    /**
     * Delete a specified item that belongs to a motor vehicle.
     */
    public function deleteMotorSpecifiedItem(int $policyId, int $coverageId, int $motorId, int $itemId): JsonResponse
    {
        if ($r = $this->ensureCoverageEditable($coverageId)) return $r;

        // CANCEL pro-rata: refund = −baseline (the item's own calculated_value).
        // Stamp BEFORE setting deleted_at so the negative pro_rate_premium is
        // queryable for Rate's sum (which filters by previousActionIdCov).
        $covActionId = (int) (PolicyCoverage::where('id', $coverageId)->value('action_id') ?? 0);
        $row = DB::table('policy_specified_items')
            ->where('id', $itemId)
            ->where('policy_coverage_id', $coverageId)
            ->where('motor_id', $motorId)
            ->first();
        $refund = $row ? -(float) ($row->calculated_value ?? 0) : 0.0;

        DB::table('policy_specified_items')
            ->where('id', $itemId)
            ->where('policy_coverage_id', $coverageId)
            ->where('motor_id', $motorId)
            ->update([
                'deleted_at'          => now(),
                'pro_rate_premium'    => $refund,
                'previousActionIdCov' => $covActionId ?: DB::raw('previousActionIdCov'),
                // Enum-like column — legacy stores '0'/'1' as strings.
                // Integer 1 gets coerced to 0 by MySQL's enum casting.
                'endors_flag'         => '1',
            ]);

        return response()->json(['message' => 'Specified item deleted.']);
    }

    /**
     * Reinstate a soft-deleted specified item attached to a motor vehicle —
     * mirror of deleteMotorSpecifiedItem so motor items get the same
     * soft-delete / reinstate workflow as every other coverage. Clears
     * deleted_at and re-stamps the pro-rata (re-add = +calculated_value) so
     * Rate picks the line back up.
     */
    public function reinstateMotorSpecifiedItem(int $policyId, int $coverageId, int $motorId, int $itemId): JsonResponse
    {
        if ($r = $this->ensureCoverageEditable($coverageId)) return $r;

        $covActionId = (int) (PolicyCoverage::where('id', $coverageId)->value('action_id') ?? 0);
        $row = DB::table('policy_specified_items')
            ->where('id', $itemId)
            ->where('policy_coverage_id', $coverageId)
            ->where('motor_id', $motorId)
            ->first();
        if (!$row) {
            return response()->json(['error' => 'Specified item not found.'], 404);
        }
        // Re-add the premium that was refunded on delete (delta = +calculated_value).
        $readd = (float) ($row->calculated_value ?? 0);

        DB::table('policy_specified_items')
            ->where('id', $itemId)
            ->where('policy_coverage_id', $coverageId)
            ->where('motor_id', $motorId)
            ->update([
                'deleted_at'          => null,
                'pro_rate_premium'    => $readd,
                'previousActionIdCov' => $covActionId ?: DB::raw('previousActionIdCov'),
                'endors_flag'         => '1',
                'updated_at'          => now(),
            ]);

        return response()->json(['message' => 'Specified item reinstated.']);
    }

    /**
     * Update a single specified item attached to a motor vehicle. Auto-
     * recomputes calculated_value when sum_insured and rate are provided
     * without an explicit calculated value.
     */
    public function updateMotorSpecifiedItem(Request $request, int $policyId, int $coverageId, int $motorId, int $itemId): JsonResponse
    {
        if ($r = $this->ensureCoverageEditable($coverageId)) return $r;
        $validated = $request->validate([
            // DOM/COM (22/27) per-vehicle MISC editor lets the Description be
            // re-pointed at a different master item; persist the new FK. `name`
            // is intentionally NOT accepted — the display name derives from the
            // join on specified_coverage_id (no `name` column on this table).
            'specified_coverage_id' => 'sometimes|nullable|integer',
            'sum_insured'      => 'sometimes|numeric|min:0',
            'rate'             => 'sometimes|numeric|min:0',
            'calculated_value' => 'sometimes|numeric|min:0',
        ]);

        if (isset($validated['sum_insured']) && isset($validated['rate']) && !isset($validated['calculated_value'])) {
            $validated['calculated_value'] = round(((float) $validated['sum_insured'] * (float) $validated['rate']) / 100, 2);
        }

        // Read existing row for case-helper context (specified_coverage_id +
        // custom_name don't change on update — we look them up from the row).
        $existing = DB::table('policy_specified_items')
            ->where('id', $itemId)
            ->where('policy_coverage_id', $coverageId)
            ->where('motor_id', $motorId)
            ->whereNull('deleted_at')
            ->first();
        if (!$existing) {
            return response()->json(['error' => 'Item not found.'], 404);
        }

        // Recompute pro-rata via the SI helper. Same key as on insert so the
        // case logic compares against the right baseline.
        $covActionId = (int) (PolicyCoverage::where('id', $coverageId)->value('action_id') ?? 0);
        $newCalc = array_key_exists('calculated_value', $validated)
            ? (float) $validated['calculated_value']
            : (float) ($existing->calculated_value ?? 0);
        $hasCustomNameCol = \Schema::hasColumn('policy_specified_items', 'custom_name');
        $customName = ($hasCustomNameCol && property_exists($existing, 'custom_name')) ? $existing->custom_name : null;

        // When the Description (master FK) is re-pointed, the pro-rata case must
        // compare against the NEW master, not the row's old one.
        $effectiveSpecifiedCoverageId = array_key_exists('specified_coverage_id', $validated)
            ? ($validated['specified_coverage_id'] ? (int) $validated['specified_coverage_id'] : null)
            : ($existing->specified_coverage_id ? (int) $existing->specified_coverage_id : null);

        if ($covActionId) {
            $proRataCase = self::computeSpecifiedItemProRataCase(
                $policyId,
                $coverageId,
                $covActionId,
                $motorId,
                $effectiveSpecifiedCoverageId,
                $customName,
                $newCalc
            );
            $validated['pro_rate_premium']    = $proRataCase['pro_rate_premium'];
            $validated['previousActionIdCov'] = $proRataCase['previousActionIdCov'];
            $validated['endors_flag']         = $proRataCase['endors_flag'];
        }

        $updated = DB::table('policy_specified_items')
            ->where('id', $itemId)
            ->where('policy_coverage_id', $coverageId)
            ->where('motor_id', $motorId)
            ->whereNull('deleted_at')
            ->update(array_merge($validated, ['updated_at' => now()]));

        if (!$updated) {
            return response()->json(['error' => 'Item not found.'], 404);
        }

        $fresh = DB::table('policy_specified_items')->where('id', $itemId)->first();
        return response()->json(['data' => $fresh, 'message' => 'Updated.']);
    }

    /**
     * Upsert a per-motor note. graphiteBWV8 stores a row per (pc_id, motor_id)
     * in policy_coverage_notes. Empty note deletes the row.
     */
    public function upsertMotorNote(Request $request, int $policyId, int $coverageId, int $motorId): JsonResponse
    {
        if ($r = $this->ensureCoverageEditable($coverageId)) return $r;

        // Guard: motor must exist for this coverage with a registration_no.
        // Mirrors legacy ManageCoverages::submit() which only stores motor
        // notes when (policy_coverage_id, registration_no) resolves to a row.
        $motor = DB::table('motor')->where('id', $motorId)
            ->where('policy_coverage_id', $coverageId)
            ->whereNull('deleted_at')
            ->first();
        if (!$motor) {
            return response()->json(['error' => 'Motor vehicle not found for this coverage.'], 404);
        }
        if (empty(trim((string) ($motor->registration_no ?? '')))) {
            return response()->json(['error' => 'Motor vehicle must have a registration number before adding a note.'], 422);
        }

        $validated = $request->validate([
            // DB column is TEXT (~65KB); UW pastes long excess clauses so the
            // 2000-char cap was rejecting paragraphs silently.
            'note' => 'nullable|string|max:65535',
        ]);
        $note = trim($validated['note'] ?? '');

        // Eloquent so PolicyCoverageNote Auditable fires for the Logs tab.
        $reg = trim((string) ($motor->registration_no ?? ''));
        if ($note === '') {
            \AlphaDirect\Models\PolicyCoverageNote::where('policy_coverage_id', $coverageId)
                ->where('motor_id', $motorId)->get()
                ->each(fn($n) => $n->delete());
            activity('Coverage Note')->performedOn(Policy::find($policyId))->causedBy(auth()->user())
                ->log('Motor note cleared on coverage #' . $coverageId . ($reg !== '' ? " — {$reg}" : ''));
            return response()->json(['message' => 'Note cleared.']);
        }

        $existing = \AlphaDirect\Models\PolicyCoverageNote::where('policy_coverage_id', $coverageId)
            ->where('motor_id', $motorId)->first();

        if ($existing) {
            $existing->forceFill(['note' => $note])->save();
        } else {
            // Stamp the action/term of the COVERAGE this note belongs to, not
            // "latest action by id". On an anniversary/endorse quote the latest
            // action is a higher-id future RENEW, so the old code filed the note
            // under the wrong action. The note is keyed to $coverageId, so the
            // coverage's own action_id is the correct (selected) scope.
            $cov = PolicyCoverage::where('id', $coverageId)->first();
            $action = $cov && $cov->action_id
                ? \AlphaDirect\Models\PolicyAction::find($cov->action_id)
                : \AlphaDirect\Models\PolicyAction::where('policy_id', $policyId)->orderBy('id', 'desc')->first();
            $term   = ($cov && $cov->term_id)
                ? PolicyTerm::find($cov->term_id)
                : PolicyTerm::where('policy_id', $policyId)->orderBy('id', 'desc')->first();
            $noteModel = new \AlphaDirect\Models\PolicyCoverageNote();
            $noteModel->forceFill(array_merge([
                'policy_coverage_id' => $coverageId,
                'motor_id'           => $motorId,
                'note'               => $note,
                'term_id'            => $term?->id,
                'action_id'          => $action?->id,
            ], $this->auditStamps('policy_coverage_notes')))->save();
        }

        activity('Coverage Note')->performedOn(Policy::find($policyId))->causedBy(auth()->user())
            ->log(($existing ? 'Motor note updated' : 'Motor note added') . ' on coverage #' . $coverageId . ($reg !== '' ? " — {$reg}" : ''));

        return response()->json(['message' => 'Note saved.']);
    }

    // Motor Traders Ext/Int share an identical 32-field schema. Listed here
    // once and reused by both branches' save handlers. Field names mirror the
    // motor_traders / motor_traders_internal migrations verbatim — including
    // legacy typos (unauthoried, contigent, passanger, minimun) and the
    // capitalised Loss_of_use_of_customer_* keys — so the DB column
    // round-trips cleanly without per-field aliasing.
    private const MOTOR_TRADERS_FIELDS = [
        'type_of_cover',
        'loss_or_damage_coverage_value', 'loss_or_damage_calculated_value',
        'third_party_liability_coverage_value', 'third_party_liability_calculated_value',
        'medical_benefits_coverage_value', 'medical_benefits_calculated_value',
        'vehicle_lent_hire_coverage_value', 'vehicle_lent_hire_calculated_value',
        'social_domestic_pleasure_coverage_value', 'social_domestic_pleasure_calculated_value',
        'unauthoried_use_coverage_value', 'unauthoried_use_calculated_value',
        'windscreen_coverage_value', 'windscreen_calculated_value',
        'contigent_liability_coverage_value', 'contigent_liability_calculated_value',
        'wreckage_removal_coverage_value', 'wreckage_removal_calculated_value',
        'loss_of_key_coverage_value', 'loss_of_key_calculated_value',
        'Loss_of_use_of_customer_coverage_value', 'Loss_of_use_of_customer_calculated_value',
        'motor_cycle_motor_tricycle_coverage_value', 'motor_cycle_motor_tricycle_calculated_value',
        'passanger_liability_respect_of_motor_coverage_value', 'passanger_liability_respect_of_motor_calculated_value',
        'special_type_vehicle_coverage_value', 'special_type_vehicle_calculated_value',
        'own_damage_minimun_percent', 'own_damage_minimum_amount',
        'windscreen_minimun_percent', 'windscreen_minimum_amount',
    ];

    public function getMotorTradersExternal(int $policyId, int $coverageId): JsonResponse
    {
        $row = DB::table('motor_traders')
            ->where('policy_coverage_id', $coverageId)
            ->whereNull('deleted_at')
            ->orderByDesc('id')
            ->first();
        return response()->json(['data' => $row]);
    }

    public function saveMotorTradersExternal(Request $request, int $policyId, int $coverageId): JsonResponse
    {
        if ($r = $this->ensureCoverageEditable($coverageId)) return $r;

        $payload = $request->only(self::MOTOR_TRADERS_FIELDS);
        $actionId = PolicyCoverage::find($coverageId)?->action_id;
        // Wizard stamp so writeLineLevelProRata picks this row up as
        // user-touched during the ENDORSE pro-rata sweep.
        if ($actionId && \Schema::hasColumn('motor_traders', 'previousActionIdCov')) {
            $payload['previousActionIdCov'] = $actionId;
            $payload['endors_flag'] = 1;
        }
        $existing = \AlphaDirect\Models\MotorTraders::where('policy_coverage_id', $coverageId)
            ->whereNull('deleted_at')->orderByDesc('id')->first();
        if ($existing) {
            $existing->update($payload);
            $row = $existing->fresh();
        } else {
            $row = \AlphaDirect\Models\MotorTraders::create(array_merge(
                $payload,
                ['policy_coverage_id' => $coverageId]
            ));
        }
        // Refresh policy_actions.annual_premium so Rate banner / V2 Quote
        // total reflect the new MT contribution without an explicit Rate click.
        if ($actionId) self::recomputeActionTotals($policyId, (int) $actionId);
        return response()->json(['data' => $row, 'message' => 'Saved.']);
    }

