    /**
     * Get policy vehicles available for motor coverage (not yet added to this coverage).
     *
     * Scopes by the coverage's risk_address_id — operators expect only the
     * vehicles registered against the same risk address to surface. Legacy
     * Graphite pairs vehicles to addresses via vehicle.risk_id and renders
     * motor dropdowns filtered the same way. Vehicles without a risk_id
     * (legacy data) still surface so nothing silently disappears.
     *
     * ACTION-WISE. The vehicle table carries one row per plate PER ACTION
     * (PolicyAction::replicateRecordsIfMissing clones 'AlphaDirect\Vehicle'
     * keyed on action_id), so the action scope is what keeps the dropdown to
     * one entry per plate. The anchor is the action the operator is editing —
     * policy_coverages.action_id for a saved coverage, the FE's ?action_id=
     * hint while the coverage is still unsaved — never "latest action by id",
     * which on an anniversary/back-dated quote points at a different
     * transaction than the one on screen (same rule as addCoverage).
     */
    public function availableVehiclesForMotor(int $policyId, int $coverageId): JsonResponse
    {
        $usedPlates = DB::table('motor')->where('policy_coverage_id', $coverageId)->whereNull('deleted_at')->pluck('registration_no')->toArray();

        // Resolve the coverage's risk_address_id + action_id (or take the
        // wizard's pre-save hints when the coverage row doesn't exist yet).
        $coverageRow = DB::table('policy_coverages')
            ->where('id', $coverageId)
            ->whereNull('deleted_at')
            ->first(['risk_address_id', 'action_id']);

        $coverageRiskAddressId = (int) ($coverageRow->risk_address_id ?? 0);
        if ($coverageRiskAddressId <= 0) {
            $coverageRiskAddressId = (int) request()->query('risk_address_id', 0);
        }

        $actionId = (int) ($coverageRow->action_id ?? 0);
        if ($actionId <= 0) {
            $actionId = (int) request()->query('action_id', 0);
        }
        if ($actionId <= 0) {
            // No coverage row and no FE hint — fall back to the newest action
            // in (effective_from, id) order, the project's action chronology.
            $actionId = (int) (DB::table('policy_actions')
                ->where('policy_id', $policyId)
                ->whereNull('deleted_at')
                ->orderByDesc('effective_from')
                ->orderByDesc('id')
                ->value('id') ?? 0);
        }

        $cols = ['id', 'vehiclePlate', 'make', 'model', 'year', 'estimated_value', 'engineNo', 'chassisNo', 'risk_id', 'action_id'];

        $base = DB::table('vehicle')
            ->where('policy_id', $policyId)
            ->whereNull('deleted_at')
            ->when(!empty($usedPlates), fn($q) => $q->whereNotIn('vehiclePlate', $usedPlates));

        // Narrowest scope first (policy + action + risk_address). Each
        // fallback only widens on an EMPTY result — legacy rows where
        // vehicle.risk_id or .action_id was never backfilled — so the
        // dropdown is never mysteriously blank.
        $fetch = fn($q) => $q->orderBy('id')->get($cols);

        $vehicles = collect();
        if ($actionId > 0) {
            if ($coverageRiskAddressId > 0) {
                $vehicles = $fetch((clone $base)->where('action_id', $actionId)->where('risk_id', $coverageRiskAddressId));
            }
            if ($vehicles->isEmpty()) {
                $vehicles = $fetch((clone $base)->where('action_id', $actionId));
            }
        }
        if ($vehicles->isEmpty() && $coverageRiskAddressId > 0) {
            $vehicles = $fetch((clone $base)->where('risk_id', $coverageRiskAddressId));
        }
        if ($vehicles->isEmpty()) {
            $vehicles = $fetch(clone $base);
        }

        // Collapse replicas to one row per plate. Two sources of repeats:
        // a widened fallback above (one row per plate per action) and
        // replication double-inserts inside a single action. Keep the newest
        // row (highest id) for each plate, then restore id order for display.
        $norm = fn($p) => strtoupper(preg_replace('/\s+/', '', (string) $p));
        $usedNorm = array_flip(array_map($norm, $usedPlates));

        $vehicles = $vehicles
            ->reject(fn($v) => isset($usedNorm[$norm($v->vehiclePlate)]))
            ->sortByDesc('id')
            ->unique(fn($v) => $norm($v->vehiclePlate))
            ->sortBy('id')
            ->values();

        return response()->json(['data' => $vehicles->map(fn($v) => [
            'id' => $v->id, 'plate' => $v->vehiclePlate, 'make' => $v->make, 'model' => $v->model,
            'year' => $v->year, 'estimated_value' => $v->estimated_value, 'risk_id' => $v->risk_id,
            'action_id' => $v->action_id,
            'label' => trim(($v->make ?? '') . ' ' . ($v->model ?? '') . ' — ' . ($v->vehiclePlate ?? '')),
        ])]);
    }

    public function getRiskAddressesWithCoverages(int $policyId): JsonResponse
    {
        $policy = Policy::findOrFail($policyId);

        $riskAddresses = RiskAddress::where('policy_id', $policyId)
            ->with(['coverages' => function ($q) {
