            'middle_name' => 'nullable|string|max:100',
            'last_name'   => 'required|string|max:100',
            'relation'    => 'required|string|max:100',
            'gender'      => 'required|string|in:Male,Female',
            'dob'         => 'nullable|date_format:Y-m-d',
            'omang'       => ['nullable', 'string', 'regex:/^[0-9]{4}[12][0-9]{4}$/'],
            'passport'    => 'nullable|string|max:25',
            'payment'     => 'nullable|numeric|min:0|max:100',
            'risk_id'     => 'nullable|integer|exists:risk_address,id',
        ], [
            'omang.regex' => 'Omang must be 9 digits and the 5th digit must be 1 or 2.',
