            HcbCoapplicantService::delete($policy, $coapplicantId, auth()->user(), $this->adminActorLabel());
        } catch (HcbCoapplicantException $e) {
            return response()->json(['error' => $e->getMessage()], $e->status);
        }

        return response()->json(['message' => 'Co-applicant deleted.', 'premium' => $policy->refresh()->premium]);
    }

    private function adminActorLabel(): string
    {
        $u = auth()->user();
        if (!$u) return 'System';
        $name = trim((string) ($u->firstName ?? '') . ' ' . (string) ($u->lastName ?? ''));
        return $name !== '' ? $name : ('User #' . $u->id);
    }

