    // ── Vehicles ──────────────────────────────────────────────────────────────

    /**
     * Vehicle inspection photo slots: form field (img_<pos>) → DB column.
     * Mirrors graphiteBWV8 vehicle image columns (front/back/right/left +
     * registration book + invoice/valuation).
     */
    private const VEHICLE_IMAGE_MAP = [
        'front'        => 'front',
        'back'         => 'back',
        'right'        => 'right',
        'left'         => 'left',
        'registration' => 'vehicleRegistration',
        'valuation'    => 'vehicle_valuation',
    ];

    /** Store one vehicle photo to S3 (vehicle/{policyId}/{customerId}/{position}/{file}). */
    private function storeVehicleImage(\Illuminate\Http\UploadedFile $file, int $policyId, $customerId, string $position): string
    {
        $fileName = time() . '_' . preg_replace('/\s+/', '', $file->getClientOriginalName());
        $filePath = 'vehicle/' . $policyId . '/' . $customerId . '/' . $position . '/' . $fileName;
        \Illuminate\Support\Facades\Storage::disk('s3')->put($filePath, file_get_contents($file), 'public');
        return $filePath;
    }

    /** Validation rules for the six optional vehicle photo uploads. */
    private function vehicleImageRules(): array
    {
        $rules = [];
        foreach (array_keys(self::VEHICLE_IMAGE_MAP) as $pos) {
            $rules['img_' . $pos] = 'nullable|file|mimes:jpg,jpeg,png,pdf|max:20480';
        }
        return $rules;
    }

    /**
     * Resolve uploaded/removed vehicle photos into a [column => value] array.
     * New file → S3 key; remove_<pos>=1 → null; otherwise the column is omitted.
     */
    private function resolveVehicleImages(Request $request, int $policyId, $customerId): array
    {
        $data = [];
        foreach (self::VEHICLE_IMAGE_MAP as $pos => $col) {
            if ($request->hasFile('img_' . $pos)) {
                $data[$col] = $this->storeVehicleImage($request->file('img_' . $pos), $policyId, $customerId, $pos);
            } elseif ($request->boolean('remove_' . $pos)) {
                $data[$col] = null;
            }
        }
        return $data;
    }

    public function addVehicle(Request $request, int $policyId): JsonResponse
    {
        $policy = Policy::findOrFail($policyId);
        $v = $request->validate(array_merge([
            'vehiclePlate'    => 'required|string|max:20',
            'make'            => 'required|string|max:100',
            'model'           => 'required|string|max:100',
            'year'            => 'nullable|string|max:4',
            'chassisNo'       => 'nullable|string|max:50',
            'engineNo'        => 'nullable|string|max:50',
            'vinnumber'       => 'nullable|string|max:50',
            'seats'           => 'nullable|integer',
            'cylinders'       => 'nullable|integer',
            'cubic_capacity'  => 'nullable|string|max:20',
            'mileage'         => 'nullable|string|max:20',
            'vehicle_type'    => 'nullable|string|max:50',
            'claim_count'     => 'nullable|integer|min:0|max:99',
            'estimated_value' => 'nullable|numeric|min:0',
            'is_imported'     => 'nullable|boolean',
            'is_private'      => 'nullable|boolean',
            'is_tracking'     => 'nullable|boolean',
            'financial_interest' => 'nullable|string|max:150',
            'risk_id'         => 'nullable|integer|exists:risk_address,id',
        ], $this->vehicleImageRules()));

        $action = \AlphaDirect\Models\PolicyAction::where('policy_id', $policyId)->orderBy('id', 'desc')->first();
        $term   = PolicyTerm::where('policy_id', $policyId)->orderBy('id', 'desc')->first();

        // Same rule as coverages and risk addresses. Without it a Smart Upload
        // Apply onto an ISSUED action had every section correctly refused with
        // a 409 and then registered the whole fleet against that issued
        // transaction anyway — applyVehicles runs after the section loop
        // regardless of how the sections went. A vehicle carries no cover of
        // its own, so nothing was mispriced, but it is still a write onto a
        // transaction that has already been printed and invoiced.
        if ($locked = $this->ensureActionEditable((int) ($action?->id ?? 0), 'Vehicles')) {
            return $locked;
        }

        $imageData = $this->resolveVehicleImages($request, $policyId, $policy->customer_id);

        // Eloquent ->save() (not DB::table->insertGetId) so OwenIt Auditable
        // fires a `created` event into the audits table → Logs tab picks the
        // new vehicle up. forceFill() bypasses the model's narrow $fillable
        // (chassisNo/engineNo/seats/etc. aren't whitelisted) without forcing
        // a wider mass-assignment surface; the request payload is already
        // validated above.
        $vehicle = new \AlphaDirect\Vehicle();
        $vehicle->forceFill(array_merge([
            'customer_id'     => $policy->customer_id,
            'policy_id'       => $policyId,
            'vehiclePlate'    => strtoupper($v['vehiclePlate']),
            'make'            => $v['make'],
            'model'           => $v['model'],
            'year'            => $v['year'] ?? null,
            'chassisNo'       => $v['chassisNo'] ?? null,
            'engineNo'        => $v['engineNo'] ?? null,
            'vinnumber'       => $v['vinnumber'] ?? null,
            'seats'           => $v['seats'] ?? null,
            'cylinders'       => $v['cylinders'] ?? null,
            'cubic_capacity'  => $v['cubic_capacity'] ?? null,
            'mileage'         => $v['mileage'] ?? null,
            'vehicle_type'    => $v['vehicle_type'] ?? null,
            'claim_count'     => $v['claim_count'] ?? null,
            'estimated_value' => $v['estimated_value'] ?? null,
            'is_imported'     => !empty($v['is_imported']) ? 1 : 0,
            'is_private'      => !empty($v['is_private']) ? 1 : 0,
            'is_tracking'     => !empty($v['is_tracking']) ? 1 : 0,
            'financial_interest' => $v['financial_interest'] ?? null,
            'risk_id'         => $v['risk_id'] ?? null,
            'term_id'         => $term?->id,
            'action_id'       => $action?->id,
        ], $imageData))->save();

        // Carry the new vehicle forward into every later OPEN batch of this
        // policy, so the fleet stays in step from this action's date onward.
        $carried = $action ? $this->propagateVehicleForward($vehicle, $action) : 0;

        activity('Policy Vehicle')->performedOn($policy)->causedBy(auth()->user())->log('Vehicle Added');

        return response()->json([
            'message'        => 'Vehicle added.',
            'id'             => $vehicle->id,
            'carriedForward' => $carried,
        ], 201);
    }

    /**
     * Forward-propagate one vehicle row to the policy's later OPEN actions.
     *
     * Vehicle rows are per-action snapshots: adding a vehicle on the action in
     * force only registers it there, so any batch already created for a LATER
     * effective date would keep showing the old fleet — and the next renewal,
     * replicating from those batches, would drop the vehicle permanently.
     *
     * Targets follow the settled propagation rule — actions whose
     * effective_from is on/after PolicyAction::forwardPropagationAnchor() of the
     * source action — limited to the transaction types the endorse-issue
     * propagation loop uses. Idempotent: an action that already carries the
     * plate is skipped, so re-running never duplicates. Premium is untouched;
     * rating comes off the motor rows under the coverage, not off this register.
     *
     * TWO GUARDS, both from the #1736 code review (2026-07-30) — do not relax
     * either without re-reading it:
     *
     *   1. QUOTE targets ONLY. The first version filtered on policy, date, type
     *      and not-deleted but never on status, so it wrote rows into ISSUED
     *      transactions — closed records the customer's documents came off.
     *      Anything not still open is skipped and logged, never silently.
     *
     *   2. NO cross-action risk_id. Risk addresses are per-action too. The first
     *      version fell back to the SOURCE action's risk_id when the target had
     *      no address of that name, which pointed the carried row at another
     *      action's address record — the vehicle then displayed against the
     *      wrong risk. The vehicle is still carried (losing it is the worse
     *      failure, and the replicators deliberately carry unmatched-risk rows
     *      too) but with risk_id left empty rather than wrong.
     */
    private function propagateVehicleForward(\AlphaDirect\Vehicle $vehicle, PolicyAction $sourceAction): int
    {
        try {
            $laterActions = PolicyAction::where('policy_id', $vehicle->policy_id)
                ->where('id', '!=', $sourceAction->id)
                ->where('effective_from', '>=', PolicyAction::forwardPropagationAnchor($sourceAction))
                ->whereIn('transaction_type', ['RENEW', 'ANNIVERSARY-RENEW', 'ENDORSE', 'REINSTATE'])
                ->whereNull('deleted_at')
                ->orderBy('effective_from')
                ->get();

            if ($laterActions->isEmpty()) return 0;

            // Guard 1 — only actions still open for edit may be written to.
            $open   = $laterActions->filter(fn ($a) => (string) $a->status === 'QUOTE');
            $closed = $laterActions->reject(fn ($a) => (string) $a->status === 'QUOTE');
            if ($closed->isNotEmpty()) {
                // Never silent: an operator adding a vehicle to a policy with
                // already-issued later batches needs those batches endorsed,
                // and support needs to see that this add did not reach them.
                Log::info('propagateVehicleForward: skipped non-QUOTE later actions', [
                    'policy_id' => $vehicle->policy_id,
                    'vehicle'   => $vehicle->vehiclePlate,
                    'source'    => $sourceAction->id,
                    'skipped'   => $closed->map(fn ($a) => ['id' => (int) $a->id, 'status' => $a->status])->values()->all(),
                ]);
            }
            if ($open->isEmpty()) return 0;

            // The source row's address NAME — risk_address ids differ per action,
            // the name is what carries across (same rule replicateRecords uses).
            $riskName = $vehicle->risk_id
                ? RiskAddress::where('id', $vehicle->risk_id)->value('address_name')
                : null;

            $copied = 0;
            foreach ($open as $later) {
                if (\AlphaDirect\Vehicle::duplicateOnPolicyAction($vehicle->vehiclePlate, $vehicle->policy_id, $later->id)) {
                    continue;
                }

                $clone = $vehicle->replicate();
                $clone->action_id = $later->id;
                $clone->term_id   = $later->term_id ?: $vehicle->term_id;
                // Guard 2 — the target action's OWN address row, or nothing.
                $clone->risk_id = $riskName
                    ? RiskAddress::Action($later->id)->AddressName($riskName)->value('id')
                    : null;
                $clone->save();
                $copied++;
            }

            return $copied;
        } catch (\Throwable $e) {
            // Never fail the add over propagation — the row the operator asked
            // for is already saved on the selected action.
            Log::error('propagateVehicleForward failed: ' . $e->getMessage(), [
                'vehicle_id' => $vehicle->id,
                'policy_id'  => $vehicle->policy_id,
                'source'     => $sourceAction->id,
            ]);
            return 0;
        }
    }

    public function updateVehicle(Request $request, int $policyId, int $vehicleId): JsonResponse
    {
        Policy::findOrFail($policyId);
        // Eloquent fetch with manual whereNull('deleted_at') (Vehicle model
        // doesn't use SoftDeletes trait, manages deleted_at by hand) so the
        // subsequent forceFill+save flows through Auditable and each field
        // change is captured in the audits table → Logs tab.
        $vehicle = \AlphaDirect\Vehicle::where('policy_id', $policyId)
            ->whereNull('deleted_at')->find($vehicleId);
        if (!$vehicle) return response()->json(['error' => 'Vehicle not found.'], 404);

        $v = $request->validate(array_merge([
            'vehiclePlate'    => 'required|string|max:20',
            'make'            => 'required|string|max:100',
            'model'           => 'required|string|max:100',
            'year'            => 'nullable|string|max:4',
            'chassisNo'       => 'nullable|string|max:50',
            'engineNo'        => 'nullable|string|max:50',
            'vinnumber'       => 'nullable|string|max:50',
            'seats'           => 'nullable|integer',
            'cylinders'       => 'nullable|integer',
            'cubic_capacity'  => 'nullable|string|max:20',
            'mileage'         => 'nullable|string|max:20',
            'vehicle_type'    => 'nullable|string|max:50',
            'claim_count'     => 'nullable|integer|min:0|max:99',
            'estimated_value' => 'nullable|numeric|min:0',
            'is_imported'     => 'nullable|boolean',
            'is_private'      => 'nullable|boolean',
            'is_tracking'     => 'nullable|boolean',
            'financial_interest' => 'nullable|string|max:150',
            'risk_id'         => 'nullable|integer|exists:risk_address,id',
        ], $this->vehicleImageRules()));

        $imageData = $this->resolveVehicleImages($request, $policyId, $vehicle->customer_id);

        // Eloquent forceFill+save so OwenIt Auditable diffs each changed
        // field (estimated_value, claim_count, vehicle_type, …) into the
        // audits table; the Vehicle model's transformAudit injects
        // policy_number so the Logs tab finds it by policy filter.
        // forceFill bypasses the narrow $fillable list — same as addVehicle.
        $vehicle->forceFill(array_merge([
            'vehiclePlate'    => strtoupper($v['vehiclePlate']),
            'make'            => $v['make'],
            'model'           => $v['model'],
            'year'            => $v['year'] ?? null,
            'chassisNo'       => $v['chassisNo'] ?? null,
            'engineNo'        => $v['engineNo'] ?? null,
            'vinnumber'       => $v['vinnumber'] ?? null,
            'seats'           => $v['seats'] ?? null,
            'cylinders'       => $v['cylinders'] ?? null,
            'cubic_capacity'  => $v['cubic_capacity'] ?? null,
            'mileage'         => $v['mileage'] ?? null,
            'vehicle_type'    => $v['vehicle_type'] ?? null,
            'claim_count'     => $v['claim_count'] ?? null,
            'estimated_value' => $v['estimated_value'] ?? null,
            'is_imported'     => !empty($v['is_imported']) ? 1 : 0,
            'is_private'      => !empty($v['is_private']) ? 1 : 0,
            'is_tracking'     => !empty($v['is_tracking']) ? 1 : 0,
            'financial_interest' => $v['financial_interest'] ?? null,
            'risk_id'         => $v['risk_id'] ?? null,
        ], $imageData))->save();

        activity('Policy Vehicle')->performedOn(Policy::find($policyId))->causedBy(auth()->user())->log('Vehicle Updated');

        return response()->json(['message' => 'Vehicle updated.']);
    }

    public function deleteVehicle(int $policyId, int $vehicleId): JsonResponse
    {
        Policy::findOrFail($policyId);
        // Vehicle model has no SoftDeletes trait but the table has a
        // deleted_at column (manual soft-delete pattern). Stamp deleted_at
        // via Eloquent forceFill+save so the change flows through Auditable
        // → audits table → Logs tab. ->delete() would hard-delete here.
        $vehicle = \AlphaDirect\Vehicle::where('policy_id', $policyId)
            ->whereNull('deleted_at')->find($vehicleId);
        if (!$vehicle) return response()->json(['error' => 'Vehicle not found.'], 404);
        $vehicle->forceFill(['deleted_at' => now()])->save();

        activity('Policy Vehicle')->performedOn(Policy::find($policyId))->causedBy(auth()->user())->log('Vehicle Deleted');

        return response()->json(['message' => 'Vehicle deleted.']);
    }

    // ── Devices ───────────────────────────────────────────────────────────────

    /**
     * Pre-inspection photo positions stored on policy_cellphone, mirroring
     * graphiteBWV8 (front/back/left/right/top/bottom + invoice document).
     */
    private const DEVICE_IMAGE_POSITIONS = ['front', 'back', 'left', 'right', 'top', 'bottom', 'invoice'];

    /**
     * Store one uploaded device photo to S3 using the V8 path convention
     * device/{policyId}/Cellphone/{customerId}/{position}/{file} and return the key.
     */
    private function storeDeviceImage(\Illuminate\Http\UploadedFile $file, int $policyId, $customerId, string $position): string
    {
        $fileName = time() . '_' . preg_replace('/\s+/', '', $file->getClientOriginalName());
        $filePath = 'device/' . $policyId . '/Cellphone/' . $customerId . '/' . $position . '/' . $fileName;
        \Illuminate\Support\Facades\Storage::disk('s3')->put($filePath, file_get_contents($file), 'public');
        return $filePath;
    }

    /** Validation rules for the seven optional device photo uploads. */
    private function deviceImageRules(): array
    {
        $rules = [];
        foreach (self::DEVICE_IMAGE_POSITIONS as $pos) {
            $rules['cell_phone_' . $pos] = 'nullable|file|mimes:jpg,jpeg,png,pdf|max:20480';
        }
        return $rules;
    }

    public function addDevice(Request $request, int $policyId): JsonResponse
    {
        $policy = Policy::findOrFail($policyId);
        $v = $request->validate(array_merge([
            'device_type'      => 'required|string|in:Cellphone,Tablet,Laptop,Other',
            'imei'             => 'required|string|max:50',
            'cell_phone_make'  => 'required|string|max:100',
            'cell_phone_model' => 'required|string|max:100',
            'phone_value'      => 'nullable|numeric|min:0',
            'risk_id'          => 'nullable|integer|exists:risk_address,id',
        ], $this->deviceImageRules()));

        $action = \AlphaDirect\Models\PolicyAction::where('policy_id', $policyId)->orderBy('id', 'desc')->first();
        $term   = PolicyTerm::where('policy_id', $policyId)->orderBy('id', 'desc')->first();

        // Upload any provided pre-inspection photos to S3.
        $imageData = [];
        foreach (self::DEVICE_IMAGE_POSITIONS as $pos) {
            if ($request->hasFile('cell_phone_' . $pos)) {
                $imageData['cell_phone_' . $pos] = $this->storeDeviceImage($request->file('cell_phone_' . $pos), $policyId, $policy->customer_id, $pos);
            }
        }

        $id = DB::table('policy_cellphone')->insertGetId(array_merge([
            'customer_id'      => $policy->customer_id,
            'policy_id'        => $policyId,
            'device_type'      => $v['device_type'],
            'imei'             => $v['imei'],
            'cell_phone_make'  => $v['cell_phone_make'],
            'cell_phone_model' => $v['cell_phone_model'],
            'phone_value'      => $v['phone_value'] ?? null,
            'risk_id'          => $v['risk_id'] ?? null,
            'term_id'          => $term?->id,
            'action_id'        => $action?->id,
            'created_at'       => now(),
            'updated_at'       => now(),
        ], $imageData));

        activity('Policy Device')->performedOn($policy)->causedBy(auth()->user())->log('Device Added');

        return response()->json(['message' => 'Device added.', 'id' => $id], 201);
    }

    public function updateDevice(Request $request, int $policyId, int $deviceId): JsonResponse
    {
        Policy::findOrFail($policyId);
        $row = DB::table('policy_cellphone')->where('id', $deviceId)->where('policy_id', $policyId)->first();
        if (!$row) return response()->json(['error' => 'Device not found.'], 404);

        $v = $request->validate(array_merge([
            'device_type'      => 'required|string|in:Cellphone,Tablet,Laptop,Other',
            'imei'             => 'required|string|max:50',
            'cell_phone_make'  => 'required|string|max:100',
            'cell_phone_model' => 'required|string|max:100',
            'phone_value'      => 'nullable|numeric|min:0',
            'risk_id'          => 'nullable|integer|exists:risk_address,id',
        ], $this->deviceImageRules()));

        // Replace any newly-uploaded photo; null-out a slot when remove_<pos>=1.
        $imageData = [];
        foreach (self::DEVICE_IMAGE_POSITIONS as $pos) {
            if ($request->hasFile('cell_phone_' . $pos)) {
                $imageData['cell_phone_' . $pos] = $this->storeDeviceImage($request->file('cell_phone_' . $pos), $policyId, $row->customer_id, $pos);
            } elseif ($request->boolean('remove_' . $pos)) {
                $imageData['cell_phone_' . $pos] = null;
            }
        }

        DB::table('policy_cellphone')->where('id', $deviceId)->update(array_merge([
            'device_type'      => $v['device_type'],
            'imei'             => $v['imei'],
            'cell_phone_make'  => $v['cell_phone_make'],
            'cell_phone_model' => $v['cell_phone_model'],
            'phone_value'      => $v['phone_value'] ?? null,
            'risk_id'          => $v['risk_id'] ?? null,
            'updated_at'       => now(),
        ], $imageData));

        activity('Policy Device')->performedOn(Policy::find($policyId))->causedBy(auth()->user())->log('Device Updated');

        return response()->json(['message' => 'Device updated.']);
    }

    public function deleteDevice(int $policyId, int $deviceId): JsonResponse
    {
        Policy::findOrFail($policyId);
        $deleted = DB::table('policy_cellphone')->where('id', $deviceId)->where('policy_id', $policyId)->delete();
        if (!$deleted) return response()->json(['error' => 'Device not found.'], 404);

        activity('Policy Device')->performedOn(Policy::find($policyId))->causedBy(auth()->user())->log('Device Deleted');

        return response()->json(['message' => 'Device deleted.']);
    }

    // ── Attachments ───────────────────────────────────────────────────────────

    public function uploadAttachment(Request $request, int $policyId): JsonResponse
    {
        $policy = Policy::findOrFail($policyId);
        // V8 PolicyController::attachmentUpload (line 5947) accepts arrays
        // of name[], type[], and attachment_file[i][] — one upload click
        // can create multiple policy_attachments rows, each row holding a
        // serialised array of S3 paths. Mirror that shape; keep the legacy
        // single-file payload (`file`/`name`/`type`) working for old
        // callers (Wizard, KYC upload page, etc.).
        $request->validate([
            // Multi-row payload (V8 parity)
            'name'             => 'nullable|array',
            'name.*'           => 'nullable|string|max:200',
            'type'             => 'nullable|array',
            'type.*'           => 'nullable|string|max:100',
            'attachment_file'  => 'nullable|array',
            'attachment_file.*'   => 'nullable|array',
            'attachment_file.*.*' => 'file|max:20480',
            // Legacy single-file payload
            'file'             => 'nullable|file|max:20480',
        ]);

        $createdIds = [];

        // Multi-row branch: payload looks like name=['Doc1','Doc2'],
        // type=['Invoice','Documents'], attachment_file=[ [file1,file2], [file3] ].
        if (is_array($request->input('type')) && !empty($request->input('type'))) {
            $names = $request->input('name', []);
            $types = $request->input('type', []);
            $files = $request->file('attachment_file', []);
            foreach ($types as $idx => $rowType) {
                $paths = [];
                $rowFiles = $files[$idx] ?? [];
                if (!is_array($rowFiles)) $rowFiles = [$rowFiles];
                foreach ($rowFiles as $f) {
                    if (!$f) continue;
                    $stored = $this->storeAttachmentFile($f);
                    if ($stored) $paths[] = $stored;
                }
                $createdIds[] = DB::table('policy_attachments')->insertGetId([
                    'policy_id'  => $policyId,
                    'name'       => $names[$idx] ?? null,
                    'type'       => $rowType ?: 'Documents',
                    'attachment' => serialize($paths),
                    'created_at' => now(),
                    'updated_at' => now(),
                ]);
            }
        } else {
            // Legacy single-file branch — keep the original behaviour so
            // wizard/KYC callers don't break.
            if (!$request->hasFile('file')) {
                return response()->json(['error' => 'No file provided.'], 422);
            }
            $file     = $request->file('file');
            $filePath = $this->storeAttachmentFile($file);

            $createdIds[] = DB::table('policy_attachments')->insertGetId([
                'policy_id'  => $policyId,
                'name'       => $request->input('name') ?: $file->getClientOriginalName(),
                'type'       => $request->input('type') ?: 'Documents',
                'attachment' => serialize([$filePath]),
                'created_at' => now(),
                'updated_at' => now(),
            ]);
        }

        activity('Policy Attachment')->performedOn($policy)->causedBy(auth()->user())->log('Attachment Uploaded');

        return response()->json([
            'message' => 'Attachment uploaded.',
            'ids'     => $createdIds,
            // legacy single-id field — callers that read `id` directly keep working.
            'id'      => $createdIds[0] ?? null,
        ], 201);
    }

    /**
     * Push one uploaded file to S3 under the V8 attachment path layout
     * (`MIS/Policy/Attachment/{timestamp}_{slugged_name}`) and return the
     * stored key. Shared by both single-file and multi-row branches.
     */
    private function storeAttachmentFile(\Illuminate\Http\UploadedFile $file): string
    {
        $fileName = time() . '_' . preg_replace('/\s+/', '', $file->getClientOriginalName());
        $filePath = 'MIS/Policy/Attachment/' . $fileName;
        \Illuminate\Support\Facades\Storage::disk('s3')->put($filePath, file_get_contents($file), 'public');
        return $filePath;
    }

    public function deleteAttachment(int $policyId, int $attachId): JsonResponse
    {
        Policy::findOrFail($policyId);
        $deleted = DB::table('policy_attachments')->where('id', $attachId)->where('policy_id', $policyId)->delete();
        if (!$deleted) return response()->json(['error' => 'Attachment not found.'], 404);

        activity('Policy Attachment')->performedOn(Policy::find($policyId))->causedBy(auth()->user())->log('Attachment Deleted');

        return response()->json(['message' => 'Attachment deleted.']);
    }

    // ── Banking ───────────────────────────────────────────────────────────────

    public function updateBanking(Request $request, int $policyId): JsonResponse
    {
        $policy = Policy::findOrFail($policyId);
        $v = $request->validate([
            'bankName'      => 'nullable|string|max:100',
            'branchCode'    => 'nullable|string|max:50',
            'accountNumber' => 'nullable|string|max:50',
            'bankingMethod' => 'nullable|string|max:50',
            'myzaka'        => 'nullable|string|max:20',
            'orangeMoney'   => 'nullable|string|max:20',
            'billing'       => 'nullable|string|max:100',
        ]);

        // `customer_banking` has no `bankingMethod` column — the payment method is
        // stored in `billing`. Strip it out and use it as the billing fallback.
        $bankingMethod = $v['bankingMethod'] ?? null;
        unset($v['bankingMethod']);
        if (($v['billing'] ?? null) === null && $bankingMethod !== null) {
            $v['billing'] = $bankingMethod;
        }

        $existing = DB::table('customer_banking')->where('policy_id', $policyId)->first();
        if ($existing) {
            DB::table('customer_banking')->where('policy_id', $policyId)->update(array_merge($v, ['updated_at' => now()]));
        } else {
            DB::table('customer_banking')->insert(array_merge($v, [
                'policy_id'   => $policyId,
                'customer_id' => $policy->customer_id,
                'created_at'  => now(),
                'updated_at'  => now(),
            ]));
        }

        activity('Policy Banking')->performedOn($policy)->causedBy(auth()->user())->log('Banking Updated');

        // The policy `show()` response (incl. banking.billing, which drives the
        // Add Realpay Contract tab visibility) is cached — without this the
        // saved change wouldn't be visible until the cache TTL expires.
        \AlphaDirect\Services\CacheService::forgetPolicy($policyId);

        return response()->json(['message' => 'Banking details updated.']);
    }

    // ── Banking documents (Bank Statement + Debit Authorization Form) ───────────
    // Stored on customer_banking, anchored on policy_id. Mirrors the KYC doc
    // upload/verify pattern but on the Banking Details tab.
    // Status: 0 = pending (default on upload), 1 = approved, 2 = rejected.
    private const BANKING_DOC_CATALOGUE = [
        'bank_statement_file_path' => ['column' => 'bank_statement_file_path', 'status' => 'bankStatementFileStatus', 'remark' => 'bankStatementFileRemark', 'folder' => 'bank_statement', 'label' => 'Bank Statement'],
        'debit_authorization_form' => ['column' => 'debit_authorization_form', 'status' => 'debitAuthFileStatus',     'remark' => 'debitAuthFileRemark',     'folder' => 'debit_auth',     'label' => 'Debit Authorization Form'],
    ];

    /** CloudFront/S3 URL for a stored banking-doc path (mirrors PolicyController::cdnUrl). */
    private function bankingCdnUrl(?string $path): ?string
    {
        if (empty($path)) return null;
        $path = str_replace(['\/', ' '], ['/', '%20'], $path);
        $cdn = env('AWS_CLOUDFRONT');
        if ($cdn) return rtrim($cdn, '/') . '/' . ltrim($path, '/');
        $bucket = config('filesystems.disks.s3.bucket');
        $region = config('filesystems.disks.s3.region');
        if ($bucket && $region) return "https://{$bucket}.s3.{$region}.amazonaws.com/" . ltrim($path, '/');
        return $path;
    }

    /**
     * GET /policies/{id}/banking-documents
     * Returns the Bank Statement + Debit Authorization docs for this policy's
     * banking row, each with url/status/remark for the Banking Details tab.
     */
    public function bankingDocuments(int $policyId): JsonResponse
    {
        Policy::select('id', 'customer_id')->findOrFail($policyId);
        // DB::table (not the model) — avoids the CustomerBanking date-cast on
        // billingStartDate and matches updateBanking's access pattern. The
        // `?? null` suppresses undefined-property notices when the doc columns
        // don't exist yet (migration not run) or the row is absent.
        $row = DB::table('customer_banking')->where('policy_id', $policyId)->orderBy('id', 'desc')->first();

        $documents = [];
        foreach (self::BANKING_DOC_CATALOGUE as $field => $meta) {
            $path = $row->{$meta['column']} ?? null;
            $documents[] = [
                'field'   => $field,
                'label'   => $meta['label'],
                'hasFile' => !empty($path),
                'url'     => $path ? $this->bankingCdnUrl($path) : null,
                'status'  => (int) ($row->{$meta['status']} ?? 0), // 0=pending,1=approved,2=rejected
                'remark'  => $row->{$meta['remark']} ?? null,
            ];
        }

        return response()->json(['data' => ['documents' => $documents]]);
    }

    /**
     * POST /policies/{id}/banking-documents
     * Multipart upload of Bank Statement / Debit Authorization Form. Each
     * uploaded file lands on S3 and its path + pending status (0) are written
     * to the policy's customer_banking row (created if absent).
     */
    public function uploadBankingDocuments(Request $request, int $policyId): JsonResponse
    {
        // Maker/checker split: uploaders hold -upload; verifiers keep -verify
        // (which still implies upload so approver workflows don't regress).
        $authUser = auth()->user();
        if (!$authUser || !$authUser->hasAnyPermission(['policy-banking-documents-upload', 'policy-banking-documents-verify'])) {
            return response()->json(['message' => 'You do not have permission to upload banking documents.'], 403);
        }

        $policy = Policy::findOrFail($policyId);
        if (!$policy->customer_id) {
            return response()->json(['error' => 'Policy has no customer.'], 422);
        }
        $customerId = $policy->customer_id;
        $userSlug = $authUser->firstName ? preg_replace('/[^A-Za-z0-9_-]/', '', $authUser->firstName) : ('u' . ($authUser->id ?? 0));

        $updates = [];
        $saved = [];
        foreach ($request->allFiles() as $reqKey => $_file) {
            if (!isset(self::BANKING_DOC_CATALOGUE[$reqKey])) continue; // ignore unknown keys
            $meta = self::BANKING_DOC_CATALOGUE[$reqKey];
            $file = $request->file($reqKey);
            $name = preg_replace('/[^A-Za-z0-9._-]/', '_', $file->getClientOriginalName());
            $path = "MIS/{$customerId}/Banking/{$userSlug}/{$meta['folder']}/" . time() . '_' . $name;
            try {
                \Storage::disk('s3')->put($path, file_get_contents($file->getRealPath()), 'public');
            } catch (\Throwable $e) {
                \Log::warning("uploadBankingDocuments: S3 put failed for {$reqKey}: " . $e->getMessage());
                return response()->json(['error' => "Upload failed for {$reqKey}: " . $e->getMessage()], 500);
            }
            $updates[$meta['column']] = $path;
            $updates[$meta['status']] = 0;    // pending review
            $updates[$meta['remark']] = null;
            $saved[$reqKey] = $path;
        }

        if (empty($saved)) {
            return response()->json(['error' => 'No recognised banking files submitted.'], 422);
        }

        // Upsert by policy_id — same pattern as updateBanking (DB::table insert
        // omits billingStartDate, which the existing save path also relies on).
        $existing = DB::table('customer_banking')->where('policy_id', $policyId)->orderBy('id', 'desc')->first();
        if ($existing) {
            DB::table('customer_banking')->where('id', $existing->id)->update(array_merge($updates, ['updated_at' => now()]));
        } else {
            DB::table('customer_banking')->insert(array_merge($updates, [
                'policy_id'   => $policyId,
                'customer_id' => $customerId,
                'created_at'  => now(),
                'updated_at'  => now(),
            ]));
        }

        activity('Policy Banking')->performedOn($policy)->causedBy($authUser)
            ->log('Banking documents uploaded: ' . implode(', ', array_keys($saved)));

        return response()->json(['message' => count($saved) . ' document(s) uploaded.', 'saved' => array_keys($saved)]);
    }

    /**
     * DELETE /policies/{id}/banking-documents/{field}
     * Clears one banking doc (path + status reset to pending, remark cleared).
     */
    public function deleteBankingDocument(int $policyId, string $field): JsonResponse
    {
        // Delete resets the doc to pending — part of the upload/replace
        // workflow, so uploaders may do it too (same gate as upload).
        $authUser = auth()->user();
        if (!$authUser || !$authUser->hasAnyPermission(['policy-banking-documents-upload', 'policy-banking-documents-verify'])) {
            return response()->json(['message' => 'You do not have permission to modify banking documents.'], 403);
        }
        if (!isset(self::BANKING_DOC_CATALOGUE[$field])) {
            return response()->json(['error' => "Unknown banking document field '{$field}'."], 422);
        }
        $meta = self::BANKING_DOC_CATALOGUE[$field];

        $policy = Policy::findOrFail($policyId);
        $existing = DB::table('customer_banking')->where('policy_id', $policyId)->orderBy('id', 'desc')->first();
        if (!$existing || empty($existing->{$meta['column']} ?? null)) {
            return response()->json(['error' => 'Document not found or already cleared.'], 404);
        }
        DB::table('customer_banking')->where('id', $existing->id)->update([
            $meta['column'] => null,
            $meta['status'] => 0,
            $meta['remark'] => null,
            'updated_at'    => now(),
        ]);

        activity('Policy Banking')->performedOn($policy)->causedBy($authUser)
            ->log("Banking document deleted: {$field}");

        return response()->json(['message' => "Document '{$field}' removed.", 'field' => $field]);
    }

    /**
     * POST /policies/{id}/banking-documents/verify
     * Approve / reject a banking doc with an optional remark.
     * status: 0 = pending, 1 = approved, 2 = rejected.
     */
    public function verifyBankingDocument(Request $request, int $policyId): JsonResponse
    {
        $authUser = auth()->user();
        if (!$authUser || !$authUser->hasPermissionTo('policy-banking-documents-verify')) {
            return response()->json(['message' => 'You do not have permission to verify banking documents.'], 403);
        }
        $validated = $request->validate([
            'document' => 'required|string|in:bank_statement_file_path,debit_authorization_form',
            'status'   => 'required|integer|in:0,1,2',
            'remark'   => 'nullable|string|max:500',
        ]);
        $meta = self::BANKING_DOC_CATALOGUE[$validated['document']];

        $policy = Policy::findOrFail($policyId);
        $existing = DB::table('customer_banking')->where('policy_id', $policyId)->orderBy('id', 'desc')->first();
        if (!$existing) {
            return response()->json(['error' => 'No banking record for this policy.'], 404);
        }
        $update = [$meta['status'] => $validated['status'], 'updated_at' => now()];
        if (array_key_exists('remark', $validated)) $update[$meta['remark']] = $validated['remark'];
        DB::table('customer_banking')->where('id', $existing->id)->update($update);

        $statusLabel = match ((int) $validated['status']) { 1 => 'Approved', 2 => 'Rejected', default => 'Reset to Pending' };
        activity('Policy Banking')->performedOn($policy)->causedBy($authUser)
            ->log("Banking document {$meta['label']} {$statusLabel}" . (!empty($validated['remark']) ? ": {$validated['remark']}" : ''));

        return response()->json(['message' => "Document {$statusLabel}.", 'document' => $validated['document']]);
    }

    // ── No Claims Declaration (MIS policies only) ──────────────────────────────
    //
    // A single document per policy, stored as a `policy_attachments` row with
    // type = self::CLAIMS_WAIVER_TYPE — reuses the existing generic
    // attachments table (columns: policy_id, name, type, attachment) rather
    // than adding a new table/migration for one more document. "Replace"
    // is implemented as delete-existing-row-then-insert-new, so at most one
    // row of this type ever exists per policy.
    //
    // APPROVAL (UW, 2026-08-31). Split of duties:
    //   - upload  — Underwriting, via `policy-claims-waiver-upload`. Upload
    //               only: an uploader can never approve their own document,
    //               not even holding the upload permission.
    //   - approve — only a holder of the approver ROLE, checked by
    //               Services\ClaimsWaiverApprovalGate (fail-closed, and with
    //               NO Super Admin / Manager bypass). The role is created once
    //               in /roles and attached to the named approvers there, which
    //               is what makes approval user-wise. Any number of people may
    //               hold it (the old two-person cap was removed 2026-09-07).
    //
    // Approval state lives in `policy_claims_waiver_approvals`, one row per
    // uploaded version, never deleted — see that table's migration for why it
    // is not columns on the shared `policy_attachments` table.
    //
    // A single approver's decision is final; the other holders exist so
    // approval does not stall on one person's absence. Every decision is
    // appended to the approval table, so the full "who approved / rejected,
    // and when" trail survives later decisions and re-uploads. Approval is a
    // recorded sign-off and does NOT gate issue, printing or renewal — no
    // other flow reads this document today.

    /**
     * Discriminator written to `policy_attachments`.`type` and matched in the
     * queries below. Historic value — renaming it to
     * match the new "No Claims Declaration" label would orphan every document
     * already uploaded under the old name, so the stored type stays put and
     * only the user-facing wording changed.
     */
    private const CLAIMS_WAIVER_TYPE = 'Claims Waiver Form';

    /** Approval/audit rows for the declaration. */
    private const CLAIMS_WAIVER_APPROVAL_TABLE = 'policy_claims_waiver_approvals';

    /**
     * GET /policies/{id}/claims-waiver
     * Returns the current No Claims Declaration (if any) for the No Claims
     * Declaration tab, together with its approval state and what the caller
     * is allowed to do with it. Read access follows the same convention as
     * Banking/KYC documents — any authenticated staff member can view; only
     * upload/replace/delete/approve are gated.
     */
    public function claimsWaiver(int $policyId): JsonResponse
    {
        $policy = Policy::findOrFail($policyId);
        $authUser = auth()->user();

        $row = DB::table('policy_attachments')
            ->where('policy_id', $policyId)
            ->where('type', self::CLAIMS_WAIVER_TYPE)
            ->orderByDesc('id')
            ->first();

        // Permission flags are returned even when there is no file yet, so the
        // tab can hide the upload control up front instead of failing on POST.
        $mayUpload  = \AlphaDirect\Services\AuthGate::canPerform($authUser, 'policy-claims-waiver-upload');
        $mayApprove = \AlphaDirect\Services\ClaimsWaiverApprovalGate::userMayApprove($authUser);
        $approvalMeta = [
            'mayUpload'    => $mayUpload,
            'mayApprove'   => $mayApprove,
            'approverRole' => \AlphaDirect\Services\ClaimsWaiverApprovalGate::ROLE,
            'approvers'    => \AlphaDirect\Services\ClaimsWaiverApprovalGate::approvers(),
            // Only shown to people who could act on it — an ordinary viewer
            // cannot create the role, so the notice would be noise.
            'warning'      => ($mayUpload || $mayApprove)
                ? \AlphaDirect\Services\ClaimsWaiverApprovalGate::configWarning()
                : null,
            // Full approve/reject trail. Visible to every viewer, like the
            // rest of the tab — it is a record of who signed off, and hiding
            // it would defeat the point of keeping it.
            'history'      => $this->claimsWaiverHistory($policyId),
            // OTP e-signature support (2026-09-08). The modal shows the masked
            // destination so the agent can confirm it with the customer; the
            // full number never leaves the server.
            'otpSign'      => $this->claimsWaiverOtpMeta($policy),
        ];

        if (!$row) {
            // No current document, but the trail is still shown: a deleted or
            // replaced declaration must not erase who approved what.
            return response()->json(['data' => array_merge([
                'hasFile' => false, 'url' => null, 'name' => null, 'uploadedAt' => null, 'signature' => null,
            ], $this->presentClaimsWaiverApproval(null), $approvalMeta)]);
        }

        $paths = @unserialize($row->attachment ?? '', ['allowed_classes' => false]);
        if (!is_array($paths)) $paths = $row->attachment ? [$row->attachment] : [];
        $path = $paths[0] ?? null;

        return response()->json(['data' => array_merge([
            'hasFile'    => !empty($path),
            'url'        => $path ? $this->bankingCdnUrl($path) : null,
            'name'       => $row->name,
            'uploadedAt' => $row->created_at,
            // Null for a manually uploaded scan; set when this document was
            // generated after OTP verification (method, masked number, time).
            'signature'  => app(\AlphaDirect\Services\NcdOtpSignatureService::class)->signatureForAttachment((int) $row->id),
        ], $this->presentClaimsWaiverApproval($this->currentClaimsWaiverApproval($policyId)), $approvalMeta)]);
    }

    /**
     * POST /policies/{id}/claims-waiver
     * Uploads (or replaces) the No Claims Declaration. Same mime/size standard
     * as the KYC document uploads (image or PDF, max 20MB). Every upload lands
     * as PENDING — replacing an approved document therefore withdraws the
     * approval, so only an approver may do that.
     */
    public function uploadClaimsWaiver(Request $request, int $policyId): JsonResponse
    {
        $authUser = auth()->user();
        // AuthGate::canPerform, not hasPermissionTo: admin-equivalent roles
        // (Super Admin / Manager / Admin) pass by role, and a MISSING
        // `policy-claims-waiver-upload` row denies cleanly instead of throwing
        // Spatie's PermissionDoesNotExist (a 500). The permission was never
        // seeded on prod and /roles has no endpoint to create one, so the bare
        // permission check locked everyone out with no way to grant it.
        if (!\AlphaDirect\Services\AuthGate::canPerform($authUser, 'policy-claims-waiver-upload')) {
            return response()->json(['message' => 'You do not have permission to upload the No Claims Declaration.'], 403);
        }

        $validated = $request->validate([
            'file' => 'required|file|mimes:jpg,jpeg,png,pdf|max:20480',
        ]);

        $policy = Policy::findOrFail($policyId);

        // An approved declaration is a signed-off record. Overwriting it would
        // silently reset it to PENDING, so replacement is the approver's call.
        $current = $this->currentClaimsWaiverApproval($policyId);
        if ($current
            && strtoupper((string) $current->status) === 'APPROVED'
            && !\AlphaDirect\Services\ClaimsWaiverApprovalGate::userMayApprove($authUser)) {
            activity('Policy Claims Waiver')->performedOn($policy)->causedBy($authUser)
                ->withProperties(['file' => $current->file_name ?? null])
                ->log('No Claims Declaration replace blocked (already approved)');
            return response()->json([
                'message' => 'This No Claims Declaration is already approved. Only an approver can replace it.',
            ], 403);
        }

        $file = $validated['file'];
        $name = preg_replace('/[^A-Za-z0-9._-]/', '_', $file->getClientOriginalName());
        $path = "MIS/Policy/ClaimsWaiver/{$policyId}/" . time() . '_' . $name;
        try {
            \Storage::disk('s3')->put($path, file_get_contents($file->getRealPath()), 'public');
        } catch (\Throwable $e) {
            \Log::warning("uploadClaimsWaiver: S3 put failed: " . $e->getMessage());
            return response()->json(['error' => 'Upload failed: ' . $e->getMessage()], 500);
        }

        // Replace-in-place: at most one No Claims Declaration row per policy.
        DB::table('policy_attachments')
            ->where('policy_id', $policyId)
            ->where('type', self::CLAIMS_WAIVER_TYPE)
            ->delete();
        $attachmentId = DB::table('policy_attachments')->insertGetId([
            'policy_id'  => $policyId,
            'name'       => $file->getClientOriginalName(),
            'type'       => self::CLAIMS_WAIVER_TYPE,
            'attachment' => serialize([$path]),
            'created_at' => now(),
            'updated_at' => now(),
        ]);

        // A fresh PENDING row per upload. Earlier rows stay on file: they are
        // the record of what was approved before this version replaced it.
        $this->recordClaimsWaiverUpload($policyId, (int) $attachmentId, $file->getClientOriginalName());

        // Activity-log category ('Policy Claims Waiver') is left alone — it is
        // a filterable key over existing history rows, not display text.
        // `replaced_status` says what this upload superseded, so a document
        // that quietly displaced an approved one is visible in the history.
        activity('Policy Claims Waiver')->performedOn($policy)->causedBy($authUser)
            ->withProperties([
                'attachment_id'   => (int) $attachmentId,
                'file'            => $file->getClientOriginalName(),
                'status'          => 'PENDING',
                'replaced_status' => $current ? strtoupper((string) $current->status) : null,
            ])
            ->log($current ? 'No Claims Declaration replaced (pending approval)' : 'No Claims Declaration uploaded (pending approval)');

        return response()->json([
            'message' => 'No Claims Declaration uploaded. It is pending approval.',
            'data'    => $this->presentClaimsWaiverApproval($this->currentClaimsWaiverApproval($policyId)),
        ]);
    }

    /**
     * POST /policies/{id}/claims-waiver/approve
     *
     * The approver's decision. `reject=1` (with an optional `reason`) records a
     * rejection instead. Either way the decision is APPENDED to the approval
     * table — nothing is overwritten, so every approval and rejection stays on
     * the trail — and Underwriting can re-upload afterwards, which starts a
     * new PENDING row.
     */
    public function approveClaimsWaiver(Request $request, int $policyId): JsonResponse
    {
        $authUser = auth()->user();
        $policy = Policy::findOrFail($policyId);

        // The one control. Deliberately NOT AuthGate::canPerform — an
        // admin-equivalent role must not be able to sign this off; only a
        // holder of the approver role may.
        if (!\AlphaDirect\Services\ClaimsWaiverApprovalGate::userMayApprove($authUser)) {
            return response()->json([
                'message' => 'The No Claims Declaration may only be approved by an assigned approver ("'
                    . \AlphaDirect\Services\ClaimsWaiverApprovalGate::ROLE . '").',
            ], 403);
        }

        if (!\Schema::hasTable(self::CLAIMS_WAIVER_APPROVAL_TABLE)) {
            return response()->json(['error' => 'Approval storage is missing. Ask an admin to run: php artisan migrate'], 500);
        }

        $attachment = DB::table('policy_attachments')
            ->where('policy_id', $policyId)
            ->where('type', self::CLAIMS_WAIVER_TYPE)
            ->orderByDesc('id')
            ->first();
        if (!$attachment) {
            return response()->json(['error' => 'No Claims Declaration not found. Nothing to approve.'], 404);
        }

        $validated = $request->validate([
            'reject' => 'nullable',
            'reason' => 'nullable|string|max:1000',
        ]);
        $reject = filter_var($validated['reject'] ?? false, FILTER_VALIDATE_BOOLEAN);
        $reason = trim((string) ($validated['reason'] ?? ''));

        // Documents uploaded before approval existed have no row yet; open one
        // so the decision has something to stamp.
        $current = $this->currentClaimsWaiverApproval($policyId);
        if (!$current || (int) ($current->attachment_id ?? 0) !== (int) $attachment->id) {
            $this->recordClaimsWaiverUpload($policyId, (int) $attachment->id, $attachment->name);
            $current = $this->currentClaimsWaiverApproval($policyId);
        }
        if (!$current) {
            return response()->json(['error' => 'Could not record the approval. Please try again.'], 500);
        }

        // APPEND the decision as its own row rather than stamping the PENDING
        // one in place. Overwriting lost the previous decision, so a document
        // that was approved, re-opened and then rejected only ever showed the
        // last name — "who approved / rejected, and when" has to stay
        // answerable for every decision, not just the newest. `uploaded_by`
        // is carried forward so the row still says whose upload was decided.
        DB::table(self::CLAIMS_WAIVER_APPROVAL_TABLE)->insert([
            'policy_id'        => $policyId,
            'attachment_id'    => (int) $attachment->id,
            'file_name'        => $current->file_name ?: $attachment->name,
            'status'           => $reject ? 'REJECTED' : 'APPROVED',
            'uploaded_by'      => $current->uploaded_by ?? null,
            'approved_by'      => $authUser->id ?? null,
            'approved_at'      => now(),
            'rejection_reason' => $reject ? ($reason ?: null) : null,
            'created_at'       => now(),
            'updated_at'       => now(),
        ]);

        activity('Policy Claims Waiver')->performedOn($policy)->causedBy($authUser)
            ->withProperties(['attachment_id' => (int) $attachment->id, 'file' => $attachment->name, 'reason' => $reason ?: null])
            ->log($reject ? 'No Claims Declaration rejected' : 'No Claims Declaration approved');

        return response()->json([
            'message' => $reject ? 'No Claims Declaration rejected.' : 'No Claims Declaration approved.',
            'data'    => $this->presentClaimsWaiverApproval($this->currentClaimsWaiverApproval($policyId)),
        ]);
    }

    /**
     * DELETE /policies/{id}/claims-waiver
     *
     * Underwriting may withdraw its own upload while it is still PENDING or
     * REJECTED. Removing an APPROVED declaration destroys a signed-off record,
     * so that is an approver's call.
     */
    public function deleteClaimsWaiver(int $policyId): JsonResponse
    {
        $authUser = auth()->user();
        $mayApprove = \AlphaDirect\Services\ClaimsWaiverApprovalGate::userMayApprove($authUser);

        if (!$mayApprove && !\AlphaDirect\Services\AuthGate::canPerform($authUser, 'policy-claims-waiver-upload')) {
            return response()->json(['message' => 'You do not have permission to delete the No Claims Declaration.'], 403);
        }

        $policy = Policy::findOrFail($policyId);

        $current = $this->currentClaimsWaiverApproval($policyId);
        if ($current && strtoupper((string) $current->status) === 'APPROVED' && !$mayApprove) {
            activity('Policy Claims Waiver')->performedOn($policy)->causedBy($authUser)
                ->withProperties(['file' => $current->file_name ?? null])
                ->log('No Claims Declaration delete blocked (approved)');
            return response()->json([
                'message' => 'This No Claims Declaration is approved. Only an approver can delete it.',
            ], 403);
        }

        $deleted = DB::table('policy_attachments')
            ->where('policy_id', $policyId)
            ->where('type', self::CLAIMS_WAIVER_TYPE)
            ->delete();

        if (!$deleted) {
            return response()->json(['error' => 'No Claims Declaration not found.'], 404);
        }

        activity('Policy Claims Waiver')->performedOn($policy)->causedBy($authUser)
            ->withProperties([
                'file'   => $current->file_name ?? null,
                'status' => $current ? strtoupper((string) $current->status) : null,
            ])
            ->log('No Claims Declaration deleted');

        return response()->json(['message' => 'No Claims Declaration deleted.']);

    }

    /**
     * Newest approval row for a policy's declaration, or null. Returns null
     * (never throws) on an environment where the table is not migrated yet, so
     * the tab keeps working as a plain document store there.
     */
    private function currentClaimsWaiverApproval(int $policyId)
    {
        try {
            if (!\Schema::hasTable(self::CLAIMS_WAIVER_APPROVAL_TABLE)) {
                return null;
            }

            return DB::table(self::CLAIMS_WAIVER_APPROVAL_TABLE)
                ->where('policy_id', $policyId)
                ->orderByDesc('id')
                ->first();
        } catch (\Throwable $e) {
            \Log::warning('claimsWaiver: approval lookup failed: ' . $e->getMessage());
            return null;
        }
    }

    /**
     * The full approval trail for a policy's declaration — every upload and
     * every decision, newest first, with the acting user's name resolved.
     *
     * Rows survive the document they describe (see the table's migration), so
     * the trail still reads correctly after a declaration is replaced or
     * deleted. Never throws: an un-migrated environment simply has no trail.
     *
     * @return array<int,array<string,mixed>>
     */
    private function claimsWaiverHistory(int $policyId): array
    {
        try {
            if (!\Schema::hasTable(self::CLAIMS_WAIVER_APPROVAL_TABLE)) {
                return [];
            }

            $rows = DB::table(self::CLAIMS_WAIVER_APPROVAL_TABLE)
                ->where('policy_id', $policyId)
                ->orderByDesc('id')
                ->limit(50)
                ->get();
            if ($rows->isEmpty()) {
                return [];
            }

            // One name lookup for the whole trail rather than per row.
            $names = \AlphaDirect\Services\ClaimsWaiverApprovalGate::userNames(
                $rows->flatMap(fn ($r) => [$r->uploaded_by ?? null, $r->approved_by ?? null])->all()
            );

            return $rows->map(function ($r) use ($names) {
                $status = strtoupper((string) ($r->status ?: 'PENDING'));
                // A PENDING row IS the upload event; a decided row names the
                // approver who decided it.
                $decided = $status === 'APPROVED' || $status === 'REJECTED';
                $actorId = (int) (($decided ? $r->approved_by : $r->uploaded_by) ?? 0);

                return [
                    'id'       => (int) $r->id,
                    'action'   => $decided ? $status : 'UPLOADED',
                    'status'   => $status,
                    'fileName' => $r->file_name,
                    'byId'     => $actorId ?: null,
                    'byName'   => $names[$actorId] ?? null,
                    'at'       => $decided ? ($r->approved_at ?: $r->created_at) : $r->created_at,
                    'reason'   => $r->rejection_reason,
                ];
            })->values()->all();
        } catch (\Throwable $e) {
            \Log::warning('claimsWaiver: history lookup failed: ' . $e->getMessage());
            return [];
        }
    }

    /**
     * Open a PENDING approval row for a newly uploaded declaration. Never
     * fatal: on an un-migrated environment the upload itself must still
     * succeed, it simply carries no approval state.
     */
    private function recordClaimsWaiverUpload(int $policyId, int $attachmentId, ?string $fileName, ?int $uploadedBy = null): void
    {
        try {
            if (!\Schema::hasTable(self::CLAIMS_WAIVER_APPROVAL_TABLE)) {
                return;
            }

            DB::table(self::CLAIMS_WAIVER_APPROVAL_TABLE)->insert([
                'policy_id'     => $policyId,
                'attachment_id' => $attachmentId,
                'file_name'     => $fileName,
                'status'        => 'PENDING',
                'uploaded_by'   => $uploadedBy ?: (auth()->id() ?: null),
                'created_at'    => now(),
                'updated_at'    => now(),
            ]);
        } catch (\Throwable $e) {
            \Log::warning('claimsWaiver: could not open approval row: ' . $e->getMessage());
        }
    }

    /**
     * Shape the approval half of the tab payload. A declaration that exists
     * with no row (uploaded before approval was introduced, or an un-migrated
     * environment) reads as PENDING — never as approved.
     *
     * @return array<string,mixed>
     */
    private function presentClaimsWaiverApproval($row): array
    {
        if (!$row) {
            return [
                'status'          => 'PENDING',
                'uploadedBy'      => null,
                'uploadedByName'  => null,
                'approvedBy'      => null,
                'approvedByName'  => null,
                'approvedAt'      => null,
                'rejectionReason' => null,
            ];
        }

        // Column-safe name lookup: `users` here has firstName/lastName, not
        // the Laravel default `name`, so a bare pluck('name') renders blank.
        $names = \AlphaDirect\Services\ClaimsWaiverApprovalGate::userNames([
            $row->uploaded_by ?? null,
            $row->approved_by ?? null,
        ]);

        return [
            'status'          => strtoupper((string) ($row->status ?: 'PENDING')),
            'uploadedBy'      => $row->uploaded_by ? (int) $row->uploaded_by : null,
            'uploadedByName'  => $names[(int) ($row->uploaded_by ?? 0)] ?? null,
            'approvedBy'      => $row->approved_by ? (int) $row->approved_by : null,
            'approvedByName'  => $names[(int) ($row->approved_by ?? 0)] ?? null,
            'approvedAt'      => $row->approved_at,
            'rejectionReason' => $row->rejection_reason,
        ];
    }

    // ─── No Claims Declaration: OTP e-signature ───────────────────────────
    //
    // EXCO brief (2026-09-08): the manual print → sign → scan → upload loop
    // was killing productivity. A "Generate No Claims Declaration" button now
    // SMSes an OTP to the customer's REGISTERED number (the SMS states that
    // sharing the code with the agent is consent to sign). Once the agent
    // keys the code in and it verifies, a PDF is rendered that states it was
    // signed via OTP with the cellphone number and timestamp, and it takes
    // the place of the uploaded scan in the same approval flow.
    //
    // The manual upload path is untouched — both routes remain available.

    /**
     * POST /policies/{id}/claims-waiver/otp/send
     * Issues and SMSes the OTP. Same permission as uploading the form.
     */
    public function sendClaimsWaiverOtp(Request $request, int $policyId): JsonResponse
    {
        $authUser = auth()->user();
        if (!\AlphaDirect\Services\AuthGate::canPerform($authUser, 'policy-claims-waiver-upload')) {
            return response()->json(['message' => 'You do not have permission to generate the No Claims Declaration.'], 403);
        }
        if (!\Schema::hasTable(\AlphaDirect\Services\NcdOtpSignatureService::TABLE)) {
            return response()->json(['message' => 'OTP signing is not set up on this environment yet (table not migrated).'], 503);
        }

        $policy = Policy::findOrFail($policyId);

        // Replacing an approved declaration is the approver's call — same rule
        // as a manual re-upload, enforced before an SMS is sent.
        $current = $this->currentClaimsWaiverApproval($policyId);
        if ($current
            && strtoupper((string) $current->status) === 'APPROVED'
            && !\AlphaDirect\Services\ClaimsWaiverApprovalGate::userMayApprove($authUser)) {
            return response()->json([
                'message' => 'This No Claims Declaration is already approved. Only an approver can replace it.',
            ], 403);
        }

        $result = app(\AlphaDirect\Services\NcdOtpSignatureService::class)
            ->send($policy, $authUser ? (int) $authUser->id : null, $request->ip());

        activity('Policy Claims Waiver')->performedOn($policy)->causedBy($authUser)
            ->withProperties([
                'result'    => $result['ok'] ? 'sent' : ($result['error'] ?? 'failed'),
                'cellphone' => $result['cellphoneMasked'] ?? null,
            ])
            ->log($result['ok'] ? 'No Claims Declaration OTP sent to customer' : 'No Claims Declaration OTP send failed');

        if (!$result['ok']) {
            $status = ($result['error'] ?? '') === 'cooldown' ? 429 : 422;
            return response()->json(['message' => $result['message'], 'error' => $result['error'], 'wait_s' => $result['wait_s'] ?? null], $status);
        }

        return response()->json([
            'message' => 'OTP sent to the customer\'s registered cellphone.',
            'data'    => [
                'cellphoneMasked' => $result['cellphoneMasked'],
                'expiresAt'       => $result['expiresAt'],
                'validitySeconds' => $result['validitySeconds'],
            ],
        ]);
    }

    /**
     * POST /policies/{id}/claims-waiver/otp/verify  { code }
     * Verifies the code, renders the signed PDF, files it as the current
     * declaration (PENDING approval, like an upload) and records the evidence.
     */
    public function verifyClaimsWaiverOtp(Request $request, int $policyId): JsonResponse
    {
        $authUser = auth()->user();
        if (!\AlphaDirect\Services\AuthGate::canPerform($authUser, 'policy-claims-waiver-upload')) {
            return response()->json(['message' => 'You do not have permission to generate the No Claims Declaration.'], 403);
        }
        if (!\Schema::hasTable(\AlphaDirect\Services\NcdOtpSignatureService::TABLE)) {
            return response()->json(['message' => 'OTP signing is not set up on this environment yet (table not migrated).'], 503);
        }

        $validated = $request->validate([
            'code' => 'required|digits:6',
        ]);

        $policy = Policy::findOrFail($policyId);

        $current = $this->currentClaimsWaiverApproval($policyId);
        if ($current
            && strtoupper((string) $current->status) === 'APPROVED'
            && !\AlphaDirect\Services\ClaimsWaiverApprovalGate::userMayApprove($authUser)) {
            return response()->json([
                'message' => 'This No Claims Declaration is already approved. Only an approver can replace it.',
            ], 403);
        }

        /** @var \AlphaDirect\Services\NcdOtpSignatureService $otp */
        $otp = app(\AlphaDirect\Services\NcdOtpSignatureService::class);
        $result = $otp->verify($policy, $validated['code']);

        if (!$result['ok']) {
            activity('Policy Claims Waiver')->performedOn($policy)->causedBy($authUser)
                ->withProperties(['result' => $result['error'], 'attempts_left' => $result['attempts_left'] ?? null])
                ->log('No Claims Declaration OTP verification failed');
            $status = in_array($result['error'], ['invalid', 'expired', 'no_active_otp', 'locked'], true) ? 422 : 400;
            return response()->json(['message' => $result['message'], 'error' => $result['error'], 'attempts_left' => $result['attempts_left'] ?? null], $status);
        }

        $sig = $result['row'];
        $signedAt = Carbon::parse($sig->signed_at)->setTimezone(config('app.timezone'));
        $customer = $policy->customer;
        $customerName = trim(preg_replace('/\s+/', ' ', ($customer->firstName ?? '') . ' ' . ($customer->lastName ?? ''))) ?: 'Policyholder';
        $vehicle = $policy->vehicle;
        $vehicleText = $vehicle
            ? trim(implode(' ', array_filter([$vehicle->year ?? null, $vehicle->make ?? null, $vehicle->model ?? null])) . ($vehicle->vehiclePlate ? " ({$vehicle->vehiclePlate})" : ''))
            : null;

        $fileName = 'No_Claims_Declaration_' . preg_replace('/[^A-Za-z0-9_-]/', '_', (string) $policy->policyNumber) . '_OTP_' . $signedAt->format('Ymd_His') . '.pdf';
        $path = "MIS/Policy/ClaimsWaiver/{$policyId}/" . time() . '_' . $fileName;

        // Render, then write to S3 EXPLICITLY with a public ACL — the same disk
        // and visibility as the manual upload and every other generated policy
        // PDF here. StorageService::putWithFallback was tried first and, on an
        // APP_ENV=local box, it prefers the local `public` disk; the CloudFront
        // URL the tab builds then pointed at an object that was never on S3
        // (403 AccessDenied on first staging test, 2026-09-08).
        try {
            $binary = app(\AlphaDirect\Services\PdfGeneratorService::class)->fromView(
                'v2.livewire.pdf.no-claims-declaration',
                [
                    'policyNumber'       => $policy->policyNumber,
                    'customerName'       => $customerName,
                    'productName'        => $policy->product->name ?? '',
                    'vehicle'            => $vehicleText,
                    'cellphoneDisplay'   => '+' . $sig->cellphone,
                    'signedAtDisplay'    => $signedAt->format('d M Y H:i:s'),
                    'timezone'           => config('app.timezone'),
                    'signatureId'        => (int) $sig->id,
                    'agentName'          => $authUser ? trim(($authUser->firstName ?? '') . ' ' . ($authUser->lastName ?? '')) : null,
                    'claimFreeYears'     => 1,
                    'generatedAtDisplay' => now()->format('d M Y H:i:s'),
                ]
            );
        } catch (\Throwable $e) {
            \Log::error('verifyClaimsWaiverOtp: PDF render failed', ['policy_id' => $policyId, 'error' => $e->getMessage()]);
            $otp->releaseAfterStorageFailure((int) $sig->id);
            return response()->json(['message' => 'OTP verified, but the declaration PDF could not be generated. Enter the same code again to retry.'], 500);
        }
        try {
            $ok = \Storage::disk('s3')->put($path, $binary, 'public');
            if ($ok === false) {
                throw new \RuntimeException('S3 put returned false');
            }
        } catch (\Throwable $e) {
            \Log::error('verifyClaimsWaiverOtp: S3 put failed', ['policy_id' => $policyId, 'path' => $path, 'error' => $e->getMessage()]);
            $otp->releaseAfterStorageFailure((int) $sig->id);
            return response()->json(['message' => 'OTP verified, but the declaration PDF could not be stored (document storage is unavailable). Enter the same code again to retry, or contact IT.'], 500);
        }

        // Replace-in-place, exactly as a manual upload does.
        DB::table('policy_attachments')
            ->where('policy_id', $policyId)
            ->where('type', self::CLAIMS_WAIVER_TYPE)
            ->delete();
        $attachmentId = DB::table('policy_attachments')->insertGetId([
            'policy_id'  => $policyId,
            'name'       => $fileName,
            'type'       => self::CLAIMS_WAIVER_TYPE,
            'attachment' => serialize([$path]),
            'created_at' => now(),
            'updated_at' => now(),
        ]);
        $otp->markDocumentGenerated((int) $sig->id, (int) $attachmentId, $path);
        $this->recordClaimsWaiverUpload($policyId, (int) $attachmentId, $fileName);

        activity('Policy Claims Waiver')->performedOn($policy)->causedBy($authUser)
            ->withProperties([
                'attachment_id'   => (int) $attachmentId,
                'file'            => $fileName,
                'status'          => 'PENDING',
                'signature'       => 'OTP',
                'cellphone'       => \AlphaDirect\Services\NcdOtpSignatureService::maskCellphone($sig->cellphone),
                'signed_at'       => $signedAt->toIso8601String(),
                'replaced_status' => $current ? strtoupper((string) $current->status) : null,
            ])
            ->log('No Claims Declaration signed via OTP (pending approval)');

        return response()->json([
            'message' => 'Declaration signed via OTP and generated. It is pending approval.',
            'data'    => array_merge(
                ['url' => $this->bankingCdnUrl($path), 'name' => $fileName],
                $this->presentClaimsWaiverApproval($this->currentClaimsWaiverApproval($policyId))
            ),
        ]);
    }

    /**
     * What the OTP-sign modal needs up front: whether the feature is live and
     * where the code would go (masked). Never throws.
     */
    private function claimsWaiverOtpMeta(Policy $policy): array
    {
        try {
            $svc = app(\AlphaDirect\Services\NcdOtpSignatureService::class);
            $cell = $svc->normaliseCellphone((string) ($policy->customer->cellphone ?? ''));
            return [
                'available'       => \Schema::hasTable(\AlphaDirect\Services\NcdOtpSignatureService::TABLE),
                'hasCellphone'    => $cell !== null,
                'cellphoneMasked' => $cell ? \AlphaDirect\Services\NcdOtpSignatureService::maskCellphone($cell) : null,
                'validitySeconds' => \AlphaDirect\Services\NcdOtpSignatureService::VALIDITY_SECONDS,
                'cooldownSeconds' => \AlphaDirect\Services\NcdOtpSignatureService::RESEND_COOLDOWN_SEC,
            ];
        } catch (\Throwable $e) {
            return ['available' => false, 'hasCellphone' => false, 'cellphoneMasked' => null,
                'validitySeconds' => 300, 'cooldownSeconds' => 60];
        }
    }

    /**
     * Get extensions for a policy's coverages.
     */
    public function getExtensions(int $policyId): JsonResponse
    {
        $coverageIds = DB::table('policy_coverages')
            ->where('policy_id', $policyId)
            ->whereNull('deleted_at')
            ->pluck('id');

        $extensions = DB::table('policy_extention_detail')
            ->whereIn('policy_coverage_id', $coverageIds)
            ->whereNull('deleted_at')
            ->orderBy('n_DisplaySequence')
            ->get()
            ->map(fn($e) => [
                'id' => $e->id,
                'policyCoverageId' => $e->policy_coverage_id,
                'type' => $e->type,
                'extensionType' => $e->extention_type,
                'coverageName' => $e->s_CoverageName,
                'coverageCode' => $e->s_CoverageCode,
                'screenName' => $e->s_ScreenName,
                'groupName' => $e->s_ExtensionsGroupName,
                'coverageValue' => $e->extention_coverage_value,
                'sumInsured' => $e->extention_sum_insured,
                'rate' => $e->extention_rate,
                'calculatedValue' => $e->extention_calculated_value,
                'proRatePremium' => $e->pro_rate_premium,
                'discountSurcharge' => $e->extention_discount_surcharge,
                'discountSurchargeValue' => $e->extention_discount_surcharge_value,
            ]);

        return response()->json(['data' => $extensions]);
    }

    /**
     * Stream the static MIS Customer Complaints Procedure PDF.
     */
    public function downloadComplaintProcedure(int $policyId)
    {
        $path = storage_path('app/CoverageWiseMultimark/Customer_Complaints_Procedure_July_2023.pdf');
        if (!is_file($path)) {
            return response()->json(['error' => 'Complaint procedure document not found on server.'], 404);
        }
        return response()->file($path, [
            'Content-Type'        => 'application/pdf',
            'Content-Disposition' => 'inline; filename="Customer_Complaints_Procedure.pdf"',
        ]);
    }

    /**
     * Stream the static Policy Wording PDF appropriate to the MIS product type.
     * Products 3 (Motor Comp) and 2 (Third Party) → Motor_Section.pdf
     * Product 1 (P1 Million AD) → PERSONALACCIDENT.pdf
     * Product 9 (Hospital Cashback) → Stated_Benefits_Section.pdf
     * Fallback: General_Exceptions_Conditions_Provision.pdf
     */
    public function downloadPolicyWording(int $policyId)
    {
        $policy = Policy::findOrFail($policyId);
        $base = storage_path('app/CoverageWiseMultimark');
        $map = [
            1  => 'PERSONALACCIDENT.pdf',
            2  => 'Motor_Section.pdf',
            3  => 'Motor_Section.pdf',
            4  => 'General_Exceptions_Conditions_Provision.pdf',
            5  => 'General_Exceptions_Conditions_Provision.pdf',
            6  => 'General_Exceptions_Conditions_Provision.pdf',
            9  => 'Stated_Benefits_Section.pdf',
            12 => 'Stated_Benefits_Section.pdf',
            13 => 'Stated_Benefits_Section.pdf',
        ];
        $file = $map[(int) $policy->product_id] ?? 'General_Exceptions_Conditions_Provision.pdf';
        $path = $base . '/' . $file;
        if (!is_file($path)) {
            return response()->json(['error' => 'Policy wording not found for this product.'], 404);
        }
        return response()->file($path, [
            'Content-Type'        => 'application/pdf',
            'Content-Disposition' => 'inline; filename="Policy_Wording_' . $policy->policyNumber . '.pdf"',
        ]);
    }

    /**
     * Generate and stream a policy Account Statement PDF.
     * Mirrors DocumentController::accountStatement / accountStatementDomCom.
     */
    public function generateAccountStatementPdf(int $policyId, Request $request)
    {
        try {
            $policy = Policy::with('product')->findOrFail($policyId);
            // All DomCom products use the expanded DomCom account statement (not just 7,8)
            $isDomCom = in_array($policy->product_id, [7, 8, 16, 17, 18, 19, 20, 21, 22, 23]);

            // Mirrors legacy DocumentController::accountStatementDomCom — strip
            // reversed/refunded/test payments before rendering. Otherwise the
            // statement double-counts a payment alongside its refund/reversal.
            // status casing isn't consistent across gateways ('SUCCESS' vs
            // 'Success' vs legacy 'S') — see AccountStatementService::SUCCESS_STATUSES,
            // which this query mirrors so the PDF and the on-screen ledger
            // never disagree on which payments are valid.
            // CompanyRef only means "reversed" when it's literally 'Reversed' —
            // it's otherwise an overloaded gateway-reference field (DPO's
            // TransactionBookRef, Ngenius's reference, or just the policy's own
            // number on plenty of real rows). whereNull() wrongly dropped any
            // payment where the gateway populated it at all. Both sets now come
            // straight from AccountStatementService so this endpoint and the
            // on-screen ledger cannot drift apart on the definitions.
            $validPayments = \AlphaDirect\Services\AccountStatementService::validPaymentRefs($policyId);

            // MIS ONLY: refunds are filtered by EXCLUSION, not inclusion — a
            // refund with an empty or operational trans_ref
            // ('REFUND-BACKLOG-2026') is a real accounting entry and used to be
            // dropped from this PDF while still showing in the Account View tab.
            // DomCom keeps the original inclusion test on purpose: scoping the
            // fix to the MIS family keeps the Total Dues shift off the DomCom
            // book. See AccountStatementService::refundExcludedRefs().
            $refundExcludedRefs = $isDomCom
                ? []
                : \AlphaDirect\Services\AccountStatementService::refundExcludedRefs($policyId, $validPayments);

            // Match AccountStatementService::rows() so the PDF and on-screen ledger
            // agree. Both statement blades now raise the balance from a refund's
            // OWN debit, so the original Payment must always stay in the set —
            // excluding it as well would drop the payment credit AND add the
            // refund debit, moving the balance by 2× for a same-ref refund.
            $refundedTransRefs = [];

            $reversedRefs = DB::table('payment_transactions')
                ->where('policy_id', $policyId)
                ->where(function ($q) {
                    $q->where('status', 'Reversed')->orWhereNotNull('reveral_transaction_id');
                })
                ->pluck('referenceNumber')->all();

            $reversalTransRefs = DB::table('payment_transactions')
                ->where('policy_id', $policyId)
                ->whereNotNull('reveral_transaction_id')
                ->pluck('reveral_transaction_id')->all();

            $allExcludedRefs = array_unique(array_merge($reversedRefs, $reversalTransRefs, $refundedTransRefs));

            // A credit note whose invoice was discarded is not part of the
            // statement — see AccountStatementService::orphanCreditNoteRefs().
            $orphanCreditNotes = \AlphaDirect\Services\AccountStatementService::orphanCreditNoteRefs($policyId);

            $q = DB::table('policy_ledger')->where('policy_id', $policyId)
                ->whereIn('trans_type', \AlphaDirect\Services\AccountStatementService::STATEMENT_TRANS_TYPES)
                ->whereNull('deleted_at')
                // status='Reversed' excluded for every type — see
                // AccountStatementService::rows(), which this query mirrors.
                ->where(function ($w) {
                    $w->whereNull('status')->orWhere('status', '!=', 'Reversed');
                })
                ->where(function ($outer) use ($validPayments, $allExcludedRefs, $refundExcludedRefs, $isDomCom) {
                    $outer->whereIn('trans_type', array_merge(\AlphaDirect\Services\AccountStatementService::INVOICE_TRANS_TYPES, ['Credit Note']))
                        ->orWhere(function ($q) use ($validPayments, $allExcludedRefs) {
                            $q->where('trans_type', 'Payment')
                              ->whereIn('trans_ref', $validPayments)
                              ->where('status', '!=', 'Reversed')
                              ->whereNotIn('trans_ref', $allExcludedRefs);
                        })
                        ->orWhere(function ($q) use ($validPayments, $refundExcludedRefs, $isDomCom) {
                            $q->where('trans_type', 'Refund');

                            if ($isDomCom) {
                                $q->whereIn('trans_ref', $validPayments);
                                return;
                            }

                            // MIS: NULL/'' must be spelled out — SQL's
                            // `NULL NOT IN (…)` is NULL (false), which is how
                            // un-referenced refunds went missing from the export.
                            $q->where(function ($w) use ($refundExcludedRefs) {
                                $w->whereNull('trans_ref')
                                  ->orWhere('trans_ref', '')
                                  ->orWhereNotIn('trans_ref', $refundExcludedRefs);
                            });
                        })
                        // See AccountStatementService::rows() — a Reverse
                        // Payment needs its own branch or it is filtered out.
                        ->orWhere('trans_type', 'Reverse Payment');
                });
            // NULL spelled out: `NULL NOT IN (...)` is NULL in SQL, which would
            // drop every row that carries no reference.
            if (!empty($orphanCreditNotes)) {
                $q->where(function ($w) use ($orphanCreditNotes) {
                    $w->where('trans_type', '!=', 'Credit Note')
                      ->orWhereNull('trans_ref')
                      ->orWhereNotIn('trans_ref', $orphanCreditNotes);
                });
            }
            if ($actionId = $request->query('action_id')) {
                $q->where('action_id', $actionId);
            }
            $ledger = $q->orderBy('accounting_date', 'asc')->get();

            // The archive is optional — some envs have no archive connection.
            // It lives on a SEPARATE database (graphite_archive.policy_ledger),
            // NOT as a 'policy_ledger_archive' table on this connection; the old
            // Schema::hasTable guard was therefore false everywhere and this
            // whole branch never ran. See AccountStatementService::archiveQuery().
            $archive = collect();
            if ($archiveQ = \AlphaDirect\Services\AccountStatementService::archiveQuery()) {
                try {
                    $archive = $archiveQ->where('policy_id', $policyId)
                        ->where(function ($outer) use ($allExcludedRefs) {
                            $outer->whereNotNull('invoice_file')
                                ->orWhere('trans_type', 'Refund')
                                ->orWhere(function ($q) use ($allExcludedRefs) {
                                    $q->whereNotNull('credit')
                                      ->where(function ($inner) use ($allExcludedRefs) {
                                          $inner->where('trans_type', '!=', 'Payment')
                                                ->orWhereNotIn('trans_ref', $allExcludedRefs);
                                      });
                                });
                        })
                        ->when(!empty($orphanCreditNotes), fn($qq) => $qq->where(function ($w) use ($orphanCreditNotes) {
                            $w->where('trans_type', '!=', 'Credit Note')
                              ->orWhereNull('trans_ref')
                              ->orWhereNotIn('trans_ref', $orphanCreditNotes);
                        }))
                        ->orderBy('id', 'asc')->orderBy('accounting_date', 'asc')->get();
                } catch (\Throwable $e) {
                    \Log::warning('archived ledger read failed: ' . $e->getMessage());
                }
            }

            // Sort: invoices by invoice_date (falling back to accounting_date),
            // everything else by accounting_date — matches legacy ordering.
            // Same deterministic key as AccountStatementService::rows():
            // COALESCE(invoice_date, accounting_date, system_date), then id.
            $merged = $archive->merge($ledger)->sortBy(fn($r) => sprintf(
                '%011d|%011d',
                (int) strtotime(\AlphaDirect\Services\AccountStatementService::rowSortDate($r)),
                (int) ($r->id ?? 0)
            ));
            $data = $merged->values()->all();

            $customer = \AlphaDirect\Customer::find($policy->customer_id);
            $customerProfile = \AlphaDirect\CustomerProfile::where('customer_id', $policy->customer_id)->first();
            $company = ($customerProfile && $customerProfile->company_id)
                ? Company::find($customerProfile->company_id)
                : null;

            // Balance — last invoice row wins (legacy parity); fall back to 0.
            $balance = DB::table('policy_ledger')->where('policy_id', $policyId)
                ->where('trans_type', 'Invoice')
                ->whereNull('deleted_at')
                ->orderBy('system_date', 'desc')
                ->value('balance') ?? 0;

            // Opening Balance = the running balance of every included row dated
            // BEFORE the statement's start date. This endpoint renders the full
            // history of the policy, so nothing precedes the period and the
            // opening balance is 0.00.
            //
            // It used to be SUM(invoice_amount) over invoices dated before today
            // — i.e. very nearly the whole policy — so the header printed
            // Opening Balance equal to Invoiced Amount (both P 2,271,458.67 on
            // COMG2024129977), which is not an opening balance at all and made
            // the header impossible to reconcile.
            $openingBalance = 0.0;

            // sumInvoiceAmount = total invoiced on policy (legacy fallback for
            // final_invoiced_amount which was unreliable on partial datasets).
            $sumInvoiceAmount = (float) DB::table('policy_ledger')
                ->where('policy_id', $policyId)
                ->whereNull('deleted_at')
                ->whereIn('trans_type', \AlphaDirect\Services\AccountStatementService::INVOICE_TRANS_TYPES)
                ->sum('invoice_amount');

            // Header totals are an aggregation of the very rows printed below
            // them — one pass, one row set, one resolver — so the header and the
            // Running Balance column cannot drift apart. $finalInvoicedAmount
            // used to add invoice_amount over EVERY row (counting payments as
            // invoicing, since a Payment row carries invoice_amount too) and
            // $finalPayment read a column the balance loop did not.
            $totals = \AlphaDirect\Services\AccountStatementService::headerTotals($data, $openingBalance);

            $finalInvoicedAmount = $totals['invoiced'];
            $finalPayment        = $totals['paid'];
            $finalCreditNotes    = $totals['creditNotes'];
            $finalRefunds        = $totals['refunds'];

            // Refuse to render a statement that does not balance rather than
            // hand a client a self-contradicting document.
            if ($problem = \AlphaDirect\Services\AccountStatementService::assertBalances($totals)) {
                \Log::error('Account statement refused to render: ' . $problem, [
                    'policy_id' => $policyId,
                    'totals'    => $totals,
                ]);

                return response()->json([
                    'error' => 'This statement does not balance and was not generated. '
                        . $problem . ' Please raise this with Finance.',
                ], 409);
            }

            $array = [
                'data'                  => $data,
                'balance'               => $balance,
                'opening_balance'       => $openingBalance,
                'sumInvoiceAmount'      => $sumInvoiceAmount,
                'customer'              => $customer,
                'customer_profile'      => $customerProfile,
                'company'               => $company,
                'policy'                => $policy,
                'policyNumber'          => $policy->policyNumber,
                'premium_freq'          => $policy->premium_freq,
                'final_invoiced_amount' => $finalInvoicedAmount,
                'final_payment'         => $finalPayment,
                'final_credit_notes'    => $finalCreditNotes,
                'final_refunds'         => $finalRefunds,
            ];

            $view = $isDomCom ? 'admin.notes.account_statement_domcom' : 'admin.notes.account_statement';
            if (!view()->exists($view)) {
                return response()->json(['error' => "Template {$view} is missing on this deployment."], 500);
            }
            $pdf = \PDF::loadView($view, $array);
            $name = ($customer?->firstName ?? 'customer') . '_' . ($customer?->lastName ?? '') . '_' . $policy->policyNumber . '.pdf';

            return response($pdf->output(), 200, [
                'Content-Type'        => 'application/pdf',
                'Content-Disposition' => 'inline; filename="' . $name . '"',
            ]);
        } catch (\Throwable $e) {
            \Log::error('Account statement PDF failed: ' . $e->getMessage(), ['trace' => $e->getTraceAsString()]);
            return response()->json([
                'error'   => $e->getMessage(),
                'file'    => basename($e->getFile()),
                'line'    => $e->getLine(),
            ], 500);
        }
    }

    /**
     * Generate and stream an invoice PDF for a policy_ledger row.
     * Mirrors Helper::generateInvoice (MIS) and Helper::generateInvoiceDomCom (DOM/COM).
     */
    public function generateInvoicePdf(int $policyId, int $ledgerId)
    {
        $ledger = DB::table('policy_ledger')->where('id', $ledgerId)->where('policy_id', $policyId)->first();
        if (!$ledger) {
            return response()->json(['error' => 'Ledger entry not found.'], 404);
        }

        $policy  = Policy::with(['product'])->findOrFail($policyId);
        // All DomCom family products use the v2 DomCom invoice template
        $isDomCom = in_array($policy->product_id, [7, 8, 16, 17, 18, 19, 20, 21, 22, 23]);

        $policyAction = $ledger->action_id
            ? PolicyAction::find($ledger->action_id)
            : PolicyAction::where('policy_id', $policyId)->orderBy('id', 'desc')->first();

        $term = PolicyTerm::where('policy_id', $policyId)->orderBy('id', 'desc')->first();

        $customerProfile = \AlphaDirect\CustomerProfile::where('customer_id', $ledger->customer_id)->first();
        $company = ($customerProfile && $customerProfile->company_id)
            ? Company::find($customerProfile->company_id)
            : null;
        $customer = \AlphaDirect\Customer::find($ledger->customer_id);

        // Instant (MIS/MIB) customers are often created via USSD/app without a full
        // profile. The invoice template reads $customerProfile->entity_type/address and
        // $customer->firstName directly, so provide safe fallbacks to stop the PDF render
        // from failing (which left the "View PDF" button stuck loading).
        if (!$customerProfile) {
            $customerProfile = (object) ['entity_type' => 'Individual', 'address' => '', 'company_id' => null];
        }
        if (!$customer) {
            $customer = (object) ['firstName' => '', 'lastName' => ''];
        }

        // VAT calculations (mirrors Helper logic)
        $regionVat = DB::table('regions')->where('id', 7)->value('vat') ?? 14;
        $invoiceAmount = (float) ($ledger->invoice_amount ?? $ledger->debit ?? 0);
        $premiumExcludingVAT = $invoiceAmount / (1 + ($regionVat / 100));
        if ((int) $policy->premium_freq === 1) {
            $premiumExcludingVAT = $premiumExcludingVAT / 1.08;
        }
        $vat             = $premiumExcludingVAT * ($regionVat / 100);
        $serviceCharge8  = $premiumExcludingVAT * 0.08;
        $vatServiceCharge = $serviceCharge8 * ($regionVat / 100);

        // Invoice dates
        $invoiceStartDate = $ledger->invoice_date
            ? \Carbon\Carbon::parse($ledger->invoice_date)->format('d/m/Y')
            : null;

        if ($policyAction) {
            $invoiceEndDate   = \Carbon\Carbon::parse($policyAction->effective_to)->format('d/m/Y');
            $invoiceStartDate = \Carbon\Carbon::parse($policyAction->effective_from)->format('d/m/Y');
            $note             = $policyAction->note ?? 'Gross Premium';
        } else {
            $note = 'Gross Premium';
            $invoiceEndDate = $ledger->due_date
                ? \Carbon\Carbon::parse($ledger->due_date)->subDay()->format('d/m/Y')
                : $invoiceStartDate;
        }

        // Term dates for DOM/COM
        $termStartDate = $term ? \Carbon\Carbon::parse($term->term_start_date)->format('d/m/Y') : $invoiceStartDate;
        $termEndDate   = $term ? \Carbon\Carbon::parse($term->term_end_date)->format('d/m/Y')   : $invoiceEndDate;

        // Risk address for DOM/COM
        $riskAddress = null;
        $city        = null;
        if ($isDomCom) {
            $riskAddress = DB::table('risk_address')
                ->where('policy_id', $policyId)
                ->whereNull('deleted_at')
                ->orderBy('id', 'desc')
                ->first(['address_name', 'risk_city']);
            if ($riskAddress && $riskAddress->risk_city) {
                $city = DB::table('cities')->where('id', $riskAddress->risk_city)->value('name');
            }
        }

        $policySum = DB::table('policy_ledger')->where('policy_id', $policyId)->sum('premium') ?: 0;

        $data = [
            'invoice'             => $ledger,
            'policy'              => $policy,
            'customer'            => $customer,
            'customerProfile'     => $customerProfile,
            'company'             => $company,
            'policyAction'        => $policyAction,
            'invoiceStartDate'    => $invoiceStartDate,
            'invoiceEndDate'      => $invoiceEndDate,
            'premiumExcludingVAT' => $premiumExcludingVAT,
            'vat'                 => $vat,
            'ServiceCharge8'      => $serviceCharge8,
            'vatServiceCharge'    => $vatServiceCharge,
            'note'                => $note,
            'productId'           => $policy->product_id,
            'policySum'           => $policySum,
            'policy_term'         => $term,
            'term_start_date'     => $termStartDate,
            'term_end_date'       => $termEndDate,
            'risk_address'        => $riskAddress,
            'getCity'             => $city ? (object) ['name' => $city] : null,
        ];

        $template = $isDomCom ? 'v2.livewire.policy.invoice.invoice' : 'admin.subLedger.invoice';
        $fileName = ($policy->policyNumber ?? $policyId) . '_invoice_' . ($ledger->invoice_no ?? $ledgerId) . '.pdf';

        try {
            libxml_use_internal_errors(true);
            $pdf = \PDF::loadView($template, $data);
            return response($pdf->output(), 200, [
                'Content-Type'        => 'application/pdf',
                'Content-Disposition' => 'inline; filename="' . $fileName . '"',
            ]);
        } catch (\Exception $e) {
            return response()->json(['error' => $e->getMessage()], 500);
        }
    }

    // =========================================================================
    //  Clone Policy
    // =========================================================================

    /**
     * POST /policies/{id}/clone
     *
     * Deep-clone a policy: customer, risk addresses, coverages (with sub-coverages,
     * extensions, specified items, excesses, notes), motor vehicles, and vehicle records.
     *
     * Options:
     *   - customer_id: use a different customer (default: same customer)
     *   - term_start_date / expiry_date: override dates (default: today + 1 year)
     *   - skip_motor: true to skip motor vehicle cloning (default: false)
     *
     * Returns the new policy with a detailed clone report showing exactly what was copied.
     */
    public function clonePolicy(Request $request, int $sourcePolicyId): JsonResponse
    {
        $source = Policy::with(['customer', 'profile', 'product'])->findOrFail($sourcePolicyId);
        $sourceAction = \AlphaDirect\Models\PolicyAction::where('policy_id', $sourcePolicyId)->orderByDesc('id')->first();
        $sourceTerm = PolicyTerm::where('policy_id', $sourcePolicyId)->orderByDesc('id')->first();

        if (!$sourceAction) {
            return response()->json(['error' => 'Source policy has no action record.'], 422);
        }

        $validated = $request->validate([
            'customer_id'     => 'nullable|integer|exists:customers,id',
            'term_start_date' => 'nullable|date',
            'expiry_date'     => 'nullable|date|after:term_start_date',
            'skip_motor'      => 'nullable|boolean',
        ]);

        $customerId = $validated['customer_id'] ?? $source->customer_id;
        $termStart  = $validated['term_start_date'] ?? Carbon::now()->format('Y-m-d');
        $termEnd    = $validated['expiry_date'] ?? Carbon::parse($termStart)->addYear()->subDay()->format('Y-m-d');
        $skipMotor  = $validated['skip_motor'] ?? false;

        $report = [
            'source_policy'     => $source->policyNumber,
            'risk_addresses'    => 0,
            'coverages'         => 0,
            'subcoverages'      => 0,
            'extensions'        => 0,
            'specified_items'   => 0,
            'excesses'          => 0,
            'notes'             => 0,
            'motor_vehicles'    => 0,
            'vehicles'          => 0,
            'errors'            => [],
        ];

        DB::beginTransaction();
        try {
            // ── 1. Create new policy shell ────────────────────────────────
            $newPolicy = $source->replicate(['id', 'policyNumber', 'created_at', 'updated_at', 'status']);
            $newPolicy->customer_id     = $customerId;
            $newPolicy->term_start_date = $termStart;
            $newPolicy->expiry_date     = $termEnd;
            $newPolicy->billingStartDate = null;
            $newPolicy->status          = 0; // draft/quote
            $newPolicy->save();

            // Generate policy number
            $prefix = in_array($source->product_id, [7, 16, 17]) ? 'COMG' : 'DOMG';
            $policyNumber = $prefix . Carbon::now()->format('Y') . $newPolicy->id;
            $newPolicy->policyNumber = $policyNumber;
            $newPolicy->save();

            // ── 2. Term + Action ──────────────────────────────────────────
            $newTermId = PolicyTerm::addPolicyTerm([
                'policy_id'       => $newPolicy->id,
                'term_start_date' => $termStart,
                'term_end_date'   => $termEnd,
                'premium'         => $source->premium,
                'frequency'       => $source->premium_freq,
                'trans_type'      => 'NEW BUSINESS',
                'status'          => 'Active',
                'created_at'      => now(),
            ]);

            $newAction = \AlphaDirect\Models\PolicyAction::create([
                'policy_id'        => $newPolicy->id,
                'term_id'          => $newTermId,
                'note'             => "Cloned from {$source->policyNumber}",
                'policy_quote_no'  => $policyNumber . '/01',
                'effective_from'   => $termStart,
                'effective_to'     => $termEnd,
                'transaction_type' => 'NEWBUSINESS',
                'status'           => 'QUOTE',
            ]);

            // ── 3. Risk Addresses ─────────────────────────────────────────
            $riskAddressMap = []; // old_id => new_id
            $sourceRisks = DB::table('risk_address')
                ->where('policy_id', $sourcePolicyId)
                ->where('action_id', $sourceAction->id)
                ->whereNull('deleted_at')
                ->get();

            foreach ($sourceRisks as $risk) {
                $oldId = $risk->id;
                $newRisk = (array) $risk;
                unset($newRisk['id']);
                $newRisk['policy_id'] = $newPolicy->id;
                $newRisk['action_id'] = $newAction->id;
                $newRisk['term_id']   = $newTermId;
                $newRisk['created_at'] = now();
                $newRisk['updated_at'] = now();
                $newId = DB::table('risk_address')->insertGetId($newRisk);
                $riskAddressMap[$oldId] = $newId;
                $report['risk_addresses']++;
            }

            // ── 4. Coverages + related data ───────────────────────────────
            $sourceCoverages = DB::table('policy_coverages')
                ->where('policy_id', $sourcePolicyId)
                ->where('action_id', $sourceAction->id)
                ->whereNull('deleted_at')
                ->get();

            foreach ($sourceCoverages as $cov) {
                $oldCovId = $cov->id;
                $newCov = (array) $cov;
                unset($newCov['id']);
                $newCov['policy_id']       = $newPolicy->id;
                $newCov['action_id']       = $newAction->id;
                $newCov['term_id']         = $newTermId;
                $newCov['risk_address_id'] = $riskAddressMap[$cov->risk_address_id] ?? $cov->risk_address_id;
                $newCov['created_at']      = now();
                $newCov['updated_at']      = now();
                $newCov = array_merge($newCov, $this->auditStamps('policy_coverages'));
                $newCovId = DB::table('policy_coverages')->insertGetId($newCov);
                $report['coverages']++;

                // Sub-coverages (policy_coverage_detail)
                $details = DB::table('policy_coverage_detail')
                    ->where('policy_coverage_id', $oldCovId)
                    ->whereNull('deleted_at')
                    ->get();
                foreach ($details as $d) {
                    $nd = (array) $d;
                    unset($nd['id']);
                    $nd['policy_coverage_id'] = $newCovId;
                    $nd['created_at'] = now();
                    $nd['updated_at'] = now();
                    DB::table('policy_coverage_detail')->insert($nd);
                    $report['subcoverages']++;
                }

                // Extensions (policy_extention_detail)
                $exts = DB::table('policy_extention_detail')
                    ->where('policy_coverage_id', $oldCovId)
                    ->whereNull('deleted_at')
                    ->get();
                foreach ($exts as $e) {
                    $ne = (array) $e;
                    unset($ne['id']);
                    $ne['policy_coverage_id'] = $newCovId;
                    $ne['created_at'] = now();
                    $ne['updated_at'] = now();
                    DB::table('policy_extention_detail')->insert($ne);
                    $report['extensions']++;
                }

                // Specified items
                $items = DB::table('policy_specified_items')
                    ->where('policy_coverage_id', $oldCovId)
                    ->whereNull('deleted_at')
                    ->get();
                foreach ($items as $item) {
                    $ni = (array) $item;
                    unset($ni['id']);
                    $ni['policy_coverage_id'] = $newCovId;
                    $ni['created_at'] = now();
                    $ni['updated_at'] = now();
                    $ni = array_merge($ni, $this->auditStamps('policy_specified_items'));
                    DB::table('policy_specified_items')->insert($ni);
                    $report['specified_items']++;
                }

                // Notes
                $notes = DB::table('policy_coverage_notes')
                    ->where('policy_coverage_id', $oldCovId)
                    ->get();
                foreach ($notes as $n) {
                    $nn = (array) $n;
                    unset($nn['id']);
                    $nn['policy_coverage_id'] = $newCovId;
                    $nn['created_at'] = now();
                    $nn['updated_at'] = now();
                    $nn = array_merge($nn, $this->auditStamps('policy_coverage_notes'));
                    DB::table('policy_coverage_notes')->insert($nn);
                    $report['notes']++;
                }

                // Motor vehicles
                if (!$skipMotor) {
                    $motors = DB::table('motor')
                        ->where('policy_coverage_id', $oldCovId)
                        ->whereNull('deleted_at')
                        ->get();
                    foreach ($motors as $m) {
                        $nm = (array) $m;
                        unset($nm['id']);
                        $nm['policy_coverage_id'] = $newCovId;
                        $nm['created_at'] = now();
                        $nm['updated_at'] = now();
                        DB::table('motor')->insert($nm);
                        $report['motor_vehicles']++;
                    }
                }
            }

            // ── 5. Vehicle table records ──────────────────────────────────
            if (!$skipMotor) {
                $sourceVehicles = DB::table('vehicle')
                    ->where('policy_id', $sourcePolicyId)
                    ->whereNull('deleted_at')
                    ->get();
                foreach ($sourceVehicles as $v) {
                    $nv = (array) $v;
                    unset($nv['id']);
                    $nv['policy_id']   = $newPolicy->id;
                    $nv['customer_id'] = $customerId;
                    $nv['action_id']   = $newAction->id;
                    $nv['term_id']     = $newTermId;
                    $nv['risk_id']     = $riskAddressMap[$v->risk_id] ?? $v->risk_id;
                    $nv['created_at']  = now();
                    $nv['updated_at']  = now();
                    DB::table('vehicle')->insert($nv);
                    $report['vehicles']++;
                }
            }

            // ── 6. Specialist coverages (CAR/EAR/PAR/Marine/Machinery) ───
            foreach (['car_coverages', 'ear_coverages', 'par_coverages',
                      'marine_cargo_once_off_coverages', 'marine_cargo_open_coverages',
                      'marine_directors_officers_coverages', 'machinery_breakdown_coverages',
                      'medical_evacuation_coverages', 'commercial_crime_coverages',
                      'environmental_liability_coverages', 'bonds_coverages'] as $table) {
                try {
                    $specRows = DB::table($table)->where('policy_id', $sourcePolicyId)->get();
                    foreach ($specRows as $row) {
                        $nr = (array) $row;
                        unset($nr['id']);
                        $nr['policy_id']  = $newPolicy->id;
                        $nr['created_at'] = now();
                        $nr['updated_at'] = now();
                        DB::table($table)->insert($nr);
                    }
                    if ($specRows->count() > 0) {
                        $report['specialist_' . $table] = $specRows->count();
                    }
                } catch (\Throwable $e) {
                    // Table may not exist for some products — skip silently
                }
            }

            // ── 7. Activity log ───────────────────────────────────────────
            activity('Policy Clone')
                ->performedOn($newPolicy)
                ->causedBy(auth()->user())
                ->withProperties(['source_policy_id' => $sourcePolicyId, 'report' => $report])
                ->log("Cloned from {$source->policyNumber}");

            DB::commit();

            return response()->json([
                'message' => "Policy cloned successfully from {$source->policyNumber}.",
                'data'    => [
                    'policy_id'     => $newPolicy->id,
                    'policy_number' => $policyNumber,
                    'term_id'       => $newTermId,
                    'action_id'     => $newAction->id,
                    'customer_id'   => $customerId,
                    'status'        => 'quote',
                ],
                'report'  => $report,
            ], 201);

        } catch (\Throwable $e) {
            DB::rollBack();
            Log::error("Policy clone failed", [
                'source_id' => $sourcePolicyId,
                'error'     => $e->getMessage(),
                'trace'     => substr($e->getTraceAsString(), 0, 500),
            ]);
            return response()->json([
                'error'   => 'Clone failed: ' . $e->getMessage(),
                'report'  => $report,
            ], 500);
        }
    }
}
